    /**
     * Zentral erkennbares Designprofil. Allgemeine Komponenten koennen das
     * Profil abfragen, ohne Pferde-Atelier-Werte hart in ihre Logik einzubauen.
     */
    public static function design_profile() {
        $profile = (string)apply_filters('pftk_design_profile', self::DESIGN_PROFILE);
        $profile = sanitize_key($profile);
        return $profile !== '' ? $profile : self::DESIGN_PROFILE;
    }

    public static function design_profile_contract_version() {
