    /**
     * Stabile Integrationsschnittstelle fuer die Affiliate-Zentrale.
     * Liefert nur fuer veroeffentlichte Seiten den vom Designplugin tatsaechlich
     * verwendeten Seitentyp. Die Affiliate-Zentrale muss die Ebenenlogik daher
     * nicht duplizieren oder erraten.
     */
    public static function affiliate_page_type($page_id) {
        $page_id = absint($page_id);
        $post = $page_id > 0 ? get_post($page_id) : null;
        if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') {
            return '';
        }
        $item = new stdClass();
        $item->ID = -300000 - $page_id;
        $item->db_id = $item->ID;
        $item->menu_item_parent = 0;
        $item->object_id = $page_id;
        $item->object = 'page';
        $item->type = 'post_type';
        $item->title = get_the_title($post);
        $item->url = get_permalink($post);
        $item->menu_order = 0;
        return self::current_page_template_type($item);
    }

