    /**
     * Unterdrückt Astras automatisch generierte „Ähnliche Beiträge“ auf
     * Einzelbeiträgen fail-closed. Dadurch erscheint unter dem kontrollierten
     * Artikelabschluss kein zusätzlicher Bild-/Beitragsblock.
     */
    public static function disable_astra_related_posts_query_v150329($args) {
        if (!is_singular('post')) {
            return $args;
        }
        $args = is_array($args) ? $args : [];
        $args['post__in'] = [0];
        $args['ignore_sticky_posts'] = true;
        return $args;
    }

    private static function maybe_apply_start_hero_defaults_v150174() {
        $migration_key = 'pftk_start_hero_defaults_migration_v150174';
        if ((string)get_option($migration_key, '') === '1') { return; }

        $texts = get_option(self::option_name('start', 'texts'), []);
        if (!is_array($texts)) { $texts = []; }
        $texts['hero_eyebrow'] = 'Willkommen im Pferde Atelier';
        $texts['hero_title'] = "Für eine harmonische Verbindung\nzwischen Mensch und Pferd.";
        $texts['hero_lead'] = "Wissen, Orientierung und Vertrauen für deinen gemeinsamen Weg.\nPraktisch, fundiert und mit Liebe zum Detail.";
        $texts['hero_button_1'] = 'Entdecke unsere Angebote';
        update_option(self::option_name('start', 'texts'), self::sanitize_texts('start', $texts), false);

        $media = get_option(self::option_name('start', 'media'), []);
        if (!is_array($media)) { $media = []; }
        $media['hero_alt'] = 'Frau mit Pferd auf einer sonnigen Weide';
        $media['hero_url'] = '#pftk-start-themen';
        $media['hero_target'] = '_self';
        update_option(self::option_name('start', 'media'), self::sanitize_media('start', $media), false);
        update_option($migration_key, '1', false);
    }

    /**
     * V1.50.343: Einmalige Übernahme der bestätigten Startseiten-Texte.
     * Der feste Zeilenumbruch nach „Mensch und Pferd –“ gehört ausdrücklich
     * zur freigegebenen Hero-Komposition. Andere Portalbereiche bleiben unberührt.
     */
    private static function maybe_apply_startpage_copy_v150343() {
        $migration_key = 'pftk_startpage_copy_migration_v150343';
        if ((string)get_option($migration_key, '') === '1') { return; }

        $texts = get_option(self::option_name('start', 'texts'), []);
        if (!is_array($texts)) { $texts = []; }
        $texts['hero_title'] = "Mensch und Pferd –\ngemeinsam fest im Sattel.";
        $texts['hero_lead'] = 'Pferdewissen, praktische Tipps und ausgewählte Angebote für euren gemeinsamen Alltag';
        $texts['hero_button_1'] = 'Pferdethemen entdecken';
        update_option(self::option_name('start', 'texts'), self::sanitize_texts('start', $texts), false);
        update_option($migration_key, '1', false);
    }

