    /**
     * Entfernt ausschliesslich das vollstaendige technische Importgeruest des
     * Safe-Importers: ein H2 mit exakt dem Seitentitel plus genau ein Absatz.
     * Sobald weiterer oder abweichender Inhalt vorhanden ist, bleibt alles
     * unveraendert. Dadurch werden manuell gepflegte Seiten nicht angetastet.
     */
    private static function strip_importer_placeholder_content_string($content, $page_title) {
        $content = (string)$content;
        $trimmed = trim($content);
        if ($trimmed === '') { return ''; }

        // Nur die vom Importer erzeugten Gutenberg-Kommentare entfernen. Andere
        // Blocktypen oder weitere Inhalte verhindern bewusst eine Bereinigung.
        $without_comments = preg_replace('/<!--\s*\/?wp:(?:heading|paragraph)(?:\s+\{.*?\})?\s*-->/is', '', $trimmed);
        if (!is_string($without_comments)) { return $content; }
        $without_comments = trim($without_comments);
        if (preg_match_all('/<h2\b/i', $without_comments) !== 1 || preg_match_all('/<p\b/i', $without_comments) !== 1) {
            return $content;
        }
        if (!preg_match('/^<h2\b[^>]*>(.*?)<\/h2>\s*<p\b[^>]*>(.*?)<\/p>$/is', $without_comments, $match)) {
            return $content;
        }

        $heading = trim(html_entity_decode(wp_strip_all_tags((string)$match[1]), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        $expected = trim(html_entity_decode(wp_strip_all_tags((string)$page_title), ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        if ($heading === '' || $expected === '' || $heading !== $expected) { return $content; }
        return '';
    }

    public static function strip_importer_placeholder_content($content) {
        if (is_admin() || is_feed() || !is_singular('page') || !in_the_loop() || !is_main_query()) { return $content; }
        $page_id = absint(get_the_ID());
        $type = $page_id > 0 ? self::page_type_for_id($page_id) : '';
        if (!in_array($type, ['start','hub1','hub2','category','leaf'], true)) { return $content; }
        return self::strip_importer_placeholder_content_string($content, get_the_title($page_id));
    }

