    private static function category_text_type_enabled($type, $settings = null) {
        $type = sanitize_key((string)$type);
        if (in_array($type, ['start', 'category'], true)) { return false; }
        $settings = is_array($settings) ? $settings : self::category_text_settings();
        $key = 'include_' . $type;
        return !empty($settings[$key]);
    }

    private static function start_page_id() {
        static $cached = null;
        if ($cached !== null) { return $cached; }

        $front_id = absint(get_option('page_on_front'));
        $front = $front_id > 0 ? get_post($front_id) : null;
        if ($front instanceof WP_Post && $front->post_type === 'page' && $front->post_status === 'publish') {
            $cached = $front_id;
            return $cached;
        }

        // Robuster Fallback: Manche Installationen zeigen die Portal-Startseite
        // ueber einen Startseiten-Shortcode, obwohl page_on_front nicht sauber gesetzt ist.
        // Die Seite muss trotzdem in der Sammelerzeugung und Ebenenerkennung als Startseite gelten.
        global $wpdb;
        if (isset($wpdb) && is_object($wpdb) && !empty($wpdb->posts) && method_exists($wpdb, 'prepare') && method_exists($wpdb, 'get_var') && method_exists($wpdb, 'esc_like')) {
            $patterns = [
                '[pferde_startseite',
                '[pferde_startseite_only',
                '[affiliate_portal_startseite',
            ];
            $likes = [];
            $args = [];
            foreach ($patterns as $pattern) {
                $likes[] = 'post_content LIKE %s';
                $args[] = '%' . $wpdb->esc_like($pattern) . '%';
            }
            $sql = "SELECT ID FROM {$wpdb->posts} WHERE post_type = 'page' AND post_status = 'publish' AND (" . implode(' OR ', $likes) . ') ORDER BY menu_order ASC, ID ASC LIMIT 1';
            $found = absint($wpdb->get_var($wpdb->prepare($sql, $args)));
            if ($found > 0) {
                $cached = $found;
                return $cached;
            }
        }

        $cached = 0;
        return $cached;
    }

    private static function page_type_for_id($page_id) {
        $page_id = absint($page_id);
        if ($page_id <= 0) { return ''; }
        if (array_key_exists($page_id, self::$page_type_cache)) { return self::$page_type_cache[$page_id]; }
        if ($page_id === self::start_page_id()) {
            self::$page_type_cache[$page_id] = 'start';
            return 'start';
        }
        self::$page_type_cache[$page_id] = self::affiliate_page_type($page_id);
        return self::$page_type_cache[$page_id];
    }

    private static function menu_like_page_item($page_id) {
        $post = get_post(absint($page_id));
        if (!$post instanceof WP_Post || $post->post_type !== 'page') { return null; }
        $item = new stdClass();
        $item->ID = -400000 - intval($post->ID);
        $item->db_id = $item->ID;
        $item->menu_item_parent = 0;
        $item->object_id = intval($post->ID);
        $item->object = 'page';
        $item->type = 'post_type';
        $item->title = get_the_title($post);
        $item->url = get_permalink($post);
        $item->menu_order = 0;
        return $item;
    }

    private static function category_text_parent_titles($page_id, $limit = 3) {
        $titles = [];
        $post = get_post(absint($page_id));
        $parent_id = $post instanceof WP_Post ? absint($post->post_parent) : 0;
        while ($parent_id > 0 && count($titles) < max(1, intval($limit))) {
            $parent = get_post($parent_id);
            if (!$parent instanceof WP_Post || $parent->post_type !== 'page') { break; }
            $title = trim((string)get_the_title($parent));
            if ($title !== '') { $titles[] = $title; }
            $parent_id = absint($parent->post_parent);
        }
        return $titles;
    }

    private static function category_text_terms_for_page($page_id, $type) {
        $terms = [];
        $page_id = absint($page_id);
        if (in_array($type, ['hub1','hub2'], true)) {
            foreach ((array)self::direct_published_page_children($page_id) as $child) {
                if ($child instanceof WP_Post) { $terms[] = trim((string)get_the_title($child)); }
                elseif (is_object($child) && !empty($child->title)) { $terms[] = trim((string)$child->title); }
            }
        } elseif ($type === 'category') {
            // V1.49.2: Textlogik und sichtbare Kachellogik sind strikt getrennt.
            // Die Textgenerierung darf weder auto_category_tiles_for_current() noch
            // dessen zeitbegrenzten Render-Cache aufrufen. Sonst kann ein frueher
            // Intro-Aufruf ein leeres Kachelergebnis fuer die spaetere Ausgabe cachen.
            // Reale direkte Unterseiten duerfen als Textquelle dienen; Ebene-3-Seiten
            // ohne Unterseiten bleiben durch Titel, Elternhierarchie und Fachprofil
            // trotzdem thematisch eindeutig.
            foreach ((array)self::direct_published_page_children($page_id) as $child) {
                if ($child instanceof WP_Post) { $terms[] = trim((string)get_the_title($child)); }
                elseif (is_object($child) && !empty($child->title)) { $terms[] = trim((string)$child->title); }
            }
        }
        $terms = array_values(array_unique(array_filter($terms)));
        return array_slice($terms, 0, 6);
    }

    private static function category_text_content_intents_for_page($page_id) {
        $intents = [];
        foreach (self::category_text_terms_for_page($page_id, 'category') as $term) {
            $key = self::normalize_match_key($term);
            $map = [
                'faq-' => 'Antworten auf häufige Fragen',
                'beratung-' => 'Auswahlhilfen',
                'vergleich-' => 'Vergleiche',
                'pflege-' => 'Pflegehinweise',
                'kosten-' => 'Kostenübersichten',
                'sicherheit-' => 'Sicherheitshinweise',
                'gesundheit-' => 'Gesundheitshinweise',
                'anwendung-' => 'Anwendungstipps',
                'grundlagen-' => 'Grundlagen',
                'checkliste-' => 'Checklisten',
                'checklisten-' => 'Checklisten',
            ];
            foreach ($map as $prefix => $label) {
                if (strpos($key, $prefix) === 0) {
                    $intents[] = $label;
                    break;
                }
            }
        }
        $intents = array_values(array_unique($intents));
        return !empty($intents) ? array_slice($intents, 0, 3) : ['Ratgeber', 'Vergleiche', 'praktische Hinweise'];
    }

