    private static function category_text_profile_for_page($page_id, $title) {
        $profiles = self::category_text_topic_profiles();
        $parents = self::category_text_parent_titles($page_id, 3);
        $keys = [];
        foreach (array_merge([$title], $parents) as $value) {
            $key = self::normalize_match_key($value);
            if ($key !== '') { $keys[] = $key; }
        }
        foreach ($keys as $key) {
            if (!empty($profiles[$key]) && is_array($profiles[$key])) { return $profiles[$key]; }
        }
        $context = implode('-', $keys);
        $profile_keys = array_keys($profiles);
        usort($profile_keys, function($a, $b) { return strlen((string)$b) - strlen((string)$a); });
        foreach ($profile_keys as $key) {
            if ($key !== '' && strpos($context, $key) !== false && is_array($profiles[$key])) { return $profiles[$key]; }
        }
        return ['focus' => 'Auswahl, Einsatz und praktische Unterschiede', 'criteria' => ['Eignung', 'Qualität', 'Handhabung', 'Pflege']];
    }

    private static function category_text_synonyms_for_title($title, $settings = null) {
        $settings = is_array($settings) ? $settings : self::category_text_settings();
        $needle = self::normalize_match_key((string)$title);
        $matches = [];
        foreach (preg_split('/\r\n|\r|\n/', (string)($settings['synonym_map'] ?? '')) as $line) {
            $line = trim($line);
            if ($line === '' || strpos($line, '|') === false) { continue; }
            [$key, $raw] = array_map('trim', explode('|', $line, 2));
            $key_norm = self::normalize_match_key($key);
            if ($key_norm === '' || ($needle !== $key_norm && strpos($needle, $key_norm) === false && strpos($key_norm, $needle) === false)) { continue; }
            foreach (array_map('trim', explode(',', $raw)) as $value) {
                if ($value !== '') { $matches[] = $value; }
            }
        }
        return array_values(array_unique($matches));
    }

    private static function human_list($items, $limit = 3) {
        $items = array_values(array_unique(array_filter(array_map('trim', (array)$items))));
        $items = array_slice($items, 0, max(1, intval($limit)));
        $count = count($items);
        if ($count === 0) { return ''; }
        if ($count === 1) { return $items[0]; }
        if ($count === 2) { return $items[0] . ' und ' . $items[1]; }
        return implode(', ', array_slice($items, 0, -1)) . ' und ' . end($items);
    }

    private static function category_text_variant($page_id, $title) {
        return abs(crc32(absint($page_id) . '|' . self::normalize_match_key($title))) % 2;
    }

