        }
        $parent_bucket = (int)(sprintf('%u', crc32($parent_key)) % 8);
        $base_hash = hash('sha256', 'v150396-upper|' . $subject_key . '|' . $salt);
        $base = (int)hexdec(substr($base_hash, 0, 8));
        $pool = ($salt === 's1' && count($items) >= 32) ? 8 : count($items);
        $index = ($base + $parent_bucket) % max(1, $pool);
