    /**
     * V1.50.395 – harte TABU-Zone fuer die acht obersten Hauptkategorien.
     * Die neue Intro-/Accordion-Logik darf erst unterhalb dieser Ebene greifen.
     */
    private static function intro_accordion_top_level_taboo_v150395() {
        if (!is_singular('page')) { return false; }
        $page_id = absint(get_queried_object_id());
        $post = $page_id > 0 ? get_post($page_id) : null;
        if (!$post instanceof WP_Post || absint($post->post_parent) !== 0) { return false; }
        $slug = sanitize_title((string)$post->post_name);
        return in_array($slug, ['ausruestung','stall','weide','fuetterung','gesundheit','training','transport','wissen'], true);
    }

    /**
     * V1.50.396 – bestätigte kompakte Intro-Darstellung für alle Ebenen unterhalb
     * der acht gesperrten Hauptkategorien. Der komplette Text liegt bereits im
     * initialen HTML; nur die fachliche Vertiefung wird nativ per <details>
     * eingeklappt. "Was du hier findest" bleibt immer sichtbar.
     */
    private static function deck_intro_markup_v150390($text) {
        $text = trim((string)$text);
        if ($text === '') { return '<p></p>'; }
        if (self::intro_accordion_top_level_taboo_v150395()) { return '<p>' . esc_html($text) . '</p>'; }
        $word_count = count(preg_split('/\s+/u', $text, -1, PREG_SPLIT_NO_EMPTY));
        if ($word_count < 130) { return '<p>' . esc_html($text) . '</p>'; }
        $sentences = preg_split('/(?<=[.!?])\s+(?=[\p{Lu}\d„])/u', $text, -1, PREG_SPLIT_NO_EMPTY);
        $find_count = 2;
        if (!is_array($sentences) || count($sentences) <= $find_count + 2) { return '<p>' . esc_html($text) . '</p>'; }
        $find = array_splice($sentences, -$find_count);
        $body = array_values($sentences);
        $target = 55;
        $best_i = 1; $best_delta = PHP_INT_MAX;
        for ($i = 1; $i < count($body); $i++) {
            $lead_words = count(preg_split('/\s+/u', trim(implode(' ', array_slice($body, 0, $i))), -1, PREG_SPLIT_NO_EMPTY));
            $more_words = count(preg_split('/\s+/u', trim(implode(' ', array_slice($body, $i))), -1, PREG_SPLIT_NO_EMPTY));
            if ($more_words < 25) { continue; }
            $delta = abs($lead_words - $target);
            if ($delta < $best_delta) { $best_delta = $delta; $best_i = $i; }
        }
        $lead = trim(implode(' ', array_slice($body, 0, $best_i)));
        $more = trim(implode(' ', array_slice($body, $best_i)));
        $find_text = trim(implode(' ', $find));
        if (trim($lead . ' ' . $more . ' ' . $find_text) !== $text || $more === '' || $find_text === '') { return '<p>' . esc_html($text) . '</p>'; }
        $css = '<style id="pa390-intro-fold-css">'
            . '.pa390-intro-copy{width:min(100%,900px)!important;max-width:900px!important;margin:0 auto!important;text-align:left!important}'
            . '.pa390-intro-copy>.pa390-intro-lead{max-width:none!important;margin:0!important;text-align:left!important;line-height:1.72!important}'
            . '.pa390-intro-more{max-width:none!important;margin:10px 0 12px!important;padding:0!important;border:0!important;text-align:center!important}'
            . '.pa390-intro-more>summary{display:inline-flex;align-items:center;gap:7px;cursor:pointer;list-style:none;color:#35422A;font:inherit;font-size:.9em;font-weight:700;line-height:1.3;transition:color .18s ease}'
            . '.pa390-intro-more>summary::-webkit-details-marker{display:none}'
            . '.pa390-intro-more>summary:before{content:"";display:inline-block;width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg) translateY(-1px);transform-origin:center;transition:transform .18s ease}'
            . '.pa390-intro-more[open]>summary:before{transform:rotate(225deg) translate(-1px,-1px)}'
            . '.pa390-intro-more>summary:hover,.pa390-intro-more>summary:focus-visible{color:#C89214;outline:0}'
            . '.pa390-intro-more-text{padding-top:10px;text-align:left!important}'
            . '.pa390-intro-more-text>p{max-width:none!important;margin:0!important;text-align:left!important;line-height:1.72!important}'
            . '.pa390-intro-find{max-width:none!important;margin:18px 0 0!important;padding:14px 16px!important;border:0!important;border-left:3px solid #C89214!important;background:rgba(242,232,214,.34)!important;text-align:left!important;line-height:1.62!important}'
            . '.pa390-intro-find>strong{display:block;margin:0 0 5px;color:#35422A!important;font:inherit;font-weight:700!important;line-height:1.35}'
            . '.pa390-intro-find>p{max-width:none!important;margin:0!important;text-align:left!important;line-height:1.62!important}'
            . '.pa255-intro:has(.pa390-intro-copy){border-top:0!important;padding-top:4px!important}'
            . '.pa266-category .pa266-intro:has(.pa390-intro-copy),.pa333-leaf-page .pa272-intro:has(.pa390-intro-copy),.pa273-leaf-archive .pa273-intro:has(.pa390-intro-copy){border-top:0!important;padding-top:4px!important}'
            . 'body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) .pftk-universal-breadcrumb-wrap.pftk-breadcrumb-mounted{margin-bottom:0!important}'
            . 'body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) .content-area,body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) .site-main,body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) article.page,body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) article.page>.entry-content{margin-top:0!important;padding-top:0!important}'
            . 'body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa266-category:has(.pa266-intro .pa390-intro-copy),body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa333-leaf-page:has(.pa272-intro .pa390-intro-copy),body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa273-leaf-archive:has(.pa273-intro .pa390-intro-copy){padding-top:0!important}'
            . 'body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa255-intro:has(.pa390-intro-copy),body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa266-category .pa266-intro:has(.pa390-intro-copy),body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa333-leaf-page .pa272-intro:has(.pa390-intro-copy),body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385) .pa273-leaf-archive .pa273-intro:has(.pa390-intro-copy){margin-top:0!important}'
            . '@media(max-width:620px){.pa390-intro-copy{max-width:100%!important}.pa390-intro-find{padding:12px 14px!important}.pa255-intro:has(.pa390-intro-copy){padding-top:2px!important}.pa266-category .pa266-intro:has(.pa390-intro-copy),.pa333-leaf-page .pa272-intro:has(.pa390-intro-copy),.pa273-leaf-archive .pa273-intro:has(.pa390-intro-copy){padding-top:2px!important}}'
            . '@media(max-width:544px){body:not(.pftk-has-leading-page-image-v150385):not(.pftk-has-leading-term-image-v150385):has(.pa390-intro-copy) .pftk-universal-breadcrumb-wrap.pftk-breadcrumb-mounted{margin-bottom:0!important}}'
            . '</style>';
        return $css . '<div class="pa390-intro-copy" data-pa390-intro-seo="initial-html">'
            . '<p class="pa390-intro-lead">' . esc_html($lead) . '</p>'
            . '<details class="pa390-intro-more"><summary>Mehr erfahren</summary><div class="pa390-intro-more-text"><p>' . esc_html($more) . '</p></div></details>'
            . '<div class="pa390-intro-find"><strong>Was du hier findest</strong><p>' . esc_html($find_text) . '</p></div>'
            . '</div>';
    }

    public static function generate_category_intro_text($page_id, $type = '') {
        $page_id = absint($page_id);
        $post = get_post($page_id);
        if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') { return ''; }
        $type = $type !== '' ? sanitize_key($type) : self::page_type_for_id($page_id);
        if (!in_array($type, ['start','hub1','hub2','category'], true)) { return ''; }
        $settings = self::category_text_settings();
        if (!self::category_text_type_enabled($type, $settings)) { return ''; }

        $brand = trim((string)$settings['brand_name']) ?: 'Pferde Atelier';
        $audience = trim((string)$settings['audience_phrase']);
        $title = trim((string)get_the_title($post));
        $profile = self::category_text_profile_for_page($page_id, $title);
        $focus = trim((string)($profile['focus'] ?? 'Auswahl und praktische Unterschiede'));
        $criteria = self::human_list((array)($profile['criteria'] ?? []), 4);
        $children = self::category_text_terms_for_page($page_id, $type);
        $child_list = self::human_list($children, $type === 'hub1' ? 4 : 3);
        $parents = self::category_text_parent_titles($page_id, 2);
        $parent = !empty($parents[0]) ? $parents[0] : '';
        $variant = self::category_text_variant($page_id, $title);

        if (in_array($type, ['hub2','category'], true)) {
            $pilot = self::deck_intro_only_v150389('main/' . self::normalize_match_key($title), '');
            if ($pilot !== '') { return $pilot; }
            $editorial = self::category_intro_editorial_page_batch1359_v150421($page_id);
            if ($editorial !== '') { return $editorial; }
            $intent = $type === 'category' ? self::human_list(self::category_text_content_intents_for_page($page_id), 3) : 'Ratgeber, Vergleiche und praktische Hinweise';
            return self::portal_lower_intro_v150396($title, $focus, (array)($profile['criteria'] ?? []), $parent, $children, $intent, 'generated|' . $type . '|' . self::normalize_match_key($parent) . '|' . self::normalize_match_key($title));
        }

        if ($type === 'start') {
            $text = 'Im ' . $brand . ' findest du die wichtigsten Themenwelten rund um ' . ($audience !== '' ? $audience : 'Pferde, Haltung und Reitsport') . '. Ratgeber, Vergleiche und klar gegliederte Kategorien führen dich schnell zu passenden Informationen und Angeboten.';
            $limit = 65;
        } elseif ($type === 'hub1') {
            if ($variant === 0) {
                $text = 'Im ' . $brand . ' führt dich ' . $title . ($child_list !== '' ? ' zu Bereichen wie ' . $child_list : ' zu den passenden Unterthemen') . '. Im Mittelpunkt stehen ' . $focus . '. Ratgeber und Vergleiche helfen dir, ' . $criteria . ' gezielt einzuordnen.';
            } else {
                $text = $title . ' bündelt im ' . $brand . ($child_list !== '' ? ' Themen wie ' . $child_list : ' die wichtigsten Unterbereiche') . '. So findest du schnell Informationen zu ' . $focus . ' und kannst ' . $criteria . ' besser vergleichen.';
            }
            $limit = 90;
        } elseif ($type === 'hub2') {
            if ($variant === 0) {
                $text = $title . ' bündelt im ' . $brand . ' Themen rund um ' . $focus . '.';
                if ($child_list !== '') { $text .= ' Dazu gehören ' . $child_list . '.'; }
                $text .= ' Ratgeber und Vergleiche helfen dir, ' . $criteria . ' besser einzuordnen.';
            } else {
                $text = 'Im Bereich ' . $title . ' geht es um ' . $focus . '. Das ' . $brand . ($child_list !== '' ? ' behandelt Unterthemen wie ' . $child_list : ' zeigt dir die passenden Unterthemen') . ' und erklärt, welche Rolle ' . $criteria . ' bei Auswahl und Nutzung spielen.';
            }
            $limit = 80;
        } else {
            $intents = self::human_list(self::category_text_content_intents_for_page($page_id), 3);
            if ($variant === 0) {
                $text = 'Für ' . $title . ($parent !== '' ? ' im Bereich ' . $parent : '') . ' sind ' . $criteria . ' besonders wichtig. Im ' . $brand . ' findest du dazu ' . $intents . ', die ' . $focus . ' verständlich einordnen.';
            } else {
                $text = 'Bei ' . $title . ($parent !== '' ? ' im Bereich ' . $parent : '') . ' geht es vor allem um ' . $focus . '. Im ' . $brand . ' findest du ' . $intents . ' und erfährst, worauf es bei ' . $criteria . ' ankommt.';
            }
            $limit = 70;
        }
        $text = trim(preg_replace('/\s+/', ' ', $text));
        return trim(wp_trim_words($text, $limit, ''));
    }


    private static function relevant_category_text_pages() {
        $settings = self::category_text_settings();
        $pages = get_posts([
            'post_type' => 'page',
            'post_status' => 'publish',
            'numberposts' => -1,
            'orderby' => 'menu_order title',
            'order' => 'ASC',
            'suppress_filters' => true,
        ]);
        $out = [];
        foreach ((array)$pages as $page) {
            if (!$page instanceof WP_Post) { continue; }
            $type = self::page_type_for_id($page->ID);
            if (!in_array($type, ['start','hub1','hub2','category'], true) || !self::category_text_type_enabled($type, $settings)) { continue; }
            $out[] = ['post' => $page, 'type' => $type];
        }
        return $out;
    }

    private static function upsert_generated_category_intro($page_id, $force_auto = false) {
        $page_id = absint($page_id);
        if ($page_id <= 0 || get_post_meta($page_id, self::META_CATEGORY_INTRO_HIDDEN, true) === '1') { return false; }
        $source = (string)get_post_meta($page_id, self::META_CATEGORY_INTRO_SOURCE, true);
        $current = trim((string)get_post_meta($page_id, self::META_CATEGORY_INTRO, true));
        if (!$force_auto && $current !== '') { return false; }
        if ($force_auto && $source === 'manual') { return false; }
        $type = self::page_type_for_id($page_id);
        $text = self::generate_category_intro_text($page_id, $type);
        if ($text === '') { return false; }
        update_post_meta($page_id, self::META_CATEGORY_INTRO, $text);
        update_post_meta($page_id, self::META_CATEGORY_INTRO_SOURCE, 'auto');
        return true;
    }

    public static function add_category_intro_meta_box() {
        add_meta_box('pftk_category_intro', 'Pferde Template Kit: Kategorietext & Kurzzeile', [__CLASS__, 'render_category_intro_meta_box'], 'page', 'normal', 'default');
    }

    public static function render_category_intro_meta_box($post) {
        if (!$post instanceof WP_Post) { return; }
        wp_nonce_field('pftk_save_category_intro', 'pftk_category_intro_nonce');
        $type = self::page_type_for_id($post->ID);
        $text = (string)get_post_meta($post->ID, self::META_CATEGORY_INTRO, true);
        $source = (string)get_post_meta($post->ID, self::META_CATEGORY_INTRO_SOURCE, true);
        $hidden = get_post_meta($post->ID, self::META_CATEGORY_INTRO_HIDDEN, true) === '1';
        $shortline = (string)get_post_meta($post->ID, self::META_PAGE_SHORTLINE, true);
        $shortline_hidden = get_post_meta($post->ID, self::META_PAGE_SHORTLINE_HIDDEN, true) === '1';
        echo '<p><strong>Erkannte Ebene:</strong> ' . esc_html($type !== '' ? $type : 'keine Portalebene') . '</p>';
        echo '<p><label for="pftk_page_shortline"><strong>Kurzzeile direkt unter dem Seitentitel</strong></label></p>';
        echo '<input id="pftk_page_shortline" type="text" name="pftk_page_shortline" class="widefat" maxlength="180" value="' . esc_attr($shortline) . '" placeholder="Optional – leer bedeutet keine Ausgabe">';
        echo '<p><label><input type="checkbox" name="pftk_page_shortline_hidden" value="1" ' . checked($shortline_hidden, true, false) . '> Kurzzeile auf dieser Seite ausblenden</label></p>';
        echo '<p class="description">Die Kurzzeile wird nur auf Desktop angezeigt. Auf Mobilgeräten und bei leerem Feld entsteht kein Abstand.</p>';
        echo '<hr style="margin:18px 0">';
        echo '<p><label for="pftk_category_intro_text"><strong>' . esc_html($type === 'hub1' ? 'Hero-Beschreibung' : 'Kategoriebeschreibung') . '</strong></label></p>';
        echo '<textarea id="pftk_category_intro_text" name="pftk_category_intro_text" rows="4" class="widefat">' . esc_textarea($text) . '</textarea>';
        echo '<p><label><input type="checkbox" name="pftk_category_intro_hidden" value="1" ' . checked($hidden, true, false) . '> Kategorietext auf dieser Seite ausblenden</label></p>';
        echo '<p class="description">' . esc_html($type === 'hub1' ? 'Dieser Text wird als Beschreibung im Hero angezeigt. ' : '') . 'Quelle: ' . esc_html($source !== '' ? $source : 'noch nicht erzeugt') . '. Eine manuelle Änderung wird nicht durch automatische Aktualisierungen überschrieben.</p>';
    }

    public static function save_category_intro_meta_box($post_id, $post) {
        if (!$post instanceof WP_Post || $post->post_type !== 'page' || wp_is_post_revision($post_id) || wp_is_post_autosave($post_id)) { return; }
        if (!isset($_POST['pftk_category_intro_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash((string)$_POST['pftk_category_intro_nonce'])), 'pftk_save_category_intro')) { return; }
        if (!current_user_can('edit_post', $post_id)) { return; }
        $shortline_hidden = !empty($_POST['pftk_page_shortline_hidden']);
        update_post_meta($post_id, self::META_PAGE_SHORTLINE_HIDDEN, $shortline_hidden ? '1' : '0');
        $shortline = isset($_POST['pftk_page_shortline']) ? sanitize_text_field(wp_unslash((string)$_POST['pftk_page_shortline'])) : '';
        if ($shortline !== '') { update_post_meta($post_id, self::META_PAGE_SHORTLINE, $shortline); }
        else { delete_post_meta($post_id, self::META_PAGE_SHORTLINE); }
        $hidden = !empty($_POST['pftk_category_intro_hidden']);
        update_post_meta($post_id, self::META_CATEGORY_INTRO_HIDDEN, $hidden ? '1' : '0');
        $submitted = isset($_POST['pftk_category_intro_text']) ? sanitize_textarea_field(wp_unslash((string)$_POST['pftk_category_intro_text'])) : '';
        if ($submitted !== '') {
            update_post_meta($post_id, self::META_CATEGORY_INTRO, $submitted);
            update_post_meta($post_id, self::META_CATEGORY_INTRO_SOURCE, 'manual');
            return;
        }
        $settings = self::category_text_settings();
        if (!$hidden && !empty($settings['auto_on_save'])) {
            delete_post_meta($post_id, self::META_CATEGORY_INTRO);
            delete_post_meta($post_id, self::META_CATEGORY_INTRO_SOURCE);
            self::upsert_generated_category_intro($post_id, false);
        }
    }

    /**
     * V1.50.14: Die zentralen Abstaende werden als eigene, explizite Spacer-
     * Elemente ausgegeben. Dadurch sind Startseite, Hub 1, Hub 2 und Ebene 3
     * auch unter Theme-/Builder-CSS pixelgleich. Margin-Kollaps, Abschnitts-
     * Margins und unterschiedliche Rendererpfade koennen den Wert nicht mehr
     * verschlucken oder verdoppeln.
     */
    private static function category_intro_spacer_style($pixels) {
        $pixels = max(0, min(200, intval($pixels)));
        return 'display:block!important;box-sizing:border-box!important;width:100%!important;height:' . $pixels . 'px!important;min-height:' . $pixels . 'px!important;max-height:' . $pixels . 'px!important;margin:0!important;padding:0!important;border:0!important;flex:0 0 ' . $pixels . 'px!important;line-height:0!important;font-size:0!important;overflow:hidden!important;';
    }

    private static function category_intro_layout_enabled($page_id, $type = '') {
        $page_id = absint($page_id);
        if ($page_id <= 0) { return false; }
        $settings = self::category_text_settings();
        if (empty($settings['enabled'])) { return false; }
        $type = $type !== '' ? sanitize_key($type) : self::page_type_for_id($page_id);
        if (!self::category_text_type_enabled($type, $settings)) { return false; }
        return get_post_meta($page_id, self::META_CATEGORY_INTRO_HIDDEN, true) !== '1';
    }

    private static function category_intro_html($page_id, $type = '') {
        $page_id = absint($page_id);
        if ($page_id <= 0 || !empty(self::$category_intro_rendered[$page_id])) { return ''; }
        $settings = self::category_text_settings();
        if (empty($settings['enabled'])) { return ''; }
        $type = $type !== '' ? sanitize_key($type) : self::page_type_for_id($page_id);
        if (!self::category_text_type_enabled($type, $settings) || get_post_meta($page_id, self::META_CATEGORY_INTRO_HIDDEN, true) === '1') { return ''; }
        $text = trim((string)get_post_meta($page_id, self::META_CATEGORY_INTRO, true));
        $source = trim((string)get_post_meta($page_id, self::META_CATEGORY_INTRO_SOURCE, true));
        if (in_array($type, ['hub2','category'], true) && $source !== 'manual') {
            // V1.50.396: Alte automatisch gespeicherte Kurztexte duerfen den
            // portalweiten Rollout nicht konservieren. Manuelle Texte bleiben
            // bewusst unangetastet; Auto-/Dynamic-Texte werden nur fuer die
            // Ausgabe neu erzeugt, ohne Frontend-Schreibzugriff.
            $generated = self::generate_category_intro_text($page_id, $type);
            if ($generated !== '') { $text = $generated; $source = 'dynamic-v150396'; }
        } elseif ($text === '' && !empty($settings['auto_on_save'])) {
            // Dynamische Ausgabe ohne Datenbankschreibvorgang im Frontend.
            // Speichern erfolgt beim Seiten-Speichern oder gesammelt ueber die Zentrale.
            $text = self::generate_category_intro_text($page_id, $type);
            $source = $text !== '' ? 'dynamic' : '';
        }
        if ($text === '') { return ''; }
        self::$category_intro_rendered[$page_id] = true;
        $debug = current_user_can('manage_options') ? '<!-- pftk-v' . esc_html(self::VERSION) . ' category_intro type=' . esc_html($type) . ' source=' . esc_html($source !== '' ? $source : 'stored') . ' words=' . intval(count(preg_split('/\s+/', trim($text)))) . ' -->' : '';
        $layout = self::global_layout_settings();
        $top = max(0, min(200, intval($layout['intro_margin_top'] ?? 0)));
        $bottom = max(0, min(200, intval($layout['intro_margin_bottom'] ?? 34)));
        // V1.50.28: Der Abstand ist ein echtes Hoehenelement im gemeinsamen
        // Renderer. Er kann weder kollabieren noch durch Margin-Regeln von Astra,
        // Gutenberg oder dem Kachelbereich verschwinden.
        $intro_style = 'margin-top:' . $top . 'px!important;margin-bottom:0!important;';
        return $debug . '<div class="pftk-page-intro-stack pftk-page-intro-stack-' . esc_attr($type) . '" data-pftk-page-intro="1" data-pftk-intro-space-top="' . esc_attr((string)$top) . '" data-pftk-intro-space-bottom="' . esc_attr((string)$bottom) . '">' .
            '<div class="pftk-page-intro-wrap pftk-page-intro-wrap-' . esc_attr($type) . '">' .
                '<div class="pftk-page-intro pftk-page-intro-' . esc_attr($type) . '" style="' . esc_attr($intro_style) . '">' . self::deck_intro_markup_v150390($text) . '</div>' .
            '</div>' .
            '<div class="pftk-page-intro-spacer pftk-page-intro-spacer-bottom" style="height:' . esc_attr((string)$bottom) . 'px!important" aria-hidden="true"></div>' .
            '</div>';
    }

    public static function prepend_category_intro_to_content($content) {
        if (is_admin() || is_feed() || !is_singular('page') || !in_the_loop() || !is_main_query()) { return $content; }
        // Prioritaet 99: Shortcode- und Auto-Append-Ausgaben haben den Text zu
        // diesem Zeitpunkt bereits innerhalb ihres eigenen Portalcontainers
        // gerendert. Nur falls kein Portalrenderer lief, greift dieser Fallback.
        if (strpos((string)$content, 'data-pftk-page-intro="1"') !== false) { return $content; }
        $page_id = absint(get_the_ID());
        $html = self::category_intro_html($page_id);
        return $html !== '' ? $html . $content : $content;
    }

    private static function page_shortline_html($page_id, $type = '') {
        $page_id = absint($page_id);
        if ($page_id <= 0 || !empty(self::$page_shortline_rendered[$page_id])) { return ''; }
        $type = $type !== '' ? sanitize_key($type) : self::page_type_for_id($page_id);
        if (!in_array($type, ['start','hub1','hub2','category'], true)) { return ''; }
        if (get_post_meta($page_id, self::META_PAGE_SHORTLINE_HIDDEN, true) === '1') { return ''; }
        $text = trim((string)get_post_meta($page_id, self::META_PAGE_SHORTLINE, true));
        if ($text === '') { return ''; }
        self::$page_shortline_rendered[$page_id] = true;
        return '<div class="pftk-page-shortline" data-pftk-page-shortline="1"><p>' . esc_html($text) . '</p></div>';
    }

    public static function prepend_page_shortline_to_content($content) {
        if (is_admin() || is_feed() || !is_singular('page') || !in_the_loop() || !is_main_query()) { return $content; }
        if (strpos((string)$content, 'data-pftk-page-shortline="1"') !== false) { return $content; }
        $page_id = absint(get_the_ID());
        $html = self::page_shortline_html($page_id);
        return $html !== '' ? $html . $content : $content;
    }

    public static function handle_save_category_text_settings() {
        if (!current_user_can('manage_options')) { wp_die('Keine Berechtigung.'); }
        check_admin_referer('pftk_save_category_text_settings', 'pftk_category_text_nonce');
        $raw = isset($_POST['pftk_category_text']) && is_array($_POST['pftk_category_text']) ? wp_unslash($_POST['pftk_category_text']) : [];
        update_option(self::OPTION_CATEGORY_TEXT_SETTINGS, self::sanitize_category_text_settings($raw), false);
        wp_safe_redirect(add_query_arg(['page' => 'pferde-template-kit-kategorietexte', 'saved' => '1'], admin_url('admin.php')));
        exit;
    }

    public static function handle_generate_category_texts() {
        if (!current_user_can('manage_options')) { wp_die('Keine Berechtigung.'); }
        check_admin_referer('pftk_generate_category_texts', 'pftk_generate_category_texts_nonce');
        // Kompatibilitaetsweg fuer alte gespeicherte Admin-Links: bewusst auf eine
        // kleine Charge begrenzt. Die regulaere Bedienung nutzt AJAX-Chargen und
        // kann dadurch nicht mehr an einem einzigen langen PHP-Request scheitern.
        $mode = isset($_POST['mode']) ? sanitize_key((string)$_POST['mode']) : 'missing';
        $ids = get_posts([
            'post_type' => 'page', 'post_status' => 'publish', 'numberposts' => 20,
            'fields' => 'ids', 'orderby' => 'menu_order title', 'order' => 'ASC',
            'suppress_filters' => false,
        ]);
        $count = 0;
        foreach ((array)$ids as $page_id) {
            $type = self::page_type_for_id((int)$page_id);
            if (!self::category_text_type_enabled($type)) { continue; }
            if (self::upsert_generated_category_intro((int)$page_id, $mode === 'refresh_auto')) { $count++; }
        }
        wp_safe_redirect(add_query_arg(['page' => 'pferde-template-kit-kategorietexte', 'generated' => $count, 'mode' => $mode, 'bounded' => '1'], admin_url('admin.php')));
        exit;
    }

    public static function ajax_generate_category_text_batch() {
        if (!current_user_can('manage_options')) { wp_send_json_error(['message' => 'Keine Berechtigung.'], 403); }
        check_ajax_referer('pftk_generate_category_text_batch', 'nonce');
        $mode = isset($_POST['mode']) ? sanitize_key((string)$_POST['mode']) : 'missing';
        if (!in_array($mode, ['missing','refresh_auto'], true)) { $mode = 'missing'; }
        $offset = max(0, intval($_POST['offset'] ?? 0));
        $batch = max(3, min(10, intval($_POST['batch'] ?? 5)));
        $slice = get_posts([
            'post_type' => 'page', 'post_status' => 'publish', 'numberposts' => $batch,
            'offset' => $offset, 'fields' => 'ids', 'orderby' => 'menu_order title', 'order' => 'ASC',
            'suppress_filters' => false, 'no_found_rows' => true,
        ]);
        $counts = function_exists('wp_count_posts') ? wp_count_posts('page') : null;
        $total = is_object($counts) ? intval($counts->publish ?? 0) : ($offset + count((array)$slice));
        $processed = 0;
        $changed = 0;
        foreach ((array)$slice as $page_id) {
            $processed++;
            $type = self::page_type_for_id((int)$page_id);
            if (!self::category_text_type_enabled($type)) { continue; }
            if (self::upsert_generated_category_intro((int)$page_id, $mode === 'refresh_auto')) { $changed++; }
        }
        $next = $offset + count((array)$slice);
        wp_send_json_success([
            'processed' => $processed,
            'changed' => $changed,
            'next_offset' => $next,
            'total' => $total,
            'done' => count((array)$slice) < $batch || ($total > 0 && $next >= $total),
        ]);
    }

    /**
     * V1.49.5: Read-only-Prüfung auf alte oder überflüssige Template-Shortcodes.
     * Die automatische Ausgabe des Plugins benötigt auf Portal-Seiten keine
     * manuell hinterlegten Template-/Banner-Shortcodes mehr. Die Prüfung ändert
     * keinerlei Seiteninhalte und zeigt ausschließlich Fundstellen an.
     */
    private static function shortcode_audit_tags() {
        return [
            'pferde_template_oben',
            'pferde_template_unten',
            'pferde_banner',
            'pferde_produkte',
            'pferde_startseite',
            'pferde_startseite_only',
            'pferde_hub_ebene_1',
            'pferde_hauptseite',
            'pferde_hub_ebene_2',
            'pferde_hub_auto',
            'affiliate_portal_startseite',
            'affiliate_portal_hub_1',
            'affiliate_portal_hub_2',
            'affiliate_portal_hub_auto',
            'affiliate_portal_kategorie',
            'affiliate_portal_produkt',
            'pferde_journal',
            'affiliate_portal_journal',
        ];
    }

    private static function shortcode_audit_find_tags($content) {
        $content = (string)$content;
        if ($content === '') { return []; }
        $found = [];
        foreach (self::shortcode_audit_tags() as $tag) {
            if (has_shortcode($content, $tag)) { $found[] = $tag; }
        }
        sort($found, SORT_STRING);
        return array_values(array_unique($found));
    }

    private static function shortcode_audit_collect_block_refs($blocks, &$ids) {
        foreach ((array)$blocks as $block) {
            if (!is_array($block)) { continue; }
            if (($block['blockName'] ?? '') === 'core/block') {
                $ref = absint($block['attrs']['ref'] ?? 0);
                if ($ref > 0) { $ids[$ref] = $ref; }
            }
            if (!empty($block['innerBlocks'])) {
                self::shortcode_audit_collect_block_refs($block['innerBlocks'], $ids);
            }
        }
    }

    private static function shortcode_audit_results() {
        $pages = get_posts([
            'post_type' => 'page',
            'post_status' => ['publish', 'draft', 'private', 'pending', 'future'],
            'posts_per_page' => -1,
            'orderby' => 'title',
            'order' => 'ASC',
            'no_found_rows' => true,
            'suppress_filters' => false,
            'update_post_meta_cache' => false,
            'update_post_term_cache' => false,
        ]);
        $results = [];
        $block_cache = [];
        foreach ((array)$pages as $page) {
            if (!$page instanceof WP_Post) { continue; }
            $found = self::shortcode_audit_find_tags($page->post_content);
            $sources = [];
            if (!empty($found)) { $sources[] = 'Seiteninhalt'; }

            if (function_exists('parse_blocks')) {
                $block_ids = [];
                self::shortcode_audit_collect_block_refs(parse_blocks((string)$page->post_content), $block_ids);
                foreach ($block_ids as $block_id) {
                    if (!array_key_exists($block_id, $block_cache)) {
                        $block_post = get_post($block_id);
                        $block_tags = [];
                        $block_title = 'Block #' . $block_id;
                        if ($block_post instanceof WP_Post && $block_post->post_type === 'wp_block' && $block_post->post_status !== 'trash') {
                            $block_tags = self::shortcode_audit_find_tags($block_post->post_content);
                            $stored_title = trim((string)get_the_title($block_post));
                            if ($stored_title !== '') { $block_title = $stored_title; }
                        }
                        $block_cache[$block_id] = ['tags' => $block_tags, 'title' => $block_title];
                    }
                    if (!empty($block_cache[$block_id]['tags'])) {
                        $found = array_merge($found, $block_cache[$block_id]['tags']);
                        $sources[] = 'Wiederverwendeter Block: ' . $block_cache[$block_id]['title'];
                    }
                }
            }

            $found = array_values(array_unique($found));
            sort($found, SORT_STRING);
            $sources = array_values(array_unique($sources));
            if (empty($found)) { continue; }
            $results[] = [
                'post' => $page,
                'tags' => $found,
                'sources' => $sources,
            ];
        }
        return $results;
    }

    public static function shortcode_audit_page() {
        if (!current_user_can('manage_options')) { return; }
        $results = self::shortcode_audit_results();
        echo '<div class="wrap"><h1>Shortcode-Prüfung</h1>';
        echo '<p>Read-only-Prüfung aller Seiten auf alte Template-, Hub- und Banner-Shortcodes. Es wird nichts automatisch gelöscht oder verändert.</p>';
        echo '<p><a class="button" href="' . esc_url(admin_url('admin.php?page=pferde-template-kit-shortcode-pruefung')) . '">Erneut prüfen</a></p>';
        if (empty($results)) {
            echo '<div class="notice notice-success inline"><p><strong>Keine betroffenen Seiten gefunden.</strong></p></div></div>';
            return;
        }
        echo '<div class="notice notice-warning inline"><p><strong>' . count($results) . ' Seite(n) mit Plugin-Shortcodes gefunden.</strong> Jede Fundstelle kann direkt im Editor geprüft werden.</p></div>';
        echo '<table class="widefat striped"><thead><tr><th>Seite</th><th>Status</th><th>Gefundene Shortcodes</th><th>Fundstelle</th><th></th></tr></thead><tbody>';
        foreach ($results as $entry) {
            $post = $entry['post'];
            $shortcodes = array_map(function($tag) { return '[' . $tag . ']'; }, $entry['tags']);
            $status = get_post_status_object($post->post_status);
            $status_label = $status ? $status->label : $post->post_status;
            echo '<tr>';
            echo '<td><strong>' . esc_html(get_the_title($post)) . '</strong><br><small>ID ' . intval($post->ID) . '</small></td>';
            echo '<td>' . esc_html($status_label) . '</td>';
            echo '<td><code>' . esc_html(implode(' ', $shortcodes)) . '</code></td>';
            echo '<td>' . esc_html(implode('; ', $entry['sources'])) . '</td>';
            echo '<td><a class="button button-small" href="' . esc_url(get_edit_post_link($post->ID)) . '">Seite bearbeiten</a></td>';
            echo '</tr>';
        }
        echo '</tbody></table></div>';
    }

    public static function category_texts_page() {
        if (!current_user_can('manage_options')) { return; }
        $settings = self::category_text_settings();
        $pages = self::relevant_category_text_pages();
        if (!empty($_GET['saved'])) { echo '<div class="notice notice-success"><p>Kategorietext-Einstellungen gespeichert.</p></div>'; }
        if (isset($_GET['generated'])) { echo '<div class="notice notice-success"><p>' . intval($_GET['generated']) . ' Kategorietexte in einer begrenzten Kompatibilitätscharge verarbeitet.</p></div>'; }
        echo '<div class="wrap"><h1>Kategorietexte</h1>';
        echo '<p>Ein zentraler Workflow: Texte werden automatisch aus Seitentitel, Ebene, realen Unterthemen und Synonymprofil erzeugt und direkt unter dem Seitentitel ausgegeben. Beim Speichern einer Seite oder per Sammelschaltfläche werden sie dauerhaft eingepflegt. Manuelle Texte bleiben geschützt.</p>';
        echo '<form method="post" action="' . esc_url(admin_url('admin-post.php')) . '"><input type="hidden" name="action" value="pftk_save_category_text_settings">';
        wp_nonce_field('pftk_save_category_text_settings', 'pftk_category_text_nonce');
        echo '<table class="form-table" role="presentation"><tbody>';
        echo '<tr><th scope="row">Automatische Ausgabe</th><td><label><input type="checkbox" name="pftk_category_text[enabled]" value="1" ' . checked($settings['enabled'], '1', false) . '> aktiv</label></td></tr>';
        echo '<tr><th scope="row">Automatisch einpflegen</th><td><label><input type="checkbox" name="pftk_category_text[auto_on_save]" value="1" ' . checked($settings['auto_on_save'], '1', false) . '> fehlende Texte automatisch anzeigen und beim Speichern einer Seite einpflegen</label></td></tr>';
        echo '<tr><th scope="row">Projektname</th><td><input type="text" class="regular-text" name="pftk_category_text[brand_name]" value="' . esc_attr($settings['brand_name']) . '"></td></tr>';
        echo '<tr><th scope="row">Zielgruppe / Kontext</th><td><input type="text" class="regular-text" name="pftk_category_text[audience_phrase]" value="' . esc_attr($settings['audience_phrase']) . '"><p class="description">Wird natürlich in Hub-Texten verwendet.</p></td></tr>';
        echo '<tr><th scope="row">Ebenen</th><td>';
        foreach (['hub1'=>'Hub Ebene 1','hub2'=>'Hub Ebene 2'] as $key => $label) {
            echo '<label style="display:block;margin:4px 0"><input type="checkbox" name="pftk_category_text[include_' . esc_attr($key) . ']" value="1" ' . checked($settings['include_' . $key], '1', false) . '> ' . esc_html($label) . '</label>';
        }
        echo '<p class="description">Startseite und Produkt-/Kategorieebene verwenden ihre verbindlichen Renderertexte und sind fuer diese Automatik gesperrt.</p>';
        echo '</td></tr>';
        echo '<tr><th scope="row">Synonymprofil</th><td><textarea class="large-text code" rows="12" name="pftk_category_text[synonym_map]">' . esc_textarea($settings['synonym_map']) . '</textarea><p class="description">Eine Zeile pro Thema: <code>Ausrüstung|Pferdebedarf, Reitzubehör, Ausstattung</code>. Technischer Kern bleibt allgemeingültig.</p></td></tr>';
        echo '</tbody></table>';
        submit_button('Einstellungen speichern');
        echo '</form>';
        echo '<hr><h2>Automatisch einpflegen</h2><div style="display:flex;gap:12px;flex-wrap:wrap">';
        echo '<button type="button" class="button button-primary pftk-generate-category-texts" data-mode="missing">Nur fehlende Texte erzeugen</button>';
        echo '<button type="button" class="button pftk-generate-category-texts" data-mode="refresh_auto">Automatisch erzeugte Texte aktualisieren</button>';
        echo '</div><div id="pftk-category-text-progress" style="display:none;max-width:760px;margin-top:14px"><div style="height:12px;background:#dcdcde;border-radius:8px;overflow:hidden"><div id="pftk-category-text-progress-bar" style="height:100%;width:0;background:#2271b1"></div></div><p id="pftk-category-text-progress-label">Vorbereitung …</p></div>';
        $ajax_nonce = wp_create_nonce('pftk_generate_category_text_batch');
        echo '<script>(function(){const buttons=document.querySelectorAll(".pftk-generate-category-texts");const box=document.getElementById("pftk-category-text-progress");const bar=document.getElementById("pftk-category-text-progress-bar");const label=document.getElementById("pftk-category-text-progress-label");let running=false;function setDisabled(v){buttons.forEach(b=>b.disabled=v)}async function run(mode,offset,changed){const body=new URLSearchParams({action:"pftk_generate_category_text_batch",nonce:' . wp_json_encode($ajax_nonce) . ',mode:mode,offset:String(offset),batch:"5"});const response=await fetch(ajaxurl,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"},body:body.toString()});const json=await response.json();if(!json.success){throw new Error((json.data&&json.data.message)||"Unbekannter Fehler")}const d=json.data;changed+=Number(d.changed||0);const pct=d.total>0?Math.round((Number(d.next_offset||0)/Number(d.total))*100):100;bar.style.width=pct+"%";label.textContent=pct+" % - "+changed+" Texte gespeichert oder aktualisiert";if(!d.done){return run(mode,Number(d.next_offset||0),changed)}label.textContent="Fertig: "+changed+" Texte gespeichert oder aktualisiert.";running=false;setDisabled(false);window.setTimeout(()=>window.location.reload(),700)}buttons.forEach(button=>button.addEventListener("click",function(){if(running)return;running=true;setDisabled(true);box.style.display="block";bar.style.width="0";label.textContent="Start …";run(this.dataset.mode,0,0).catch(error=>{running=false;setDisabled(false);label.textContent="Fehler: "+error.message})}))})();</script>';
        echo '<h2 style="margin-top:28px">Übersicht</h2><table class="widefat striped"><thead><tr><th>Seite</th><th>Ebene</th><th>Status</th><th>Text</th><th></th></tr></thead><tbody>';
        foreach ($pages as $entry) {
            $post = $entry['post']; $type = $entry['type'];
            $text = trim((string)get_post_meta($post->ID, self::META_CATEGORY_INTRO, true));
            $source = (string)get_post_meta($post->ID, self::META_CATEGORY_INTRO_SOURCE, true);
            $hidden = get_post_meta($post->ID, self::META_CATEGORY_INTRO_HIDDEN, true) === '1';
            $display_text = $text;
            $status = $hidden ? 'ausgeblendet' : ($text === '' ? 'fehlt' : ($source === 'manual' ? 'manuell' : 'automatisch gespeichert'));
            echo '<tr><td><strong>' . esc_html(get_the_title($post)) . '</strong></td><td>' . esc_html($type) . '</td><td>' . esc_html($status) . '</td><td>' . esc_html(wp_trim_words($display_text, 18, ' …')) . '</td><td><a href="' . esc_url(get_edit_post_link($post->ID)) . '">Bearbeiten</a></td></tr>';
        }
        echo '</tbody></table></div>';
    }

