    private static function global_card_title_colors() {
        $value = get_option('pftk_global_card_title_colors', self::default_global_card_title_colors());
        if (!is_array($value)) { $value = []; }
        return array_merge(self::default_global_card_title_colors(), $value);
    }

    public static function sanitize_global_card_title_colors($input) {
        $input = is_array($input) ? $input : [];
        $defaults = self::default_global_card_title_colors();
        $out = [];
        foreach ($defaults as $key => $default) {
            $out[$key] = sanitize_hex_color((string)($input[$key] ?? '')) ?: $default;
        }
        return $out;
    }

