    public static function sanitize_global_layout_settings($input) {
        $input = is_array($input) ? $input : [];
        $font_weight = (string)($input['intro_font_weight'] ?? '400');
        if (!in_array($font_weight, ['inherit','normal','100','200','300','400','500','600','700','800','900'], true)) { $font_weight = '400'; }
        $font_style_raw = (string)($input['intro_font_style'] ?? 'normal');
        $font_style = in_array($font_style_raw, ['normal','italic'], true) ? $font_style_raw : 'normal';
        $text_decoration_raw = (string)($input['intro_text_decoration'] ?? 'none');
        $text_decoration = in_array($text_decoration_raw, ['none','underline'], true) ? $text_decoration_raw : 'none';
        $text_align_raw = (string)($input['intro_text_align'] ?? 'left');
        $text_align = in_array($text_align_raw, ['left','center','right'], true) ? $text_align_raw : 'left';
        $line_height = (float)($input['intro_line_height'] ?? 1.7);
        if ($line_height < 1.0 || $line_height > 2.5) { $line_height = 1.7; }
        return [
            'main_block_top_gap' => (string)max(0, min(200, intval($input['main_block_top_gap'] ?? 30))),
            'content_width' => (string)max(760, min(1600, intval($input['content_width'] ?? 1200))),
            'content_axis_width' => (string)max(620, min(1400, intval($input['content_axis_width'] ?? 900))),
            'post_reading_width' => (string)max(620, min(1000, intval($input['post_reading_width'] ?? 760))),
            'breadcrumb_axis_width' => (string)max(620, min(1400, intval($input['breadcrumb_axis_width'] ?? 900))),
            'breadcrumb_title_gap' => (string)max(0, min(80, intval($input['breadcrumb_title_gap'] ?? 10))),
            'navigation_content_gap_desktop' => (string)max(0, min(160, intval($input['navigation_content_gap_desktop'] ?? 18))),
            'navigation_content_gap_tablet' => (string)max(0, min(160, intval($input['navigation_content_gap_tablet'] ?? 14))),
            'navigation_content_gap_mobile' => (string)max(0, min(40, intval($input['navigation_content_gap_mobile'] ?? 10))),
            'global_card_radius' => (string)max(0, min(40, intval($input['global_card_radius'] ?? 12))),
            'title_image_gap' => (string)max(0, min(80, intval($input['title_image_gap'] ?? 12))),
            'category_tile_font_family' => sanitize_text_field((string)($input['category_tile_font_family'] ?? 'inherit')) ?: 'inherit',
            'intro_max_width' => (string)max(320, min(1600, intval($input['intro_max_width'] ?? 740))),
            'intro_font_family' => sanitize_text_field((string)($input['intro_font_family'] ?? 'inherit')) ?: 'inherit',
            'intro_font_size' => (string)max(10, min(40, intval($input['intro_font_size'] ?? 17))),
            'intro_font_weight' => $font_weight,
            'intro_font_style' => $font_style,
            'intro_text_decoration' => $text_decoration,
            'intro_text_color' => sanitize_hex_color((string)($input['intro_text_color'] ?? '')) ?: '#2b2b2b',
            'intro_line_height' => (string)$line_height,
            'intro_text_align' => $text_align,
            'intro_margin_top' => (string)max(0, min(200, intval($input['intro_margin_top'] ?? 0))),
            'intro_margin_bottom' => (string)max(0, min(200, intval($input['intro_margin_bottom'] ?? 34))),
        ];
    }

