    public static function sanitize_start_selection($input) {
        $input = is_array($input) ? $input : [];
        $ids = isset($input['page_ids']) && is_array($input['page_ids']) ? $input['page_ids'] : [];
        $out = [];
        $front_id = intval(get_option('page_on_front'));
        foreach ($ids as $id) {
            $id = intval($id);
            if ($id <= 0 || $id === $front_id || isset($out[$id])) { continue; }
            $post = get_post($id);
            if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') { continue; }
            $out[$id] = $id;
            if (count($out) >= 8) { break; }
        }
        return ['configured' => '1', 'page_ids' => array_values($out)];
    }

    private static function start_selection() {
        $value = get_option(self::option_name('start', 'selection'), ['configured' => '0', 'page_ids' => []]);
        if (!is_array($value)) { $value = []; }
        return [
            'configured' => isset($value['configured']) && (string)$value['configured'] === '1' ? '1' : '0',
            'page_ids' => isset($value['page_ids']) && is_array($value['page_ids']) ? array_values(array_map('intval', $value['page_ids'])) : [],
        ];
    }

    public static function admin_assets($hook) {
        if (!is_string($hook) || strpos($hook, 'pferde-template-kit') === false) { return; }
        wp_enqueue_script('jquery-ui-autocomplete');
        wp_register_style('pftk-admin-autocomplete', false, [], self::VERSION);
        wp_enqueue_style('pftk-admin-autocomplete');
        wp_add_inline_style('pftk-admin-autocomplete', '.pftk-page-choice{display:grid;grid-template-columns:34px minmax(260px,620px) auto;gap:8px;align-items:center;margin:7px 0}.pftk-page-choice input[type=text]{width:100%}.pftk-page-choice .pftk-order{font-weight:700;text-align:center}.ui-autocomplete{z-index:100000!important;max-height:320px;overflow-y:auto;overflow-x:hidden;background:#fff;border:1px solid #8c8f94;padding:4px;box-shadow:0 3px 8px rgba(0,0,0,.15)}.ui-menu-item-wrapper{padding:7px 9px;cursor:pointer}.ui-state-active{background:#2271b1!important;color:#fff!important;border:0!important;margin:0!important}');
        $config = wp_json_encode([
            'url' => admin_url('admin-ajax.php'),
            'action' => 'pftk_search_published_pages',
            'nonce' => wp_create_nonce('pftk_search_published_pages'),
        ]);
        $script = <<<'PFTKJS'
jQuery(function($){
    var cfg=__PFTK_CONFIG__;
    $('.pftk-page-search').each(function(){
        var input=$(this),row=input.closest('.pftk-page-choice'),hidden=row.find('.pftk-page-id');
        input.on('input',function(){hidden.val('');});
        input.autocomplete({
            minLength:2,delay:180,
            source:function(req,res){$.getJSON(cfg.url,{action:cfg.action,nonce:cfg.nonce,term:req.term}).done(res);},
            select:function(e,ui){input.val(ui.item.label);hidden.val(ui.item.id);return false;},
            change:function(){if($.trim(input.val())===''){hidden.val('');}}
        });
    });
    $('.pftk-page-clear').on('click',function(){
        var row=$(this).closest('.pftk-page-choice');
        row.find('input').val('');
    });
});
PFTKJS;
        wp_add_inline_script('jquery-ui-autocomplete', str_replace('__PFTK_CONFIG__', $config, $script));
    }

    public static function ajax_search_published_pages() {
        if (!current_user_can('manage_options')) { wp_send_json_error(['message' => 'Keine Berechtigung.'], 403); }
        check_ajax_referer('pftk_search_published_pages', 'nonce');
        $term = sanitize_text_field(wp_unslash($_GET['term'] ?? ''));
        if (mb_strlen($term) < 2) { wp_send_json([]); }
        $front_id = intval(get_option('page_on_front'));
        $pages = get_posts([
            'post_type' => 'page',
            'post_status' => 'publish',
            'posts_per_page' => 20,
            's' => $term,
            'orderby' => 'title',
            'order' => 'ASC',
            'post__not_in' => $front_id > 0 ? [$front_id] : [],
            'no_found_rows' => true,
        ]);
        $out = [];
        foreach ($pages as $page) {
            if (!$page instanceof WP_Post) { continue; }
            $out[] = ['id' => intval($page->ID), 'label' => get_the_title($page) . ' (/' . $page->post_name . '/)', 'value' => get_the_title($page)];
        }
        wp_send_json($out);
    }

