    public static function sanitize_texts($type, $input) {
        $input = is_array($input) ? $input : [];
        $existing = self::opt($type, 'texts');
        $out = array_merge(self::default_texts($type), $existing);
        foreach ($input as $key => $value) {
            if (!array_key_exists($key, self::default_texts($type))) { continue; }
            $value = (string)$value;
            if (($type === 'start' && $key === 'hero_title') || strpos($key, '_body') !== false || strpos($key, '_lead') !== false || strpos($key, '_intro') !== false || strpos($key, '_text') !== false) {
                $out[$key] = sanitize_textarea_field($value);
            } else {
                $out[$key] = sanitize_text_field($value);
            }
        }
        return $out;
    }

    public static function sanitize_styles($type, $input) {
        $input = is_array($input) ? $input : [];
        $existing = self::opt($type, 'styles');
        $defaults = self::default_styles($type);
        $out = array_merge($defaults, $existing);
        foreach ($input as $key => $value) {
            if (!array_key_exists($key, $defaults)) { continue; }
            $default = $defaults[$key];
            $value = trim((string)$value);
            if (strpos($key, '_color') !== false) {
                $out[$key] = sanitize_hex_color($value) ?: $default;
            } elseif (strpos($key, '_size') !== false) {
                $out[$key] = (string)max(10, min(90, intval($value)));
            } elseif (strpos($key, '_margin_') !== false) {
                $out[$key] = (string)max(0, min(200, intval($value)));
            } elseif (strpos($key, '_weight') !== false) {
                $out[$key] = self::sanitize_font_weight($value);
            } elseif (strpos($key, '_font') !== false) {
                $out[$key] = self::sanitize_font($value);
            } else {
                $out[$key] = sanitize_text_field($value);
            }
        }
        return $out;
    }

    private static function sanitize_font($font) {
        $font = sanitize_text_field((string)$font);
        $font = preg_replace('/[^a-zA-Z0-9\s,\-\"\']/', '', $font);
        return trim($font) !== '' ? trim($font) : 'inherit';
    }

    private static function sanitize_font_weight($weight) {
        $weight = strtolower(trim(sanitize_text_field((string)$weight)));
        $allowed = ['inherit','normal','100','200','300','400','500','600','700','800','900'];
        return in_array($weight, $allowed, true) ? $weight : '400';
    }

    public static function sanitize_media($type, $input) {
        $input = is_array($input) ? $input : [];
        $defaults = self::default_media();
        $out = array_merge($defaults, self::opt($type, 'media'));
        foreach ($input as $key => $value) {
            if (!array_key_exists($key, $defaults)) { continue; }
            $default = $defaults[$key];
            $value = trim((string)$value);
            if (strpos($key, '_target') !== false) {
                $out[$key] = in_array($value, ['_self', '_blank'], true) ? $value : $default;
            } elseif (strpos($key, '_image') !== false || strpos($key, '_url') !== false) {
                $out[$key] = esc_url_raw($value);
            } else {
                $out[$key] = sanitize_text_field($value);
            }
        }
        return $out;
    }

    public static function sanitize_blocks($type, $input) {
        $input = is_array($input) ? $input : [];
        $defaults = self::default_blocks();
        $out = array_merge($defaults, self::opt($type, 'blocks'));
        foreach ($defaults as $key => $default) {
            if (strpos($key, 'show_') === 0 || $key === 'hub_grid_ad_active') {
                // Checkboxen werden durch ein verstecktes 0-Feld immer mitgesendet.
                if (array_key_exists($key, $input)) { $out[$key] = ((string)$input[$key] === '1') ? '1' : '0'; }
                continue;
            }
            if (!array_key_exists($key, $input)) { continue; }
            $value = trim((string)$input[$key]);
            if ($key === 'posts_selection_mode') {
                $allowed = ['strategic_span', 'score_first'];
                $out[$key] = in_array($value, $allowed, true) ? $value : 'strategic_span';
            } elseif ($key === 'hub_grid_mode') {
                $out[$key] = in_array($value, ['auto', 'five'], true) ? $value : 'auto';
            } elseif ($key === 'product_articles_limit') {
                $out[$key] = intval($value) >= 8 ? '8' : '4';
            } elseif ($key === 'topics_limit') {
                $out[$key] = (string)max(1, min(8, intval($value)));
            } elseif ($key === 'hub1_topics_limit') {
                $out[$key] = (string)max(1, min(5, intval($value)));
            } elseif ($key === 'hub2_topics_limit') {
                $out[$key] = (string)max(1, min(5, intval($value)));
            } else {
                $out[$key] = (string)max(1, min(4, intval($value)));
            }
        }
        return $out;
    }

    private static function opt($type, $part) {
        $value = get_option(self::option_name($type, $part), []);
        return is_array($value) ? $value : [];
    }

    private static function text($type, $key) {
        $values = self::opt($type, 'texts');
        $defaults = self::default_texts($type);
        if (isset($values[$key]) && trim((string)$values[$key]) !== '') { return trim((string)$values[$key]); }
        return $defaults[$key] ?? '';
    }

    private static function raw_text($type, $key) {
        $values = self::opt($type, 'texts');
        $defaults = self::default_texts($type);
        return isset($values[$key]) ? (string)$values[$key] : ($defaults[$key] ?? '');
    }

    private static function style($type, $key) {
        $values = self::opt($type, 'styles');
        $defaults = self::default_styles($type);
        if (isset($values[$key]) && trim((string)$values[$key]) !== '') { return trim((string)$values[$key]); }
        return $defaults[$key] ?? '';
    }

    private static function media($type, $key) {
        $values = self::opt($type, 'media');
        $defaults = self::default_media();
        if (isset($values[$key]) && trim((string)$values[$key]) !== '') { return trim((string)$values[$key]); }
        return $defaults[$key] ?? '';
    }

    private static function block($type, $key) {
        $values = self::opt($type, 'blocks');
        $defaults = self::default_blocks();
        if (isset($values[$key]) && trim((string)$values[$key]) !== '') { return trim((string)$values[$key]); }
        return $defaults[$key] ?? '';
    }

    private static function visible($type, $key) { return self::block($type, $key) === '1'; }

    /** Nur die Startseite darf einen Hero ausgeben. Hub 1/2 und Ebene 3 beginnen direkt mit Text bzw. Kacheln. */
    private static function should_render_hero($type) {
        return $type === 'start' && self::visible($type, 'show_hero');
    }

