    public static function settings_page($type) {
        if (!current_user_can('manage_options')) { return; }
        $templates = self::templates();
        if (empty($templates[$type])) { return; }
        $cfg = $templates[$type];
        $group = $cfg['prefix'] . '_settings';

        echo '<div class="wrap pftk-admin pftk-admin-v150312">';
        echo '<h1>Pferde Template Kit – ' . esc_html($cfg['label']) . '</h1>';
        echo '<p><strong>Shortcode:</strong> <code>' . esc_html($cfg['shortcode']) . '</code></p>';
        echo '<p>';
        foreach ($templates as $t => $c) {
            $url = admin_url('admin.php?page=' . $c['slug']);
            $style = $t === $type ? 'font-weight:700;text-decoration:underline;' : '';
            echo '<a style="margin-right:16px;' . esc_attr($style) . '" href="' . esc_url($url) . '">' . esc_html($c['label']) . '</a>';
        }
        echo '</p>';
        self::settings_backend_contract_summary_v150312($type);
        echo '<form method="post" action="options.php">';
        settings_fields($group);
        echo '<div class="pftk-admin-save-top" style="margin:14px 0 18px;padding:12px 14px;background:#fff;border:1px solid #ccd0d4;border-radius:6px;">';
        submit_button('Inhalte speichern', 'primary', 'submit', false);
        echo '</div>';

        if ($type === 'start') {
            self::settings_start_hero_v150174();
            self::settings_brand_content_v150312();
            self::settings_start_manual_topics();
            self::settings_start_intents_v150198();
        } elseif ($type === 'hub1') {
            self::settings_hub1_v150198();
        } elseif ($type === 'hub2') {
            self::settings_hub_automatic_topics($type);
            self::settings_hub_grid_status($type);
        } elseif ($type === 'category') {
            self::settings_category_automatic($type);
            self::settings_hub_grid_status($type);
        }

        submit_button('Inhalte speichern');
        echo '</form></div>';
    }

