    private static function render_shortcode_template($requested_type, $atts = []) {
        $allowed = ['start', 'hub1', 'hub2', 'category', 'leaf'];
        $requested_type = in_array($requested_type, $allowed, true) ? $requested_type : 'category';
        $resolved_type = $requested_type;

        // Auf echten Seiten entscheidet immer die reale Seitenstruktur. Alte oder
        // falsch hinterlegte Shortcodes duerfen keinen zweiten/falschen Seitentyp ausgeben.
        $blocked_wrong_shortcode = false;
        if (!is_admin() && is_singular('page')) {
            if (function_exists('is_front_page') && is_front_page()) {
                $resolved_type = 'start';
            } else {
                $current = self::current_page_as_menu_like_item();
                $actual = self::current_page_template_type($current);
                if (in_array($actual, $allowed, true)) {
                    $resolved_type = $actual;
                } elseif (in_array($requested_type, ['start','hub1','hub2'], true)) {
                    // Ein alter Start-/Hub-Shortcode darf auf einer nicht eindeutig
                    // erkannten Unterseite niemals den Startseiten- oder Hubaufbau zeigen.
                    $blocked_wrong_shortcode = true;
                }
            }
        }

        $debug = current_user_can('manage_options')
            ? '<!-- pftk-v' . esc_html(self::VERSION) . ' template_shortcode requested=' . esc_html($requested_type) . ' resolved=' . esc_html($resolved_type) . ' -->'
            : '';

        if ($blocked_wrong_shortcode) {
            return $debug . (current_user_can('manage_options') ? '<!-- pftk-v' . esc_html(self::VERSION) . ' template_shortcode blocked=wrong_page_type -->' : '');
        }

        // Ein Volltemplate darf pro Seitenaufruf nur einmal erscheinen.
        if (!empty(self::$rendered_types[$resolved_type])) {
            return $debug . (current_user_can('manage_options')
                ? '<!-- pftk-v' . esc_html(self::VERSION) . ' template_shortcode duplicate=blocked type=' . esc_html($resolved_type) . ' -->'
                : '');
        }

        // Der Kategorietext wird ab V1.50.13 direkt im einheitlichen
        // Portalcontainer gerendert. Dadurch ist seine Position auf allen
        // Ebenen und bei allen Ausgabewegen identisch.
        return $debug . self::render($resolved_type, $atts);
    }

    /**
     * V1.50.384 – Unterdrueckt Astras vorgelagertes Seitenbild in beiden
     * tatsaechlich verwendeten Astra-Pfaden. Der moderne Einzelansichtsrenderer
     * (Astra 4.4+) prueft astra_post_featured_image_condition; der aeltere Pfad
     * prueft astra_featured_image_enabled. Die Erkennung darf deshalb nicht von
     * is_singular() abhaengen, sondern folgt – wie Astras offizielle Schnittstelle –
     * dem realen Post-Typ und der stabilen WordPress-Seitenhierarchie.
     */
    public static function astra_portal_page_featured_image_v150385($enabled) {
        if (is_admin()) { return $enabled; }

        $candidate_ids = [];
        $the_id = absint(get_the_ID());
        if ($the_id > 0) { $candidate_ids[] = $the_id; }
        $queried_id = absint(get_queried_object_id());
        if ($queried_id > 0) { $candidate_ids[] = $queried_id; }
        global $post;
        if ($post instanceof WP_Post && absint($post->ID) > 0) { $candidate_ids[] = absint($post->ID); }

        foreach (array_values(array_unique($candidate_ids)) as $page_id) {
            if (get_post_type($page_id) !== 'page') { continue; }
            $page_type = self::page_type_for_id($page_id);
            if (in_array($page_type, ['hub2', 'category', 'leaf'], true)
                && self::portal_page_image_markup_v150383($page_id, $page_type) !== '') {
                return false;
            }
            $special_type = self::special_page_image_type_v150385($page_id);
            if ($special_type !== '' && self::special_page_image_markup_v150385($page_id, $special_type) !== '') {
                return false;
            }
        }
        return $enabled;
    }

    /**
     * Liefert fuer die drei freigegebenen WordPress-Seitenebenen ausschliesslich
     * die reale Full-Datei des zugewiesenen Seitenbildes. Es wird bewusst kein
     * wp_get_attachment_image() verwendet, damit weder eine Zwischenablage noch
     * srcset/sizes eine andere Datei auswaehlen kann.
     */
    private static function portal_page_image_markup_v150383($page_id, $expected_type) {
        static $cache = [];
        $page_id = absint($page_id);
        $expected_type = sanitize_key((string)$expected_type);
        $cache_key = $page_id . '|' . $expected_type;
        if (array_key_exists($cache_key, $cache)) { return $cache[$cache_key]; }
        $cache[$cache_key] = '';
        if ($page_id <= 0 || !in_array($expected_type, ['hub2', 'category', 'leaf'], true)) { return ''; }

        $page = get_post($page_id);
        if (!$page instanceof WP_Post || ($page->post_type ?? '') !== 'page') { return ''; }
        $current = self::menu_like_page_item($page_id);
        if (!$current || self::current_page_template_type($current) !== $expected_type) { return ''; }

        $attachment_id = absint(get_post_thumbnail_id($page_id));
        if ($attachment_id <= 0 || get_post_type($attachment_id) !== 'attachment' || !wp_attachment_is_image($attachment_id)) { return ''; }

        $full = wp_get_attachment_image_src($attachment_id, 'full');
        if (!is_array($full) || empty($full[0])) { return ''; }
        $src = (string)$full[0];
        $width = absint($full[1] ?? 0);
        $height = absint($full[2] ?? 0);
        if ($src === '' || $width <= 0 || $height <= 0) { return ''; }

        $alt = trim((string)get_post_meta($attachment_id, '_wp_attachment_image_alt', true));
        if ($alt === '') { $alt = trim((string)get_the_title($attachment_id)); }

        $cache[$cache_key] = '<img src="' . esc_url($src) . '" width="' . intval($width) . '" height="' . intval($height) . '" alt="' . esc_attr($alt) . '" class="pa383-portal-page-image-element" loading="eager" decoding="async" fetchpriority="high">';
        return $cache[$cache_key];
    }

    /**
     * Gemeinsamer, ausschliesslich innerhalb des aktiven Portalrenderers
     * ausgegebener Bildblock. Ohne gueltige Full-Datei entsteht keinerlei
     * Markup, CSS, Abstand oder Theme-Unterdrueckung.
     */
    private static function portal_page_image_block_v150383($page_id, $page_type) {
        $image = self::portal_page_image_markup_v150383($page_id, $page_type);
        if ($image === '') { return ''; }
        $attachment_id = absint(get_post_thumbnail_id($page_id));
