    /**
     * Ermittelt Sonderseiten ausschließlich aus dem tatsächlich gespeicherten
     * Seiteninhalt. Journal und Anzeigenmarkt benötigen deshalb weder feste IDs
     * noch eine bestimmte Position in der Seitenhierarchie.
     */
    private static function special_page_image_type_v150385($page_id) {
        $page_id = absint($page_id);
        if ($page_id <= 0) { return ''; }
        $page = get_post($page_id);
        if (!$page instanceof WP_Post || ($page->post_type ?? '') !== 'page') { return ''; }
        $content = (string)($page->post_content ?? '');
        if (has_shortcode($content, 'pferde_journal') || has_shortcode($content, 'affiliate_portal_journal')) { return 'journal'; }
        if (self::is_market_page_id_v150386($page_id)) { return 'market'; }
        return '';
    }

    /**
     * V1.50.386 – belastbare Anzeigenmarkt-Erkennung.
     *
     * Der bisherige Stand erkannte den Markt nur, wenn der Pferde-Intro-Shortcode
     * direkt im gespeicherten Seiteninhalt vorkam. Reale HivePress-Seiten koennen
     * jedoch ueber den eigenen Listings-Shortcode, einen wiederverwendbaren Block
     * oder die bestehende Seite /anzeigenmarkt/ laufen. Es werden deshalb nur
     * eindeutige positive Signale akzeptiert; Seitentitel oder unscharfe Begriffe
     * werden bewusst nicht ausgewertet.
     */
    private static function is_market_page_id_v150386($page_id) {
        $page_id = absint($page_id);
        if ($page_id <= 0) { return false; }
        $page = get_post($page_id);
        if (!$page instanceof WP_Post || ($page->post_type ?? '') !== 'page') { return false; }

        $content = (string)($page->post_content ?? '');
        foreach (['pferde_atelier_anzeigenmarkt_intro', 'hivepress_listings', 'hivepress_listings_view'] as $shortcode) {
            if (has_shortcode($content, $shortcode)) { return true; }
        }

        $slugs = self::market_page_slugs_v150387();
        $page_slug = sanitize_title((string)($page->post_name ?? ''));
        return $page_slug !== '' && in_array($page_slug, $slugs, true);
    }

    /**
     * V1.50.387 – zentrale Slugliste fuer den Anzeigenmarkt.
     *
     * Der reale Bestand nutzt je nach Projektstand die Slugs
     * /anzeigenmarkt/, /anzeigen/ oder /listings/. Die Liste wird zentral
     * normalisiert, damit Seiten- und Request-Erkennung identisch arbeiten.
     */
    private static function market_page_slugs_v150387() {
        $slugs = apply_filters('pftk_market_page_slugs_v150386', ['anzeigenmarkt', 'anzeigen', 'listings']);
        $slugs = is_array($slugs) ? array_values(array_filter(array_map('sanitize_title', $slugs))) : ['anzeigenmarkt', 'anzeigen', 'listings'];
        if (!$slugs) { $slugs = ['anzeigenmarkt', 'anzeigen', 'listings']; }
        return array_values(array_unique($slugs));
    }

    /** Normalisiert ausschließlich den aktuellen Request-Pfad ohne Query. */
    private static function current_request_path_v150387() {
        $uri = isset($_SERVER['REQUEST_URI']) ? (string)$_SERVER['REQUEST_URI'] : '';
        if ($uri === '') { return ''; }
        if (function_exists('wp_parse_url')) {
            $path = wp_parse_url($uri, PHP_URL_PATH);
        } else {
            $path = parse_url($uri, PHP_URL_PATH);
        }
        if (!is_string($path)) { return ''; }
        return trim($path, '/');
    }

    /**
     * V1.50.387 – ermittelt die reale Anzeigenmarkt-Seite auch dann,
     * wenn HivePress die Route nicht als is_singular('page') ausliefert.
     */
    private static function resolve_market_request_page_id_v150387() {
        $candidate_ids = [];
        $the_id = absint(get_the_ID());
        if ($the_id > 0) { $candidate_ids[] = $the_id; }
        $queried_id = absint(get_queried_object_id());
        if ($queried_id > 0) { $candidate_ids[] = $queried_id; }
        global $post;
        if ($post instanceof WP_Post && absint($post->ID) > 0) { $candidate_ids[] = absint($post->ID); }

        foreach (array_values(array_unique($candidate_ids)) as $page_id) {
            if (self::is_market_page_id_v150386($page_id)) { return $page_id; }
        }

        $request_path = self::current_request_path_v150387();
        if ($request_path === '' || !function_exists('get_page_by_path') || !function_exists('get_permalink')) { return 0; }

        foreach (self::market_page_slugs_v150387() as $slug) {
            $page = get_page_by_path($slug, OBJECT, 'page');
            if (!$page instanceof WP_Post || !self::is_market_page_id_v150386(absint($page->ID))) { continue; }
            $permalink = (string)get_permalink($page);
            if ($permalink === '') { continue; }
            if (function_exists('wp_parse_url')) {
                $page_path = wp_parse_url($permalink, PHP_URL_PATH);
            } else {
                $page_path = parse_url($permalink, PHP_URL_PATH);
            }
            $page_path = is_string($page_path) ? trim($page_path, '/') : '';
            if ($page_path !== '' && $page_path === $request_path) { return absint($page->ID); }
        }
        return 0;
    }

    /** Reale Full-Datei einer Journal-/Anzeigenmarkt-Seite, ohne srcset/sizes. */
    private static function special_page_image_markup_v150385($page_id, $expected_type) {
        static $cache = [];
        $page_id = absint($page_id);
        $expected_type = sanitize_key((string)$expected_type);
        $key = $page_id . '|' . $expected_type;
        if (array_key_exists($key, $cache)) { return $cache[$key]; }
        $cache[$key] = '';
        if (!in_array($expected_type, ['journal', 'market'], true)
            || self::special_page_image_type_v150385($page_id) !== $expected_type) { return ''; }
        $attachment_id = absint(get_post_thumbnail_id($page_id));
        $cache[$key] = self::full_attachment_image_markup_v150385($attachment_id, 'pa385-leading-page-image-element');
        return $cache[$key];
    }

    /** Gemeinsame fail-closed Full-Datei-Ausgabe ohne WordPress-srcset. */
    private static function full_attachment_image_markup_v150385($attachment_id, $class) {
        $attachment_id = absint($attachment_id);
        if ($attachment_id <= 0 || get_post_type($attachment_id) !== 'attachment' || !wp_attachment_is_image($attachment_id)) { return ''; }
        $full = wp_get_attachment_image_src($attachment_id, 'full');
        if (!is_array($full) || empty($full[0])) { return ''; }
        $src = (string)$full[0];
        $width = absint($full[1] ?? 0);
        $height = absint($full[2] ?? 0);
        if ($src === '' || $width <= 0 || $height <= 0) { return ''; }
        $alt = trim((string)get_post_meta($attachment_id, '_wp_attachment_image_alt', true));
        if ($alt === '') { $alt = trim((string)get_the_title($attachment_id)); }
        return '<img src="' . esc_url($src) . '" width="' . intval($width) . '" height="' . intval($height) . '" alt="' . esc_attr($alt) . '" class="' . esc_attr($class) . '" loading="eager" decoding="async" fetchpriority="high">';
    }

    /**
     * Einheitlicher Bildblock für Sonderseiten und Standard-Taxonomiearchive.
     * Der vorhandene Inhaltscontainer begrenzt die Breite; das Originalformat
     * bleibt über width:100% und height:auto erhalten.
     */
    private static function leading_image_block_v150385($image, $context, $attachment_id) {
        if ($image === '') { return ''; }
        $context = sanitize_key((string)$context);
        return '<style id="pa385-leading-image-css">'
            . '.pa385-leading-image{display:block!important;position:static!important;box-sizing:border-box!important;width:100%!important;max-width:100%!important;height:auto!important;min-height:0!important;max-height:none!important;aspect-ratio:auto!important;margin:0 0 24px!important;margin-left:0!important;margin-right:0!important;padding:0!important;overflow:visible!important;background:transparent!important;transform:none!important}'
            . '.pa385-leading-image>img{display:block!important;position:static!important;width:100%!important;max-width:100%!important;height:auto!important;min-width:0!important;min-height:0!important;max-height:none!important;aspect-ratio:auto!important;object-fit:initial!important;object-position:initial!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;box-shadow:none!important;transform:none!important}'
            . '@media(max-width:620px){.pa385-leading-image{margin-bottom:20px!important}}'
            . '</style><figure class="pa385-leading-image pa385-leading-image-' . esc_attr($context) . '" data-pa385-leading-image="' . intval($attachment_id) . '" data-pa385-context="' . esc_attr($context) . '">' . $image . '</figure>';
    }

    private static function special_page_image_block_v150385($page_id, $type) {
        $render_key = 'page|' . absint($page_id) . '|' . sanitize_key((string)$type);
        if (!empty(self::$leading_image_rendered_v150385[$render_key])) { return ''; }
        $image = self::special_page_image_markup_v150385($page_id, $type);
        if ($image === '') { return ''; }
        self::$leading_image_rendered_v150385[$render_key] = true;
        return self::leading_image_block_v150385($image, $type, get_post_thumbnail_id($page_id));
    }


    /**
     * V1.50.386 – eigenstaendiger Anzeigenmarkt-Bildrenderer am Astra-Hook.
     * Der Render-Schluessel verhindert eine zweite Ausgabe im bestehenden
     * Intro-Shortcode. Ohne gueltige Full-Datei entsteht keinerlei Markup.
     */
    public static function render_market_page_image_v150386() {
        if (is_admin()) { return; }
        $page_id = self::resolve_market_request_page_id_v150387();
        if ($page_id <= 0 || self::special_page_image_type_v150385($page_id) !== 'market') { return; }
        $block = self::special_page_image_block_v150385($page_id, 'market');
        if ($block === '') { return; }
        echo '<div class="pa386-market-image-axis">' . $block . '</div>';
    }

    /** Liest den von der Bildzentrale nur konfigurierten HivePress-Schlüssel read-only. */
    private static function term_image_meta_key_v150385($term) {
        if (!is_object($term)) { return ''; }
        $taxonomy = sanitize_key((string)($term->taxonomy ?? ''));
        if ($taxonomy === 'category') { return 'thumbnail_id'; }
        $config = get_option('pabz_taxonomy_image_config_v1', []);
        if (!is_array($config)) { return ''; }
        $configured_taxonomy = sanitize_key((string)($config['hivepress_taxonomy'] ?? ''));
        $configured_key = sanitize_key((string)($config['hivepress_image_meta_key'] ?? ''));
        return ($taxonomy !== '' && $taxonomy === $configured_taxonomy && $configured_key !== '') ? $configured_key : '';
    }

    private static function term_archive_image_data_v150385($term) {
        if (!is_object($term) || empty($term->term_id) || empty($term->taxonomy)) { return []; }
        $meta_key = self::term_image_meta_key_v150385($term);
        if ($meta_key === '') { return []; }
        $attachment_id = absint(get_term_meta(absint($term->term_id), $meta_key, true));
        $image = self::full_attachment_image_markup_v150385($attachment_id, 'pa385-leading-term-image-element');
        return $image === '' ? [] : ['attachment_id' => $attachment_id, 'image' => $image, 'taxonomy' => sanitize_key((string)$term->taxonomy)];
    }

    /**
     * Standard-WordPress- und konfigurierte HivePress-Taxonomiearchive werden
     * am offiziellen Astra-Hook innerhalb von #primary ausgegeben. Der separate
     * Portal-Leaf-Renderer bleibt alleiniger Besitzer seines Bildes.
     */
    public static function render_term_archive_image_v150385() {
        if (is_admin() || (!is_category() && !is_tax())) { return; }
        $term = get_queried_object();
        if (!is_object($term)) { return; }
        if ((string)($term->taxonomy ?? '') === 'category' && self::is_portal_leaf_category_v150273(absint($term->term_id ?? 0))) { return; }
        $data = self::term_archive_image_data_v150385($term);
        if (!$data) { return; }
        $key = 'term|' . sanitize_key((string)$data['taxonomy']) . '|' . absint($term->term_id);
        if (!empty(self::$leading_image_rendered_v150385[$key])) { return; }
        self::$leading_image_rendered_v150385[$key] = true;
        echo '<div class="pa385-term-image-axis">' . self::leading_image_block_v150385($data['image'], 'term-' . $data['taxonomy'], $data['attachment_id']) . '</div>';
    }


    /**
     * V1.50.405: Scope fuer die privaten HivePress-Anzeigen. Erkannt wird bewusst
     * der reale Taxonomie-Unterbaum statt einer eBay-/Import-Kennung, damit auch
     * manuell eingestellte private Anzeigen in allen Unterkategorien identisch sind.
     */
    private static function private_listing_archive_scope_v150397($term) {
        if (!is_object($term) || empty($term->term_id) || empty($term->taxonomy)) { return false; }
        $root_slug = sanitize_title((string)apply_filters('pftk_private_listing_root_slug_v150397', 'private-anzeigen'));
        $taxonomy = sanitize_key((string)$term->taxonomy);
        $listing_taxonomy = sanitize_key((string)apply_filters('pftk_private_listing_taxonomy_v150397', 'hp_listing_category'));
        if ($root_slug === '' || $listing_taxonomy === '' || $taxonomy !== $listing_taxonomy) { return false; }
        if (sanitize_title((string)($term->slug ?? '')) === $root_slug) { return true; }
        foreach ((array)get_ancestors(absint($term->term_id), $taxonomy, 'taxonomy') as $ancestor_id) {
            $ancestor = get_term(absint($ancestor_id), $taxonomy);
            if (!$ancestor || is_wp_error($ancestor)) { continue; }
            if (sanitize_title((string)($ancestor->slug ?? '')) === $root_slug) { return true; }
        }
        return false;
    }

    public static function print_private_listing_image_css_v150397() {
        if (is_admin()) { return; }
        echo '<style id="pftk-private-listing-images-v150397">'
            . 'body.pftk-private-listing-scope-v150397 .hp-listing--view-block .hp-listing__image{'
            . 'box-sizing:border-box!important;border:1px solid #35422A!important;background:#fff!important;overflow:hidden!important;box-shadow:none!important;}'
            . 'body.pftk-private-listing-scope-v150397 .hp-listing--view-block .hp-listing__image>a,'
            . 'body.pftk-private-listing-scope-v150397 .hp-listing--view-block .hp-listing__image picture,'
            . 'body.pftk-private-listing-scope-v150397 .hp-listing--view-block .hp-listing__image img{'
            . 'background:#fff!important;box-shadow:none!important;}'
            . '</style>';
    }

    /** V1.50.420 – ausschließlich die acht per Term-ID konfigurierten Journal-Kategorien. */
    private static function journal_category_image_gap_scope_v150420($term) {
        if (!is_object($term) || (string)($term->taxonomy ?? '') !== 'category') { return false; }
        $term_id = absint($term->term_id ?? 0);
        if ($term_id <= 0) { return false; }
        foreach (self::journal_category_config() as $settings) {
            if ($term_id === absint($settings['term_id'] ?? 0)) { return true; }
        }
        return false;
    }

    public static function portal_body_classes($classes) {
        $classes = is_array($classes) ? $classes : [];
        if (is_admin()) { return $classes; }
        $classes[] = 'pftk-redesign-v15065';
        $classes[] = 'pftk-design-profile-' . self::design_profile();
        $classes[] = 'pftk-design-contract-v' . str_replace('.', '-', self::design_profile_contract_version());
        if (is_category() || is_tax()) {
            $term = get_queried_object();
            if (self::private_listing_archive_scope_v150397($term)) { $classes[] = 'pftk-private-listing-scope-v150397'; }
            if (self::term_archive_image_data_v150385($term)) {
                $classes[] = 'pftk-has-leading-term-image-v150385';
                if (is_category() && self::journal_category_image_gap_scope_v150420($term)) {
                    $classes[] = 'pftk-journal-category-image-gap-v150420';
                }
            }
            return array_values(array_unique($classes));
        }
        if (!is_singular('page')) {
            $market_page_id = self::resolve_market_request_page_id_v150387();
            if ($market_page_id > 0 && self::special_page_image_markup_v150385($market_page_id, 'market') !== '') {
                $classes[] = 'pftk-has-leading-page-image-v150385';
            }
            return array_values(array_unique($classes));
        }
        $page_id = absint(get_queried_object_id());
        $type = $page_id > 0 ? self::page_type_for_id($page_id) : '';
        $special_type = $page_id > 0 ? self::special_page_image_type_v150385($page_id) : '';
        if (($special_type !== '' && self::special_page_image_markup_v150385($page_id, $special_type) !== '')
            || (in_array($type, ['hub2','category','leaf'], true) && self::portal_page_image_markup_v150383($page_id, $type) !== '')) {
            $classes[] = 'pftk-has-leading-page-image-v150385';
        }
        if (!in_array($type, ['start','hub1','hub2','category'], true)) { return array_values(array_unique($classes)); }
        $classes[] = 'pftk-portal-page';
        $classes[] = 'pftk-portal-' . $type;
        if ($type === 'hub1' && self::hub1_is_pilot_v150210($page_id)) {
            $classes[] = 'pftk-hub1-pilot-v150210';
        }
        if (self::category_intro_layout_enabled($page_id, $type)) {
            $classes[] = 'pftk-has-page-intro';
        }
        $shortline = trim((string)get_post_meta($page_id, self::META_PAGE_SHORTLINE, true));
        if ($shortline !== '' && get_post_meta($page_id, self::META_PAGE_SHORTLINE_HIDDEN, true) !== '1') {
            $classes[] = 'pftk-has-page-shortline';
        }
        return array_values(array_unique($classes));
    }

