    private static function journal_category_row($term, $settings) {
        if (!$term || is_wp_error($term) || empty($term->term_id)) { return null; }
        $url = get_term_link($term, 'category');
        if (is_wp_error($url)) { return null; }
        $description = trim(wp_strip_all_tags((string)term_description($term, 'category')));
        if ($description === '') { $description = (string)($settings['fallback'] ?? 'Wissen und Beiträge aus diesem Journal-Bereich.'); }
        return [
            'term' => $term,
            'url' => $url,
            'description' => $description,
            'color' => (string)($settings['color'] ?? '#5e665f'),
            'icon' => (string)($settings['icon'] ?? 'horse'),
            'config_key' => (string)($settings['config_key'] ?? ''),
        ];
    }

    /**
     * Löst ausschließlich die acht verbindlichen Term-IDs auf. Es gibt keinen
     * Fallback über Namen, Slugs, Navigation, Beiträge oder gespeicherte Altwerte.
     */
    private static function journal_resolved_categories($config, &$missing, &$source) {
        $missing = [];
        $rows = [];
        $resolved_ids = [];

        foreach ((array)$config as $config_key => $settings) {
            $term_id = absint($settings['term_id'] ?? 0);
            if ($term_id <= 0 || !function_exists('get_term')) {
                $missing[] = (string)$term_id;
                continue;
            }

            $term = get_term($term_id, 'category');
            if (!$term || is_wp_error($term) || absint($term->term_id ?? 0) !== $term_id) {
                $missing[] = (string)$term_id;
                continue;
            }

            $settings['config_key'] = (string)$config_key;
            $row = self::journal_category_row($term, $settings);
            if (!$row) {
                $missing[] = $term_id . ':link';
                continue;
            }

            $rows[] = $row;
            $resolved_ids[] = $term_id;
        }

        $source = count($rows) === count($config)
            ? 'fixed-wordpress-category-ids'
            : 'partial-fixed-wordpress-category-ids';

        self::$journal_resolution_meta = [
            'contract_count' => count($config),
            'taxonomy_terms' => 0,
            'resolved_ids' => $resolved_ids,
            'missing' => $missing,
            'ambiguous' => [],
            'seed_post_id' => 0,
        ];

        return $rows;
    }

