    private static function journal_affiliate_content_is_real_v150369($candidate) {
        if (!self::hub1_product_content_is_real_v150214($candidate)) { return false; }
        $plain = strtolower(trim(wp_strip_all_tags((string)$candidate)));
        $legacy_placeholders = [
            'ausgewählte empfehlung',
            'fachbuch und nachschlagewerk',
            'praxisnaher kurs',
            'hilfreiches arbeitsmaterial',
            'beim anbieter ansehen',
            'vertiefendes wissen für pferdehalter und reiter',
            'ausgewählte lernangebote passend zu den journalthemen',
            'checklisten, vorlagen und praktische orientierung',
        ];
        foreach ($legacy_placeholders as $marker) {
            if ($plain !== '' && strpos($plain, $marker) !== false) { return false; }
        }
        return true;
    }

    private static function journal_affiliate_slot($slot) {
        $slot = sanitize_key((string)$slot);
        if ($slot === '' || !function_exists('shortcode_exists') || !shortcode_exists('pp_affiliate_slot')) { return ''; }
        $out = do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]');
        if (!self::journal_affiliate_content_is_real_v150369($out)) { return ''; }
        return '<aside class="pftk-journal-affiliate pftk-curve" data-pftk-journal-affiliate="' . esc_attr($slot) . '">' . $out . '</aside>';
    }

    /**
     * V1.50.46: Eine feste neunte Werbekachel direkt im 3x3-Journalraster.
     * Echte Kampagnen bzw. der zentrale Bildplatzhalter der Affiliate-Zentrale
     * haben Vorrang. Ohne Provider-Ausgabe bleibt eine neutrale graue, textfreie
     * Reservierungsflaeche bestehen.
     */
    private static function journal_grid_affiliate_card() {
        $data = self::hub_grid_affiliate_data('hub2', 1, 'journal_grid');
        if (empty($data['valid'])) {
            $data = self::structural_ad_placeholder_data('hub2', 1, 'journal_grid');
        }

        $is_placeholder = self::affiliate_data_is_placeholder($data);
        $image = esc_url_raw((string)($data['image'] ?? ''));
        $url = esc_url_raw((string)($data['url'] ?? ''));
        $target = in_array((string)($data['target'] ?? '_self'), ['_self', '_blank'], true) ? (string)$data['target'] : '_self';
        $source = sanitize_key((string)($data['source'] ?? 'journal-grid-placeholder')) ?: 'journal-grid-placeholder';
        $visual = $image !== ''
            ? '<span class="pftk-journal-affiliate-visual"><img src="' . esc_url($image) . '" alt="" loading="lazy"></span>'
            : '<span class="pftk-journal-affiliate-reserved" aria-hidden="true"></span>';
        $attrs = ' class="pftk-journal-category-card pftk-journal-affiliate-card pftk-curve" data-pftk-journal-affiliate-grid="1" data-pftk-affiliate-source="' . esc_attr($source) . '" data-pftk-placeholder="' . ($is_placeholder ? '1' : '0') . '" aria-label="' . esc_attr($is_placeholder ? 'Werbeplatz' : 'Anzeige') . '" style="--pftk-journal-color:#a7a7a7;--pftk-accent:#a7a7a7"';

        if ($url !== '' && $image !== '') {
            $rel = $is_placeholder
                ? ($target === '_blank' ? ' rel="noopener noreferrer"' : '')
                : ($target === '_blank' ? ' rel="sponsored nofollow noopener noreferrer"' : ' rel="sponsored nofollow"');
            return '<a' . $attrs . ' href="' . esc_url($url) . '" target="' . esc_attr($target) . '"' . $rel . '>' . $visual . '</a>';
        }
        return '<div' . $attrs . '>' . $visual . '</div>';
    }

    private static function journal_post_category($post_id, $categories) {
        $by_id = [];
        foreach ((array)$categories as $row) {
            $term_id = absint($row['term']->term_id ?? 0);
            if ($term_id > 0) { $by_id[$term_id] = $row; }
        }
        if (function_exists('wp_get_post_categories')) {
            $post_terms = wp_get_post_categories($post_id, ['fields' => 'all']);
        } elseif (function_exists('wp_get_object_terms')) {
            $post_terms = wp_get_object_terms($post_id, 'category', ['fields' => 'all']);
        } else {
            $post_terms = get_the_category($post_id);
        }
        if (is_wp_error($post_terms)) { $post_terms = []; }
        foreach ((array)$post_terms as $term) {
            $term_id = absint($term->term_id ?? 0);
            if ($term_id > 0 && isset($by_id[$term_id])) { return [$term, $by_id[$term_id]]; }
        }
        return [null, ['color' => '#5e665f', 'icon' => 'horse']];
    }


    /**
     * V1.50.279 – kompakter oberer Designbereich für die HivePress-Anzeigenübersicht.
     * Der Intro-Shortcode enthält nur Kopf, Aktionen und einen schmalen Partnerbanner.
     * Der direkt vermietbare Werbeplatz wird separat weiter unten eingesetzt.
     */
    /**
     * V1.50.337 – Ein befüllter Anzeigenmarkt-Partnerbanner muss eine echte
     * grafische oder netzwerkseitige Creative-Ausgabe enthalten. Reine Texte,
     * Debugausgaben und Platzhalter gelten nicht als Befüllung.
     */
    private static function anzeigenmarkt_partner_banner_is_real_v150337($candidate) {
        $candidate = trim((string)$candidate);
        if ($candidate === '') { return false; }
        if (strpos($candidate, 'pftk-affiliate-placeholder-v15072') !== false
            || strpos($candidate, 'pftk-affiliate-slot-debug') !== false
            || strpos($candidate, 'data-pftk-placeholder="1"') !== false) {
            return false;
        }
        $lower = strtolower($candidate);
        $has_visual = strpos($lower, '<img') !== false
            || strpos($lower, '<picture') !== false
            || strpos($lower, '<video') !== false
            || strpos($lower, '<svg') !== false;
        $has_widget = strpos($lower, '<iframe') !== false
            || strpos($lower, '<script') !== false
            || strpos($lower, 'data-affiliate') !== false;
        return $has_visual || $has_widget;
    }

