    private static function journal_post_cards_v150280($query, $categories, $class = 'pftk-journal-post-grid-v150280') {
        if (!$query instanceof WP_Query || !$query->have_posts()) { return ''; }
        $post_total = count((array)$query->posts);
        $out = '<div class="' . esc_attr($class) . '" data-count="' . esc_attr((string)$post_total) . '">';
        while ($query->have_posts()) {
            $query->the_post();
            $post_id = absint(get_the_ID());
            [$post_term, $post_settings] = self::journal_post_category($post_id, $categories);
            $excerpt = trim(wp_strip_all_tags((string)get_the_excerpt($post_id)));
            if ($excerpt === '') {
                $post_obj = get_post($post_id);
                $excerpt = $post_obj ? wp_trim_words(wp_strip_all_tags((string)$post_obj->post_content), 24, ' …') : '';
            }
            $url = get_permalink($post_id);
            $out .= '<article class="pftk-journal-post-card-v150280">';
            $out .= '<a class="pftk-journal-post-image-v150280" href="' . esc_url($url) . '">';
            if (has_post_thumbnail($post_id)) {
                $out .= get_the_post_thumbnail($post_id, 'medium_large', ['loading' => 'lazy', 'alt' => get_the_title($post_id)]);
            } else {
                $out .= '<span aria-hidden="true">' . self::journal_icon_svg((string)($post_settings['icon'] ?? 'horse')) . '</span>';
            }
            $out .= '</a><div class="pftk-journal-post-copy-v150280">';
            if ($post_term) { $out .= '<span class="pftk-journal-post-meta-v150280">' . esc_html((string)$post_term->name) . '</span>'; }
            $out .= '<h3><a href="' . esc_url($url) . '">' . esc_html(get_the_title($post_id)) . '</a></h3>';
            if ($excerpt !== '') { $out .= '<p>' . esc_html($excerpt) . '</p>'; }
            $out .= '<a class="pftk-journal-button-v150280" href="' . esc_url($url) . '">Weiterlesen</a></div></article>';
        }
        $out .= '</div>';
        wp_reset_postdata();
        return $out;
    }

    private static function journal_admin_preview_allowed_v150370() {
        return function_exists('current_user_can') && current_user_can('manage_options');
    }

    private static function journal_module_heading_v150371($kicker, $title, $id) {
        return '<header class="pftk-journal-module-heading-v150371" style="display:block!important;visibility:visible!important;opacity:1!important" data-pftk-journal-module-heading="1">'
            . '<span>' . esc_html((string)$kicker) . '</span>'
            . '<h2 id="' . esc_attr((string)$id) . '">' . esc_html((string)$title) . '</h2>'
            . '</header>';
    }

    private static function journal_partner_banner_v150280() {
        $real = self::journal_affiliate_slot('journal_banner');
        $preview = false;
        if ($real === '') {
            if (!self::journal_admin_preview_allowed_v150370()) { return ''; }
            $preview = true;
            $real = '<div class="pftk-journal-admin-banner-preview-v150370" role="status">'
                . '<span>Administratorvorschau</span><strong>Partnerbanner</strong>'
                . '<p>Noch kein reales Banner für den Slot <code>journal_banner</code> zugeordnet.</p></div>';
        }
        return '<section class="pftk-journal-partner-section-v150368' . ($preview ? ' is-admin-preview' : '') . '" aria-labelledby="pftk-journal-partner-title-v150371">'
            . self::journal_module_heading_v150371('Ausgewählter Partner', 'Partner im Journal', 'pftk-journal-partner-title-v150371')
            . '<div class="pftk-journal-banner-v150280" aria-label="Werbung">' . $real . '</div>'
            . '</section>';
    }

    private static function journal_recommendation_slot_v150280($index) {
        $index = max(1, min(3, intval($index)));
        $slot = 'journal_product_' . $index;
        $candidate = '';
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            $candidate = (string)do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]');
        }
        if (self::journal_affiliate_content_is_real_v150369($candidate)) {
            return '<div class="pftk-journal-recommendation-v150280 is-real" data-pftk-slot="' . esc_attr($slot) . '">' . $candidate . '</div>';
        }
        if (!self::journal_admin_preview_allowed_v150370()) { return ''; }
        return '<div class="pftk-journal-recommendation-v150280 is-admin-preview" data-pftk-slot="' . esc_attr($slot) . '">'
            . '<span>Administratorvorschau</span><h3>Produktplatz ' . esc_html((string)$index) . '</h3>'
            . '<p>Noch kein reales Produkt zugeordnet.</p><b>Nicht öffentlich sichtbar</b></div>';
    }

