<script id="pftk-journal-tablet-enforcer-v150371">
(function(){
  var rootSelector='.pftk-journal-v150371';
  function set(el,prop,val){if(el)el.style.setProperty(prop,val,'important');}
  function clear(el,props){if(!el)return;props.forEach(function(p){el.style.removeProperty(p);});}
  function apply(){
    var width=Math.max(document.documentElement.clientWidth||0,window.innerWidth||0);
    var tablet=width>=621&&width<=1100;
    var mobile=width<=620;
    document.querySelectorAll(rootSelector+' .pftk-journal-post-grid-v150280').forEach(function(grid){
      var cards=Array.prototype.filter.call(grid.children,function(el){return el.classList&&el.classList.contains('pftk-journal-post-card-v150280');});
      if(tablet||mobile){
        set(grid,'display','grid');set(grid,'grid-template-columns','minmax(0,1fr)');set(grid,'grid-auto-flow','row');set(grid,'width','100%');
      }else{
        clear(grid,['display','grid-template-columns','grid-auto-flow','width']);
      }
      cards.forEach(function(card){
        var image=card.querySelector('.pftk-journal-post-image-v150280');
        if(tablet){
          set(card,'display','grid');set(card,'grid-template-columns','minmax(220px,32%) minmax(0,1fr)');set(card,'grid-template-rows','minmax(220px,auto)');set(card,'min-height','220px');set(card,'height','auto');set(card,'width','100%');
          set(image,'height','100%');set(image,'min-height','220px');
        }else if(mobile){
          set(card,'display','flex');set(card,'flex-direction','column');set(card,'min-height','0');set(card,'height','auto');set(card,'width','100%');
          set(image,'height','205px');set(image,'min-height','0');
        }else{
          clear(card,['display','grid-template-columns','grid-template-rows','flex-direction','min-height','height','width']);
          clear(image,['height','min-height']);
        }
      });
    });
    document.querySelectorAll(rootSelector+' .pftk-journal-module-heading-v150371').forEach(function(h){set(h,'display','block');set(h,'visibility','visible');set(h,'opacity','1');});
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',apply);}else{apply();}
  window.addEventListener('load',apply,{once:true});
  window.addEventListener('resize',apply,{passive:true});
  setTimeout(apply,100);setTimeout(apply,500);
  if(window.MutationObserver){new MutationObserver(apply).observe(document.documentElement,{childList:true,subtree:true});}
})();
</script>
