    public static function journal_shortcode($atts = []) {
        $atts = shortcode_atts(['posts' => 6], is_array($atts) ? $atts : [], 'pferde_journal');
        $post_count = max(3, min(12, absint($atts['posts'] ?? 6)));
        $config = self::journal_category_config();
        $missing = [];
        $category_source = '';
        $categories = self::journal_resolved_categories($config, $missing, $category_source);
        $term_ids = array_values(array_filter(array_map(static function($row) { return absint($row['term']->term_id ?? 0); }, $categories)));

        $latest_query = null;
        $featured_query = null;
        $latest_ids = [];
        if (!empty($term_ids) && class_exists('WP_Query')) {
            $latest_query = new WP_Query([
                'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => $post_count,
                'category__in' => $term_ids, 'ignore_sticky_posts' => true, 'no_found_rows' => true,
            ]);
            $latest_ids = wp_list_pluck((array)$latest_query->posts, 'ID');
            $featured_query = new WP_Query([
                'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => 3,
                'category__in' => $term_ids, 'post__not_in' => array_map('absint', $latest_ids),
                'orderby' => 'comment_count', 'order' => 'DESC', 'ignore_sticky_posts' => true, 'no_found_rows' => true,
            ]);
        }

        $product_slots = [];
        for ($i = 1; $i <= 3; $i++) {
            $slot_html = self::journal_recommendation_slot_v150280($i);
            if ($slot_html !== '') { $product_slots[] = $slot_html; }
        }

        ob_start();
        echo '<div class="pftk pftk-journal-v150280 pftk-journal-v150368 pftk-journal-v150369 pftk-journal-v150370 pftk-journal-v150371" data-pftk-journal-version="' . esc_attr(self::VERSION) . '">';
        echo self::journal_inline_system_css_v150371();
        $journal_page_id = absint(get_queried_object_id());
        echo self::special_page_image_block_v150385($journal_page_id, 'journal');
        echo '<section class="pftk-journal-hero-v150280"><div class="pftk-journal-kicker-v150280"><i></i><span>Wissen, das Pferde besser verstehen lässt</span><i></i></div><h1>Pferde Journal</h1><p>Im Pferde Journal findest du verständliches Wissen rund um Pferd und Reiter. Es geht um Verhalten, Haltung, Gesundheit, Ernährung und Ausbildung. Die Beiträge sind praxisnah, seriös und klar gegliedert.</p></section>';

        echo '<section class="pftk-journal-section-v150280" aria-labelledby="pftk-journal-categories-v150280"><header><span>Wissensbereiche</span><h2 id="pftk-journal-categories-v150280">Themen im Pferde Journal</h2></header>';
        if (!empty($categories)) {
            echo '<div class="pftk-journal-category-grid-v150280">';
            foreach ($categories as $row) {
                $term = $row['term'];
                echo '<a class="pftk-journal-category-card-v150280" href="' . esc_url($row['url']) . '"><span class="pftk-journal-category-icon-v150280">' . self::journal_icon_svg($row['icon']) . '</span><span class="pftk-journal-category-copy-v150280"><strong>' . esc_html((string)$term->name) . '</strong><span>' . esc_html($row['description']) . '</span><b>Entdecken</b></span></a>';
            }
            echo '</div>';
        } else {
            echo '<p class="pftk-journal-empty-v150280">Die Journal-Kategorien konnten noch nicht aufgelöst werden.</p>';
        }
        echo '</section>';

        echo '<section class="pftk-journal-section-v150280" aria-labelledby="pftk-journal-latest-v150280"><header><span>Frisch veröffentlicht</span><h2 id="pftk-journal-latest-v150280">Neu im Journal</h2><p>Aktuelle Beiträge mit verständlichem Wissen für Pferdehalter und Reiter.</p></header>';
        $latest_html = $latest_query instanceof WP_Query ? self::journal_post_cards_v150280($latest_query, $categories) : '';
        echo $latest_html !== '' ? $latest_html : '<p class="pftk-journal-empty-v150280">Neue Journalbeiträge erscheinen hier automatisch.</p>';
        echo '</section>';

        $partner_html = self::journal_partner_banner_v150280();
        if ($partner_html !== '') { echo $partner_html; }

        if ($featured_query instanceof WP_Query && $featured_query->have_posts()) {
