    public static function brand_menu_preview_items_v15069($items, $args) {
        if (!is_object($args) || (string)($args->menu_class ?? '') !== 'pftk-brand-menu-v15065') { return $items; }
        $items = array_values((array)$items);
        $by_id = [];
        $children = [];
        foreach ($items as $item) {
            $id = intval($item->ID ?? 0);
            $parent = intval($item->menu_item_parent ?? 0);
            if ($id <= 0) { continue; }
            $by_id[$id] = $item;
            $children[$parent][] = $item;
        }
        $depth_cache = [];
        $depth_of = static function ($id) use (&$depth_of, &$depth_cache, $by_id) {
            $id = intval($id);
            if ($id <= 0 || !isset($by_id[$id])) { return 0; }
            if (isset($depth_cache[$id])) { return $depth_cache[$id]; }
            $depth = 0; $seen = [];
            $parent = intval($by_id[$id]->menu_item_parent ?? 0);
            while ($parent > 0 && isset($by_id[$parent]) && empty($seen[$parent])) {
                $seen[$parent] = true; $depth++; $parent = intval($by_id[$parent]->menu_item_parent ?? 0);
            }
            return $depth_cache[$id] = $depth;
        };
        $remove = [];
        $synthetic = [];
        $synthetic_id = -15074000;
        foreach ($items as $parent_item) {
            $parent_id = intval($parent_item->ID ?? 0);
            if ($parent_id <= 0 || $depth_of($parent_id) !== 1) { continue; }
            $parent_url = trim((string)($parent_item->url ?? ''));
            if ($parent_url === '' || $parent_url === '#') { continue; }
            $direct = array_values((array)($children[$parent_id] ?? []));
            // V1.50.122: Der Sammellink ist nur sinnvoll, wenn nach den fünf
            // sichtbaren Vorschaukategorien tatsächlich weitere Kategorien existieren.
            if (count($direct) <= 5) { continue; }
            foreach (array_slice($direct, 5) as $hidden_item) { $remove[intval($hidden_item->ID ?? 0)] = true; }
            $all = clone $parent_item;
            $all->ID = $synthetic_id--;
            $all->db_id = $all->ID;
            $all->menu_item_parent = (string)$parent_id;
            $all->object_id = 0;
            $all->title = 'Alle Kategorien anzeigen';
            $all->url = $parent_url;
            $all->target = '';
            $all->attr_title = 'Alle Kategorien unter ' . wp_strip_all_tags((string)($parent_item->title ?? '')) . ' anzeigen';
            $all->description = '';
            $all->classes = ['pftk-mega-all-v15074'];
            $all->xfn = '';
            $all->type = 'custom';
            $all->object = 'custom';
            $all->status = 'publish';
            $synthetic[$parent_id] = $all;
        }
        $out = [];
        $inserted = [];
        foreach ($items as $item) {
            $id = intval($item->ID ?? 0);
            if (!empty($remove[$id])) { continue; }
            $out[] = $item;
            $parent_id = intval($item->menu_item_parent ?? 0);
            if ($parent_id > 0 && isset($synthetic[$parent_id])) {
                $direct = array_values((array)($children[$parent_id] ?? []));
                $kept = array_slice($direct, 0, 5);
                $last_id = !empty($kept) ? intval(end($kept)->ID ?? 0) : 0;
                if ($id === $last_id) { $out[] = $synthetic[$parent_id]; $inserted[$parent_id] = true; }
            }
            if (isset($synthetic[$id]) && empty($children[$id])) { $out[] = $synthetic[$id]; $inserted[$id] = true; }
        }
        foreach ($synthetic as $parent_id => $all) {
            if (empty($inserted[$parent_id])) { $out[] = $all; }
        }
        return array_values($out);
    }

    public static function brand_menu_remove_hivepress_account_v150114($items, $args) {
        if (!is_object($args) || !in_array((string)($args->menu_class ?? ''), ['pftk-brand-menu-v15065','pftk-mobile-menu-v15074'], true)) { return $items; }
        $items = array_values((array)$items);
        $remove = [];
        foreach ($items as $item) {
            $id = intval($item->ID ?? 0);
            $classes = array_map('strval', (array)($item->classes ?? []));
            $url = trim((string)($item->url ?? ''));
            $path = (string)wp_parse_url($url, PHP_URL_PATH);
            $is_account = in_array('menu-item--user-account', $classes, true)
                || in_array('hp-menu__item--user-account', $classes, true)
                || preg_match('~/(?:account|user-account)(?:/|$)~i', $path);
            if ($is_account && $id !== 0) { $remove[$id] = true; }
        }
        do {
            $changed = false;
            foreach ($items as $item) {
                $id = intval($item->ID ?? 0);
                $parent = intval($item->menu_item_parent ?? 0);
                if ($id !== 0 && $parent !== 0 && !empty($remove[$parent]) && empty($remove[$id])) {
                    $remove[$id] = true;
                    $changed = true;
                }
            }
        } while ($changed);
        return array_values(array_filter($items, static function ($item) use ($remove) {
            return empty($remove[intval($item->ID ?? 0)]);
        }));
    }

    /**
     * V1.50.408: Nur das manuell gerenderte Headerformular darf die gruppierte
     * AJAX-Ausgabe aktivieren. Andere Relevanssi-Live-Suchen bleiben unangetastet.
     */
    private static function is_header_live_search_request_v150408() {
        $action = isset($_REQUEST['action']) ? sanitize_key(wp_unslash((string)$_REQUEST['action'])) : '';
        $marker = isset($_REQUEST['pftk_header_search']) ? sanitize_text_field(wp_unslash((string)$_REQUEST['pftk_header_search'])) : '';
        return $action === 'relevanssi_live_search' && $marker === '1';
    }

    /**
     * V1.50.408: Eigenes Ergebnis-Template ausschliesslich fuer die globale
     * Header-Live-Suche. Relevanssi bleibt Suchmaschine und AJAX-Transport.
     */
    public static function header_search_results_template_v150408($template, $config = '') {
        if (!self::is_header_live_search_request_v150408()) { return $template; }
        $candidate = plugin_dir_path(__FILE__) . 'templates/search-results-pftk-v150408.php';
        return is_readable($candidate) ? $candidate : $template;
    }


    /**
     * V1.50.413: Belastbarer Endpunkt fuer die Header-Live-Suche. Relevanssi
     * Live Ajax Search ruft die Template-Funktion nach der eigentlichen Query
     * auf; fremde Live-Suchformulare behalten ihren bisherigen Renderer.
     */
    public static function header_search_template_function_v150413($template_function) {
        if (!self::is_header_live_search_request_v150408()) { return $template_function; }
        return 'pftk_render_grouped_live_search_v150413';
    }

    /**
     * Oeffentliche, durchsuchbare Portal-Inhaltstypen. HivePress-Modelle und
     * Attachments werden fuer die PORTAL-Gruppe bewusst ausgeschlossen.
     */
    private static function portal_search_post_types_v150408() {
        $types = [];
        foreach ((array)get_post_types(['public' => true], 'objects') as $name => $object) {
            $name = sanitize_key((string)$name);
            if ($name === '' || $name === 'attachment' || $name === 'hp_listing' || strpos($name, 'hp_') === 0) { continue; }
            if (is_object($object) && !empty($object->exclude_from_search)) { continue; }
            $types[] = $name;
        }
        if (!$types) { $types = ['post', 'page']; }
        return array_values(array_unique(apply_filters('pftk_portal_search_post_types_v150408', $types)));
    }

    /**
     * Vollstaendige Portalsuche hinter "Alle Portalergebnisse ansehen". Die
     * Taxonomie "category" bleibt als Relevanssi-Premium-Ergebnis moeglich,
     * waehrend hp_listing und andere HivePress-Modelle ausgeschlossen bleiben.
     */
    public static function portal_search_scope_v150408($query) {
        if (is_admin() || !is_object($query) || !method_exists($query, 'is_main_query') || !$query->is_main_query() || !$query->is_search()) { return; }
        $scope = isset($_GET['pftk_scope']) ? sanitize_key(wp_unslash((string)$_GET['pftk_scope'])) : '';
        if ($scope !== 'portal') { return; }
        $types = self::portal_search_post_types_v150408();
        // Relevanssi Premium repraesentiert indexierte Kategorien als Ergebnisobjekte
        // mit post_type "category". Ohne Relevanssi ignoriert WP diesen Typ einfach.
        $types[] = 'category';
        $types = array_values(array_unique($types));
        $query->set('post_type', $types);
        $query->set('post_types', $types); // Relevanssi-spezifisch, u. a. fuer Seiten/Taxonomietreffer.
        $query->set('post_status', 'publish');
    }

    /**
     * Fuehrt eine getrennte Suchabfrage ueber denselben Relevanssi-Kern aus.
     * Nur wenn Relevanssi selbst nicht verfuegbar ist, greift WordPress als
     * funktionaler Fallback. Es wird keine parallele Suchmaschine eingefuehrt.
     */
    private static function grouped_search_query_v150408($search, $post_types, $limit = 5) {
        $search = trim((string)$search);
        if ($search === '') { return []; }
        $limit = max(1, min(50, absint($limit)));
        $args = [
            's' => $search,
            'posts_per_page' => $limit,
            'post_status' => 'publish',
            'ignore_sticky_posts' => true,
            'no_found_rows' => true,
        ];
        if (is_array($post_types) && $post_types) { $post_types = array_values(array_unique($post_types)); $args['post_type'] = $post_types; $args['post_types'] = $post_types; }

        if (function_exists('relevanssi_do_query')) {
            $query = new WP_Query();
            $query->parse_query($args);
            relevanssi_do_query($query);
            return is_array($query->posts ?? null) ? $query->posts : [];
        }
        $query = new WP_Query($args);
        return is_array($query->posts ?? null) ? $query->posts : [];
    }

    private static function grouped_result_url_v150408($item) {
        if (!is_object($item)) { return ''; }
        foreach (['relevanssi_link', 'link'] as $key) {
            if (!empty($item->{$key}) && is_string($item->{$key})) { return (string)$item->{$key}; }
        }
        if (!empty($item->term_id) && !empty($item->taxonomy)) {
            $url = get_term_link(absint($item->term_id), sanitize_key((string)$item->taxonomy));
            return is_wp_error($url) ? '' : (string)$url;
        }
        if (!empty($item->ID) && intval($item->ID) > 0) {
            $url = get_permalink(absint($item->ID));
            return $url ? (string)$url : '';
        }
        return '';
    }

    private static function grouped_result_title_v150408($item) {
        if (!is_object($item)) { return ''; }
        if (isset($item->post_title)) { return trim(wp_strip_all_tags((string)$item->post_title)); }
        if (isset($item->name)) { return trim(wp_strip_all_tags((string)$item->name)); }
        return '';
    }

    private static function grouped_result_key_v150408($item) {
        if (!is_object($item)) { return ''; }
        $type = sanitize_key((string)($item->post_type ?? $item->taxonomy ?? ''));
        $id = isset($item->term_id) ? absint($item->term_id) : absint($item->ID ?? 0);
        $url = self::grouped_result_url_v150408($item);
        return $type . '|' . $id . '|' . $url;
    }

    private static function grouped_filter_results_v150408($items, $group, $limit = 5) {
        $out = [];
        $seen = [];
        $portal_types = array_flip(self::portal_search_post_types_v150408());
        foreach ((array)$items as $item) {
            if (!is_object($item)) { continue; }
            $type = sanitize_key((string)($item->post_type ?? $item->taxonomy ?? ''));
            $is_listing = $type === 'hp_listing';
            if ($group === 'anzeigen') {
                if (!$is_listing) { continue; }
            } else {
                if ($is_listing || strpos($type, 'hp_') === 0 || $type === 'attachment') { continue; }
                // Kategorie-Treffer nur dann zeigen, wenn die bestehende Relevanssi-
                // Konfiguration sie tatsaechlich geliefert hat. Andere fremde
                // Pseudo-Objekte (z. B. Benutzer) werden nicht in PORTAL gemischt.
                if ($type !== 'category' && !isset($portal_types[$type])) { continue; }
            }
            $title = self::grouped_result_title_v150408($item);
            $url = self::grouped_result_url_v150408($item);
            if ($title === '' || $url === '') { continue; }
            $key = self::grouped_result_key_v150408($item);
            if ($key === '' || isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $out[] = $item;
            if (count($out) >= $limit) { break; }
        }
        return $out;
    }

    private static function render_grouped_result_rows_v150408($items, $label) {
        $first = true;
        foreach ((array)$items as $item) {
            $title = self::grouped_result_title_v150408($item);
            $url = self::grouped_result_url_v150408($item);
            if ($title === '' || $url === '') { continue; }
            $classes = 'relevanssi-live-search-result pftk-grouped-search-result-v150408';
            if ($first) { $classes .= ' pftk-grouped-search-first-v150408'; }
            echo '<div class="' . esc_attr($classes) . '">';
            if ($first) { echo '<div class="pftk-grouped-search-label-v150408">' . esc_html($label) . '</div>'; }
            echo '<p><a href="' . esc_url($url) . '">' . esc_html($title) . '</a></p></div>';
            $first = false;
        }
    }

    private static function render_grouped_more_row_v150408($label, $url) {
        echo '<div class="relevanssi-live-search-result pftk-grouped-search-more-v150408"><p><a href="' . esc_url($url) . '">' . esc_html($label) . '</a></p></div>';
    }

    /**
     * Sichtbare Live-Ausgabe: maximal 5 Anzeigen und 5 Portal-Ergebnisse. Beide
     * Gruppen werden unabhaengig ueber Relevanssi abgefragt und leer komplett
     * ausgeblendet.
     */
    public static function render_grouped_live_search_v150408($original_query = null) {
        $search = isset($_REQUEST['rlvquery']) ? sanitize_text_field(wp_unslash((string)$_REQUEST['rlvquery'])) : '';
        if ($search === '' && isset($_REQUEST['s'])) { $search = sanitize_text_field(wp_unslash((string)$_REQUEST['s'])); }
        $search = trim($search);
        echo '<div class="relevanssi-live-search-results pftk-grouped-live-search-v150408" role="listbox">';
        if ($search === '') {
            echo '<div class="relevanssi-live-search-result-status"><p>Keine Ergebnisse gefunden.</p></div></div>';
            return;
        }

        $anzeigen_raw = self::grouped_search_query_v150408($search, ['hp_listing'], 12);
        $anzeigen = self::grouped_filter_results_v150408($anzeigen_raw, 'anzeigen', 5);

        $portal_types = self::portal_search_post_types_v150408();
        $portal_query_types = array_values(array_unique(array_merge($portal_types, ['category'])));
        $portal_raw = self::grouped_search_query_v150408($search, $portal_query_types, 18);
        $portal = self::grouped_filter_results_v150408($portal_raw, 'portal', 5);

        // Falls die installierte Relevanssi-Konfiguration Kategorieobjekte nur in
        // der urspruenglichen Live-Abfrage liefert, koennen sie fehlende Portal-
        // Plaetze ergaenzen. Vorhandene Portal-Treffer bleiben vorn und eindeutig.
        if (count($portal) < 5 && is_object($original_query) && is_array($original_query->posts ?? null)) {
            $fallback = self::grouped_filter_results_v150408($original_query->posts, 'portal', 10);
            $seen = [];
            foreach ($portal as $item) { $seen[self::grouped_result_key_v150408($item)] = true; }
            foreach ($fallback as $item) {
                $key = self::grouped_result_key_v150408($item);
                if ($key === '' || isset($seen[$key])) { continue; }
                $portal[] = $item;
                $seen[$key] = true;
                if (count($portal) >= 5) { break; }
            }
        }

        if (!$anzeigen && !$portal) {
            echo '<div class="relevanssi-live-search-result-status"><p>Keine Ergebnisse gefunden.</p></div></div>';
            return;
        }

        if ($anzeigen) {
            self::render_grouped_result_rows_v150408($anzeigen, 'ANZEIGEN');
            $all_ads = add_query_arg(['s' => $search], home_url('/anzeigenmarkt/'));
            self::render_grouped_more_row_v150408('Alle Anzeigen ansehen', $all_ads);
        }
        if ($portal) {
            self::render_grouped_result_rows_v150408($portal, 'PORTAL');
            $all_portal = add_query_arg(['s' => $search, 'pftk_scope' => 'portal'], home_url('/'));
            self::render_grouped_more_row_v150408('Alle Portalergebnisse ansehen', $all_portal);
        }
        echo '</div>';
    }

