            . '#pftk-brand-live-results-v150297 .pftk-grouped-search-result-v150408 p{margin:0!important;padding:6px 14px 10px!important;line-height:1.35!important}'
            . '#pftk-brand-live-results-v150297 .pftk-grouped-search-result-v150408:not(.pftk-grouped-search-first-v150408) p{padding-top:10px!important}'
