    /**
     * V1.50.414: Nativer Query-Fallback fuer den eng gescopten Header-Suchpfad.
     * suppress_filters verhindert, dass Relevanssi einen bewusst nativen
     * HivePress-Fallback erneut ueber seinen Indexumfang begrenzt.
     */
    private static function direct_search_query_v150414($search, $post_type, $limit = 10) {
        $search = trim((string)$search);
        $post_type = sanitize_key((string)$post_type);
        if ($search === '' || $post_type === '') { return []; }
        $query = new WP_Query([
            's' => $search,
            'post_type' => $post_type,
            'posts_per_page' => max(1, min(50, absint($limit))),
            'post_status' => 'publish',
            'ignore_sticky_posts' => true,
            'no_found_rows' => true,
            'suppress_filters' => true,
        ]);
        return is_array($query->posts ?? null) ? $query->posts : [];
    }

    /** Relevanssi zuerst, native Treffer nur zum Auffuellen bzw. als Index-Fallback. */
    private static function merged_post_type_results_v150414($search, $post_type, $limit = 5) {
        $post_type = sanitize_key((string)$post_type);
        $limit = max(1, min(20, absint($limit)));
        if ($post_type === '') { return []; }
        $primary = self::grouped_search_query_v150408($search, [$post_type], max(10, $limit * 2));
        $native = self::direct_search_query_v150414($search, $post_type, max(10, $limit * 2));
        $out = []; $seen = [];
        foreach (array_merge((array)$primary, (array)$native) as $item) {
            if (!is_object($item) || sanitize_key((string)($item->post_type ?? '')) !== $post_type) { continue; }
            $title = self::grouped_result_title_v150408($item);
            $url = self::grouped_result_url_v150408($item);
            if ($title === '' || $url === '') { continue; }
            $key = $post_type . '|' . absint($item->ID ?? 0) . '|' . $url;
            if (isset($seen[$key])) { continue; }
            $seen[$key] = true; $out[] = $item;
            if (count($out) >= $limit) { break; }
        }
        return $out;
    }

    private static function header_search_category_results_v150414($search, $limit = 5) {
        $limit = max(1, min(10, absint($limit)));
        $out = []; $seen = [];

        // Echte WordPress-Kategorien zuerst: Sie sind die inhaltlichen Leaf-Ziele
        // des Portals. Hoehere Portal-Hierarchieseiten fuellen danach freie Plaetze.
        if (function_exists('get_terms')) {
            $terms = get_terms([
                'taxonomy' => 'category',
                'hide_empty' => false,
                'search' => trim((string)$search),
                'number' => max(10, $limit * 3),
            ]);
            if (!is_wp_error($terms)) {
                foreach ((array)$terms as $term) {
                    if (!is_object($term) || empty($term->term_id)) { continue; }
                    $title = trim(wp_strip_all_tags((string)($term->name ?? '')));
                    $url = get_term_link(absint($term->term_id), 'category');
                    if ($title === '' || is_wp_error($url) || !$url) { continue; }
                    $url = (string)$url; $key = strtolower($url);
                    if (isset($seen[$key])) { continue; }
                    $seen[$key] = true;
                    $out[] = ['title' => $title, 'url' => $url, 'kind' => 'category'];
                    if (count($out) >= $limit) { return $out; }
                }
            }
        }

        // Portal-Hierarchieseiten sind fuer Besucher ebenfalls Kategorien/Themen,
        // werden aber nie als technische "Seiten" beschriftet.
        foreach (self::merged_post_type_results_v150414($search, 'page', $limit * 2) as $item) {
            $title = self::grouped_result_title_v150408($item);
            $url = self::grouped_result_url_v150408($item);
            $key = strtolower($url);
            if ($title === '' || $url === '' || isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $out[] = ['title' => $title, 'url' => $url, 'kind' => 'page'];
            if (count($out) >= $limit) { break; }
        }
        return $out;
    }

    private static function header_search_post_results_v150414($search, $post_type, $limit = 5) {
        $out = [];
        foreach (self::merged_post_type_results_v150414($search, $post_type, $limit) as $item) {
            $title = self::grouped_result_title_v150408($item);
            $url = self::grouped_result_url_v150408($item);
            if ($title === '' || $url === '') { continue; }
            $out[] = ['title' => $title, 'url' => $url, 'kind' => sanitize_key((string)$post_type)];
        }
        return $out;
    }

    /**
     * V1.50.417: Eng gescopter Fuzzy-Fallback nur fuer HivePress-Anzeigen im
     * globalen Header. Er dient ausschliesslich dazu, kleine Tippfehler wie
     * "regendeckel" -> "Regendecke/Regendecken" abzufangen, ohne Relevanssi-
     * Einstellungen oder andere Suchformulare zu veraendern.
     */
    private static function header_search_normalize_v150417($value) {
        $value = trim((string)$value);
        if ($value === '') { return ''; }
        if (function_exists('remove_accents')) { $value = remove_accents($value); }
        $value = function_exists('mb_strtolower') ? mb_strtolower($value, 'UTF-8') : strtolower($value);
        $value = preg_replace('/[^a-z0-9]+/u', ' ', $value);
        return trim(preg_replace('/\s+/', ' ', (string)$value));
    }

    private static function header_search_longest_token_v150417($value) {
        $normalized = self::header_search_normalize_v150417($value);
        if ($normalized === '') { return ''; }
        $tokens = preg_split('/\s+/', $normalized, -1, PREG_SPLIT_NO_EMPTY);
        $best = '';
        foreach ((array)$tokens as $token) {
            if (strlen($token) > strlen($best)) { $best = $token; }
        }
        return $best;
    }

    private static function header_search_fuzzy_score_v150417($search, $candidate) {
        $needle = self::header_search_longest_token_v150417($search);
        $haystack = self::header_search_normalize_v150417($candidate);
        if ($needle === '' || $haystack === '' || strlen($needle) < 4) { return 0; }
        if ($needle === $haystack) { return 120; }
        if (strpos($haystack, $needle) !== false) { return 115; }

        $tokens = preg_split('/\s+/', $haystack, -1, PREG_SPLIT_NO_EMPTY);
        $best = 0;
        foreach ((array)$tokens as $token) {
            if ($token === $needle) { return 120; }
            if (strlen($token) >= 4 && (strpos($token, $needle) !== false || strpos($needle, $token) !== false)) {
                $short = min(strlen($token), strlen($needle));
                if ($short >= 5) { $best = max($best, 108); }
            }
            if (strlen($token) < 5) { continue; }
            $distance = levenshtein($needle, $token);
            $allowed = strlen($needle) >= 9 ? 2 : 1;
            if ($distance <= $allowed) { $best = max($best, 100 - ($distance * 5)); }
        }
        return $best;
    }

    private static function header_search_listing_fuzzy_title_candidates_v150417($search, $limit = 24) {
        global $wpdb;
        $limit = max(1, min(40, absint($limit)));
        $token = self::header_search_longest_token_v150417($search);
        if (strlen($token) < 4 || !is_object($wpdb) || empty($wpdb->posts)
            || !method_exists($wpdb, 'prepare') || !method_exists($wpdb, 'get_results')) { return []; }

        // Der DB-Pool nutzt sowohl den originalen Unicode-Anfang als auch die
        // akzentbereinigte Form. Damit funktionieren z. B. "Führstrik" und
        // "fuhrstrik" unabhaengig von der konkreten MySQL-Collation.
        $raw = trim((string)$search);
        $raw = function_exists('mb_strtolower') ? mb_strtolower($raw, 'UTF-8') : strtolower($raw);
        $raw = trim(preg_replace('/[^\p{L}\p{N}]+/u', ' ', $raw));
        $raw_tokens = preg_split('/\s+/', $raw, -1, PREG_SPLIT_NO_EMPTY);
        $raw_token = '';
        foreach ((array)$raw_tokens as $candidate) {
            $candidate_len = function_exists('mb_strlen') ? mb_strlen($candidate, 'UTF-8') : strlen($candidate);
            $current_len = function_exists('mb_strlen') ? mb_strlen($raw_token, 'UTF-8') : strlen($raw_token);
            if ($candidate_len > $current_len) { $raw_token = $candidate; }
        }
        $raw_prefix = function_exists('mb_substr') ? mb_substr($raw_token, 0, 5, 'UTF-8') : substr($raw_token, 0, 5);
        $norm_prefix = substr($token, 0, min(5, strlen($token)));
        if (method_exists($wpdb, 'esc_like')) {
            $raw_prefix = $wpdb->esc_like($raw_prefix);
            $norm_prefix = $wpdb->esc_like($norm_prefix);
        } else {
            $raw_prefix = addcslashes($raw_prefix, '_%\\');
            $norm_prefix = addcslashes($norm_prefix, '_%\\');
        }
        $raw_like = '%' . $raw_prefix . '%';
        $norm_like = '%' . $norm_prefix . '%';
        $sql = $wpdb->prepare(
            "SELECT ID, post_title, post_type FROM {$wpdb->posts} WHERE post_type = %s AND post_status = 'publish' AND (post_title LIKE %s OR post_title LIKE %s) ORDER BY post_date DESC LIMIT %d",
            'hp_listing', $raw_like, $norm_like, $limit
        );
        $rows = $wpdb->get_results($sql);
        $scored = [];
        foreach ((array)$rows as $row) {
            if (!is_object($row)) { continue; }
            $row->post_type = 'hp_listing';
            $score = self::header_search_fuzzy_score_v150417($search, (string)($row->post_title ?? ''));
            if ($score < 95) { continue; }
            $scored[] = ['score' => $score, 'item' => $row];
        }
        usort($scored, static function($a, $b){ return intval($b['score']) <=> intval($a['score']); });
        return array_values(array_map(static function($row){ return $row['item']; }, $scored));
    }

    private static function header_search_listing_fuzzy_terms_v150417($search, $limit = 8) {
        if (!function_exists('get_terms')) { return []; }
        $taxonomy = 'hp_listing_category';
        $terms = get_terms(['taxonomy' => $taxonomy, 'hide_empty' => true, 'number' => 0]);
        if (is_wp_error($terms) || !$terms) { return []; }
        $scored = [];
        foreach ((array)$terms as $term) {
            if (!is_object($term) || empty($term->term_id)) { continue; }
            $candidate = trim((string)($term->name ?? '') . ' ' . (string)($term->slug ?? ''));
            $score = self::header_search_fuzzy_score_v150417($search, $candidate);
            if ($score < 95) { continue; }
            $scored[] = ['score' => $score, 'term_id' => absint($term->term_id)];
        }
        usort($scored, static function($a, $b){ return intval($b['score']) <=> intval($a['score']); });
        $ids = [];
        foreach ($scored as $row) {
            $id = absint($row['term_id']);
            if ($id > 0 && !in_array($id, $ids, true)) { $ids[] = $id; }
            if (count($ids) >= max(1, min(20, absint($limit)))) { break; }
        }
        return $ids;
    }

    private static function header_search_listing_results_v150417($search, $limit = 5) {
        $limit = max(1, min(10, absint($limit)));
        $out = []; $seen = [];
        $append = static function($item) use (&$out, &$seen, $limit) {
            if (!is_object($item) || sanitize_key((string)($item->post_type ?? '')) !== 'hp_listing') { return; }
            $title = Pferde_Template_Kit::grouped_result_title_v150408($item);
            $url = Pferde_Template_Kit::grouped_result_url_v150408($item);
            if ($title === '' || $url === '') { return; }
            $key = absint($item->ID ?? 0) . '|' . strtolower($url);
            if (isset($seen[$key]) || count($out) >= $limit) { return; }
            $seen[$key] = true;
            $out[] = ['title' => $title, 'url' => $url, 'kind' => 'hp_listing'];
        };

        // 1. Bestehende Relevanssi/native Direkttreffer behalten immer Prioritaet.
        foreach (self::merged_post_type_results_v150414($search, 'hp_listing', $limit * 2) as $item) { $append($item); }

        // 2. Tippfehler in konkreten Anzeigentiteln: enger Prefix-Pool + Fuzzy-Score.
        if (count($out) < $limit) {
            foreach (self::header_search_listing_fuzzy_title_candidates_v150417($search, 24) as $item) { $append($item); }
        }

        // 3. Tippfehler/Pluralformen in HivePress-Kategorien, anschliessend echte
        //    veroeffentlichte Listings aus genau diesen Kategorien.
        if (count($out) < $limit) {
            $term_ids = self::header_search_listing_fuzzy_terms_v150417($search, 8);
            if ($term_ids) {
                $query = new WP_Query([
                    'post_type' => 'hp_listing',
                    'posts_per_page' => max(10, $limit * 3),
                    'post_status' => 'publish',
                    'ignore_sticky_posts' => true,
                    'no_found_rows' => true,
                    'suppress_filters' => true,
                    'tax_query' => [[
                        'taxonomy' => 'hp_listing_category',
                        'field' => 'term_id',
                        'terms' => $term_ids,
                        'include_children' => true,
                        'operator' => 'IN',
                    ]],
                ]);
                foreach ((array)($query->posts ?? []) as $item) { $append($item); }
            }
        }
        return $out;
    }

    private static function header_search_render_group_v150414($items, $label, $group) {
        $items = array_values(array_filter((array)$items, static function($item){
            return is_array($item) && trim((string)($item['title'] ?? '')) !== '' && trim((string)($item['url'] ?? '')) !== '';
        }));
        if (!$items) { return; }
        echo '<section class="pftk-header-search-group-v150414" data-pftk-search-group="' . esc_attr($group) . '">';
        echo '<div class="pftk-header-search-label-v150414">' . esc_html($label) . '</div>';
        foreach ($items as $item) {
            echo '<div class="relevanssi-live-search-result pftk-header-search-result-v150414"><p><a href="' . esc_url($item['url']) . '">' . esc_html($item['title']) . '</a></p></div>';
        }
        echo '</section>';
    }

    /**
     * V1.50.417: Header-Suche auf dem live bewaehrten V1.50.414-Transport; ANZEIGEN erhalten nur einen eng gescopten Tippfehler-Fallback. Ergebniswelten:
     * ANZEIGEN = hp_listing, KATEGORIEN = Portal-Hierarchieseiten + WP-Kategorien,
     * BEITRAEGE = normale WordPress-Beitraege. Maximal fuenf je Gruppe.
     */
    /** Testbarer Renderer fuer den exakt gescopten Header-Suchpfad. */
    public static function header_search_html_v150414($search) {
        $search = trim(sanitize_text_field((string)$search));
        if (function_exists('mb_substr')) { $search = mb_substr($search, 0, 80); }
        else { $search = substr($search, 0, 80); }
        if ($search === '' || strlen($search) < 2) { return ''; }

        $ads = self::header_search_listing_results_v150417($search, 5);
        $categories = self::header_search_category_results_v150414($search, 5);
        $posts = self::header_search_post_results_v150414($search, 'post', 5);

        ob_start();
        echo '<div class="relevanssi-live-search-results pftk-header-search-results-v150414" role="listbox">';
        if (!$ads && !$categories && !$posts) {
            echo '<div class="relevanssi-live-search-result-status"><p>Keine Ergebnisse gefunden.</p></div>';
        } else {
            self::header_search_render_group_v150414($ads, 'ANZEIGEN', 'anzeigen');
            self::header_search_render_group_v150414($categories, 'KATEGORIEN', 'kategorien');
            self::header_search_render_group_v150414($posts, 'BEITRÄGE', 'beitraege');
        }
        echo '</div>';
        return (string)ob_get_clean();
    }

    public static function header_search_ajax_v150414() {
        if (function_exists('check_ajax_referer')) { check_ajax_referer('pftk_header_search_v150414', 'nonce'); }
        $search = isset($_REQUEST['q']) ? sanitize_text_field(wp_unslash((string)$_REQUEST['q'])) : '';
        $html = self::header_search_html_v150414($search);
        wp_send_json_success(['html' => $html]);
    }

