    public static function print_real_affiliate_product_js_v150414() {
        if (is_admin()) { return; }
        echo <<<'PFTK414AFFJS'
<script id="pftk-real-affiliate-products-v150414-js">
(function(){
  var CARD_SELECTOR='.pa255-product.is-real,.pa266-product.is-real';
  function norm(s){return String(s||'').replace(/\s+/g,' ').trim();}
  function providerFrom(link,text){
    var href=String((link&&link.getAttribute('href'))||'').toLowerCase(),hay=String(text||'').toLowerCase();
    if(href.indexOf('ebay.')!==-1||hay.indexOf('ebay-angebot')!==-1||hay.indexOf('ebay angebot')!==-1)return {key:'ebay',cta:'Bei eBay ansehen'};
    if(href.indexOf('amazon.')!==-1||href.indexOf('amzn.')!==-1||hay.indexOf('amazon-angebot')!==-1||hay.indexOf('amazon angebot')!==-1)return {key:'amazon',cta:'Bei Amazon ansehen'};
    return {key:'other',cta:'Zum Angebot'};
  }
  function productLink(card){
    var links=Array.prototype.slice.call(card.querySelectorAll('a[href]')); if(!links.length)return null;
    links.sort(function(a,b){var ai=a.querySelector('img')?1:0,bi=b.querySelector('img')?1:0;return bi-ai||norm(b.textContent).length-norm(a.textContent).length;});
    return links[0];
  }
  function disclosureText(card){
    var nodes=Array.prototype.slice.call(card.querySelectorAll('small,span,p,div')); var best='';
    nodes.forEach(function(n){var t=norm(n.textContent);if((/affiliate-links?/i.test(t)&&/provision/i.test(t))||(/^werbung\b/i.test(t)&&/provision/i.test(t))){if(!best||t.length<best.length)best=t;}});
    if(best)return best;
    var t=norm(card.textContent),m=t.match(/Hinweis:\s*Einige Links auf dieser Seite sind Affiliate-Links\.[\s\S]*?Mehrkosten\./i);return m?norm(m[0]):'';
  }
  function priceFrom(text){
    var m=norm(text).match(/(?:^|[^\d])(\d{1,5}(?:[.,]\d{2})?)\s*(EUR|€)(?![A-Za-z])/i); if(!m)return '';
    return m[1].replace('.',',')+' €';
  }
  function usefulTitleNode(link){
    var selectors=['[data-product-title]','[data-item-title]','[itemprop="name"]','.product-title','.item-title','.title','h1','h2','h3','h4','h5','h6'];
    for(var i=0;i<selectors.length;i++){var nodes=link.querySelectorAll(selectors[i]);for(var j=0;j<nodes.length;j++){var t=norm(nodes[j].textContent);if(t&&t.length>4&&!/mehr erfahren|zum angebot|bei .* ansehen|affiliate|provision|zustand|available/i.test(t))return t;}}
    return '';
  }
  function fallbackTitle(text,img){
    var alt=img?norm(img.getAttribute('alt')):'';
    if(alt&&alt.length>7&&!/^(produkt(?:bild)?|product(?: image)?|image|bild|ebay|amazon)$/i.test(alt))return alt;
    var t=norm(text)
      .replace(/Hinweis:\s*Einige Links auf dieser Seite sind Affiliate-Links\.[\s\S]*?Mehrkosten\./ig,' ')
      .replace(/[A-Za-z0-9ÄÖÜäöüß .&+]+-Angebot\s*[·\-]\s*Affiliate/ig,' ')
      .replace(/\bMehr erfahren\b/ig,' ')
      .replace(/\bBei\s+(?:eBay|Amazon)\s+ansehen\b|\bZum Angebot\b/ig,' ')
      .replace(/\bavailable\b/ig,' ');
    t=norm(t).replace(/\s*[·|]\s*\d{1,5}(?:[.,]\d{2})?\s*(?:EUR|€)[\s\S]*$/i,'').replace(/\s+\d{1,5}(?:[.,]\d{2})?\s*(?:EUR|€)[\s\S]*$/i,'');
    var cuts=[' Dein Pferd',' Dieses ',' Diese ',' Dieser ',' Das ',' Der ',' Die ',' Mit ',' Inspiriert ',' Perfekt ',' Ideal ',' Robust ',' Hochwertig ',' Geeignet ',' Ob '],cut=-1;
    cuts.forEach(function(x){var i=t.indexOf(x);if(i>=32&&(cut<0||i<cut))cut=i;});
    var punct=t.search(/[.!?]\s/);if(punct>=32&&(cut<0||punct<cut))cut=punct;
    if(cut>0)t=t.slice(0,cut);
    if(t.length>96){var s=t.slice(0,96),sp=s.lastIndexOf(' ');t=(sp>60?s.slice(0,sp):s).trim();}
    return t;
  }
  function ensureDisclosure(grid,text){
    if(!grid||!text||grid.querySelector('[data-pftk-affiliate-grid-disclosure-v150414="1"]'))return;
    var note=document.createElement('p');note.setAttribute('data-pftk-affiliate-grid-disclosure-v150414','1');note.textContent=text;grid.insertBefore(note,grid.firstChild);
  }
  function cloneLinkAttrs(src,dst){
    ['href','target','referrerpolicy'].forEach(function(a){var v=src.getAttribute(a);if(v)dst.setAttribute(a,v);});
    var rel=norm(src.getAttribute('rel'));var parts=rel?rel.split(/\s+/):[];['sponsored','nofollow','noopener'].forEach(function(x){if(parts.indexOf(x)<0)parts.push(x);});dst.setAttribute('rel',parts.join(' '));
  }
  function decorate(card){
    if(!card||card.getAttribute('data-pftk-affiliate-card-v150414')==='1')return;
    var link=productLink(card);if(!link)return;
    var raw=norm(card.textContent),provider=providerFrom(link,raw),img=link.querySelector('img')||card.querySelector('img'),price=priceFrom(raw),title=usefulTitleNode(link)||fallbackTitle(link.textContent||raw,img);
    if(!title)title='Produkt beim Anbieter';
    var disclosure=disclosureText(card),grid=card.closest('.pa255-product-grid,.pa266-product-grid,.pa272-product-grid,.pa273-product-grid');
    card.setAttribute('data-pftk-affiliate-card-v150414','1');card.setAttribute('data-pftk-affiliate-provider-v150414',provider.key);
    if(grid){grid.setAttribute('data-pftk-affiliate-real-grid-v150414','1');ensureDisclosure(grid,disclosure);}

    var source=document.createElement('div');source.setAttribute('data-pftk-affiliate-source-v150414','1');while(card.firstChild)source.appendChild(card.firstChild);card.appendChild(source);
    var shell=document.createElement('div');shell.setAttribute('data-pftk-affiliate-clean-shell-v150414','1');
    var bodyLink=document.createElement('a');bodyLink.setAttribute('data-pftk-affiliate-clean-link-v150414','1');cloneLinkAttrs(link,bodyLink);
    if(img){var imageBox=document.createElement('span');imageBox.setAttribute('data-pftk-affiliate-image-v150414','1');var cloned=img.cloneNode(true);imageBox.appendChild(cloned);bodyLink.appendChild(imageBox);}
    var h=document.createElement('span');h.setAttribute('data-pftk-affiliate-title-v150414','1');h.textContent=title;bodyLink.appendChild(h);
    if(price){var p=document.createElement('span');p.setAttribute('data-pftk-affiliate-price-v150414','1');p.textContent=price;bodyLink.appendChild(p);}
    shell.appendChild(bodyLink);card.appendChild(shell);
    var cta=document.createElement('a');cta.setAttribute('data-pftk-affiliate-cta-v150414','1');cloneLinkAttrs(link,cta);cta.textContent=provider.cta;card.appendChild(cta);
  }
  function scan(){document.querySelectorAll(CARD_SELECTOR).forEach(decorate);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',scan,{once:true});else scan();
  new MutationObserver(scan).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
