    public static function relevanssi_live_search_published_only_v150297($args) {
        $args = is_array($args) ? $args : [];
        $args['post_status'] = 'publish';
        // V1.50.408: Fuer das Header-Dropdown holen wir einen groesseren neutralen
        // Relevanssi-Pool, damit bereits von Relevanssi gelieferte Taxonomie-Treffer
        // erhalten bleiben. Sichtbar bleiben spaeter dennoch maximal 5 je Gruppe.
        if (self::is_header_live_search_request_v150408()) {
            $args['posts_per_page'] = 50;
        }
        return $args;
    }

    public static function render_brand_header_v15065() {
        if (is_admin()) { return; }
        $location = self::brand_menu_location_v15065();
        $logo = plugin_dir_url(__FILE__) . 'assets/pferde-atelier-logo-pferd-b.png';
        $brand = self::brand_settings_v15065();
        $tagline = trim((string)($brand['header_tagline'] ?? ''));
