    public static function footer_pb_one_link_v150137($content) {
        $content = (string)$content;
        if (preg_match('~<a\b[^>]*href=[\"\'][^\"\']*p-b\.one[^\"\']*[\"\'][^>]*>~i', $content)) { return $content; }
        return preg_replace('~\bPB\s+one\b~iu', '<a href="https://p-b.one/" target="_blank" rel="noopener noreferrer">PB one</a>', $content);
    }

    private static function footer_page_link_v15065($slugs, $label) {
        foreach ((array)$slugs as $slug) {
            $page = get_page_by_path((string)$slug);
            if ($page instanceof WP_Post && $page->post_status === 'publish') {
                return '<a href="' . esc_url(get_permalink($page)) . '">' . esc_html($label) . '</a>';
            }
        }
        return '';
    }

    private static function footer_links_v15065() {
        $locations = function_exists('get_nav_menu_locations') ? (array)get_nav_menu_locations() : [];
        if (function_exists('wp_get_nav_menu_items')) {
            foreach (['footer-menu','footer','footer_menu','menu-2'] as $candidate) {
                $menu_id = absint($locations[$candidate] ?? 0);
                if ($menu_id <= 0) { continue; }
                $items = wp_get_nav_menu_items($menu_id);
                $links = [];
                foreach ((array)$items as $item) {
                    if (!is_object($item) || absint($item->menu_item_parent ?? 0) !== 0) { continue; }
                    $url = trim((string)($item->url ?? ''));
                    $title = trim((string)($item->title ?? ''));
                    if ($url !== '' && $title !== '') { $links[] = '<a href="' . esc_url($url) . '">' . esc_html($title) . '</a>'; }
                }
                if (!empty($links)) { return implode('', $links) . self::footer_account_links_v150114(); }
            }
        }

        $links = [];
        foreach ([
            [['ueber-uns','uber-uns'], 'Über uns'],
            [['kontakt'], 'Kontakt'],
            [['partner-werden','werbung'], 'Partner werden'],
            [['impressum'], 'Impressum'],
        ] as $entry) {
            $link = self::footer_page_link_v15065($entry[0], $entry[1]);
            if ($link !== '') { $links[] = $link; }
        }
        $privacy = function_exists('get_privacy_policy_url') ? trim((string)get_privacy_policy_url()) : '';
        if ($privacy !== '') { $links[] = '<a href="' . esc_url($privacy) . '">Datenschutz</a>'; }
        elseif (($link = self::footer_page_link_v15065(['datenschutz'], 'Datenschutz')) !== '') { $links[] = $link; }
        return implode('', $links) . self::footer_account_links_v150114();
    }

    private static function footer_account_links_v150114() {
        $base = home_url('/account/');
        if (is_user_logged_in()) {
            return '<a class="pftk-footer-account-link-v150114" href="' . esc_url($base) . '">Mein Konto</a>'
                . '<a class="pftk-footer-account-link-v150114" href="' . esc_url(home_url('/account/listings/')) . '">Meine Anzeigen</a>'
                . '<a class="pftk-footer-account-link-v150114" href="' . esc_url(wp_logout_url(home_url('/'))) . '">Abmelden</a>';
        }
        return '<a class="pftk-footer-account-link-v150114" href="' . esc_url($base) . '">Anmelden / Konto</a>';
    }

