        return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4.2a7.8 7.8 0 0 0-2.8 15.1c-.1-1.3 0-2.8.3-4.1l1-4.2s-.2-.6-.2-1.5c0-1.4.8-2.5 1.9-2.5.9 0 1.3.7 1.3 1.5 0 .9-.6 2.2-.9 3.4-.3 1 .5 1.9 1.5 1.9 1.8 0 3.2-1.9 3.2-4.7 0-2.4-1.8-4.1-4.3-4.1-2.9 0-4.6 2.2-4.6 4.4 0 .9.3 1.8.8 2.3.1.1.1.2.1.4l-.3 1.2c-.1.4-.3.5-.7.3-1.6-.7-2.6-2.9-2.6-4.6 0-3.8 2.8-7.3 8-7.3 4.2 0 7.4 3 7.4 7 0 4.2-2.6 7.5-6.3 7.5-1.2 0-2.4-.6-2.8-1.4l-.8 2.9c-.3 1.3-1.1 2.8-1.6 3.7.8.2 1.7.3 2.6.3a7.8 7.8 0 0 0 0-15.6z" fill="currentColor"/></svg>';
    }

