    public static function footer_pb_one_link_script_v150142() {
        if (is_admin()) { return; }
        ?>
<script id="pftk-pb-one-link-v150142">
(function(){
  function apply(){
    var root=document.querySelector('footer#colophon .site-primary-footer-wrap .ast-footer-copyright');
    if(!root || root.querySelector('a[href^="https://p-b.one/"]')) return;
    var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
    var nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
    nodes.some(function(node){
      var m=node.nodeValue.match(/PB\s*one/i); if(!m) return false;
      var before=node.nodeValue.slice(0,m.index), after=node.nodeValue.slice(m.index+m[0].length);
      var a=document.createElement('a'); a.href='https://p-b.one/'; a.target='_blank'; a.rel='noopener noreferrer'; a.textContent='PB one';
      var frag=document.createDocumentFragment();
      if(before) frag.appendChild(document.createTextNode(before)); frag.appendChild(a); if(after) frag.appendChild(document.createTextNode(after));
      node.parentNode.replaceChild(frag,node); return true;
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',apply,{once:true}); else apply();
})();
</script>
        <?php
    }

