            . 'var html=' . wp_json_encode('<nav class="pftk-footer-account-v150115" aria-label="Konto">' . $links . '</nav>') . ';'
            . 'function isAccountNode(n){if(!n||n.nodeType!==1)return false;var c=(n.className||"").toString().toLowerCase();var a=n.matches&&n.matches("a")?n:n.querySelector&&n.querySelector("a");var h=a?(a.getAttribute("href")||"").toLowerCase():"";var t=(n.textContent||"").replace(/\\s+/g," ").trim().toLowerCase();return /(?:^|\\s)(?:hp-menu__item--user-account|menu-item--user-account|hp-menu__item--account)(?:\\s|$)/.test(c)||/(?:\\/account(?:\\/|$)|\\/user-account(?:\\/|$))/.test(h)||/^(?:anmelden|mein konto|konto|abmelden|registrieren)(?:\\s|$)/.test(t);}'
            . 'function clean(root){if(!root)return;root.querySelectorAll("li,a").forEach(function(n){var li=n.closest("li");var target=li||n;if(isAccountNode(target))target.remove();});}'
            . 'function run(){document.querySelectorAll(".pftk-brand-menu-v15065,.pftk-mobile-menu-v15074").forEach(clean);}'
            . 'function watch(){run();document.querySelectorAll(".pftk-brand-nav-v15065").forEach(function(root){new MutationObserver(run).observe(root,{childList:true,subtree:true});});}'
            . 'if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",watch,{once:true});else watch();window.addEventListener("load",run,{once:true});setTimeout(run,250);setTimeout(run,1200);})();</script>';
    }

