        echo <<<'HTML'
<script id="pftk-brand-header-interactions-v150114">
(function(){
  function direct(parent, selector){
    for(var i=0;i<parent.children.length;i++){var n=parent.children[i];if(n.matches&&n.matches(selector))return n;}
    return null;
  }
  function closeSiblings(item){
    var parent=item.parentElement;if(!parent)return;
    Array.prototype.forEach.call(parent.children,function(sib){
      if(sib===item||!sib.classList)return;
      sib.classList.remove('pftk-menu-open-v15065');
      var b=direct(sib,'button.pftk-brand-menu-toggle-v15065,button.pftk-mobile-submenu-toggle-v15074');
      if(b)b.setAttribute('aria-expanded','false');
    });
  }
  function addToggle(item, submenu, cls){
    if(!item||!submenu)return;
    var old=direct(item,'button.'+cls);if(old)return;
    Array.prototype.forEach.call(item.querySelectorAll(':scope > button.ast-menu-toggle'),function(n){n.remove();});
    var link=direct(item,'a');if(!link)return;
    Array.prototype.forEach.call(link.querySelectorAll('.dropdown-menu-toggle,.ast-header-navigation-arrow'),function(n){n.remove();});
    var button=document.createElement('button');button.type='button';button.className=cls;
    button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Untermenü öffnen');
    button.innerHTML='<span aria-hidden="true"></span>';link.insertAdjacentElement('afterend',button);
    button.addEventListener('click',function(e){
      e.preventDefault();e.stopPropagation();var open=!item.classList.contains('pftk-menu-open-v15065');
      closeSiblings(item);item.classList.toggle('pftk-menu-open-v15065',open);button.setAttribute('aria-expanded',open?'true':'false');
    });
  }
  function initDesktop(){
    var menu=document.querySelector('.pftk-brand-menu-v15065');if(!menu)return;
    Array.prototype.forEach.call(menu.children,function(item){var sub=direct(item,'.sub-menu');if(sub)addToggle(item,sub,'pftk-brand-menu-toggle-v15065');});
  }
  function initMobile(){
    var header=document.querySelector('.pftk-brand-header-v15065'),nav=document.querySelector('.pftk-mobile-nav-v15074'),main=document.querySelector('.pftk-mobile-main-toggle-v15071');
    if(!header||!nav||!main)return;
    if(main.dataset.enhanced!=='1'){
      main.dataset.enhanced='1';main.addEventListener('click',function(){var open=!header.classList.contains('pftk-mobile-menu-open-v15074');header.classList.toggle('pftk-mobile-menu-open-v15074',open);main.setAttribute('aria-expanded',open?'true':'false');});
    }
    nav.querySelectorAll('li').forEach(function(item){var sub=direct(item,'.sub-menu');if(sub)addToggle(item,sub,'pftk-mobile-submenu-toggle-v15074');});
  }
  function init(){initDesktop();initMobile();}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
  new MutationObserver(init).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
HTML;
