    private static function render_hub1_legacy_v150198() {
        $ctx = self::context('hub1');
        $items = self::published_page_items($ctx['top_items'] ?? [], 0, false);
        $items = self::sort_structural_items($items);
        $primary = array_slice($items, 0, 6);
        $remaining = array_slice($items, 6);
        $page_id = is_singular('page') ? absint(get_queried_object_id()) : 0;
        $intro = $page_id > 0 ? self::category_intro_html($page_id, 'hub1') : '';
        $page_title = $page_id > 0 ? get_the_title($page_id) : '';
        $topics_title = trim((string)self::text('hub1','topics_title'));
        if ($topics_title === '' || $topics_title === 'Ausgewählte Themen') { $topics_title = 'Passende Bereiche entdecken'; }
        $topics_intro = trim((string)self::text('hub1','topics_intro'));
        $button_page = self::topic_cta_v150325();
        ob_start();
        echo '<div class="pftk-hub1-new-v150198">';
        echo $intro;
        echo '<section class="pftk-hub1-intro-v150198"><span>Orientierung im Pferde Atelier</span><h2>' . esc_html($topics_title) . '</h2>' . ($topics_intro !== '' ? '<p>' . esc_html($topics_intro) . '</p>' : '') . '</section>';
        if (!empty($primary)) {
            echo '<section class="pftk-hub1-grid-v150198" aria-label="Unterkategorien">';
            foreach ($primary as $i=>$item) {
                echo '<a class="pftk-hub1-card-v150198" href="' . esc_url($item->url) . '">' . self::hub1_modern_art_v150198($i) . '<div><h3>' . esc_html($item->title) . '</h3><p>' . esc_html(self::start_category_description_v150161($item->title)) . '</p><b>' . esc_html($button_page) . ' <span>›</span></b></div></a>';
            }
            echo '</section>';
        }
        echo '<div class="pftk-hub1-ad-v150198 pftk-hub1-ad-wide-v150198">' . self::hub1_banner_slot_v150211('hub_after_cards') . '</div>';
        if (!empty($remaining)) {
            $title = trim((string)self::text('hub1','structure_title')) ?: 'Weitere Themen';
            $intro2 = trim((string)self::text('hub1','structure_intro'));
            echo '<section class="pftk-hub1-more-v150198"><header><h2>' . esc_html($title) . '</h2>' . ($intro2 !== '' ? '<p>' . esc_html($intro2) . '</p>' : '') . '</header><div>';
            foreach ($remaining as $item) { echo '<a href="' . esc_url($item->url) . '"><span>' . esc_html($item->title) . '</span><b>›</b></a>'; }
            echo '</div></section>';
        }
        if (self::visible('hub1','show_posts')) { echo self::render_posts('hub1',$ctx); }
        echo '<div class="pftk-hub1-ad-v150198 pftk-hub1-ad-mid-v150198">' . self::hub1_banner_slot_v150211('hub_mid_banner') . '</div>';
        echo '</div>';
        return ob_get_clean();
    }


    /**
     * V1.50.210: allgemeingültige Hub-1-Bild- und Seitenlogik.
     * Aktiv ist zunächst ausschließlich die Pilotkategorie Ausrüstung. Alle acht
     * Hauptkategorie-Fotos liegen bereits getrennt und austauschbar im Plugin.
     */
    private static function hub1_category_key_v150210($page_id = 0) {
        $page_id = absint($page_id);
        if ($page_id <= 0 && is_singular('page')) { $page_id = absint(get_queried_object_id()); }
        $post = $page_id > 0 ? get_post($page_id) : null;
        $title = $post instanceof WP_Post ? get_the_title($post) : '';
        $slug = $post instanceof WP_Post ? (string)$post->post_name : '';
        $haystack = self::normalize_match_key($title . ' ' . $slug);
        $rules = [
            'ausruestung' => ['ausruestung','ausstattung','equipment'],
            'stall' => ['stall','stallhaltung'],
            'weide' => ['weide','koppel'],
            'fuetterung' => ['fuetterung','futter','ernaehrung'],
            'gesundheit' => ['gesundheit','pferdegesundheit'],
            'training' => ['training','ausbildung','reitweisen'],
            'transport' => ['transport','unterwegs','anhaenger'],
            'wissen' => ['wissen','ratgeber','magazin'],
        ];
        foreach ($rules as $key => $tokens) {
            foreach ($tokens as $token) {
                if ($haystack === $token || strpos($haystack, $token) !== false) { return $key; }
            }
        }
        return 'generic';
    }

    private static function hub1_is_pilot_v150210($page_id = 0) {
        $key = self::hub1_category_key_v150210($page_id);
        $enabled_keys = ['ausruestung','stall','weide','fuetterung','gesundheit','training','transport','wissen'];
        $enabled = in_array($key, $enabled_keys, true);
        return (bool)apply_filters('pftk_hub1_v150210_enabled', $enabled, $key, absint($page_id));
    }

    private static function hub1_hero_config_v150210($page_id, $key) {
        $fallbacks = [
            'ausruestung' => [
                'Pferde Atelier – gut ausgerüstet',
                'Von Decken und Sattelzeug bis Pflege- und Reiterbedarf: Hier findest du Orientierung zu Passform, Material, Sicherheit und einer sinnvollen Auswahl für Pferd und Reiter.',
                'Ausrüstung für Pferd und Reiter',
            ],
            'stall' => [
                'Pferde Atelier – gut aufgestellt',
                'Von Offenstall und Stallklima bis Technik und Organisation: Hier findest du Lösungen für sichere Abläufe, gute Haltung und einen verlässlichen Stallalltag.',
                'Stall und Haltung',
            ],
            'weide' => [
                'Pferde Atelier – sicher draußen',
                'Von Zauntechnik und Weideausstattung bis Paddock und Reitplatz: Hier findest du Orientierung für sichere Flächen, zuverlässige Versorgung und wetterfeste Lösungen.',
                'Weide und Koppel',
            ],
            'fuetterung' => [
                'Pferde Atelier – gut versorgt',
                'Von Raufutter und Mineralversorgung bis Lagerung und Fütterungstechnik: Hier findest du verständliche Orientierung für eine bedarfsgerechte Pferdefütterung.',
                'Pferdefütterung',
            ],
            'gesundheit' => [
                'Pferde Atelier – aufmerksam begleiten',
                'Von Erste Hilfe und Hufpflege bis Fell, Hygiene und Regeneration: Hier findest du praktische Orientierung für Vorsorge, Pflege und Wohlbefinden.',
                'Pferdegesundheit',
            ],
            'training' => [
                'Pferde Atelier – fair trainieren',
                'Von Bodenarbeit und Longieren bis Reitplatztraining und Hilfsmitteln: Hier findest du Ideen für klare Kommunikation, faire Übungen und passende Trainingswege.',
                'Training und Ausbildung',
            ],
            'transport' => [
                'Pferde Atelier – sicher unterwegs',
                'Von Pferdeanhänger und Zugfahrzeug bis Verladen und Reisevorbereitung: Hier findest du Orientierung für sichere Fahrten und entspannteres Unterwegssein.',
                'Transport und Unterwegssein',
            ],
            'wissen' => [
                'Pferde Atelier – klar erklärt',
                'Von Büchern und Kursen bis Planung, Recht und digitalen Helfern: Hier findest du verständliche Grundlagen und praktische Entscheidungshilfen für den Pferdealltag.',
                'Wissen und Ratgeber',
            ],
        ];
        $fallback = $fallbacks[$key] ?? $fallbacks['ausruestung'];
        $title = $page_id > 0 ? trim((string)get_the_title($page_id)) : '';
        if ($title === '') { $title = $fallback[2]; }

        // V1.50.356: Die automatisch erzeugten, oft gleichförmigen Hub-1-Texte
        // werden durch acht individuelle, themenbezogene Referenztexte ersetzt.
        // Ein ausdrücklich manuell gepflegter Introtext bleibt erhalten.
        $shortline = $fallback[0];
        $stored_intro = $page_id > 0 ? trim((string)get_post_meta($page_id, self::META_CATEGORY_INTRO, true)) : '';
        $stored_source = $page_id > 0 ? trim((string)get_post_meta($page_id, self::META_CATEGORY_INTRO_SOURCE, true)) : '';
        $intro = ($stored_source === 'manual' && $stored_intro !== '') ? $stored_intro : $fallback[1];

        $image = $page_id > 0 ? (string)get_the_post_thumbnail_url($page_id, 'full') : '';
        if ($image === '') { $image = plugin_dir_url(__FILE__) . 'assets/hub1/hub1-hero-' . $key . '-v150210.webp'; }
        $button = trim((string)self::text('hub1','hero_button_1'));
        if ($button === '' || $button === 'Ausgewählte Themen ansehen') { $button = 'Alle Themen entdecken'; }
        return ['title'=>$title,'shortline'=>$shortline,'intro'=>$intro,'image'=>$image,'alt'=>$fallback[2],'button'=>$button];
    }

    private static function hub1_benefits_v150210() {
        $items = [
            ['health','Geprüfte Qualität','Nur ausgewählte Produkte für dich & dein Pferd'],
            ['recommend','Erfahrung & Wissen','Praxiserprobt & verständlich erklärt'],
            ['horse','Für dich & dein Pferd','Passende Lösungen für jeden Anspruch'],
            ['knowledge','Sicher entscheiden','Vergleiche, Tipps & Empfehlungen'],
        ];
        $out = '<section class="pftk-hub1-benefits-v150210" aria-label="Vorteile">';
        foreach ($items as $item) {
            $out .= '<div>' . self::start_art_v150170($item[0]) . '<p><strong>' . esc_html($item[1]) . '</strong><span>' . esc_html($item[2]) . '</span></p></div>';
