    private static function hub1_posts_v150210($ctx, $page_title) {
        $cat_ids = array_values(array_unique(array_filter(array_map('intval', (array)($ctx['hub_post_cat_ids'] ?? ($ctx['cat_ids'] ?? []))))));
        $posts = self::top_posts_by_importance($cat_ids, 3);

        $title = trim((string)self::text('hub1','posts_title'));
        if ($title === '' || $title === 'Wichtige Ratgeber') { $title = 'Wissen für den Pferdealltag'; }
        $button = self::article_excerpt_cta_v150325();
        $out = '<section class="pftk-hub1-section-v150210 pftk-hub1-guides-v150210"><header><h2>' . esc_html($title) . '</h2></header><div class="pftk-hub1-guide-grid-v150210">';
        $rendered = 0;
        foreach ((array)$posts as $post) {
            if (!$post instanceof WP_Post) { continue; }
            $image = (string)get_the_post_thumbnail_url($post->ID, 'large');
            $cats = get_the_category($post->ID);
            $label = !empty($cats) && $cats[0] instanceof WP_Term ? $cats[0]->name : $page_title;
            $excerpt = self::clean_excerpt($post);
            $out .= '<article class="pftk-hub1-guide-card-v150210">';
            if ($image !== '') { $out .= '<a class="pftk-hub1-guide-image-v150210" href="' . esc_url(get_permalink($post)) . '"><img src="' . esc_url($image) . '" alt="' . esc_attr(get_the_title($post)) . '" loading="lazy"></a>'; }
            else { $out .= '<a class="pftk-hub1-guide-image-v150210 is-fallback" href="' . esc_url(get_permalink($post)) . '">' . self::hub1_modern_icon_v150222('wissen') . '</a>'; }
            $out .= '<div><span>' . esc_html($label) . '</span><h3><a href="' . esc_url(get_permalink($post)) . '">' . esc_html(get_the_title($post)) . '</a></h3>' . ($excerpt !== '' ? '<p>' . esc_html($excerpt) . '</p>' : '') . '<a class="pftk-hub1-textlink-v150210" href="' . esc_url(get_permalink($post)) . '"><span class="pftk-hub1-button-label-v150221">' . esc_html($button) . '</span></a></div></article>';
            $rendered++;
        }
        $out .= '<aside class="pftk-hub1-magazine-v150210">' . self::hub1_modern_icon_v150222('wissen') . '<h3>Noch mehr Wissen rund um ' . esc_html($page_title) . '?</h3><p>Anleitungen, Checklisten und praktische Tipps im Journal.</p><a href="' . esc_url(home_url('/journal/')) . '"><span class="pftk-hub1-button-label-v150221">Journal</span></a></aside>';
        return $out . '</div></section>';
    }

    private static function hub1_product_content_is_real_v150214($candidate) {
        $candidate = trim((string)$candidate);
        if ($candidate === '') { return false; }
        $plain = strtolower(trim(wp_strip_all_tags($candidate)));
        $markers = ['affiliate-werbefläche', 'affiliate werbefläche', 'produktplatz', 'noch nicht belegt', 'nicht belegt', 'placeholder', 'platzhalter'];
        foreach ($markers as $marker) {
            if ($plain !== '' && strpos($plain, $marker) !== false) { return false; }
            if (strpos(strtolower($candidate), $marker) !== false) { return false; }
        }
        $has_link = stripos($candidate, '<a') !== false && stripos($candidate, 'href=') !== false;
        $has_content = stripos($candidate, '<img') !== false || mb_strlen($plain) >= 12;
        return $has_link && $has_content;
    }

