    private static function hub1_product_slot_v150210($index) {
        $index = max(1, min(3, intval($index)));
        $slot = 'hub_product_' . $index;
        $content = '';
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            $candidate = do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]');
            if (self::hub1_product_content_is_real_v150214($candidate)) { $content = (string)$candidate; }
        }
        if ($content !== '') {
            return ['html' => '<div class="pftk-hub1-product-slot-v150210 is-product-v150214" data-pftk-slot="' . esc_attr($slot) . '">' . $content . '</div>', 'is_product' => true];
        }
        return ['html' => '', 'is_product' => false];
    }

