    private static function hub1_products_v150356($page_title = '', $test_state = '') {
        $slots = [];
        $product_count = 0;
        if ($test_state === 'both' || $test_state === 'products') {
            for ($i = 1; $i <= 3; $i++) {
                $slots[] = self::hub1_test_product_v150356($i, $page_title);
                $product_count++;
            }
        } elseif ($test_state !== 'banner' && $test_state !== 'none') {
            for ($i = 1; $i <= 3; $i++) {
                $slot = self::hub1_product_slot_v150210($i);
                if (!empty($slot['html'])) { $slots[] = $slot['html']; }
                if (!empty($slot['is_product'])) { $product_count++; }
            }
        }
        if ($product_count <= 0) { return ['html'=>'','count'=>0]; }
        $out = '<section class="pa356-products" data-pftk-product-count="' . intval($product_count) . '"><header><span>Produktvorschläge</span><h2>Passend zu ' . esc_html($page_title) . ' ausgewählt</h2><p>Nur Produkte mit nachvollziehbarem Bezug zum jeweiligen Themenbereich.</p></header><div class="pa356-product-grid">' . implode('', $slots) . '</div></section>';
        return ['html'=>$out,'count'=>$product_count];
    }

