    private static function hub1_neighbor_items_v150210($page_id) {
        $ctx = self::context('start');
        $items = self::published_page_items($ctx['top_items'] ?? [], 0, false);
        $out = [];
        foreach ($items as $item) {
            if (intval($item->object_id ?? 0) === intval($page_id)) { continue; }
            $out[] = $item;
            if (count($out) >= 4) { break; }
        }
        return $out;
    }


