    private static function portal_icon_markup_v150251($key, $context = 'hub1') {
        $key = sanitize_key((string)$key);
        $catalog = self::portal_icon_catalog_v150251();
        // V1.50.374: fail-closed. Ein unbekannter Key darf nicht mehr still
        // als allgemeines Wissensicon erscheinen und damit eine falsche
        // Zuordnung verdecken.
        if (!isset($catalog[$key])) { return ''; }
        $file = $catalog[$key] ?? '';
        if ($file === '') { return ''; }
        $src = plugin_dir_url(__FILE__) . 'assets/icons-v150251/' . $file . '?ver=' . rawurlencode(self::VERSION);
        $classes = $context === 'start'
            ? 'pftk-home-art-v150170 pa251-icon pa251-icon-start'
            : 'pa251-icon pa251-icon-hub';
        return '<span class="' . esc_attr($classes) . '" data-pa251-icon="' . esc_attr($key) . '" aria-hidden="true"><img src="' . esc_url($src) . '" alt="" width="256" height="220" loading="lazy"></span>';
    }

    private static function portal_main_icon_key_v150251($item) {
        $title = self::normalize_match_key((string)(is_object($item) ? ($item->title ?? '') : $item));
        $url = self::normalize_match_key((string)(is_object($item) ? ($item->url ?? '') : ''));
        $hay = $title . '-' . $url;
        $map = [
            'ausruestung' => 'main-ausruestung',
            'stall' => 'main-stall',
            'weide' => 'main-weide',
            'fuetterung' => 'main-fuetterung',
            'gesundheit' => 'main-gesundheit',
            'training' => 'main-training',
            'transport' => 'main-transport',
            'wissen' => 'main-wissen',
            'ratgeber' => 'main-wissen',
        ];
        foreach ($map as $token => $icon) {
            if ($title === $token || strpos($hay, $token) !== false) { return $icon; }
        }
        return 'utility-knowledge';
    }

