    private static function portal_item_slug_v150374($item) {
        $url = (string)(is_object($item) ? ($item->url ?? '') : '');
        $path = (string)parse_url($url, PHP_URL_PATH);
        $path = trim(rawurldecode($path), '/');
        $slug = $path !== '' ? sanitize_title(basename($path)) : '';
        if ($slug === '') {
            $title = (string)(is_object($item) ? ($item->title ?? '') : $item);
            $slug = sanitize_title($title);
        }
        return $slug;
    }

    private static function portal_structural_icon_markup_v150374($item) {
        $slug = self::portal_item_slug_v150374($item);
        $catalog = self::portal_structural_icon_catalog_v150374();
        if ($slug === '' || !isset($catalog[$slug])) {
            // Fail-closed: keine irrefuehrende Eltern- oder Universalgraphik.
            return '';
        }
        $file = (string)$catalog[$slug];
        $path = plugin_dir_path(__FILE__) . 'assets/structural-icons-v150374/' . $file;
        if (!is_readable($path)) { return ''; }
        $src = plugin_dir_url(__FILE__) . 'assets/structural-icons-v150374/' . $file . '?ver=' . rawurlencode(self::VERSION);
        return '<span class="pa251-icon pa251-icon-hub pa374-structural-icon" data-pa374-icon="' . esc_attr($slug) . '" aria-hidden="true"><img src="' . esc_url($src) . '" alt="" width="64" height="64" loading="lazy"></span>';
    }

