    private static function hub1_posts_v150223($ctx, $page_title, $key = 'generic') {
        $cat_ids = array_values(array_unique(array_filter(array_map('intval', (array)($ctx['hub_post_cat_ids'] ?? ($ctx['cat_ids'] ?? []))))));
        $posts = self::top_posts_by_importance($cat_ids, 3);
        $copy = self::hub1_section_copy_v150358($key, $page_title);
        $count = 0;
        $cards = '';
        foreach ((array)$posts as $post) {
            if (!$post instanceof WP_Post) { continue; }
            $url = get_permalink($post);
            $image = (string)get_the_post_thumbnail_url($post->ID, 'large');
            $cats = get_the_category($post->ID);
            $label = !empty($cats) && $cats[0] instanceof WP_Term ? $cats[0]->name : $page_title;
            $excerpt = wp_trim_words(self::clean_excerpt($post), 14, '…');
            $cards .= '<article class="pa223-guide">';
            if ($image !== '') {
                $cards .= '<a class="pa223-guide-image" href="' . esc_url($url) . '"><img src="' . esc_url($image) . '" alt="' . esc_attr(get_the_title($post)) . '" loading="lazy"></a>';
            } else {
                $cards .= '<a class="pa223-guide-image pa223-fallback" href="' . esc_url($url) . '">' . self::hub1_icon_v150227('wissen') . '</a>';
            }
            $cards .= '<div class="pa223-guide-copy"><span>' . esc_html($label) . '</span><h3><a href="' . esc_url($url) . '">' . esc_html(get_the_title($post)) . '</a></h3>'
                . ($excerpt !== '' ? '<p>' . esc_html($excerpt) . '</p>' : '<p aria-hidden="true"></p>')
                . '<a class="pa223-button pa223-read" href="' . esc_url($url) . '"><span>Weiterlesen</span></a></div></article>';
            $count++;
        }

        $out = '<section class="pa223-section pa223-guides"><header class="pa356-section-heading"><span>Ratgeber zu ' . esc_html($page_title) . '</span><h2>' . esc_html($copy['posts']) . '</h2></header>';
        if ($count > 0) {
            $out .= '<div class="pa223-guide-grid count-' . intval($count) . '" data-pftk-post-card-count="' . intval($count) . '">' . $cards . '</div>';
        }
        $out .= self::bridge_v150363('hub1', $page_title, $key);
        return $out . '</section>';
    }

    private static function hub1_bottom_editorial_v150418($key) {
        static $catalog = null;
        if (!is_array($catalog)) {
            $catalog = [];
            $path = plugin_dir_path(__FILE__) . 'assets/hub1-bottom-editorial-v150418.json';
            if (is_readable($path)) {
                $decoded = json_decode((string)file_get_contents($path), true);
                if (is_array($decoded) && (string)($decoded['contract'] ?? '') === 'PFERDE_ATELIER_HUB1_BOTTOM_EDITORIAL_V150418' && isset($decoded['pages']) && is_array($decoded['pages'])) {
                    $catalog = $decoded['pages'];
                }
            }
        }
        $key = sanitize_key((string)$key);
        if ($key === '' || empty($catalog[$key]) || !is_array($catalog[$key])) { return ''; }
        $entry = $catalog[$key];
        $title = trim((string)($entry['title'] ?? ''));
        $paragraphs = isset($entry['paragraphs']) && is_array($entry['paragraphs']) ? $entry['paragraphs'] : [];
        if ($title === '' || empty($paragraphs)) { return ''; }
        $links = [
            'Ausrüstung' => home_url('/ausruestung/'),
            'Stall' => home_url('/stall/'),
            'Weide' => home_url('/weide/'),
            'Fütterung' => home_url('/fuetterung/'),
            'Gesundheit' => home_url('/gesundheit/'),
            'Training' => home_url('/training/'),
            'Transport' => home_url('/transport/'),
            'Wissen' => home_url('/wissen/'),
        ];
        $rendered = [];
        foreach ($paragraphs as $paragraph) {
            $paragraph = trim((string)$paragraph);
            if ($paragraph === '') { continue; }
            $html = esc_html($paragraph);
            foreach ($links as $name => $url) {
                $token = esc_html('[[' . $name . ']]');
                if (strpos($html, $token) === false) { continue; }
                $html = str_replace($token, '<a href="' . esc_url($url) . '">' . esc_html($name) . '</a>', $html);
            }
            $rendered[] = $html;
        }
        if (empty($rendered)) { return ''; }
        $lead = '<p class="pa419-hub1-bottom-lead">' . array_shift($rendered) . '</p>';
        $copy = '';
        foreach ($rendered as $html) { $copy .= '<p>' . $html . '</p>'; }
        $css = '<style id="pftk-hub1-bottom-editorial-v150419-css">'
            . '.pa419-hub1-bottom{margin:64px 0 0!important;padding:clamp(42px,5.5vw,70px) clamp(22px,5vw,64px)!important;border:1px solid rgba(53,66,42,.18)!important;border-top:0!important;background:#FBF8F2!important;color:#35422A!important}'
            . '.pa419-hub1-bottom-head{max-width:930px!important;margin:0 auto 34px!important;text-align:center!important}'
            . '.pa419-hub1-bottom-head:before{content:"";display:block;width:44px;height:1px;margin:0 auto 16px;background:#C89214}'
            . '.pa419-hub1-bottom-head h2{margin:0 0 20px!important;color:#35422A!important;font-family:var(--pa-global-title-font,"Cormorant Garamond",Georgia,"Times New Roman",serif)!important;font-size:clamp(34px,4vw,50px)!important;font-weight:500!important;line-height:1.06!important;text-align:center!important}'
            . '.pa419-hub1-bottom-lead{max-width:82ch!important;margin:0 auto!important;color:#3F473C!important;font-size:16px!important;line-height:1.76!important;text-align:left!important}'
            . '.pa419-hub1-bottom-copy{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:0!important;max-width:1120px!important;margin:0 auto!important;border-top:1px solid rgba(53,66,42,.22)!important;border-left:1px solid rgba(53,66,42,.22)!important}'
            . '.pa419-hub1-bottom-copy p{min-width:0!important;margin:0!important;padding:clamp(26px,3vw,38px)!important;border-right:1px solid rgba(53,66,42,.22)!important;border-bottom:1px solid rgba(53,66,42,.22)!important;background:rgba(255,255,255,.58)!important;color:#3F473C!important;font-size:16px!important;line-height:1.76!important;text-align:left!important}'
            . '.pa419-hub1-bottom a,.pa419-hub1-bottom a:link,.pa419-hub1-bottom a:visited{color:#35422A!important;font-weight:600!important;text-decoration:underline!important;text-decoration-color:rgba(53,66,42,.42)!important;text-underline-offset:3px!important}'
            . '.pa419-hub1-bottom a:hover,.pa419-hub1-bottom a:focus{color:#C89214!important;text-decoration-color:#C89214!important}'
            . '@media(max-width:780px){.pa419-hub1-bottom{padding:38px 20px!important}.pa419-hub1-bottom-head{margin-bottom:26px!important}.pa419-hub1-bottom-copy{grid-template-columns:1fr!important}.pa419-hub1-bottom-lead,.pa419-hub1-bottom-copy p{font-size:15.5px!important;line-height:1.74!important}}'
            . '</style>';
        return $css . '<section class="pa419-hub1-bottom" aria-label="Vertiefende Informationen"><header class="pa419-hub1-bottom-head"><h2>' . esc_html($title) . '</h2>' . $lead . '</header><div class="pa419-hub1-bottom-copy">' . $copy . '</div></section>';
    }

    private static function render_hub1_v150223() {
        $page_id = is_singular('page') ? absint(get_queried_object_id()) : 0;
        if (!self::hub1_is_pilot_v150210($page_id)) { return self::render_hub1_legacy_v150198(); }
        $ctx = self::context('hub1');
        $items = self::sort_structural_items(self::published_page_items($ctx['top_items'] ?? [], 0, false));
        $primary = array_slice($items, 0, 6);
        $key = self::hub1_category_key_v150210($page_id);
        $hero = self::hub1_hero_config_v150210($page_id, $key);
        $copy = self::hub1_section_copy_v150358($key, $hero['title']);
        $test_state = self::hub1_test_state_v150356();
        if ($page_id > 0) {
            self::$category_intro_rendered[$page_id] = true;
            self::$page_shortline_rendered[$page_id] = true;
        }
        $button_page = self::topic_cta_v150325();
        $partner_banner = self::hub1_real_partner_banner_v150356($test_state);
        $direct_ad = self::hub1_direct_ad_v150359($test_state);

        ob_start();
        echo '<div class="pa223 pa356 pa358 pa359 pa361" data-pftk-page-intro="1" data-pftk-page-shortline="1" data-pftk-hub1-category="' . esc_attr($key) . '" data-pftk-hub1-test="' . esc_attr($test_state) . '">';
        echo '<section class="pa223-hero"><div class="pa223-hero-copy"><span class="pa223-eyebrow">' . esc_html($hero['shortline']) . '</span><h1>' . esc_html($hero['title']) . '</h1><p>' . esc_html($hero['intro']) . '</p><a class="pa223-button" href="#pa223-topics"><span>' . esc_html($hero['button']) . '</span></a></div><figure><img src="' . esc_url($hero['image']) . '" alt="' . esc_attr($hero['alt']) . '" fetchpriority="high"></figure></section>';
        if ($primary) {
            echo '<section class="pa223-section pa223-topics" id="pa223-topics"><header class="pa356-section-heading"><span>Themenbereiche</span><h2>' . esc_html($copy['topics']) . '</h2></header><div class="pa223-topic-grid">';
            foreach ($primary as $item) {
                echo '<a class="pa223-topic" href="' . esc_url($item->url) . '">' . self::hub1_assigned_icon_v150243($item) . '<h3>' . esc_html($item->title) . '</h3><p>' . esc_html(self::hub1_topic_description_v150356($item)) . '</p><span class="pa223-linklabel">' . esc_html($button_page) . '</span></a>';
            }
            echo '</div></section>';
        }
        if ($partner_banner !== '') {
            echo '<section class="pa356-partner pa359-partner" aria-label="Partnerbanner"><div class="pa356-ad-label">Ausgewählter Partner</div>' . $partner_banner . '</section>';
        }
        echo self::hub1_posts_v150223($ctx, $hero['title'], $key);
        echo '<section class="pa356-partner pa359-direct" aria-label="Direkt buchbarer Werbeplatz"><div class="pa356-ad-label">Direkt buchbarer Werbeplatz</div>' . $direct_ad . '</section>';
        echo self::hub1_bottom_editorial_v150418($key);
        echo '</div>';
        return ob_get_clean();
    }

    private static function render_hub1_v150210() {
        $page_id = is_singular('page') ? absint(get_queried_object_id()) : 0;
        if (!self::hub1_is_pilot_v150210($page_id)) { return self::render_hub1_legacy_v150198(); }
        $ctx = self::context('hub1');
        $items = self::sort_structural_items(self::published_page_items($ctx['top_items'] ?? [], 0, false));
        $primary = array_slice($items, 0, 6);
        $remaining = array_slice($items, 6);
        $key = self::hub1_category_key_v150210($page_id);
        $hero = self::hub1_hero_config_v150210($page_id, $key);
        if ($page_id > 0) {
            self::$category_intro_rendered[$page_id] = true;
            self::$page_shortline_rendered[$page_id] = true;
        }
        $button_page = self::topic_cta_v150325();
        $used_icons = [];
        ob_start();
        echo '<div class="pftk-hub1-v150210" data-pftk-page-intro="1" data-pftk-page-shortline="1" data-pftk-hub1-category="' . esc_attr($key) . '">';
        echo '<section class="pftk-hub1-hero-v150210"><div class="pftk-hub1-hero-copy-v150210"><span>' . esc_html($hero['shortline']) . '</span><h1>' . esc_html($hero['title']) . '</h1><p>' . esc_html($hero['intro']) . '</p><a href="#pftk-hub1-topics-v150210"><span class="pftk-hub1-button-label-v150221">' . esc_html($hero['button']) . '</span></a></div><figure><img src="' . esc_url($hero['image']) . '" alt="' . esc_attr($hero['alt']) . '" fetchpriority="high"></figure></section>';
        if ($primary) {
            $topics_title = trim((string)self::text('hub1','topics_title'));
            if ($topics_title === '' || $topics_title === 'Ausgewählte Themen') { $topics_title = 'Die wichtigsten Themen rund um ' . $hero['title']; }
            echo '<section class="pftk-hub1-section-v150210 pftk-hub1-topics-v150210" id="pftk-hub1-topics-v150210"><h2>' . esc_html($topics_title) . '</h2><div class="pftk-hub1-topic-grid-v150210">';
            foreach ($primary as $item) {
                $icon_markup = self::hub1_modern_icon_v150222($item->title);
                echo '<a class="pftk-hub1-topic-v150210" href="' . esc_url($item->url) . '">' . $icon_markup . '<h3>' . esc_html($item->title) . '</h3><p>' . esc_html(self::start_category_description_v150161($item->title)) . '</p><span>' . esc_html($button_page) . '</span></a>';
            }
            echo '</div></section>';
        }
        echo self::hub1_products_v150210();
        echo '<section class="pftk-hub1-banner-v150210 pftk-hub1-banner-main-v150210" aria-label="Werbung und Affiliate">' . self::hub1_banner_slot_v150211('hub_after_cards') . '</section>';
        echo self::hub1_posts_v150210($ctx, $hero['title']);
        echo '</div>';
        return ob_get_clean();
    }

