    /**
     * V1.50.282 – allgemeiner Designvertrag: schlanke Überschriften.
     *
     * Die geblockte Startseite ist ausschließlich die optische Referenz und wird
     * über is_front_page() vollständig von dieser Ausgabe ausgeschlossen.
     * Es wird ausschließlich font-weight gesetzt; keine Farbe, Schriftart,
     * Größe, Abstände, Ausrichtung oder sonstige Darstellung wird verändert.
     */
    public static function print_heading_weight_reference_contract_v150282() {
        if (is_admin() || is_front_page()) { return; }
        echo '<style id="pftk-heading-weight-reference-contract-v150282">'
            . 'html body h1,html body h2,html body h3,html body h4,html body h5,html body h6,'
            . 'html body .entry-title,html body .page-title,html body .wp-block-post-title,'
            . 'html body .wp-block-heading,html body .widget-title,'
            . 'html body .pftk-heading,html body .pftk-heading-card_title,'
            . 'html body .pftk-journal-category-copy-v150280>strong,'
            . 'html body .pftk-journal-banner-v150280>strong,'
            . 'html body .pftk-market-partner-placeholder-v150279>strong,'
            . 'html body .hp-page__title,html body .hp-listing__title,'
            . 'html body .hp-listing-category__name'
            . '{font-weight:400!important}'
            . '</style>';
    }

    public static function styles() {
        wp_register_style('pferde-template-kit', false, [], self::VERSION);
        wp_enqueue_style('pferde-template-kit');
        wp_add_inline_style('pferde-template-kit', self::css());
    }

    public static function render($type, $atts = []) {
        self::$rendered_types[$type] = true;
        // V1.50.161: Startseite vollständig neu und isoliert. Kein Alt-Renderer,
        // kein generischer Hero, kein altes Themen-/SEO-/Showcase-Markup.
        if ($type === 'start') { return self::render_startpage_v150176(); }
        if ($type === 'hub1') { return self::render_hub1_v150223(); }
        if ($type === 'hub2') { return self::render_hub2_v150255(); }
        if ($type === 'category') { return self::render_category_level_v150269(); }
        if ($type === 'leaf') { return self::render_leaf_level_v150272(); }
        if ($type === 'category') { self::$category_grid_ad_rendered = false; }
        $ctx = self::context($type);
        $page_id = 0;
        if (!is_admin() && is_singular('page')) {
            $page_id = absint(get_queried_object_id());
            if ($page_id <= 0) { $page_id = absint(get_the_ID()); }
        }
        $intro = $page_id > 0 ? self::category_intro_html($page_id, $type) : '';
        ob_start();
        echo '<div class="pftk pftk-' . esc_attr($type) . ($intro !== '' ? ' pftk-has-inline-intro' : '') . '">';
        echo $intro;
        if (self::should_render_hero($type)) { echo self::render_hero($type); }
        // Hub 1/2 verwenden ab V1.45.0 ausschließlich die integrierte Affiliate-Kachel
        // im 5/6-Raster. Zusätzliche obere/mittlere Hub-Banner werden nicht mehr
        // gerendert, damit Navigation und kommerzieller Hauptimpuls nicht konkurrieren.
        // Ebene 3 nutzt ausschließlich die kleine integrierte Werbekachel.
        // Große Werbeflächen und der frühere category_recommendation-Slot werden
        // nicht gerendert, damit alle Ebene-3-Seiten strukturell gleich bleiben.
        if ($type !== 'category' && self::visible($type, 'show_seo_top')) { echo self::render_seo($type, 'top'); }
        // Harte Regel ab V1.8.0: Ebene-3-Kategorie-Kacheln sind Pflicht.
        // Die Ausgabe haengt nicht vom Header-Menue und nicht vom normalen Themenblock ab.
        // Wenn passende WordPress-Kategorien erkannt wurden, werden sie sichtbar ausgegeben.
        $must_show_category_tiles = !empty($ctx['force_all_category_tiles']);
        if ($must_show_category_tiles) { self::$auto_category_tiles_appended = true; }
        if (current_user_can('manage_options') && !empty($ctx['category_tile_debug'])) { echo $ctx['category_tile_debug']; }
        if (self::visible($type, 'show_topics') || $must_show_category_tiles) {
            echo self::render_topics($type, $ctx);
            if ($must_show_category_tiles || $type === 'category') {
                // V1.49.2: Ebene 3 hat keine zusätzliche breite Werbefläche.
                // Die Werbeausgabe erfolgt ausschliesslich als kleine Rasterkachel.
                echo self::render_product_articles_after_category_tiles($type, $ctx);
            }
        }
        if (in_array($type, ['hub1', 'hub2'], true)) {
            // Klarer Hub-Workflow: Hauptkacheln -> weitere Themen -> Ratgeber.
            // Generischer Orientierungsblock, separater Medienblock und weitere
            // Hub-Bannerslots sind auf Hub 1/2 bewusst deaktiviert.
            echo self::render_hub_remaining_topics($type, $ctx);
            if (self::visible($type, 'show_posts')) { echo self::render_posts($type, $ctx); }
        }
        // Ebene 3 besitzt ausschließlich Kategorietext, Kategorie-Kacheln,
        // eine optionale kleine Werbekachel im Raster und den Artikelblock.
        // Kein Hero, kein Startseiten-/Orientierungsblock und kein zweiter SEO-Text.
        if ($type !== 'category' && self::visible($type, 'show_seo_bottom')) { echo self::render_seo($type, 'bottom'); }
        echo '</div>';
        return ob_get_clean();
    }

    private static function hub2_topic_label_v150255($title) {
        $title = trim(wp_strip_all_tags((string)$title));
        if ($title === '') { return 'diesem Thema'; }
        $key = self::normalize_match_key($title);
        $map = [
            'decken' => 'Pferdedecken',
            'sattel' => 'Pferdesättel',
            'trensen-gebisse' => 'Trensen und Gebisse',
            'halfter-stricke' => 'Halfter und Stricke',
