    private static function hub2_intro_v150264($page_id, $page_title) {
        $custom = $page_id > 0 ? trim((string)get_post_meta($page_id, 'portal_category_text', true)) : '';
        if ($custom !== '') { return $custom; }
        $key = self::normalize_match_key($page_title);
        $pilot = self::deck_intro_only_v150389('main/' . $key, '');
        if ($pilot !== '') { return $pilot; }
        $editorial = self::category_intro_editorial_page_batch1359_v150421($page_id);
        if ($editorial !== '') { return $editorial; }
        $profile = self::category_text_profile_for_page($page_id, $page_title);
        $focus = trim((string)($profile['focus'] ?? ('Auswahl, Einsatz und praktische Unterschiede rund um ' . $page_title)));
        $criteria = array_values(array_filter(array_map('trim', (array)($profile['criteria'] ?? ['Eignung','Qualität','Handhabung','Praxisnutzen']))));
        $parents = self::category_text_parent_titles($page_id, 1);
        $parent = trim((string)($parents[0] ?? ''));
        $children = self::category_text_terms_for_page($page_id, 'hub2');
        return self::portal_lower_intro_v150396($page_title, $focus, $criteria, $parent, $children, 'Ratgeber, Vergleiche und praktische Hinweise', 'hub2|' . self::normalize_match_key($parent) . '|' . $key);
    }

    private static function category_content_type_icon_v150265($title) {
        $key = self::normalize_match_key((string)$title);
        $map = [
            'beratung' => 'utility-advice', 'kaufberatung' => 'utility-advice', 'orientierung' => 'utility-advice',
            'faq' => 'utility-knowledge', 'fragen-antworten' => 'utility-knowledge',
            'vergleich' => 'utility-compare', 'vergleiche' => 'utility-compare',
            'pflege' => 'utility-health', 'reinigung' => 'utility-health',
            'anleitung' => 'utility-knowledge', 'checkliste' => 'utility-knowledge',
            'test' => 'utility-recommend', 'tests' => 'utility-recommend',
            'problemlosung' => 'utility-advice', 'ratgeber' => 'utility-knowledge',
        ];
        foreach ($map as $token => $icon) {
            if ($key === $token || strpos($key, $token) !== false) { return $icon; }
        }
        return 'utility-knowledge';
    }

    /**
     * V1.50.304: Die bestaetigten Beitragsart-Motive und SVG-Dateien bleiben
     * unveraendert. Der gemeinsame Renderer gibt Icon-, Titel-, Text- und
     * Buttonzone direkt mit Inline-!important aus. Damit kann spaeter geladenes
     * Theme-CSS die kartenuebergreifenden Achsen nicht mehr verschieben.
     *
     * Die lokal gemessenen optischen Iconkorrekturen bleiben erhalten. Sie
     * veraendern keine SVG-Datei, sondern nur deren Lage in der festen 44-x-44-
     * Flaeche. Die Inlineausgabe schliesst Lazyload-/Bildoptimierungseinfluesse
     * weiterhin aus.
     */
    private static function category_utility_icon_v150304($title) {
        $key = self::normalize_match_key((string)$title);
        if (strpos($key, 'vergleich') !== false) {
            $file = 'compare.svg';
        } elseif (strpos($key, 'faq') !== false || strpos($key, 'frage') !== false) {
            $file = 'faq.svg';
        } elseif (strpos($key, 'beratung') !== false || strpos($key, 'orientierung') !== false) {
            $file = 'advice.svg';
        } elseif (strpos($key, 'pflege') !== false || strpos($key, 'reinigung') !== false) {
            $file = 'care.svg';
        } elseif (strpos($key, 'sicherheit') !== false) {
            $file = 'safety.svg';
        } elseif (strpos($key, 'anwendung') !== false) {
            $file = 'application.svg';
        } elseif (strpos($key, 'kosten') !== false || strpos($key, 'preis') !== false) {
            $file = 'costs.svg';
        } elseif (strpos($key, 'installation') !== false || strpos($key, 'montage') !== false) {
            $file = 'installation.svg';
        } elseif (strpos($key, 'lagerung') !== false || strpos($key, 'aufbewahrung') !== false) {
            $file = 'storage.svg';
        } elseif (strpos($key, 'uebungen') !== false || strpos($key, 'training') !== false) {
            $file = 'exercises.svg';
        } elseif (strpos($key, 'alle-inhalte') !== false) {
            $file = 'all-content.svg';
        } elseif (strpos($key, 'check') !== false) {
            $file = 'checklist.svg';
        } elseif (strpos($key, 'anleitung') !== false) {
            $file = 'instructions.svg';
        } else {
            // V1.50.374 fail-closed: unbekannte Beitragsarten erhalten kein
            // allgemeines Dokumenticon, das eine fehlende Zuordnung verdeckt.
            return '';
        }

        $offsets = [
            'advice.svg' => 2,
            'care.svg' => 5,
            'checklist.svg' => 0,
            'compare.svg' => 2,
            'document.svg' => 0,
            'safety.svg' => 1,
            'application.svg' => 1,
            'costs.svg' => 1,
            'installation.svg' => 1,
            'storage.svg' => 1,
            'exercises.svg' => 1,
            'all-content.svg' => 1,
            'faq.svg' => 2,
            'instructions.svg' => 2,
        ];
        $optical_y = isset($offsets[$file]) ? intval($offsets[$file]) : 0;

        static $svg_cache = [];
        if (!isset($svg_cache[$file])) {
            $path = plugin_dir_path(__FILE__) . 'assets/category-icons-v150299/' . $file;
            $raw = is_readable($path) ? file_get_contents($path) : '';
            if (!is_string($raw) || strpos($raw, '<svg') === false) {
                $raw = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" stroke="#35422A" stroke-linecap="round" stroke-linejoin="round"><g transform="scale(2.6666666667)" stroke-width="0.61875"><path d="M5 4h14v16H5z"/><path d="M8 8h8M8 12h8M8 16h5"/></g></svg>';
            }
            $svg_open = '<svg class="pa304-inline-icon-svg" aria-hidden="true" focusable="false" role="presentation" width="44" height="44" preserveAspectRatio="xMidYMid meet" style="display:block!important;box-sizing:border-box!important;width:44px!important;height:44px!important;min-width:44px!important;min-height:44px!important;max-width:44px!important;max-height:44px!important;margin:0!important;padding:0!important;position:static!important;inset:auto!important;overflow:visible!important;transform:translate3d(0,' . $optical_y . 'px,0)!important;transform-origin:50% 50%!important;vertical-align:middle!important;" ';
            $raw = preg_replace('/<svg\s+/', $svg_open, trim($raw), 1);
            $svg_cache[$file] = is_string($raw) ? $raw : '';
        }

        return '<span class="pa267-utility-icon pa299-start-icon-reference pa304-inline-icon" data-pa299-icon="' . esc_attr(pathinfo($file, PATHINFO_FILENAME)) . '" data-pa304-optical-y="' . esc_attr((string)$optical_y) . '" aria-hidden="true" style="display:grid!important;grid-column:1!important;grid-row:1!important;place-items:center!important;align-self:start!important;justify-self:center!important;box-sizing:border-box!important;width:58px!important;height:58px!important;min-width:58px!important;min-height:58px!important;max-width:58px!important;max-height:58px!important;margin:0 auto!important;padding:0!important;position:static!important;inset:auto!important;transform:none!important;line-height:0!important;overflow:visible!important;contain:layout size style!important;color:#35422A!important;">' . $svg_cache[$file] . '</span>';
