    /**
     * V1.50.286: Seitenweite Exklusivpruefung fuer grosse Zwischenueberschriften.
     * Das exakte Seitenkeyword darf in diesem Satz hoechstens zweimal vorkommen.
     * Weitere Vorkommen werden nur aus der betroffenen Ueberschrift entfernt;
     * Karten, Texte, Layout und alle anderen Komponenten bleiben unberuehrt.
     */
    private static function enforce_section_heading_keyword_balance_v150286($headings, $title) {
        $headings = array_values((array)$headings);
        $title = trim((string)$title);
        if ($title === '') { return $headings; }

        $key = self::normalize_match_key($title);
        $primary = preg_split('/-+/u', $key, -1, PREG_SPLIT_NO_EMPTY)[0] ?? '';
        if ($primary === '' || mb_strlen($primary, 'UTF-8') < 4) { return $headings; }
        // Flexionsfester Wortstamm: Decke/Decken/Pferdedecken sowie
        // Sattel/Saettel/Sattelmarken werden als dieselbe Keyword-Familie gezaehlt.
        $root = preg_replace('/(ungen|ung|ern|en|er|es|e|n)$/u', '', $primary);
        $root_overrides = ['zubehoer'=>'zubeh','uebergangsdecken'=>'bergangsdeck','ubergangsdecken'=>'bergangsdeck'];
        if (isset($root_overrides[$key])) { $root = $root_overrides[$key]; }
        elseif (isset($root_overrides[$primary])) { $root = $root_overrides[$primary]; }
        if (mb_strlen((string)$root, 'UTF-8') < 4) { $root = $primary; }

