        $root_pattern = str_replace(['ae','oe','ue'], ['(?:ae|ä)','(?:oe|ö)','(?:ue|ü)'], $root_pattern);
        $seen = 0;
        $replacement_index = 0;
        foreach ($headings as $i => $heading) {
            $pattern = '/\b[\p{L}]*' . $root_pattern . '[\p{L}]*/iu';
            $count = preg_match_all($pattern, (string)$heading, $matches);
            if (!$count) { continue; }
            if ($seen + $count <= 2) { $seen += $count; continue; }

            $allowed_here = max(0, 2 - $seen);
            $local_seen = 0;
            $heading = preg_replace_callback($pattern, static function($match) use (&$local_seen, $allowed_here, &$replacement_index, $replacements) {
                $local_seen++;
                if ($local_seen <= $allowed_here) { return $match[0]; }
                if (!$replacements) { return ''; }
                $replacement = $replacements[$replacement_index % count($replacements)];
                $replacement_index++;
                return $replacement;
            }, (string)$heading);
