    private static function category_level_text_profile_v150269($page_id, $title) {
        $title = trim((string)$title);
        if ($title === '') { $title = 'Themenbereich'; }
        $key = self::normalize_match_key($title);
        $profiles = self::category_text_topic_profiles();
        $profile = isset($profiles[$key]) && is_array($profiles[$key]) ? $profiles[$key] : [];
        $focus = trim((string)($profile['focus'] ?? ('Auswahl, Nutzung und Pflege von ' . $title)));
        $criteria = array_values(array_filter(array_map('trim', (array)($profile['criteria'] ?? ['Einsatz', 'Qualität', 'Passform', 'Pflege']))));
        while (count($criteria) < 4) { $criteria[] = 'Praxisnutzen'; }

        $kickers = [
            'regendecken' => 'Trocken durch Regen und Wind',
            'winterdecken' => 'Wärme, wenn dein Pferd sie braucht',
            'uebergangsdecken' => 'Gut gerüstet für wechselhafte Tage',
