    private static function category_type_card_text_v150268($item_title, $category_title) {
        $item_title = trim((string)$item_title);
        $category_title = trim((string)$category_title);
        $key = self::normalize_match_key($item_title);

        // V1.50.307 – kompakter allgemeingültiger Beitragsart-Kachelvertrag:
        // Im sichtbaren Kachelblock werden keine redundanten Beschreibungstexte
        // mehr ausgegeben. Diese Funktion erzeugt ausschließlich die eindeutige
        // dunkelolive Kartenüberschrift; Icon und CTA liefern die übrige Führung.
        if (strpos($key, 'vergleich') !== false) {
            return ['title' => $category_title . ' vergleichen'];
        }
        if (strpos($key, 'kosten') !== false || strpos($key, 'preis') !== false) {
            return ['title' => 'Kosten von ' . $category_title];
        }
        if (strpos($key, 'pflege') !== false || strpos($key, 'reinigung') !== false) {
            return ['title' => $category_title . ' richtig pflegen'];
        }
        if (strpos($key, 'faq') !== false || strpos($key, 'frage') !== false) {
            return ['title' => 'Häufige Fragen zu ' . $category_title];
        }
        if (strpos($key, 'beratung') !== false || strpos($key, 'orientierung') !== false) {
            return ['title' => 'Beratung zu ' . $category_title];
        }
        if (strpos($key, 'checkliste') !== false || strpos($key, 'check') !== false) {
            return ['title' => 'Checkliste für ' . $category_title];
        }
        if (strpos($key, 'anleitung') !== false) {
            return ['title' => 'Anleitungen zu ' . $category_title];
        }
        return ['title' => $item_title];
    }

    private static function category_affiliate_slot_v150266($index, $title) {
        $index = max(1, min(3, intval($index)));
        $slot = 'category_product_' . $index;
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            $candidate = (string)do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]');
            if (self::hub1_product_content_is_real_v150214($candidate)) {
                return '<div class="pa266-product is-real" data-pa266-slot="' . esc_attr($slot) . '">' . $candidate . '</div>';
            }
        }
        return '<article class="pa266-product is-placeholder" data-pa266-slot="' . esc_attr($slot) . '"><div class="pa266-product-image">Produktbild aus Affiliate-Feed</div><div><small>Affiliate-Empfehlung</small><h3>Passende Empfehlung zu ' . esc_html($title) . '</h3><p>Hier erscheint automatisch ein konkretes Produkt eines externen Händlers.</p><a href="#" rel="nofollow sponsored">Beim Händler ansehen</a></div></article>';
    }


    /**
     * V1.50.308 – bekannte öffentliche Platzhalter, Eigenwerbung und
     * historische Design-Fallbacks dürfen niemals als reales Affiliate-
     * Werbemittel gewertet werden.
     */
    private static function category_affiliate_content_is_placeholder_v150308($candidate) {
        $candidate = trim((string)$candidate);
        if ($candidate === '') { return true; }
        $haystack = strtolower($candidate . ' ' . wp_strip_all_tags($candidate));
        $markers = [
            'pftk-affiliate-placeholder-v15072',
            'pftk-affiliate-slot-debug',
            'pftk-start-ad-slot-v150162',
            'pftk-ad-contact-link-v150218',
            'pftk-ad-wide-layer-v150177',
            'affiliate-werbefläche',
            'affiliate werbefläche',
            'thematisch passender affiliate-banner',
            'produktbild aus affiliate-feed',
            'affiliate-empfehlung',
            'passende empfehlung zu',
            'hier erscheint automatisch ein konkretes produkt',
            'noch nicht belegt',
            'nicht belegt',
            'placeholder',
            'platzhalter',
            'hier könnte ihre werbung stehen',
            'hier könnte ihre anzeige stehen',
            'das könnte dein werbeplatz sein',
            'werbeplatz anfragen',
            'exklusive werbefläche',
        ];
        foreach ($markers as $marker) {
            if (strpos($haystack, $marker) !== false) { return true; }
        }
        return false;
    }

    /**
     * V1.50.308 – echte Produktinhalte können klassische Links/Bilder,
     * native Widgets, iframe- oder scriptbasierte Händlerausgaben sein.
     * Bekannte Platzhalter werden vorher hart ausgeschlossen.
     */
    private static function category_affiliate_product_is_real_v150308($candidate) {
        $candidate = trim((string)$candidate);
        if (self::category_affiliate_content_is_placeholder_v150308($candidate)) { return false; }
        $lower = strtolower($candidate);
        $plain = trim(wp_strip_all_tags($candidate));
        $has_link = stripos($candidate, '<a') !== false && stripos($candidate, 'href=') !== false;
        $has_widget = stripos($candidate, '<iframe') !== false || stripos($candidate, '<script') !== false || strpos($lower, 'data-amazon') !== false || strpos($lower, 'data-affiliate') !== false;
        $has_visual = stripos($candidate, '<img') !== false || stripos($candidate, '<picture') !== false || stripos($candidate, '<video') !== false;
        return $has_widget || ($has_link && ($has_visual || mb_strlen($plain) >= 12));
    }

    /**
     * V1.50.308 – echte Banner müssen ein auslieferbares Werbemittel sein.
     * Der historische eigene Werbeplatz ist ausdrücklich kein Affiliate-
     * Banner und wird durch die Platzhalterprüfung ausgeschlossen.
     */
    private static function category_affiliate_banner_is_real_v150308($candidate) {
        $candidate = trim((string)$candidate);
        if (self::category_affiliate_content_is_placeholder_v150308($candidate)) { return false; }
        $lower = strtolower($candidate);
        $plain = trim(wp_strip_all_tags($candidate));
        $has_link = stripos($candidate, '<a') !== false && stripos($candidate, 'href=') !== false;
        $has_widget = stripos($candidate, '<iframe') !== false || stripos($candidate, '<script') !== false || strpos($lower, 'data-affiliate') !== false;
        $has_visual = stripos($candidate, '<img') !== false || stripos($candidate, '<picture') !== false || stripos($candidate, '<video') !== false;
        return $has_widget || ($has_link && ($has_visual || mb_strlen($plain) >= 12));
    }

    /**
     * V1.50.308 – Admin-Vorschau ist ausschließlich für eingeloggte
     * Administratoren bestimmt. Normale Besucher sehen niemals Vorschau-
     * oder Platzhalterkarten. ?pftk_affiliate_preview=0 deaktiviert sie;
     * 1, 2 oder 3 erzwingt die jeweilige Produktanzahl für die Designprüfung.
     */
    private static function category_affiliate_admin_preview_count_v150308() {
        if (!function_exists('current_user_can') || !current_user_can('manage_options')) { return 0; }
        if (isset($_GET['pftk_affiliate_preview'])) {
            $requested = intval($_GET['pftk_affiliate_preview']);
            if ($requested <= 0) { return 0; }
            return max(1, min(3, $requested));
        }
        return 3;
    }

    private static function category_affiliate_product_preview_v150308($index, $title) {
