    }

    /**
     * V1.50.308 – öffentlich ausschließlich tatsächlich befüllte Produkte.
     * Wenn noch keine echte Feed-Auslieferung vorhanden ist, erhalten nur
     * Administratoren eine moderne 1/2/3-Karten-Vorschau zur Designprüfung.
     */
    /**
     * V1.50.341 – reale Produktbefüllung auf der gesamten Ebene derselben
     * strukturellen Tiefe wie „Regendecken“. Prüfvorschauen werden bewusst
     * getrennt erzeugt, damit der Direktwerbe-Fallback nicht durch Admin-
     * Platzhalter verfälscht wird.
     */
    private static function category_real_affiliate_products_only_v150341() {
        $products = [];
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            for ($index = 1; $index <= 3; $index++) {
                $slot = 'category_product_' . $index;
                $candidate = (string)do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]');
                if (!self::category_affiliate_product_is_real_v150308($candidate)) { continue; }
                $products[] = '<div class="pa266-product is-real" data-pa266-slot="' . esc_attr($slot) . '">' . $candidate . '</div>';
            }
        }
        return $products;
    }

    /**
     * Kompatibilitätsmethode für bestehende interne Aufrufer: reale Produkte
     * oder – nur für Administratoren – die bereits bekannte Designvorschau.
     */
    private static function category_real_affiliate_products_v150306($title = '') {
        $products = self::category_real_affiliate_products_only_v150341();
        if ($products) { return $products; }
        $preview_count = self::category_affiliate_admin_preview_count_v150308();
        for ($index = 1; $index <= $preview_count; $index++) {
            $products[] = self::category_affiliate_product_preview_v150308($index, trim((string)$title) !== '' ? trim((string)$title) : 'Produkt');
        }
        return $products;
    }

    /**
     * V1.50.308 – öffentlich nur ein reales Affiliate-Banner. Historische
     * Eigenwerbe-/Direktverkaufsbanner werden hart verworfen. Administratoren
     * sehen bei fehlender Befüllung eine neutrale moderne Vorschau.
     */
    /**
     * V1.50.341 – ausschließlich reale Bannerbefüllung. Die Trennung von
     * realer Ausgabe und Admin-Vorschau ist Voraussetzung für die korrekte
     * Fallbackentscheidung.
     */
    private static function category_real_affiliate_banner_only_v150341() {
        $banner = trim((string)self::render_design_affiliate_slot('category', 'product_after_category_tiles'));
        return self::category_affiliate_banner_is_real_v150308($banner) ? $banner : '';
    }

    /**
     * Kompatibilitätsmethode für bestehende interne Aufrufer.
     */
    private static function category_real_affiliate_banner_v150306() {
        $banner = self::category_real_affiliate_banner_only_v150341();
        if ($banner !== '') { return $banner; }
        if (self::category_affiliate_admin_preview_count_v150308() > 0) {
            return self::category_affiliate_banner_preview_v150308();
        }
        return '';
    }

    /**
     * Administratorischer Vier-Zustände-Test ohne Einfluss auf Besucher:
     * ?pftk_category_affiliate_test=both|banner|products|none
     */
    private static function category_affiliate_test_state_v150341() {
        if (!function_exists('current_user_can') || !current_user_can('manage_options')) { return ''; }
        if (!isset($_GET['pftk_category_affiliate_test'])) { return ''; }
        $raw = (string)$_GET['pftk_category_affiliate_test'];
        if (function_exists('wp_unslash')) { $raw = wp_unslash($raw); }
        $state = sanitize_key($raw);
        return in_array($state, ['both', 'banner', 'products', 'none'], true) ? $state : '';
    }

    /**
     * V1.50.341 – gemeinsame Anzeigelogik für alle Produkt-/Kategorie-Seiten
     * derselben Ebene wie „Regendecken“:
     * - Banner und Produkte befüllt: kein Direktwerbeplatz;
     * - genau einer der beiden Bereiche fehlt: vorhandener Bereich plus
     *   Direktwerbeplatz;
     * - beide fehlen: ausschließlich Direktwerbeplatz;
     * - öffentlich niemals mehr als zwei Werbezonen.
     */
    private static function category_affiliate_layout_v150341($title = '') {
        $real_banner = self::category_real_affiliate_banner_only_v150341();
        $real_products = self::category_real_affiliate_products_only_v150341();
        $test_state = self::category_affiliate_test_state_v150341();

        if ($test_state !== '') {
            $show_banner = in_array($test_state, ['both', 'banner'], true);
            $show_products = in_array($test_state, ['both', 'products'], true);
            $products = [];
            if ($show_products) {
                $count = self::category_affiliate_admin_preview_count_v150308();
                if ($count <= 0) { $count = 3; }
                for ($index = 1; $index <= $count; $index++) {
                    $products[] = self::category_affiliate_product_preview_v150308($index, trim((string)$title) !== '' ? trim((string)$title) : 'Produkt');
                }
            }
            return [
                'banner' => $show_banner ? self::category_affiliate_banner_preview_v150308() : '',
                'products' => $products,
                'direct_visible' => !($show_banner && $show_products),
                'real_banner_filled' => $real_banner !== '',
                'real_products_filled' => count($real_products) > 0,
                'test_state' => $test_state,
            ];
        }

        $admin_preview = function_exists('current_user_can') && current_user_can('manage_options');
        $display_banner = $real_banner;
        $display_products = $real_products;
        if ($admin_preview) {
            if ($display_banner === '') { $display_banner = self::category_affiliate_banner_preview_v150308(); }
            if (!$display_products) {
                $count = self::category_affiliate_admin_preview_count_v150308();
                for ($index = 1; $index <= $count; $index++) {
                    $display_products[] = self::category_affiliate_product_preview_v150308($index, trim((string)$title) !== '' ? trim((string)$title) : 'Produkt');
                }
            }
        }

        return [
            'banner' => $display_banner,
            'products' => $display_products,
            'direct_visible' => $admin_preview ? false : ($real_banner === '' || count($real_products) === 0),
            'real_banner_filled' => $real_banner !== '',
            'real_products_filled' => count($real_products) > 0,
            'test_state' => '',
        ];
    }

    /**
     * V1.50.272: Letzte Kategorieebene. Schwerpunkt sind reale Einzelbeitraege.
     * Keine weitere Unterkategorie-/Inhaltsarten-Navigation.
     */
    /**
     * V1.50.333 – Textprofil des tatsächlich live verwendeten Leaf-SEITEN-Renderers.
     * Ausschließlich Seiten vom strukturellen Typ "leaf". Keine Kategoriearchive,
     * Hubseiten oder Einzelbeiträge werden hier verändert.
     */
    private static function leaf_level_text_profile_v150272($page_id, $title) {
        $title = trim((string)$title);
        $parents = self::category_text_parent_titles($page_id, 2);
        $parent_topic = trim((string)($parents[0] ?? ''));
        $hub_topic = trim((string)($parents[1] ?? ''));

        $type_map = [
            'faq' => 'FAQ', 'beratung' => 'Beratung', 'vergleich' => 'Vergleich',
            'pflege' => 'Pflege', 'sicherheit' => 'Sicherheit', 'anwendung' => 'Anwendung',
            'kosten' => 'Kosten', 'installation' => 'Installation', 'lagerung' => 'Lagerung',
            'uebungen' => 'Übungen', 'uebung' => 'Übungen', 'anleitung' => 'Anleitung',
            'checklisten' => 'Checkliste', 'checkliste' => 'Checkliste', 'test' => 'Test',
        ];
        $normalized = self::normalize_match_key($title);
        $type = 'Beratung';
        $matched_token = '';
        foreach ($type_map as $token => $label) {
            if (preg_match('/(?:^|-)' . preg_quote($token, '/') . '(?:-|$)/', $normalized)) {
                $type = $label;
                $matched_token = $token;
                break;
            }
        }

        $topic = $title;
        if ($matched_token !== '') {
            $topic = trim((string)preg_replace('/\b' . preg_quote(str_replace('-', ' ', $matched_token), '/') . '\b/iu', '', $topic, 1));
        }
        $topic = trim((string)preg_replace('/\s{2,}/u', ' ', $topic));
        if ($topic === '') { $topic = $parent_topic; }
        if ($topic === '') { $topic = 'dieses Thema'; }

        $profile = self::leaf_category_topic_profile_v150330($topic);
        $criteria = array_values(array_filter(array_map('trim', (array)($profile['criteria'] ?? []))));
        while (count($criteria) < 4) { $criteria[] = 'Praxisnutzen'; }

        $posts_titles = [
            'FAQ' => 'Antworten aus der Praxis',
            'Beratung' => 'Orientierung für deine Entscheidung',
            'Vergleich' => 'Ratgeber und Vergleiche',
