        $profile = isset($profiles[$key]) && is_array($profiles[$key]) ? $profiles[$key] : [];
        $focus = trim((string)($profile['focus'] ?? ('passende Lösungen rund um ' . $category)));
        $criteria = array_values(array_filter(array_map('trim', (array)($profile['criteria'] ?? ['Einsatz', 'Qualität', 'Passform', 'Pflege']))));
