            'post_placeholder_text' => 'Ein passender Praxisbeitrag wird hier ergänzt.',
            'post_placeholder_button' => 'Weiterlesen',
        ];
        $section_headings = self::contextual_section_headings_v150286($category, $focus, $criteria);
        foreach (['topics_title','network_title','products_title','direct_title','guide_title','more_title','posts_title'] as $field) {
            if (!empty($section_headings[$field])) { $texts[$field] = $section_headings[$field]; }
        }
        foreach ($texts as $field => $value) {
            $custom = $page_id > 0 ? trim((string)get_post_meta($page_id, 'portal_hub2_text_' . $field, true)) : '';
            if ($custom !== '') { $texts[$field] = $custom; }
