        $texts = apply_filters('pftk_hub2_text_profile_v150269', $texts, $page_id, $page_title, $topic);
        if (!is_array($texts)) { $texts = []; }
        // V1.50.323 – verbindliche redaktionell individuelle Affiliate-Ueberschriften fuer
