        $texts['network_kicker'] = 'Ausgewählter Partner';
        $texts['network_title'] = $affiliate_headings['network_title'];
        $texts['network_intro'] = '';
        $texts['products_kicker'] = 'Produktvorschläge';
        $texts['products_title'] = $affiliate_headings['products_title'];
        $texts['products_intro'] = '';
        // V1.50.324 – Der direkt buchbare Werbeplatz übernimmt auf der gesamten
        // Hub-2-Ebene exakt den bereits geblockten Regendecken-Vertrag.
        // Keine themenspezifische Werbeüberschrift und kein erklärender Untertext.
        $texts['direct_kicker'] = 'Direkt buchbarer Werbeplatz';
        $texts['direct_title'] = 'Das könnte Dein Werbeplatz sein';
        $texts['direct_intro'] = '';
        // V1.50.325 – letzter Ratgeberblock: individuell, breit genug für
        // Auswahl, Nutzung und Pflege, mit genau einem Hauptthema in der H2.
        // Der generische Untertext entfällt als redundante Wiederholung.
        $texts['posts_kicker'] = 'Wissen aus der Praxis';
        $texts['posts_title'] = self::hub2_guide_heading_v150325($topic);
        $texts['posts_intro'] = '';
        $texts['post_button'] = self::article_excerpt_cta_v150325();
        $texts['post_placeholder_button'] = self::article_excerpt_cta_v150325();
        $texts['topic_button'] = self::topic_cta_v150325();
        return $texts;
    }

