    private static function hub2_tile_slug_v150318($item) {
        $slug = '';
        if (in_array((string)($item->object ?? ''), ['page','post'], true)) {
            $object_id = absint($item->object_id ?? 0);
            if ($object_id > 0 && function_exists('get_post_field')) {
                $slug = trim((string)get_post_field('post_name', $object_id));
            }
        }
        if ($slug === '') {
            $path = trim((string)parse_url((string)($item->url ?? ''), PHP_URL_PATH), '/');
            if ($path !== '') {
                $parts = array_values(array_filter(explode('/', $path), 'strlen'));
                $slug = (string)end($parts);
            }
        }
        return sanitize_title($slug);
    }

    private static function hub2_tile_teaser_clean_v150318($text, $title = '') {
        $text = trim(wp_strip_all_tags(strip_shortcodes((string)$text)));
        if ($text === '') { return ''; }
        $text = preg_replace('/\s+/u', ' ', $text);
        if (preg_match('/\b(?:Pferde)?alltag\b/iu', $text)) { return ''; }
        if (preg_match('/\bIm Pferde Atelier\b/iu', $text)) { return ''; }
        if (preg_match('/\bHier findest du\b/iu', $text)) { return ''; }
        if (preg_match('/wirklich\s+ankommt/iu', $text)) { return ''; }
        $text = trim($text, " \t\n\r\0\x0B,;:-");
        if ($text === '') { return ''; }

        $title = trim(wp_strip_all_tags((string)$title));
        if ($title !== '') {
            $quoted = preg_quote($title, '/');
            if (preg_match('/^' . $quoted . '\s+(?:gehört|gehören)\b/iu', $text)) { return ''; }
            if (preg_match('/^' . $quoted . '\s+(?:ist|sind)\s+(?:im|in der|für den|wichtig)\b/iu', $text)) { return ''; }
        }
        $text = wp_trim_words($text, 11, '');
        $text = rtrim(trim($text), " \t\n\r\0\x0B,;:-.!?");
        $words = preg_split('/\s+/u', $text, -1, PREG_SPLIT_NO_EMPTY);
        if ($text === '' || count((array)$words) < 4) { return ''; }
        return $text . '.';
    }

    private static function hub2_tile_teaser_v150318($item, $parent_title = '', $seen = []) {
        $slug = self::hub2_tile_slug_v150318($item);
        $map = self::hub2_tile_teaser_map_v150318();
        if ($slug !== '' && isset($map[$slug])) { return $map[$slug]; }

        $title = trim((string)($item->title ?? ''));
        $title_key = sanitize_title($title);
        $context_key = sanitize_title((string)$parent_title) . '|' . $title_key;
        $context_map = self::hub2_tile_teaser_context_map_v150318();
        if ($title_key !== '' && isset($context_map[$context_key])) { return $context_map[$context_key]; }
        $title_map = self::hub2_tile_teaser_title_map_v150318();
        if ($title_key !== '' && isset($title_map[$title_key])) { return $title_map[$title_key]; }

        // Neue, noch nicht katalogisierte Seiten nutzen nur tatsächlich gepflegte
        // individuelle Inhalte. Allgemeine Serien- und Fallbacksätze werden nicht gezeigt.
        $raw = [];
        if (in_array((string)($item->object ?? ''), ['page','post'], true)) {
            $object_id = absint($item->object_id ?? 0);
            if ($object_id > 0 && get_post_meta($object_id, self::META_PAGE_SHORTLINE_HIDDEN, true) !== '1') {
                $shortline = trim((string)get_post_meta($object_id, self::META_PAGE_SHORTLINE, true));
                if ($shortline !== '') { $raw[] = $shortline; }
            }
        }
        $excerpt = trim((string)self::item_excerpt($item));
        if ($excerpt !== '' && stripos($excerpt, 'Direkt zur nächsten Themenebene') === false) {
            foreach ((array)preg_split('/(?<=[.!?])\s+/u', $excerpt, -1, PREG_SPLIT_NO_EMPTY) as $sentence) {
                $raw[] = $sentence;
            }
        }
        foreach ($raw as $candidate) {
            $candidate = self::hub2_tile_teaser_clean_v150318($candidate, $title);
            $signature = self::normalize_match_key($candidate);
            if ($candidate !== '' && $signature !== '' && empty($seen[$signature])) { return $candidate; }
        }
        return '';
    }

    /**
     * V1.50.320 – Prüfansicht für sämtliche Hub-2-Seiten derselben Ebene.
     * Eingeloggte Benutzer sehen bei fehlender realer Befüllung neutrale
     * Vorschauen. Öffentliche Besucher sehen ausschließlich echte Inhalte.
     */
    private static function hub2_affiliate_preview_enabled_v150320() {
        return function_exists('is_user_logged_in') && is_user_logged_in();
    }

    private static function hub2_affiliate_preview_count_v150320() {
        if (!self::hub2_affiliate_preview_enabled_v150320()) { return 0; }
        if (isset($_GET['pftk_affiliate_preview'])) {
            $requested = intval($_GET['pftk_affiliate_preview']);
            if ($requested >= 1 && $requested <= 3) { return $requested; }
        }
        return 3;
    }

    private static function hub2_affiliate_banner_preview_v150320() {
        return '<div class="pa320-banner-preview" data-pa320-login-preview="1" role="img" aria-label="Eingeloggte Vorschau eines Affiliate-Banners"><small>Nur eingeloggte Vorschau</small><strong>Affiliate-Banner</strong></div>';
    }

    private static function hub2_affiliate_product_preview_v150320($index, $topic) {
        $index = max(1, min(3, intval($index)));
        $topic = trim((string)$topic) !== '' ? trim((string)$topic) : 'diesem Thema';
        return '<article class="pa255-product is-preview" data-pa320-login-preview="1"><div class="pa255-product-image"><span>Produktvorschau</span><small>spätere Feed-Ausgabe</small></div><div><span>Partnerprodukt</span><h3>' . esc_html($topic . ' – Produkt ' . $index) . '</h3><p>Vorschau der später automatisch befüllten Produktkarte.</p><b>Beim Händler ansehen</b></div></article>';
    }

    /**
     * V1.50.339 – Reale Hub-2-Befüllung wird einmalig und getrennt von der
     * eingeloggten Prüfvorschau ermittelt. Diese Trennung ist erforderlich,
     * damit der direkt buchbare Werbeplatz ausschließlich als echter Fallback
     * auf fehlende Partner- oder Produktbefüllung reagieren kann.
     */
    private static function hub2_real_affiliate_banner_v150339() {
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            $candidate = trim((string)do_shortcode('[pp_affiliate_slot type="hub_after_cards" intent="portal_context"]'));
            if (self::category_affiliate_banner_is_real_v150308($candidate)) { return $candidate; }
        }
        return '';
    }

    private static function hub2_real_affiliate_products_v150339() {
        $products = [];
        if (!function_exists('shortcode_exists') || !shortcode_exists('pp_affiliate_slot')) { return $products; }
        for ($index = 1; $index <= 3; $index++) {
            $slot = 'category_product_' . $index;
            $candidate = trim((string)do_shortcode('[pp_affiliate_slot type="' . esc_attr($slot) . '" intent="portal_context"]'));
            if (!self::category_affiliate_product_is_real_v150308($candidate)) { continue; }
            $products[] = '<div class="pa255-product is-real" data-pa255-slot="' . esc_attr($slot) . '">' . $candidate . '</div>';
        }
        return $products;
    }

    /**
     * Administratorischer Vier-Zustände-Test ohne Einfluss auf Besucher:
     * ?pftk_hub2_affiliate_test=both|banner|products|none
     */
    private static function hub2_affiliate_test_state_v150339() {
        if (!self::hub2_affiliate_preview_enabled_v150320()) { return ''; }
        if (function_exists('current_user_can') && !current_user_can('manage_options')) { return ''; }
        if (!isset($_GET['pftk_hub2_affiliate_test'])) { return ''; }
        $raw = (string)$_GET['pftk_hub2_affiliate_test'];
        if (function_exists('wp_unslash')) { $raw = wp_unslash($raw); }
        $state = sanitize_key($raw);
        return in_array($state, ['both', 'banner', 'products', 'none'], true) ? $state : '';
    }

    /**
     * V1.50.339 – Gemeinsame, deterministische Ausgabelogik für alle Seiten
     * derselben Hub-2-Ebene:
     * - öffentlich: echte Inhalte; Direktwerbung genau dann, wenn Banner ODER
     *   Produkte fehlen;
     * - eingeloggt: fehlende Bereiche bleiben als bekannte Prüfvorschau
     *   sichtbar; der Direktwerbe-Fallback wird über den Vier-Zustände-Test
     *   isoliert geprüft, damit niemals drei Werbezonen zugleich erscheinen.
     */
    private static function hub2_affiliate_layout_v150339($topic = '') {
        $real_banner = self::hub2_real_affiliate_banner_v150339();
        $real_products = self::hub2_real_affiliate_products_v150339();
        $test_state = self::hub2_affiliate_test_state_v150339();

        if ($test_state !== '') {
            $show_banner = in_array($test_state, ['both', 'banner'], true);
            $show_products = in_array($test_state, ['both', 'products'], true);
            $products = [];
            if ($show_products) {
                $count = self::hub2_affiliate_preview_count_v150320();
                if ($count <= 0) { $count = 3; }
                for ($index = 1; $index <= $count; $index++) {
                    $products[] = self::hub2_affiliate_product_preview_v150320($index, $topic);
                }
            }
            return [
                'banner' => $show_banner ? self::hub2_affiliate_banner_preview_v150320() : '',
                'products' => $products,
                'direct_visible' => !($show_banner && $show_products),
                'real_banner_filled' => $real_banner !== '',
                'real_products_filled' => count($real_products) > 0,
                'test_state' => $test_state,
            ];
        }

        $logged_in = self::hub2_affiliate_preview_enabled_v150320();
        $display_banner = $real_banner;
        $display_products = $real_products;
        if ($logged_in) {
            if ($display_banner === '') { $display_banner = self::hub2_affiliate_banner_preview_v150320(); }
            if (!$display_products) {
                $count = self::hub2_affiliate_preview_count_v150320();
                for ($index = 1; $index <= $count; $index++) {
                    $display_products[] = self::hub2_affiliate_product_preview_v150320($index, $topic);
                }
            }
        }

        return [
            'banner' => $display_banner,
            'products' => $display_products,
            'direct_visible' => $logged_in ? false : ($real_banner === '' || count($real_products) === 0),
            'real_banner_filled' => $real_banner !== '',
            'real_products_filled' => count($real_products) > 0,
            'test_state' => '',
        ];
    }

    /**
     * Kompatibilitätsmethoden für bestehende interne Tests und Aufrufer.
     */
    private static function hub2_affiliate_banner_v150320() {
        $layout = self::hub2_affiliate_layout_v150339('');
