    private static function start_resolve_page_v150170(array $paths) {
        foreach ($paths as $path) {
            $path = trim((string)$path, '/');
            if ($path === '') { continue; }
            $page = get_page_by_path($path, OBJECT, 'page');
            if ($page instanceof WP_Post && $page->post_status === 'publish') {
                return ['title' => get_the_title($page), 'url' => get_permalink($page), 'id' => (int)$page->ID];
            }
        }
        return null;
    }

    /** V1.50.203: Semantische, dublettenfreie Startseiten-Grafikzuordnung. */
    private static function start_icon_catalog_v150203() {
        return ['equipment','feeding','health','stable','training','transport','horse','knowledge','market','search','compare','recommend','provider'];
    }

    private static function start_icon_semantic_candidates_v150203($title, $url = '') {
        $haystack = self::normalize_match_key(trim((string)$title . ' ' . (string)$url));
        $rules = [
            'feeding' => ['futter','fuetter','ernahrung','heu','mineral','raufutter','kraftfutter','pferdefutter','tranke','wasser'],
            'health' => ['gesund','erste-hilfe','tierarzt','krank','wunde','huf','pflege','vorsorge','therapie'],
            'stable' => ['stall','haltung','weide','offenstall','unterstand','box','paddock'],
            'training' => ['training','ausbildung','reitweise','reiten','bodenarbeit','dressur','springen','longier'],
            'transport' => ['transport','anhaenger','pferdeanhaenger','verladen','turnierfahrt'],
            'market' => ['anzeigen','markt','anbieter','dienstleister','shop','verkauf','kaufen'],
            'horse' => ['pferd-verstehen','verhalten','kommunikation','rasse','pferdetyp','pferde-verstehen'],
            'compare' => ['vergleich','vergleichen','entscheidung','kaufberatung'],
            'search' => ['suche','finden','orientierung','ratgeber'],
            'recommend' => ['empfehlung','produkte','produkt','auswahl'],
            'knowledge' => ['wissen','magazin','journal','artikel','lexikon','recht','finanzen','organisation'],
            'equipment' => ['ausruestung','sattel','decke','halfter','trense','zubehoer','reiterbedarf'],
            'provider' => ['anbieter','service','dienstleistung'],
        ];
        $matched = [];
        foreach ($rules as $icon => $tokens) {
            foreach ($tokens as $token) {
                if ($haystack === $token || strpos($haystack, $token) !== false) { $matched[] = $icon; break; }
            }
        }
        if (!$matched) { $matched = ['horse','knowledge','equipment','search']; }
        return array_values(array_unique(array_merge($matched, self::start_icon_catalog_v150203())));
    }

    private static function start_icon_assign_unique_v150203($title, $url, $preferred, &$used) {
        $catalog = self::start_icon_catalog_v150203();
        $candidates = self::start_icon_semantic_candidates_v150203($title, $url);
        $preferred = sanitize_key((string)$preferred);
        if ($preferred !== '' && $preferred !== 'auto' && in_array($preferred, $catalog, true) && in_array($preferred, $candidates, true) && empty($used[$preferred])) {
            $used[$preferred] = true;
            return $preferred;
        }
        foreach ($candidates as $candidate) {
            if (in_array($candidate, $catalog, true) && empty($used[$candidate])) {
                $used[$candidate] = true;
                return $candidate;
            }
        }
        return 'horse';
    }

