    private static function start_category_art_key_v150170($title, $url = '', &$used = null) {
        if (!is_array($used)) { $used = []; }
        return self::start_icon_assign_unique_v150203($title, $url, 'auto', $used);
    }

    private static function start_categories_v150170() {
        $definitions = [
            ['title' => 'Ausrüstung', 'paths' => ['ausruestung'], 'description' => 'Ausrüstung, Pflege und Zubehör für Pferd und Reiter.'],
            ['title' => 'Gesundheit', 'paths' => ['gesundheit'], 'description' => 'Vorsorge, Pflege und Gesundheit des Pferdes.'],
            ['title' => 'Fütterung', 'paths' => ['fuetterung'], 'description' => 'Pferdefutter, Ergänzung und Fütterung im Alltag.'],
            ['title' => 'Stall', 'paths' => ['stall'], 'description' => 'Haltung, Stallalltag und praktische Lösungen.'],
        ];
        $ctx = self::context('start');
        $pool = array_values((array)($ctx['top_items'] ?? []));
        $items = [];
        foreach ($definitions as $definition) {
            $found = null;
            $wanted = self::normalize_match_key($definition['title']);
            foreach ($pool as $candidate) {
                if (!is_object($candidate) && !is_array($candidate)) { continue; }
                $title = is_object($candidate) ? (string)($candidate->title ?? $candidate->label ?? '') : (string)($candidate['title'] ?? $candidate['label'] ?? '');
                $url = is_object($candidate) ? (string)($candidate->url ?? '') : (string)($candidate['url'] ?? '');
                $haystack = self::normalize_match_key($title . ' ' . $url);
                if ($haystack === $wanted || strpos($haystack, $wanted) !== false) {
                    $found = ['title' => $definition['title'], 'url' => $url, 'description' => $definition['description']];
                    break;
                }
            }
            if (!$found || trim((string)$found['url']) === '') {
                $page = self::start_resolve_page_v150170($definition['paths']);
                if ($page) { $found = ['title' => $definition['title'], 'url' => $page['url'], 'description' => $definition['description']]; }
            }
            if ($found && trim((string)$found['url']) !== '') { $items[] = $found; }
        }
        if (!$items) { return ''; }
        $out = '<section class="pftk-home-section-v150170" id="pftk-start-themen"><header class="pftk-home-heading-v150170"><span>Pferdethemen</span><h2>Was dein Pferd bewegt</h2></header><div class="pftk-home-categories-v150170">';
        foreach ($items as $item) {
            $icon_item = (object)['title' => $item['title'], 'url' => $item['url']];
            $out .= '<a class="pftk-home-category-v150170" href="'.esc_url($item['url']).'">'.self::portal_icon_markup_v150251(self::portal_main_icon_key_v150251($icon_item), 'start').'<strong>'.esc_html($item['title']).'</strong><small>'.esc_html($item['description']).'</small><b>Bereich öffnen <span>›</span></b></a>';
        }
        return $out.'</div></section>';
    }

