    private static function start_posts_v150170() {
        $candidates = get_posts([
            'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => 100,
            'orderby' => 'date', 'order' => 'DESC', 'ignore_sticky_posts' => true,
            'no_found_rows' => true, 'update_post_meta_cache' => true,
        ]);
        if (!$candidates) { return ''; }
        $views = [];
        $total_views = 0;
        $positive_posts = 0;
        foreach ($candidates as $candidate) {
            $count = self::post_views_in_window_v150297($candidate->ID, self::POST_VIEW_WINDOW_DAYS);
            $views[intval($candidate->ID)] = $count;
            $total_views += $count;
            if ($count > 0) { $positive_posts++; }
        }
        $minimum = max(1, intval(apply_filters('pftk_popularity_minimum_sample', 1, [], $candidates)));
        $use_popularity = ($total_views >= $minimum && $positive_posts >= 1);
        if ($use_popularity) {
            usort($candidates, function($a, $b) use ($views) {
                $va = intval($views[intval($a->ID)] ?? 0);
                $vb = intval($views[intval($b->ID)] ?? 0);
                if ($va !== $vb) { return $vb <=> $va; }
                $title_cmp = strcasecmp((string)get_the_title($a), (string)get_the_title($b));
                if ($title_cmp !== 0) { return $title_cmp; }
                return intval($a->ID) <=> intval($b->ID);
            });
            $posts = array_slice($candidates, 0, 6);
            $kicker = 'Pferderatgeber';
            $heading = 'Meistgelesen im Pferde Atelier';
            $mode = 'popularity-90d';
        } else {
            $posts = [];
            $used_post_ids = [];
            $used_category_ids = [];
            foreach ($candidates as $candidate) {
                $category_ids = wp_get_post_categories($candidate->ID, ['fields' => 'ids']);
                $fresh_category = 0;
                foreach ($category_ids as $category_id) {
                    $category_id = intval($category_id);
                    if ($category_id > 0 && !isset($used_category_ids[$category_id])) { $fresh_category = $category_id; break; }
                }
                if ($fresh_category < 1) { continue; }
                $posts[] = $candidate;
                $used_post_ids[intval($candidate->ID)] = true;
                $used_category_ids[$fresh_category] = true;
                if (count($posts) >= 6) { break; }
            }
            if (count($posts) < 6) {
                foreach ($candidates as $candidate) {
                    if (isset($used_post_ids[intval($candidate->ID)])) { continue; }
                    $posts[] = $candidate;
                    if (count($posts) >= 6) { break; }
                }
            }
            $kicker = 'Pferderatgeber';
            $heading = 'Ausgewählt im Pferde Atelier';
            $mode = 'editorial-new';
        }
        if (!$posts) { return ''; }
        $out = '<section class="pftk-home-section-v150170 pftk-home-post-slider-v150205" id="pftk-start-aktuell" data-pftk-post-mode="'.esc_attr($mode).'"><div class="pftk-home-post-head-v150205"><header class="pftk-home-heading-v150170"><span>'.esc_html($kicker).'</span><h2>'.esc_html($heading).'</h2></header><div class="pftk-home-post-controls-v150205" aria-label="Beiträge durchblättern"><button type="button" class="is-prev" aria-label="Vorherige Beiträge"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M14.5 5.5 8 12l6.5 6.5"/></svg></button><button type="button" class="is-next" aria-label="Weitere Beiträge"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M9.5 5.5 16 12l-6.5 6.5"/></svg></button></div></div><div class="pftk-home-posts-v150170" tabindex="0">';
        foreach ($posts as $post) {
            $image = get_the_post_thumbnail_url($post->ID, 'large');
            $categories = get_the_category($post->ID);
            $category_label = !empty($categories) ? $categories[0]->name : 'Pferderatgeber';
            $out .= '<article><a class="pftk-home-post-image-v150170" href="'.esc_url(get_permalink($post)).'">'.($image ? '<img src="'.esc_url($image).'" alt="" loading="lazy">' : '').'</a><div class="pftk-home-post-copy-v150204"><span class="pftk-home-post-category-v150204">'.esc_html($category_label).'</span><h3><a href="'.esc_url(get_permalink($post)).'">'.esc_html(get_the_title($post)).'</a></h3><p>'.esc_html(wp_trim_words(wp_strip_all_tags(get_the_excerpt($post)), 15, '…')).'</p><a class="pftk-home-more-v150170" href="'.esc_url(get_permalink($post)).'">Weiterlesen</a></div></article>';
        }
        return $out.'</div></section>';
    }

    private static function start_home_banner_v150342() {
        $candidate = '';
        if (function_exists('shortcode_exists') && shortcode_exists('pp_affiliate_slot')) {
            $candidate = trim((string)do_shortcode('[pp_affiliate_slot type="start_after_topics" intent="portal_context"]'));
        }
        $plain = strtolower(wp_strip_all_tags($candidate));
        $is_real = $candidate !== ''
            && preg_match('/<(?:img|picture|iframe|a|video)\b/i', $candidate)
            && strpos($candidate, 'data-ppar-placeholder') === false
            && strpos($candidate, 'ppar-placeholder-slot') === false
            && strpos($candidate, 'pftk-affiliate-slot-debug') === false
            && strpos($candidate, 'pftk-affiliate-placeholder') === false
            && strpos($plain, 'affiliate-werbefläche') === false
            && strpos($plain, 'affiliate-werbeflaeche') === false;
        if ($is_real) {
            return '<section class="pftk-home-ad-wide-v150172 is-real-partner-v150342" aria-label="Partnerbanner">'.$candidate.'</section>';
        }
        return '<div class="pftk-home-ad-wide-v150172 is-direct-fallback-v150342">'.self::start_ad_slot_v150162('home-wide-01', 'startseite-nach-hauptkategorien', 'wide').'</div>';
    }

    private static function start_brand_close_v150342() {
        $image = plugin_dir_url(__FILE__) . 'assets/startseite-anzeigenmarkt-pferd-v150192.webp?ver=' . rawurlencode(self::VERSION);
        return '<section class="pftk-home-brand-close-v150342"><div class="pftk-home-brand-close-copy-v150342"><span>Pferde Atelier</span><h2>Mit Blick fürs Pferd</h2><p>Wissen, Orientierung und ausgewählte Angebote – klar verbunden an einem Ort.</p></div><img src="'.esc_url($image).'" alt="Braunes Pferd am Stall" width="838" height="659" loading="lazy"></section>';
    }

    /** V1.50.344: Natürliche interne Startseitenlinks, nur wenn das reale Ziel veröffentlicht ist. */
    private static function start_about_link_v150344($label, array $paths) {
        $page = self::start_resolve_page_v150170($paths);
        if (!$page || trim((string)($page['url'] ?? '')) === '') { return esc_html($label); }
        return '<a class="pftk-home-about-link-v150344" href="'.esc_url($page['url']).'">'.esc_html($label).'</a>';
    }

    /** V1.50.344: Langer Portaltext unter dem unveränderten emotionalen Pferdebild. */
    private static function start_about_v150344() {
        $first_aid = self::start_about_link_v150344('Erste Hilfe beim Pferd', [
            'gesundheit/gesundheit-erste-hilfe', 'gesundheit/erste-hilfe', 'gesundheit-erste-hilfe', 'erste-hilfe'
        ]);
        $groundwork = self::start_about_link_v150344('Bodenarbeit', [
            'training/training-bodenarbeit', 'training/bodenarbeit', 'training-bodenarbeit', 'bodenarbeit'
        ]);
        $trailers = self::start_about_link_v150344('Pferdeanhänger', [
            'transport/transport-anhaenger', 'transport/anhaenger', 'transport-anhaenger', 'anhaenger'
        ]);

        return '<section class="pftk-home-about-v150344" aria-labelledby="pftk-home-about-title-v150344">'
            . '<header class="pftk-home-about-head-v150344"><span>Darum das Pferde Atelier</span><h2 id="pftk-home-about-title-v150344">Weniger Stallgerüchte. Mehr Pferdeverstand.</h2>'
            . '<p>Zwischen gut gemeinten Tipps aus der Stallgasse, widersprüchlichen Empfehlungen und immer neuen Produkten kann man schnell den Überblick verlieren. Das Pferde Atelier bringt Ordnung in den Pferdealltag – verständlich, praktisch und ohne unnötiges Herumreiten um die eigentliche Frage.</p>'
            . '<p>Hier findest du fundiertes Pferdewissen, hilfreiche Anregungen und ausgewählte Angebote an einem Ort. Von Haltung, Fütterung und Gesundheit über Training und Ausrüstung bis zu passenden Anbietern und Dienstleistungen. Nicht alles, was laut beworben wird, ist automatisch sinnvoll. Und nicht jede Lösung passt zu jedem Pferd. Deshalb schauen wir genauer hin, erklären Zusammenhänge und helfen dir dabei, besser einzuordnen, was für euch wirklich relevant ist.</p></header>'
            . '<div class="pftk-home-about-grid-v150344">'
            . '<article><h3>Verstehen statt weitersuchen</h3><p>Gute Entscheidungen beginnen mit verständlichen Informationen. Deshalb bereiten wir wichtige Themen so auf, dass du dich nicht erst durch endlose Fachtexte und halbe Antworten arbeiten musst. Klar gegliedert, nachvollziehbar erklärt und mit kurzen Wegen zu den passenden Bereichen.</p><p>So findest du schneller Antworten auf Fragen, die im Alltag tatsächlich auftauchen – zum Beispiel, wenn es um '.$first_aid.' geht und schnelle Orientierung zählt.</p></article>'
            . '<article><h3>Praktisch statt nur theoretisch</h3><p>Pferdewissen sollte nicht an der Bildschirmkante enden. Es muss im Stall, auf der Weide und im täglichen Umgang weiterhelfen.</p><p>Darum geht es nicht nur darum, <strong>was</strong> richtig oder wichtig sein könnte, sondern auch darum, <strong>wie</strong> sich Wissen praktisch anwenden lässt – von der '.$groundwork.' bis zu Fütterung, Haltung und Gesundheit. Verständlich genug für den Alltag, fundiert genug für gute Entscheidungen.</p></article>'
            . '<article><h3>Ausgewählt statt überladen</h3><p>Mehr Auswahl bedeutet nicht automatisch mehr Orientierung. Deshalb soll das Pferde Atelier kein unübersichtlicher Produktkatalog und keine Dauerwerbesendung werden.</p><p>Journalbeiträge, Anbieter, Dienstleistungen und ausgewählte Angebote werden so miteinander verbunden, dass du gezielt weiterkommst – auch bei größeren Entscheidungen rund um '.$trailers.'. Weniger wahlloses Stöbern, mehr passende Anlaufstellen.</p></article>'
            . '<article><h3>Für euren gemeinsamen Alltag</h3><p>Jedes Pferd ist anders. Und auch der gemeinsame Alltag folgt keinem festen Lehrbuch. Das Pferde Atelier möchte deshalb keine fertigen Antworten überstülpen, sondern Orientierung geben, Zusammenhänge verständlich machen und neue Wege zeigen.</p><p>Damit Mensch und Pferd nicht nur irgendwie durch den Alltag kommen, sondern gemeinsam fest im Sattel bleiben.</p></article>'
            . '</div></section>';
    }

    private static function render_startpage_v150176() {
        $hero_override = trim((string) self::media('start', 'hero_image'));
        $hero = $hero_override !== '' ? $hero_override : plugin_dir_url(__FILE__) . 'assets/startseite-hero-frau-pferd-clean-v150173.webp?ver=' . rawurlencode(self::VERSION);
        $hero_alt = trim((string) self::media('start', 'hero_alt'));
        if ($hero_alt === '') { $hero_alt = 'Frau mit Pferd auf einer sonnigen Weide'; }
        $hero_eyebrow = trim((string) self::text('start', 'hero_eyebrow'));
        $hero_title = trim((string) self::text('start', 'hero_title'));
        $hero_lead = trim((string) self::text('start', 'hero_lead'));
        return '<div class="pftk-home-v150170">'
            . '<section class="pftk-home-hero-v150173">'
            . '<img class="pftk-home-hero-bg-v150173" src="'.esc_url($hero).'" alt="'.esc_attr($hero_alt).'" width="2000" height="638" fetchpriority="high">'
            . '<div class="pftk-home-hero-copy-v150173">'
            . ($hero_eyebrow !== '' ? '<span>'.esc_html($hero_eyebrow).'</span>' : '')
            . ($hero_title !== '' ? '<h1>'.nl2br(esc_html($hero_title)).'</h1>' : '')
            . ($hero_lead !== '' ? '<p>'.nl2br(esc_html($hero_lead)).'</p>' : '')
            . '<a href="#pftk-start-themen">Pferdethemen entdecken</a>'
            . '</div></section>'
            . self::start_categories_v150170()
            . self::start_home_banner_v150342()
            . self::start_intents_v150198()
            . self::start_posts_v150170()
            . self::start_subcategories_v150170()
            . self::start_brand_close_v150342()
            . '<div class="pftk-home-brand-about-gap-v150345" aria-hidden="true"></div>'
            . self::start_about_v150344()
            . '</div>';
    }

