    public static function startpage_cleanup_v150199() {
        if (is_admin() || !is_front_page()) { return; }
        ?>
<script id="pftk-start-cleanup-v150199">
document.addEventListener('DOMContentLoaded',function(){
  var root=document.querySelector('.pftk-home-v150170');
  if(!root){return;}
  document.querySelectorAll('h1,h2,h3,h4').forEach(function(h){
    if(root.contains(h)){return;}
    if((h.textContent||'').trim().toLowerCase()!=='aktuelle beiträge'){return;}
    var box=h.closest('section,article,.wp-block-group,.entry-content>div');
    if(box){box.remove();}
  });
  var slider=root.querySelector('.pftk-home-post-slider-v150205 .pftk-home-posts-v150170');
  var prev=root.querySelector('.pftk-home-post-controls-v150205 .is-prev');
  var next=root.querySelector('.pftk-home-post-controls-v150205 .is-next');
  function sliderStep(){
    if(!slider){return 0;}
    var card=slider.querySelector('article');
    if(!card){return 0;}
    var gap=parseFloat(window.getComputedStyle(slider).columnGap)||16;
    return card.getBoundingClientRect().width+gap;
  }
  function updateSliderButtons(){
    if(!slider||!prev||!next){return;}
    var max=Math.max(0,slider.scrollWidth-slider.clientWidth-2);
    prev.disabled=slider.scrollLeft<=2;
    next.disabled=slider.scrollLeft>=max;
  }
  if(slider&&prev&&next){
    prev.addEventListener('click',function(){slider.scrollBy({left:-sliderStep(),behavior:'smooth'});});
    next.addEventListener('click',function(){slider.scrollBy({left:sliderStep(),behavior:'smooth'});});
    slider.addEventListener('scroll',function(){window.requestAnimationFrame(updateSliderButtons);},{passive:true});
    updateSliderButtons();
  }
  function syncPostTitles(){
    var titles=Array.prototype.slice.call(root.querySelectorAll('.pftk-home-post-copy-v150204 h3'));
    titles.forEach(function(t){t.style.minHeight='0px';});
    if(window.matchMedia('(max-width:720px)').matches){return;}
    var max=0;titles.forEach(function(t){max=Math.max(max,t.getBoundingClientRect().height);});
    titles.forEach(function(t){t.style.minHeight=Math.ceil(max)+'px';});
  }
  syncPostTitles();
  var rt;window.addEventListener('resize',function(){clearTimeout(rt);rt=setTimeout(function(){syncPostTitles();updateSliderButtons();},120);});
});
</script>
        <?php
    }

    private static function render_guide($type) {
        $title = self::text($type, 'guide_title');
        $intro = self::text($type, 'guide_intro');
        $cards = [
            ['01', self::text($type, 'guide_1_title'), self::text($type, 'guide_1_text'), '#pftk-topics'],
            ['02', self::text($type, 'guide_2_title'), self::text($type, 'guide_2_text'), '#pftk-posts'],
            ['03', self::text($type, 'guide_3_title'), self::text($type, 'guide_3_text'), '#pftk-structure'],
        ];
        $has = false;
        foreach ($cards as $c) { if ($c[1] !== '' || $c[2] !== '') { $has = true; } }
        if ($title === '' && $intro === '' && !$has) { return ''; }

        $out = '<section class="pftk-section" id="pftk-guide"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-guide_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div><div class="pftk-guide-grid">';
        foreach ($cards as $i => $c) {
            if ($c[1] === '' && $c[2] === '') { continue; }
            $out .= '<a class="pftk-card pftk-card-guide pftk-curve" style="--pftk-accent:' . esc_attr(self::color($i)) . '" href="' . esc_url($c[3]) . '">' .
                '<span class="pftk-number">' . esc_html($c[0]) . '</span>' .
                ($c[1] !== '' ? '<strong class="pftk-heading pftk-heading-card_title">' . esc_html($c[1]) . '</strong>' : '') .
                ($c[2] !== '' ? '<em>' . esc_html($c[2]) . '</em>' : '') .
                '</a>';
        }
        return $out . '</div></section>';
    }

    private static function render_posts($type, $ctx) {
        $cat_ids = array_values(array_unique(array_filter(array_map('intval', (array)($ctx['cat_ids'] ?? [])))));
        $selection_mode = self::block($type, 'posts_selection_mode');
        $limit = intval(self::block($type, 'posts_limit'));
        $title = self::text($type, 'posts_title');
        $intro = self::text($type, 'posts_intro');

        // Hub Ebene 1 und 2: meistgelesene Beiträge aus allen passenden Kategorien.
        // Die Kategoriequelle wird aus realen Menüvorkommen und Seitenhierarchie
        // zusammengeführt; das Veröffentlichungsdatum ist kein Sortierkriterium.
        if (in_array($type, ['hub1', 'hub2'], true)) {
            $cat_ids = array_values(array_unique(array_filter(array_map('intval', (array)($ctx['hub_post_cat_ids'] ?? $cat_ids)))));
            $hub_limit = max(3, min(6, intval(self::block($type, 'posts_limit'))));
            $posts = self::top_posts_by_importance($cat_ids, $hub_limit);
            $raw_title = trim((string)self::raw_text($type, 'posts_title'));
            $raw_intro = trim((string)self::raw_text($type, 'posts_intro'));
            if ($raw_title === '' || $raw_title === 'Wichtige Ratgeber' || $raw_title === 'Ratgeber aus diesem Bereich') { $title = 'Meistgelesene Beiträge aus diesem Bereich'; }
            if ($raw_intro === '' || $raw_intro === 'Automatisch ausgewählte Beiträge mit breiter Themen- und Suchintent-Abdeckung statt nur neueste Beiträge.') {
                $intro = 'Beliebte Beiträge aus diesem Bereich – auf Basis der Aufrufe der letzten 90 Tage.';
            }
            $selection_mode = 'popularity-90d-with-editorial-fallback';
            $limit = $hub_limit;
        } else {
            $posts = self::top_posts_from_categories($cat_ids, $limit, $selection_mode);
        }

        $debug = '';
        if (current_user_can('manage_options') && in_array($type, ['hub1','hub2'], true)) {
            $selected = [];
            foreach ((array)$posts as $debug_post) {
                if ($debug_post instanceof WP_Post) { $selected[] = intval($debug_post->ID); }
            }
            $debug = '<!-- pftk-v' . esc_html(self::VERSION) . ' hub_posts type=' . esc_html($type) .
                ' mode=' . esc_html($selection_mode) . ' cat_count=' . intval(count($cat_ids)) .
                ' post_count=' . intval(count((array)$posts)) . ' cat_ids=' . esc_html(implode(',', $cat_ids)) .
                ' selected=' . esc_html(implode(',', $selected)) . ' -->';
        }

        if (empty($posts) && self::text($type, 'empty_text') === '') { return $debug; }
        $out = '<section class="pftk-section" id="pftk-posts"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-posts_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div>';
        if (empty($posts)) { return $debug . $out . self::empty_box($type) . '</section>'; }
        $count_class = 'pftk-card-grid-count-' . intval(count((array)$posts));
        $out .= '<div class="pftk-card-grid ' . esc_attr($count_class) . '">';
        $n = 1;
        foreach ($posts as $post) {
            $excerpt = self::clean_excerpt($post);
            $out .= '<a class="pftk-card pftk-card-post pftk-curve" style="--pftk-accent:' . esc_attr(self::color($n - 1)) . '" href="' . esc_url(get_permalink($post)) . '">' .
                '<span class="pftk-number">' . esc_html(str_pad((string)$n, 2, '0', STR_PAD_LEFT)) . '</span>' .
                '<strong class="pftk-heading pftk-heading-card_title">' . esc_html(get_the_title($post)) . '</strong>' .
                ($excerpt ? '<em>' . esc_html($excerpt) . '</em>' : '') .
                '<b>' . esc_html(self::article_excerpt_cta_v150325()) . '</b>' .
                '</a>';
            $n++;
        }
        return $debug . $out . '</div></section>';
    }
    private static function render_product_articles_after_category_tiles($type, $ctx) {
        $force_articles = !empty($ctx['force_product_articles']);
        if (!$force_articles && !self::visible('category', 'show_product_articles_after_category_tiles')) { return ''; }
        $cat_ids = !empty($ctx['cat_ids']) ? (array)$ctx['cat_ids'] : self::category_ids_from_items($ctx['top_items'] ?? []);
        $cat_ids = array_values(array_unique(array_filter(array_map('intval', $cat_ids))));
        $limit = self::block('category', 'product_articles_limit') === '8' ? 8 : 4;
        $current = $ctx['current_item'] ?? null;

        // V2.5 / Design 1.16.0:
        // Ebene-3-Artikel duerfen nicht nur von Menue-/Shortcode-Kontext oder
        // existierenden cat_ids abhaengen. Die Logik nutzt zuerst die konkret
        // erkannten Ebene-4-Kacheln/Kategorien und faellt dann auf harte
        // Produktschluessel der aktuellen Seite zurueck, z. B.
        // Fuetterung > Frostschutz > Frostschutzkabel -> Frostschutzkabel.
        $posts = array_slice(self::top_posts_for_product_context($cat_ids, $limit, $current), 0, $limit);
        $debug = current_user_can('manage_options') ? self::product_articles_debug_comment($current, $cat_ids, $posts) : '';

        $manual_title = trim((string)self::raw_text('category', 'product_articles_title'));
        $title = $manual_title !== '' ? $manual_title : self::automatic_product_articles_title($current);
        $intro = trim((string)self::raw_text('category', 'product_articles_intro'));
        if (empty($posts)) {
            if (current_user_can('manage_options')) {
                return $debug . '<section class="pftk-section pftk-product-articles pftk-product-articles-empty" id="pftk-product-articles"><div class="pftk-section-head">' .
                    ($title !== '' ? '<h2 class="pftk-heading pftk-heading-product_articles_title">' . esc_html($title) . '</h2>' : '') .
                    '</div><div class="pftk-empty">Artikelblock aktiv, aber keine passenden sichtbaren Beiträge gefunden.</div></section>';
            }
            return $debug;
        }
        $out = $debug . '<section class="pftk-section pftk-product-articles" id="pftk-product-articles"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-product_articles_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div><div class="pftk-card-grid pftk-card-grid-count-' . intval(count((array)$posts)) . '" data-pftk-card-count="' . esc_attr((string)count((array)$posts)) . '">';
        $n = 1;
        foreach ($posts as $post) {
            $excerpt = self::clean_excerpt($post);
            $out .= '<a class="pftk-card pftk-card-post pftk-curve" style="--pftk-accent:' . esc_attr(self::color($n - 1)) . '" href="' . esc_url(get_permalink($post)) . '">' .
                '<span class="pftk-number">' . esc_html(str_pad((string)$n, 2, '0', STR_PAD_LEFT)) . '</span>' .
                '<strong class="pftk-heading pftk-heading-card_title">' . esc_html(get_the_title($post)) . '</strong>' .
                ($excerpt ? '<em>' . esc_html($excerpt) . '</em>' : '') .
                '<b>' . esc_html(self::article_excerpt_cta_v150325()) . '</b>' .
                '</a>';
            $n++;
        }
        return $out . '</div></section>';
    }

    private static function product_articles_debug_comment($current, $cat_ids, $posts) {
        $title = is_object($current) && !empty($current->title) ? (string)$current->title : '';
        $keys = self::category_tile_product_keys_for_current($current);
        return '<!-- pftk-v' . esc_html(self::VERSION) . ' product_articles current=' . esc_html($title) .
            ' keys=' . esc_html(implode(',', array_slice($keys, 0, 8))) .
            ' cat_ids=' . esc_html(implode(',', array_map('intval', (array)$cat_ids))) .
            ' count=' . intval(count((array)$posts)) . ' -->';
    }

    private static function top_posts_for_product_context($cat_ids, $limit, $current = null) {
        $limit = max(1, min(50, intval($limit)));
        $picked = [];
        $seen = [];

        if (!empty($cat_ids)) {
            foreach (self::top_posts_by_importance($cat_ids, $limit) as $post) {
                if ($post instanceof WP_Post && empty($seen[$post->ID])) { $picked[] = $post; $seen[$post->ID] = true; }
                if (count($picked) >= $limit) { return $picked; }
            }
        }

        // Fallback fuer Seiten, bei denen Kategorien zwar semantisch existieren,
        // aber nicht sauber als cat_ids durchgereicht werden: suche publizierte
        // Beitraege ueber starke Produktschluessel im Titel/Slug. Begrenzt und
        // score-sortiert, damit es auch bei vielen Beitraegen beherrschbar bleibt.
        $keys = self::category_tile_product_keys_for_current($current);
        $fallback_posts = self::posts_by_product_keys($keys, max(24, $limit * 4));
        foreach ($fallback_posts as $post) {
            if ($post instanceof WP_Post && empty($seen[$post->ID])) { $picked[] = $post; $seen[$post->ID] = true; }
            if (count($picked) >= $limit) { break; }
        }
        return $picked;
    }

    private static function posts_by_product_keys($keys, $limit) {
        $keys = array_values(array_filter(array_unique(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        if (empty($keys)) { return []; }
        $limit = max(8, min(80, intval($limit)));
        $candidates = [];
        $seen = [];
        foreach (array_slice($keys, 0, 6) as $key) {
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            $posts = get_posts([
                'post_type' => 'post',
                'post_status' => self::frontend_visible_post_statuses(),
                'posts_per_page' => $limit,
                's' => str_replace('-', ' ', $key),
                'ignore_sticky_posts' => true,
                'no_found_rows' => true,
            ]);
            foreach ($posts as $post) {
                if (!$post instanceof WP_Post || isset($seen[$post->ID])) { continue; }
                $score = self::post_product_key_score($post, $keys);
                if ($score <= 0) { continue; }
                $seen[$post->ID] = true;
                $candidates[] = ['score' => $score + self::post_strategy_score($post), 'post' => $post];
            }
        }
        $total_views = 0;
        foreach ($candidates as $index => $row) {
            $view_count = self::post_views_in_window_v150297($row['post']->ID, self::POST_VIEW_WINDOW_DAYS);
            $candidates[$index]['views'] = $view_count;
            $total_views += $view_count;
        }
        $minimum = max(1, intval(apply_filters('pftk_popularity_minimum_sample', 10, [], array_map(function($row){ return $row['post']; }, $candidates))));
        $use_popularity = $total_views >= $minimum;
        usort($candidates, function($a, $b) use ($use_popularity) {
            if ($use_popularity && intval($a['views'] ?? 0) !== intval($b['views'] ?? 0)) {
                return intval($b['views'] ?? 0) <=> intval($a['views'] ?? 0);
            }
            if ($a['score'] === $b['score']) {
                $title_cmp = strcasecmp((string)get_the_title($a['post']), (string)get_the_title($b['post']));
                if ($title_cmp !== 0) { return $title_cmp; }
                return intval($a['post']->ID) <=> intval($b['post']->ID);
            }
            return $b['score'] <=> $a['score'];
        });
        return array_map(function($row) { return $row['post']; }, $candidates);
    }

    private static function post_product_key_score($post, $keys) {
        $hay = self::normalize_match_key(get_the_title($post) . ' ' . $post->post_name);
        $best = 0;
        foreach ((array)$keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            if (self::slug_has_token($hay, $key)) { $best = max($best, 120); }
            elseif (strpos($hay, $key) !== false) { $best = max($best, 90); }
            else {
                $hits = 0;
                foreach (self::strong_tokens($key) as $token) {
                    if (strpos($hay, $token) !== false) { $hits++; }
                }
                if ($hits > 0) { $best = max($best, 40 + ($hits * 12)); }
            }
        }
        return $best;
    }

    private static function category_ids_from_items($items) {
        $ids = [];
        foreach ((array)$items as $item) {
            if (!is_object($item)) { continue; }
            if (($item->object ?? '') === 'category' && !empty($item->object_id)) {
                $ids[] = intval($item->object_id);
                continue;
            }
            $resolved = self::resolve_category_id_from_item($item);
            if ($resolved > 0) { $ids[] = $resolved; }
        }
        return array_values(array_unique(array_filter($ids)));
    }

    private static function resolve_category_id_from_item($item) {
        if (!is_object($item)) { return 0; }
        if (($item->object ?? '') === 'category' && !empty($item->object_id)) { return intval($item->object_id); }
        $candidates = [];
        if (!empty($item->url)) { $candidates[] = self::last_path_part_from_url((string)$item->url); }
        if (!empty($item->title)) { $candidates[] = (string)$item->title; }
        foreach ($candidates as $candidate) {
            $slug = self::normalize_match_key($candidate);
            if ($slug === '') { continue; }
            $term = get_term_by('slug', $slug, 'category');
            if ($term && !is_wp_error($term) && !empty($term->term_id)) { return intval($term->term_id); }
        }
        // Fallback: wenn URL/Title Intent + Produkt enthalten, passenden Term anhand aller Kategorien finden.
        foreach ($candidates as $candidate) {
            $key = self::normalize_match_key($candidate);
            if ($key === '') { continue; }
            $terms = self::all_category_terms_cached();
            foreach ($terms as $term) {
                if (self::normalize_match_key($term->slug) === $key || self::normalize_match_key($term->name) === $key) {
                    return intval($term->term_id);
                }
            }
        }
        return 0;
    }

    private static function automatic_category_tiles_title($current) {
        $topic = '';
        if (is_object($current) && !empty($current->title)) { $topic = trim((string)$current->title); }
        if ($topic === '') {
            $post = get_queried_object();
            if ($post instanceof WP_Post) { $topic = get_the_title($post); }
        }
        $topic = trim(wp_strip_all_tags($topic));
        if ($topic === '') { return 'Passende Themen'; }
        return 'Themen zu ' . self::horse_topic_label($topic);
    }

    private static function automatic_product_articles_title($current) {
        $topic = '';
        if (is_object($current) && !empty($current->title)) { $topic = trim((string)$current->title); }
        if ($topic === '') {
            $post = get_queried_object();
            if ($post instanceof WP_Post) { $topic = get_the_title($post); }
        }
        $topic = trim(wp_strip_all_tags($topic));
        if ($topic === '') { return 'Ausgewählte Artikel'; }
        return 'Ausgewählte Artikel zu ' . self::horse_topic_label($topic);
    }

    private static function horse_topic_label($topic) {
        $topic = trim((string)$topic);
        if ($topic === '') { return ''; }
        $lower = strtolower($topic);
        $lower = str_replace(['ä','ö','ü','ß'], ['ae','oe','ue','ss'], $lower);
        if (strpos($lower, 'pferd') !== false) { return $topic; }
        $map = [
            'decken' => 'Pferdedecken',
            'futter' => 'Pferdefutter',
            'anhaenger' => 'Pferdeanhänger',
            'anhänger' => 'Pferdeanhänger',
            'sattel' => 'Pferdesattel',
            'halfter' => 'Pferdehalfter',
            'trense' => 'Pferdetrensen',
        ];
        $norm = self::normalize_match_key($topic);
        foreach ($map as $needle => $label) {
            if ($norm === self::normalize_match_key($needle)) { return $label; }
        }
        if (strpos($norm, 'decken') !== false || strpos($norm, 'decke') !== false) { return $topic . ' für Pferde'; }
        if (strpos($norm, 'futter') !== false) { return 'Pferde' . lcfirst($topic); }
        return $topic . ' für Pferde';
    }


    private static function render_media_block($type) {
        $feature = self::media($type, 'feature_image');
        $banner1 = self::media($type, 'banner_1_image');
        $banner2 = self::media($type, 'banner_2_image');
        $banner1_text = self::text($type, 'banner_1_text');
        $banner2_text = self::text($type, 'banner_2_text');
        if ($feature === '' && $banner1 === '' && $banner2 === '' && $banner1_text === '' && $banner2_text === '') { return ''; }

        $title = self::text($type, 'media_title');
        $intro = self::text($type, 'media_intro');
        $out = '<section class="pftk-section"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-media_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div><div class="pftk-media-grid">';

        if ($feature !== '') {
            $alt = self::media($type, 'feature_alt') ?: $title;
            $inner = '<img src="' . esc_url($feature) . '" alt="' . esc_attr($alt) . '">';
            $out .= '<div class="pftk-photo-box pftk-curve">' . self::wrap_link($inner, self::media($type, 'feature_url'), self::media($type, 'feature_target'), false, 'pftk-image-link') . '</div>';
        }
        $out .= self::banner_box($type, 1);
        $out .= self::banner_box($type, 2);
        return $out . '</div></section>';
    }

    private static function banner_box($type, $slot) {
        $image = self::media($type, 'banner_' . $slot . '_image');
        $text = self::text($type, 'banner_' . $slot . '_text');
        $url = self::media($type, 'banner_' . $slot . '_url');
        if ($image === '' && $text === '') { return ''; }
        $inner = $image !== ''
            ? '<img src="' . esc_url($image) . '" alt="' . esc_attr($text ?: self::text($type, 'banner_label')) . '">'
            : '<span>' . esc_html(self::text($type, 'banner_label')) . '</span><strong>' . esc_html($text) . '</strong>';
        return '<div class="pftk-banner pftk-curve">' . self::wrap_link($inner, $url, self::media($type, 'banner_' . $slot . '_target'), true, '') . '</div>';
    }

    private static function render_hub_remaining_topics($type, $ctx) {
        if (!in_array($type, ['hub1', 'hub2', 'category'], true)) { return ''; }
        $items = self::published_page_items($ctx['top_items'] ?? [], 0, false);
        $items = self::sort_structural_items($items);
        $remaining = array_slice($items, 5);
        if (empty($remaining)) { return ''; }
        $title = self::text($type, 'structure_title');
        $intro = self::text($type, 'structure_intro');
        $out = '<section class="pftk-section pftk-hub-more" id="pftk-structure"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-structure_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div><div class="pftk-more-links">';
        foreach ($remaining as $item) {
            $out .= '<a class="pftk-more-link" href="' . esc_url($item->url) . '"><span>' . esc_html($item->title) . '</span><b aria-hidden="true">›</b></a>';
        }
        if (current_user_can('manage_options')) {
            $out .= '<!-- pftk-v' . esc_html(self::VERSION) . ' hub_remaining type=' . esc_html($type) . ' count=' . intval(count($remaining)) . ' -->';
        }
        return $out . '</div></section>';
    }

    private static function render_structure($type, $ctx) {
        // Startseite: „Weitere Themen“ darf die manuell bereits oben gewählten
        // Themen nicht wiederholen. Dafür liefert der Start-Kontext eine eigene,
        // bereinigte Themenquelle. Auf allen anderen Ebenen bleibt die bisherige
        // Quelle unverändert.
        $source_items = array_key_exists('structure_items', $ctx) ? $ctx['structure_items'] : ($ctx['top_items'] ?? []);
        $parents = array_slice(self::sort_items($source_items), 0, intval(self::block($type, 'structure_groups')));
        if (empty($parents)) { return ''; }
        $title = self::text($type, 'structure_title');
        $intro = self::text($type, 'structure_intro');
        $out = '<section class="pftk-section" id="pftk-structure"><div class="pftk-section-head">' .
            ($title !== '' ? '<h2 class="pftk-heading pftk-heading-structure_title">' . esc_html($title) . '</h2>' : '') .
            ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
            '</div><div class="pftk-structure-grid">';
        foreach ($parents as $gi => $parent) {
            if (isset($ctx['structure_children_map']) && array_key_exists(intval($parent->ID), $ctx['structure_children_map'])) {
                $children = self::sort_items($ctx['structure_children_map'][intval($parent->ID)]);
            } else {
                $children = isset($ctx['children_map'][$parent->ID]) ? self::sort_items($ctx['children_map'][$parent->ID]) : [];
            }
            $parent_url = isset($parent->url) ? trim((string)$parent->url) : '';
            $style = '--pftk-accent:' . esc_attr(self::color($gi));

            // Startseite: Jede „Weitere Themen“-Kachel braucht ein echtes Ziel.
            // Ohne Unterlinks wird die komplette Kachel verlinkt. Mit Unterlinks
            // bleibt valides HTML erhalten und der Kacheltitel verlinkt die Hauptseite.
            if ($type === 'start' && empty($children) && $parent_url !== '') {
                $out .= '<a class="pftk-structure-card pftk-structure-card-link pftk-curve" style="' . $style . '" href="' . esc_url($parent_url) . '"><strong class="pftk-heading pftk-heading-card_title">' . esc_html($parent->title) . '</strong><b class="pftk-structure-card-cta">ansehen</b></a>';
                continue;
            }

            $out .= '<div class="pftk-structure-card pftk-curve" style="' . $style . '">';
            if ($type === 'start' && $parent_url !== '') {
                $out .= '<a class="pftk-structure-parent-link" href="' . esc_url($parent_url) . '"><strong class="pftk-heading pftk-heading-card_title">' . esc_html($parent->title) . '</strong></a>';
            } else {
                $out .= '<strong class="pftk-heading pftk-heading-card_title">' . esc_html($parent->title) . '</strong>';
            }
            if (!empty($children)) {
                $out .= '<ul>';
                $shown = 0;
                foreach ($children as $child) {
                    $out .= '<li><a href="' . esc_url($child->url) . '">' . esc_html($child->title) . '</a></li>';
                    $shown++;
                    if ($shown >= intval(self::block($type, 'structure_links'))) { break; }
                }
                $out .= '</ul>';
            }
            $out .= '</div>';
        }
        return $out . '</div></section>';
    }

    private static function hub_grid_affiliate_context($type, $placement_index = 1, $placement_mode = 'grid') {
        $object = function_exists('get_queried_object') ? get_queried_object() : null;
        $id = function_exists('get_queried_object_id') ? intval(get_queried_object_id()) : 0;
        $title = '';
        $slug = '';
        $url = '';
        if ($object instanceof WP_Post) {
            $id = intval($object->ID);
            $title = get_the_title($object);
            $slug = (string)$object->post_name;
            $url = get_permalink($object);
        } elseif (is_object($object)) {
            $title = isset($object->name) ? (string)$object->name : '';
            $slug = isset($object->slug) ? (string)$object->slug : '';
        }
        return [
            'template' => $type,
            'object_id' => $id,
            'title' => trim((string)$title),
            'slug' => trim((string)$slug),
            'url' => trim((string)$url),
            'slot' => $type === 'category' ? 'product_after_category_tiles' : 'hub_grid_card',
            'placement_index' => max(1, intval($placement_index)),
            'placement_mode' => sanitize_key((string)$placement_mode) ?: 'grid',
            'allow_placeholder' => $placement_mode !== 'leaf_category',
            'contract' => self::AFFILIATE_CONTRACT,
            'design_version' => self::VERSION,
        ];
    }

    private static function hub_grid_affiliate_data($type, $placement_index = 1, $placement_mode = 'grid') {
        $context = self::hub_grid_affiliate_context($type, $placement_index, $placement_mode);
        // Das Designplugin definiert nur die Flächen. Die Bannerwahl erfolgt zentral
        // im Affiliate Router. Bei Ebene-3-Endseiten und bei genau drei Unterkategorien
        // können über placement_index zwei unterschiedliche Kampagnen angefordert werden.
        $data = [
            'active' => false,
            'contract' => '',
            'label' => 'Anzeige',
            'title' => '',
            'text' => '',
            'button' => 'mehr erfahren',
            'image' => '',
            'url' => '',
            'target' => '_blank',
            'source' => 'none',
            'kind' => 'none',
        ];
        $filtered = apply_filters('pftk_hub_grid_affiliate_data', $data, $type, $context);
        if (!is_array($filtered)) { return ['valid' => false, 'source' => 'filter-invalid']; }
        $data = array_merge($data, $filtered);
        if (($data['contract'] ?? '') !== self::AFFILIATE_CONTRACT) {
            return ['valid' => false, 'source' => 'contract-mismatch', 'contract' => self::AFFILIATE_CONTRACT];
        }
        $data['active'] = !empty($data['active']);
        $data['label'] = sanitize_text_field((string)$data['label']);
        $data['title'] = sanitize_text_field((string)$data['title']);
        $data['text'] = sanitize_textarea_field((string)$data['text']);
        $data['button'] = sanitize_text_field((string)$data['button']);
        $data['image'] = esc_url_raw((string)$data['image']);
        $data['url'] = esc_url_raw((string)$data['url']);
        $data['target'] = in_array((string)$data['target'], ['_self', '_blank'], true) ? (string)$data['target'] : '_blank';
        $data['source'] = sanitize_key((string)($data['source'] ?? 'manual')) ?: 'manual';
        $data['kind'] = in_array((string)($data['kind'] ?? 'campaign'), ['campaign','placeholder'], true) ? (string)$data['kind'] : 'campaign';
        $data['is_placeholder'] = !empty($data['is_placeholder']);
        $data['contract'] = self::AFFILIATE_CONTRACT;
        $is_placeholder = self::affiliate_data_is_placeholder($data);
        if ($is_placeholder) {
            $data['kind'] = 'placeholder';
            $data['is_placeholder'] = true;
            // Harte Quellensperre: Platzhaltertexte duerfen den Renderer niemals erreichen.
            $data['label'] = '';
            $data['title'] = '';
            $data['text'] = '';
            $data['button'] = '';
        }
        // V1.50.5: Werbekacheln sind visuelle Bildflaechen. Eine echte Kampagne
        // ohne Bild darf niemals als reine Textkachel erscheinen. Der Router soll
        // in diesem Fall auf das zentrale Platzhalterbild zurueckfallen. Diese
        // zweite Sperre blockiert auch alte oder fremde Provider-Ausgaben.
        if (!$is_placeholder && $data['kind'] === 'campaign' && $data['image'] === '') {
            return [
                'valid' => false,
                'active' => false,
                'contract' => self::AFFILIATE_CONTRACT,
                'source' => 'campaign-missing-grid-image',
                'kind' => 'none',
            ];
        }
        $has_creative = $is_placeholder || $data['title'] !== '' || $data['image'] !== '';
        $has_destination = $data['url'] !== '' || $is_placeholder;
        $data['valid'] = $data['active'] && $has_creative && $has_destination;
        return $data;
    }

    /**
     * Platzhalter werden nicht nur ueber `kind`, sondern auch ueber das explizite
     * Provider-Flag und die reservierten Quellen erkannt. Damit kann ein alter oder
     * zusaetzlicher Filter den Platzhalter nicht versehentlich als Kampagne rendern.
     */
    private static function affiliate_data_is_placeholder($data) {
        if (!is_array($data)) { return false; }
        if (!empty($data['is_placeholder'])) { return true; }
        if ((string)($data['kind'] ?? '') === 'placeholder') { return true; }
        $source = sanitize_key((string)($data['source'] ?? ''));
        return strpos($source, 'placeholder-') === 0 || strpos($source, 'design-placeholder-') === 0;
    }

    /**
     * Verbindlicher, rein struktureller Werbeplatz ohne Text oder Bild.
     * Er wird nur dort eingesetzt, wo das vereinbarte Raster einen reservierten
     * Werbeplatz verlangt und die Affiliate-Zentrale weder Kampagne noch eigenen
     * Platzhalter liefert. Endkategorien ohne Unterkategorien bleiben davon ausgenommen.
     */
    private static function structural_ad_placeholder_data($type, $placement_index, $placement_mode) {
        return [
            'active' => true,
            'valid' => true,
            'contract' => self::AFFILIATE_CONTRACT,
            'label' => '',
            'title' => '',
            'text' => '',
            'button' => '',
            'image' => '',
            'url' => '',
            'target' => '_self',
            'source' => 'design-placeholder-' . sanitize_key((string)$type) . '-' . max(1, intval($placement_index)),
            'kind' => 'placeholder',
            'is_placeholder' => true,
            'placement_index' => max(1, intval($placement_index)),
            'placement_mode' => sanitize_key((string)$placement_mode) ?: 'grid',
        ];
    }

    /**
     * Liefert genau so viele Werbekarten, wie das jeweilige Kategorie-Raster
     * verbindlich vorsieht. Echte Kampagnen haben Vorrang. Fehlt eine Kampagne
     * oder liefert der Router dieselbe Kampagne doppelt, bleibt der Platz als
     * neutrale leere Werbekachel erhalten.
     */
    private static function grid_affiliate_cards($type, $content_count) {
        if (!in_array($type, ['hub1', 'hub2', 'category'], true)) { return []; }
        $content_count = intval($content_count);
        $slot_map = [2 => 1, 3 => 2, 4 => 2, 5 => 1, 6 => 0];
        $slots = intval($slot_map[$content_count] ?? 0);
        if ($slots <= 0) { return []; }
        $mode = 'balanced_' . $content_count . '_tiles';
        $cards = [];
        $campaign_sources = [];
        for ($position = 1; $position <= $slots; $position++) {
            $data = self::hub_grid_affiliate_data($type, $position, $mode);
            if (empty($data['valid'])) {
                $data = self::structural_ad_placeholder_data($type, $position, $mode);
            }
            $kind = (string)($data['kind'] ?? 'campaign');
            $source = sanitize_key((string)($data['source'] ?? ''));
            if ($kind === 'campaign' && $source !== '' && isset($campaign_sources[$source])) {
                $data = self::structural_ad_placeholder_data($type, $position, $mode);
                $kind = 'placeholder';
            }
            if ($kind === 'campaign' && $source !== '') { $campaign_sources[$source] = true; }
            $card = self::hub_grid_ad_card($type, $data, 'pftk-balanced-grid-ad pftk-balanced-grid-ad-' . $position);
            if ($card !== '') { $cards[] = $card; }
        }
        return $cards;
    }

    private static function hub_grid_ad_card($type, $data = null, $extra_class = '') {
        if (!in_array($type, ['hub1', 'hub2', 'category'], true)) { return ''; }
        if (!is_array($data)) { $data = self::hub_grid_affiliate_data($type); }
        if (empty($data['valid'])) { return ''; }
        $target = $data['target'];
        $is_placeholder = self::affiliate_data_is_placeholder($data);
        $extra_class = sanitize_html_class((string)$extra_class);
        $classes = 'pftk-card pftk-card-ad pftk-curve pftk-hub-grid-ad pftk-hub-grid-image-only' . ($is_placeholder ? ' pftk-hub-grid-placeholder' : '') . ($extra_class !== '' ? ' ' . $extra_class : '');

        // V1.50.6: Alle Werbekacheln innerhalb der Kachelraster sind verbindlich
        // bild-only. Das gilt sowohl fuer Platzhalter als auch fuer echte Kampagnen.
        // Kennzeichnung, Titel, Kurztext und Button duerfen in dieser Flaeche niemals
        // als sichtbarer HTML-Inhalt ausgegeben werden. Andere Banner-Slots bleiben
        // davon unberuehrt.
        $visual = $data['image'] !== ''
            ? '<span class="pftk-hub-grid-ad-image"><img src="' . esc_url($data['image']) . '" alt="" loading="lazy"></span>'
            : '';
        $placeholder_attr = $is_placeholder ? ' data-pftk-placeholder="1"' : ' data-pftk-placeholder="0"';
        $placement_index = max(1, min(2, intval($data['placement_index'] ?? 1)));
        $aria_label = $is_placeholder ? 'Werbeplatz' : 'Anzeige';
        $card_style = '--pftk-accent:#a7a7a7';
        if ($data['image'] !== '') {
            $card_style .= ';background-image:url("' . esc_url($data['image']) . '")!important';
        }
        $attrs = ' class="' . esc_attr($classes) . '" data-pftk-affiliate-source="' . esc_attr($data['source']) . '" data-pftk-placement-index="' . esc_attr((string)$placement_index) . '"' . $placeholder_attr . ' aria-label="' . esc_attr($aria_label) . '" style="' . esc_attr($card_style) . '"';
        if ($visual !== '' && $data['url'] !== '') {
            $rel = $is_placeholder
                ? ($target === '_blank' ? ' rel="noopener noreferrer"' : '')
                : ($target === '_blank' ? ' rel="sponsored nofollow noopener noreferrer"' : ' rel="sponsored nofollow"');
            return '<a' . $attrs . ' href="' . esc_url($data['url']) . '" target="' . esc_attr($target) . '"' . $rel . '>' . $visual . '</a>';
        }
        return '<div' . $attrs . '>' . $visual . '</div>';
    }


    /**
     * Ebene 3 ohne Unterkategorien: bis zu zwei echte, unterschiedliche Kampagnen.
     * Keine Platzhalter, keine leeren Rasterfelder. Eine einzelne Anzeige wird mittig
     * dargestellt; zwei Anzeigen stehen gleich breit nebeneinander.
     */
    private static function leaf_category_affiliate_section() {
        $cards = [];
        $sources = [];
        for ($position = 1; $position <= 2; $position++) {
            $data = self::hub_grid_affiliate_data('category', $position, 'leaf_category');
            if (empty($data['valid']) || ($data['kind'] ?? '') !== 'campaign') { continue; }
            $source = sanitize_key((string)($data['source'] ?? ''));
            if ($source !== '' && isset($sources[$source])) { continue; }
            if ($source !== '') { $sources[$source] = true; }
            $card = self::hub_grid_ad_card('category', $data, 'pftk-leaf-category-ad');
            if ($card !== '') { $cards[] = $card; }
        }
        $count = count($cards);
        if ($count === 0) { return ''; }
        $debug = current_user_can('manage_options')
            ? '<!-- pftk-v' . esc_html(self::VERSION) . ' leaf_category_ads count=' . intval($count) . ' -->'
            : '';
        return $debug . '<section class="pftk-section pftk-leaf-category-ads" aria-label="Anzeigen"><div class="pftk-leaf-category-ad-grid pftk-leaf-category-ad-count-' . intval($count) . '" data-pftk-leaf-ad-count="' . esc_attr((string)$count) . '">' . implode('', $cards) . '</div></section>';
    }


    /**
     * V1.50.19: Einheitlicher reduzierter Line-Icon-Stil. Enthalten sind
     * Ausruestung, Fuetterung, Stall, Weide, Gesundheit, Training, Transport, Wissen, ihre direkten Unterkategorien sowie die sechs direkten Unterkategorien von Ausruestung > Decken. Die Zuordnung erfolgt
     * deterministisch ueber Slug oder Titel. Es gibt keine Bilddatei und kein
     * JavaScript; die SVGs uebernehmen per currentColor die jeweilige Kachelfarbe.
     */
    private static function category_tile_icon_key($item) {
        if (!is_object($item)) { return ''; }
        $keys = [];
        $title_key = self::normalize_match_key((string)($item->title ?? ''));
        if ($title_key !== '') { $keys[] = $title_key; }
        $object = (string)($item->object ?? '');
        $object_id = intval($item->object_id ?? 0);
        if ($object === 'page' && $object_id > 0) {
            $slug = (string)get_post_field('post_name', $object_id);
            $slug_key = self::normalize_match_key($slug);
            if ($slug_key !== '') { $keys[] = $slug_key; }
        } elseif ($object === 'category' && $object_id > 0) {
            $term = get_term($object_id, 'category');
            if ($term && !is_wp_error($term)) {
                $slug_key = self::normalize_match_key((string)($term->slug ?? ''));
                if ($slug_key !== '') { $keys[] = $slug_key; }
            }
        }
        $url_parts = self::path_parts_from_url((string)($item->url ?? ''));
        if (!empty($url_parts)) {
