            'uebungen' => 'topic-exercise',
        ];
        foreach ($unique_keys as $key) {
            foreach ($theme_map as $token => $icon_key) {
                if ($key === $token || strpos($key, $token . '-') === 0 || substr($key, -strlen('-' . $token)) === '-' . $token) {
                    return $icon_key;
                }
            }
        }
        return '';
    }

