    /**
     * V1.50.375: Ausschliesslich normale WordPress-Kategoriekacheln duerfen
     * das von der Bildzentrale gepflegte Termbild verwenden. Der bestehende
     * Iconpfad bleibt unveraendert und wird von cards_section() nur dann als
     * Fallback genutzt, wenn thumbnail_id fehlt oder kein gueltiges Bild ist.
     */
    private static function category_tile_term_image_markup($item) {
        if (!is_object($item) || (string)($item->object ?? '') !== 'category') { return ''; }
        $term_id = absint($item->object_id ?? 0);
        if ($term_id <= 0) { return ''; }

        $attachment_id = absint(get_term_meta($term_id, 'thumbnail_id', true));
        if ($attachment_id <= 0 || !wp_attachment_is_image($attachment_id)) { return ''; }

        $image = wp_get_attachment_image($attachment_id, 'medium', false, [
            'class' => 'pftk-category-image-element',
            'alt' => '',
            'aria-hidden' => 'true',
            'loading' => 'lazy',
            'decoding' => 'async',
        ]);
        if (!is_string($image) || trim($image) === '') { return ''; }

        return '<span class="pftk-category-icon pftk-category-image" aria-hidden="true">' . $image . '</span>';
    }

    private static function cards_section($type, $id, $title_key, $intro_key, $items, $item_type = 'page', $hide_head = false) {
        $items = self::valid_card_items($items);
        if (empty($items) && $type === 'category' && $id === 'pftk-topics') {
            return self::leaf_category_affiliate_section();
        }
        if (empty($items) && self::text($type, 'empty_text') === '') { return ''; }
        $title = $hide_head ? '' : self::text($type, $title_key);
        $intro = $hide_head ? '' : self::text($type, $intro_key);
        $section_classes = ['pftk-section'];
        if ($type === 'category' && $id === 'pftk-topics') {
            // V1.50.17: Ebene 3 mit Unterkategorie-Kacheln erhält eine explizite
            // Klasse. Der Abstand unter dem Kategorietext stammt dann ausschließlich
            // aus dem zentralen unteren Spacer - nie zusätzlich aus section margin.
            $section_classes[] = 'pftk-section-after-intro';
        }
        $section_style = ($type === 'category' && $id === 'pftk-topics') ? ' style="padding-top:34px!important"' : '';
        $out = '<section class="' . esc_attr(implode(' ', $section_classes)) . '" id="' . esc_attr($id) . '"' . $section_style . '>';
        if (!$hide_head && ($title !== '' || $intro !== '')) {
            $out .= '<div class="pftk-section-head">' .
                ($title !== '' ? '<h2 class="pftk-heading pftk-heading-' . esc_attr($title_key) . '">' . esc_html($title) . '</h2>' : '') .
                ($intro !== '' ? '<p>' . esc_html($intro) . '</p>' : '') .
                '</div>';
        }
        if (empty($items)) { return $out . self::empty_box($type) . '</section>'; }
        $count = count($items);
        $affiliate_cards = [];
        if ($id === 'pftk-topics' && in_array($type, ['hub1','hub2','category'], true) && in_array($count, [2,3,4,5], true)) {
            $affiliate_cards = self::grid_affiliate_cards($type, $count);
        }
        $render_count = $count + count($affiliate_cards);
        if (current_user_can('manage_options') && $id === 'pftk-topics' && in_array($type, ['hub1','hub2','category'], true)) {
            $out .= '<!-- pftk-v' . esc_html(self::VERSION) . ' balanced_grid type=' . esc_html($type) . ' real=' . intval($count) . ' ads=' . intval(count($affiliate_cards)) . ' render=' . intval($render_count) . ' -->';
        }
        $count_class = 'pftk-card-grid-count-' . intval($render_count);
        $out .= '<div class="pftk-card-grid ' . esc_attr($count_class) . '" data-pftk-card-count="' . esc_attr((string)$render_count) . '" data-pftk-real-count="' . esc_attr((string)$count) . '" data-pftk-partner-count="' . esc_attr((string)count($affiliate_cards)) . '">';
        $n = 1;
        foreach ($items as $item) {
            $desc = self::item_excerpt($item);
            $card_class = $item_type === 'post' ? 'pftk-card-post' : 'pftk-card-nav';
            $icon = '';
            if ($item_type === 'category') {
                $icon = self::category_tile_term_image_markup($item);
                if ($icon === '') { $icon = self::category_tile_icon_markup($item); }
            } elseif ($item_type === 'page') {
                $icon = self::category_tile_icon_markup($item);
            }
            if ($icon !== '') { $card_class .= ' pftk-has-category-icon'; }
            $cta = $item_type === 'post' ? self::article_excerpt_cta_v150325() : self::topic_cta_v150325();
            $out .= '<a class="pftk-card ' . esc_attr($card_class) . ' pftk-curve" style="--pftk-accent:' . esc_attr(self::color($n - 1)) . '" href="' . esc_url($item->url) . '">' .
                '<span class="pftk-number">' . esc_html(str_pad((string)$n, 2, '0', STR_PAD_LEFT)) . '</span>' .
                '<strong class="pftk-heading pftk-heading-card_title">' . esc_html($item->title) . '</strong>' .
                ($desc ? '<em>' . esc_html($desc) . '</em>' : '') .
                $icon .
                '<b>' . esc_html($cta) . '</b>' .
                '</a>';
            $n++;
        }
        $out .= implode('', $affiliate_cards);
        $out .= '</div>';
        return $out . '</section>';
    }

    private static function valid_card_items($items) {
        if ($items instanceof Traversable) { $items = iterator_to_array($items); }
        if (!is_array($items)) { $items = []; }
        $out = [];
        $seen = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $object = (string)($item->object ?? '');
            $object_id = intval($item->object_id ?? 0);
            $key = $object . ':' . $object_id . ':' . (string)($item->url ?? '');
            if (isset($seen[$key])) { continue; }
            if (in_array($object, ['page','post'], true)) {
                $post = get_post($object_id);
                if (!$post instanceof WP_Post || $post->post_status !== 'publish' || $post->post_type !== $object) { continue; }
                $item->title = get_the_title($post);
                $item->url = get_permalink($post);
            } elseif ($object === 'category') {
                $term = get_term($object_id, 'category');
                if (!$term || is_wp_error($term)) { continue; }
                $item->title = trim((string)$item->title) !== '' ? $item->title : $term->name;
                $url = get_term_link($term, 'category');
                if (is_wp_error($url)) { continue; }
                $item->url = $url;
            }
            if (empty($item->title) || empty($item->url)) { continue; }
            $out[] = $item;
            $seen[$key] = true;
        }
        return array_values($out);
    }

    private static function empty_box($type) {
        $text = self::text($type, 'empty_text');
        return $text !== '' ? '<div class="pftk-empty pftk-curve">' . esc_html($text) . '</div>' : '';
    }

    private static function wrap_link($html, $url, $target, $affiliate = false, $class = '') {
        $url = trim((string)$url);
        if ($url === '') { return $html; }
        $target = in_array($target, ['_self', '_blank'], true) ? $target : '_self';
        $rel = [];
        if ($affiliate) { $rel[] = 'sponsored'; $rel[] = 'nofollow'; }
        if ($target === '_blank') { $rel[] = 'noopener'; $rel[] = 'noreferrer'; }
        return '<a' . ($class ? ' class="' . esc_attr($class) . '"' : '') . ' href="' . esc_url($url) . '" target="' . esc_attr($target) . '"' . (!empty($rel) ? ' rel="' . esc_attr(implode(' ', array_unique($rel))) . '"' : '') . '>' . $html . '</a>';
    }


    /**
     * Entfernt auf automatisch gestalteten Portal-Seiten ausschliesslich leere
     * Absatz- und Spacer-Reste aus dem Editor. Inhalt, Bilder und Shortcodes
     * bleiben unangetastet. V1.50.15 setzt das automatisch erzeugte Portaltemplate
     * vor verbleibenden Editorinhalt. Damit beginnt der Kategorietext auf Ebene 3
     * immer direkt unter dem echten Seitentitel - auch bei Offenstallraufen.
     */
    private static function normalize_portal_spacing_content($content) {
        $content = (string)$content;
        $content = preg_replace('/<!--\s*wp:spacer\b.*?<!--\s*\/wp:spacer\s*-->/is', '', $content);
        $content = preg_replace('/<div\b[^>]*class=("|\')[^"\']*\bwp-block-spacer\b[^"\']*\1[^>]*>\s*<\/div>/is', '', $content);
        $content = preg_replace('/<p\b[^>]*>(?:\s|&nbsp;|&#160;|<br\s*\/?\s*>)*<\/p>/is', '', $content);
        return trim((string)$content);
    }

    private static function breadcrumb_home_crumb() {
        return ['name' => 'Startseite', 'url' => home_url('/')];
    }

    private static function breadcrumb_page_chain($page_id, $current_unlinked = true) {
        $page_id = absint($page_id);
        if ($page_id < 1) { return []; }
        $ids = array_reverse(array_map('absint', (array)get_post_ancestors($page_id)));
        $ids[] = $page_id;
        $crumbs = [self::breadcrumb_home_crumb()];
        foreach ($ids as $index => $id) {
            $title = trim((string)get_the_title($id));
            if ($title === '') { continue; }
            $is_last = ($index === count($ids) - 1);
            $crumbs[] = [
                'name' => $title,
                'url' => ($is_last && $current_unlinked) ? '' : (string)get_permalink($id),
            ];
        }
        return $crumbs;
    }

    private static function breadcrumb_category_chain($term_id, $current_unlinked = true) {
        $term_id = absint($term_id);
        if ($term_id < 1) { return []; }
        $ids = array_reverse(array_map('absint', (array)get_ancestors($term_id, 'category', 'taxonomy')));
        $ids[] = $term_id;
        $crumbs = [self::breadcrumb_home_crumb()];
        foreach ($ids as $index => $id) {
            $term = get_term($id, 'category');
            if (!is_object($term) || is_wp_error($term)) { continue; }
            $is_last = ($index === count($ids) - 1);
            $url = get_category_link($id);
            if (is_wp_error($url)) { $url = ''; }
            $crumbs[] = [
                'name' => (string)$term->name,
                'url' => ($is_last && $current_unlinked) ? '' : (string)$url,
            ];
        }
        return $crumbs;
    }

    /**
     * Artikelkategorien tragen im Produktionssystem einen Inhaltsart-Praefix
     * (z. B. FAQ, Beratung, Vergleich, Pflege oder Kosten). Der eigentliche
     * Portalpfad liegt auf der gleichnamigen veroeffentlichten Seite ohne diesen
     * Praefix. Nur ein exakt eindeutiger Seitentreffer ist zulaessig.
     */

    /**
     * V1.50.310: Die WordPress-Kategorien der letzten Portalebene sind technisch
     * flach (parent=0). Der fachliche Breadcrumbpfad wird daher aus der bestehenden
     * Menühierarchie aufgelöst und gegen einen vollständigen, sluggebundenen
     * Strukturvertrag mit 1.124 Kategorien abgesichert. Sichtbare Kategorienamen
     * stammen immer dynamisch aus dem aktuellen WP_Term; IDs, Slugs, URLs und
     * Taxonomie-Parents werden weder verändert noch ersetzt.
     */
    private static function breadcrumb_portal_contract_v150310() {
        static $map = null;
        if ($map !== null) { return $map; }
        $path = plugin_dir_path(__FILE__) . 'assets/breadcrumb-portal-map-v150310.json';
        if (!is_readable($path)) { return $map = []; }
        $raw = file_get_contents($path);
        $decoded = is_string($raw) ? json_decode($raw, true) : null;
        if (!is_array($decoded)
            || ($decoded['contract'] ?? '') !== 'PFTK_BREADCRUMB_PORTAL_MAP_V150310'
            || intval($decoded['category_count'] ?? 0) !== 1124
            || !is_array($decoded['categories'] ?? null)
            || count($decoded['categories']) !== 1124) {
            return $map = [];
        }
        return $map = $decoded['categories'];
    }

    private static function breadcrumb_page_crumb_v150310($page_id) {
        $page_id = absint($page_id);
        if ($page_id < 1) { return null; }
        $page = get_post($page_id);
        if (!$page instanceof WP_Post || $page->post_type !== 'page' || $page->post_status !== 'publish') { return null; }
        $title = trim((string)get_the_title($page_id));
        $url = trim((string)get_permalink($page_id));
        if ($title === '' || $url === '') { return null; }
        return ['name' => $title, 'url' => $url, 'page_id' => $page_id, 'slug' => (string)$page->post_name];
    }

    private static function breadcrumb_expected_page_slugs_v150310($term) {
        if (!is_object($term) || empty($term->slug)) { return []; }
        $map = self::breadcrumb_portal_contract_v150310();
        $entry = $map[(string)$term->slug] ?? null;
        if (!is_array($entry) || !is_array($entry['pages'] ?? null) || count($entry['pages']) !== 3) { return []; }
        $slugs = [];
        foreach ($entry['pages'] as $page) {
            $slug = sanitize_title((string)($page['slug'] ?? ''));
            if ($slug === '') { return []; }
            $slugs[] = $slug;
        }
        return $slugs;
    }

    /**
     * Primärquelle: bestehende WordPress-Menüstruktur. Mehrere Menüs sind nur
     * zulässig, wenn sie auf dieselbe Folge realer Seitenobjekte auflösen.
     */
    private static function breadcrumb_menu_page_chain_v150310($term) {
        if (!is_object($term) || empty($term->term_id) || empty($term->slug)) { return []; }
        $items = self::raw_nav_menu_items_unfiltered_bounded();
        if (empty($items)) { return []; }
        $by_id = [];
        foreach ($items as $item) {
            if (is_object($item) && !empty($item->ID)) { $by_id[absint($item->ID)] = $item; }
        }
        $expected = self::breadcrumb_expected_page_slugs_v150310($term);
        $chains = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $matches_term = (($item->object ?? '') === 'category' && absint($item->object_id ?? 0) === absint($term->term_id));
            if (!$matches_term && !empty($item->url)) {
                $matches_term = self::category_slug_from_url((string)$item->url) === (string)$term->slug;
            }
            if (!$matches_term) { continue; }
            $page_ids = [];
            $parent_id = absint($item->menu_item_parent ?? 0);
            $guard = 0;
            while ($parent_id > 0 && isset($by_id[$parent_id]) && $guard < 12) {
                $parent = $by_id[$parent_id];
                if (($parent->object ?? '') === 'page' && absint($parent->object_id ?? 0) > 0) {
                    $page_ids[] = absint($parent->object_id);
                }
                $parent_id = absint($parent->menu_item_parent ?? 0);
                $guard++;
            }
            $page_ids = array_reverse($page_ids);
            if (empty($page_ids)) { continue; }
            $crumbs = [self::breadcrumb_home_crumb()];
            $actual_slugs = [];
            $valid = true;
            foreach ($page_ids as $page_id) {
                $crumb = self::breadcrumb_page_crumb_v150310($page_id);
                if (!is_array($crumb)) { $valid = false; break; }
                $actual_slugs[] = sanitize_title((string)$crumb['slug']);
                unset($crumb['page_id'], $crumb['slug']);
                $crumbs[] = $crumb;
            }
            if (!$valid) { continue; }
            if (!empty($expected) && $actual_slugs !== $expected) { continue; }
            $key = implode('>', $actual_slugs);
            $chains[$key] = $crumbs;
        }
        return count($chains) === 1 ? reset($chains) : [];
    }

    /**
     * Sekundärquelle: vollständiger Strukturvertrag. Jede Seite muss als genau
     * ein veröffentlichtes Kind der vorherigen Seite existieren; sonst fail-closed.
     */
    private static function breadcrumb_contract_page_chain_v150310($term) {
        if (!is_object($term) || empty($term->slug)) { return []; }
        $map = self::breadcrumb_portal_contract_v150310();
        $entry = $map[(string)$term->slug] ?? null;
        if (!is_array($entry) || !is_array($entry['pages'] ?? null) || count($entry['pages']) !== 3) { return []; }
        $crumbs = [self::breadcrumb_home_crumb()];
        $parent_id = 0;
        foreach ($entry['pages'] as $expected) {
            $slug = sanitize_title((string)($expected['slug'] ?? ''));
            if ($slug === '') { return []; }
            $matches = get_posts([
                'post_type' => 'page',
                'post_status' => 'publish',
                'name' => $slug,
                'post_parent' => $parent_id,
                'posts_per_page' => 3,
                'orderby' => 'ID',
                'order' => 'ASC',
                'no_found_rows' => true,
                'suppress_filters' => true,
            ]);
            if (!is_array($matches) || count($matches) !== 1 || !$matches[0] instanceof WP_Post) { return []; }
            $page = $matches[0];
            $crumb = self::breadcrumb_page_crumb_v150310($page->ID);
            if (!is_array($crumb) || sanitize_title((string)$crumb['slug']) !== $slug) { return []; }
            $parent_id = absint($page->ID);
            unset($crumb['page_id'], $crumb['slug']);
            $crumbs[] = $crumb;
        }
        return count($crumbs) === 4 ? $crumbs : [];
    }

    private static function breadcrumb_portal_page_chain_v150310($term) {
        static $cache = [];
        if (!is_object($term) || empty($term->term_id) || empty($term->slug)) { return []; }
        $key = absint($term->term_id) . ':' . (string)$term->slug;
        if (array_key_exists($key, $cache)) { return $cache[$key]; }
        $menu = self::breadcrumb_menu_page_chain_v150310($term);
        if (!empty($menu)) { return $cache[$key] = $menu; }
        return $cache[$key] = self::breadcrumb_contract_page_chain_v150310($term);
    }

    private static function breadcrumb_portal_category_chain_v150310($term, $current_unlinked = true) {
        if (!is_object($term) || empty($term->term_id) || empty($term->name)) { return []; }
        $crumbs = self::breadcrumb_portal_page_chain_v150310($term);
        if (empty($crumbs)) { return []; }
        $url = get_category_link(absint($term->term_id));
        if (is_wp_error($url)) { $url = ''; }
        $crumbs[] = [
            'name' => (string)$term->name,
            'url' => $current_unlinked ? '' : (string)$url,
        ];
        return $crumbs;
    }

    private static function article_category_topic_name_v150297($category_name) {
        $name = trim((string)$category_name);
        if ($name === '') { return ''; }
        $intents = [
            'FAQ','Beratung','Kaufberatung','Vergleich','Pflege','Kosten','Checkliste','Checklisten',
            'Ratgeber','Anwendung','Sicherheit','Lagerung','Installation','Übungen','Uebungen',
            'Einsatz','Material','Modelle','Arten','Test','Anleitung'
        ];
        $pattern = implode('|', array_map(function($v){ return preg_quote($v, '/'); }, $intents));
        $topic = trim((string)preg_replace('/^(?:' . $pattern . ')\s+/iu', '', $name));
        if ($topic === $name) {
            $topic = trim((string)preg_replace('/\s+(?:' . $pattern . ')$/iu', '', $name));
        }
        return $topic === $name ? '' : $topic;
    }

    private static function resolve_portal_page_id_for_article_category($category) {
        if (!is_object($category) || empty($category->name)) { return 0; }
        $topic = self::article_category_topic_name_v150297((string)$category->name);
        if ($topic === '') { return 0; }
        $matches = [];
        foreach ((array)get_pages(['post_status' => 'publish', 'post_type' => 'page']) as $page) {
            if (!is_object($page) || empty($page->ID)) { continue; }
            if (trim(wp_strip_all_tags((string)get_the_title($page->ID))) === $topic) {
                $matches[] = absint($page->ID);
                if (count($matches) > 1) { return 0; }
            }
        }
        return count($matches) === 1 ? $matches[0] : 0;
    }

    /**
     * Verbindliche Primärkategorie fuer Beitrags-Breadcrumbs.
     * Reihenfolge: expliziter Filter, Yoast, Rank Math, eigene Meta, exakt eine
     * zugewiesene Kategorie. Bei mehreren Kategorien ohne eindeutige Vorgabe
     * wird nur dann fortgefahren, wenn genau eine erkannte Artikelkategorie
     * eindeutig auf eine Portalseite aufloest. Sonst fail-closed.
     */
    private static function primary_article_category_v150297($post_id) {
        $post_id = absint($post_id);
        if ($post_id < 1) { return null; }
        $categories = get_the_category($post_id);
        if (!is_array($categories) || empty($categories)) { return null; }
        $by_id = [];
        foreach ($categories as $category) {
            if (is_object($category) && !empty($category->term_id)) {
                $by_id[absint($category->term_id)] = $category;
            }
        }
        if (empty($by_id)) { return null; }

        $explicit_ids = [
            absint(apply_filters('pftk_primary_article_category_id', 0, $post_id, array_values($by_id))),
            absint(get_post_meta($post_id, '_yoast_wpseo_primary_category', true)),
            absint(get_post_meta($post_id, 'rank_math_primary_category', true)),
            absint(get_post_meta($post_id, '_pftk_primary_category', true)),
        ];
        foreach ($explicit_ids as $term_id) {
            if ($term_id > 0 && isset($by_id[$term_id])) { return $by_id[$term_id]; }
        }
        if (count($by_id) === 1) { return reset($by_id); }

        $resolved = [];
        foreach ($by_id as $term_id => $category) {
            if (self::resolve_portal_page_id_for_article_category($category) > 0) {
                $resolved[$term_id] = $category;
            }
        }
        return count($resolved) === 1 ? reset($resolved) : null;
    }

    private static function render_breadcrumb_markup($crumbs, $include_style = true) {
        if (!is_array($crumbs) || count($crumbs) < 2) { return ''; }
        $visible = [];
        $schema_items = [];
        $position = 1;
        foreach ($crumbs as $crumb) {
            $name = trim((string)($crumb['name'] ?? ''));
            $url = trim((string)($crumb['url'] ?? ''));
            if ($name === '') { continue; }
            if ($url === '') {
                $visible[] = '<span class="pftk-content-breadcrumb-current" aria-current="page">' . esc_html($name) . '</span>';
            } else {
                $visible[] = '<a href="' . esc_url($url) . '">' . esc_html($name) . '</a>';
            }
            $item = ['@type' => 'ListItem', 'position' => $position, 'name' => wp_strip_all_tags($name)];
            if ($url !== '') { $item['item'] = $url; }
            $schema_items[] = $item;
            $position++;
        }
        if (count($visible) < 2) { return ''; }
        $schema = ['@context' => 'https://schema.org', '@type' => 'BreadcrumbList', 'itemListElement' => $schema_items];
        $style = $include_style
            ? '<style id="pftk-universal-breadcrumb-v150311">.pftk-universal-breadcrumb-wrap{width:100%;margin:0 0 16px}.pftk-content-breadcrumb{display:flex;flex-wrap:wrap;align-items:center;column-gap:7px;row-gap:5px;margin:0 0 16px;font-size:14px;line-height:1.5;color:#72786F}.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb-separator{display:inline-flex;align-items:center;margin-left:2px;margin-right:3px;color:#92988F!important}.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb a,.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb a:visited{color:#72786F!important;font-weight:400!important;text-decoration:none!important;text-decoration-color:transparent!important}.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb a:hover,.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb a:focus-visible{color:#9A6400!important;text-decoration:underline!important;text-decoration-color:#9A6400!important;text-underline-offset:3px}.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb a:focus-visible{outline:2px solid #9A6400!important;outline-offset:3px}.pftk-universal-breadcrumb-wrap .pftk-content-breadcrumb-current{color:#4F5650!important;font-weight:500!important;text-decoration:none!important}
