    /**
     * V1.50.332 – robuste Erkennung der ausschließlich untersten
     * Kategorie-/Beitragsübersichts-Ebene.
     *
     * Der bisherige Menütest war im Live-System falsch: Unterste Kategorien müssen
     * nicht selbst als Menüpunkt eingetragen sein. Deshalb wurde das echte Archiv
     * „Vergleich Winterdecken“ trotz korrekter Kategorie-URL nicht erkannt und der
     * alte Renderer blieb aktiv. Ab V1.50.332 gilt ausschließlich die tatsächliche
     * Taxonomiestruktur: keine Kindkategorie + eindeutig erkannte Beitragsart.
     */
    private static function leaf_category_intent_v150332($term) {
        if (!is_object($term)) { return ''; }
        $key = self::normalize_match_key(trim((string)($term->name ?? '')) . ' ' . trim((string)($term->slug ?? '')));
        if ($key === '') { return ''; }
        $intents = [
            'faq' => 'faq',
            'beratung' => 'beratung',
            'vergleich' => 'vergleich',
            'pflege' => 'pflege',
            'sicherheit' => 'sicherheit',
            'anwendung' => 'anwendung',
            'kosten' => 'kosten',
            'installation' => 'installation',
            'lagerung' => 'lagerung',
            'uebung' => 'uebungen',
            'uebungen' => 'uebungen',
            'test' => 'test',
            'anleitung' => 'anleitung',
            'checkliste' => 'checkliste',
            'checklisten' => 'checkliste',
        ];
        $tokens = array_values(array_filter(explode('-', $key)));
        foreach ($intents as $needle => $intent) {
            if (in_array($needle, $tokens, true)) { return $intent; }
        }
        return '';
    }

    private static function is_portal_leaf_category_v150273($term_id = 0) {
        if (!is_category()) { return false; }
        $term_id = absint($term_id ?: get_queried_object_id());
        if ($term_id <= 0) { return false; }
        $term = get_term($term_id, 'category');
        if (!$term || is_wp_error($term) || empty($term->term_id)) { return false; }

        // Harte Negativregel: Sobald eine direkte oder indirekte Unterkategorie
        // existiert, ist dies keine unterste Kategorieebene.
        $children = get_term_children($term_id, 'category');
        if (is_wp_error($children) || !empty($children)) { return false; }

        // Harte Positivregel: Die unterste Portalebene besitzt eine definierte
        // Beitragsart im realen Kategorienamen/-slug. Journal- und sonstige
        // Taxonomiearchive ohne diese Beitragsart bleiben unangetastet.
        return self::leaf_category_intent_v150332($term) !== '';
    }

    public static function owns_leaf_category_affiliate_slots_v150334($owned, $term_id = 0) {
        if (is_admin() || !is_category()) { return (bool)$owned; }
        $term_id = absint($term_id ?: get_queried_object_id());
        return self::is_portal_leaf_category_v150273($term_id) ? true : (bool)$owned;
    }

    public static function portal_leaf_category_template_v150273($template) {
        if (is_admin() || !is_category()) { return $template; }
        $term_id = absint(get_queried_object_id());
        if (!self::is_portal_leaf_category_v150273($term_id)) { return $template; }
        $custom = plugin_dir_path(__FILE__) . 'templates/category-leaf-v150273.php';
        return is_readable($custom) ? $custom : $template;
    }

    /**
     * V1.50.330 – ausschließlich unterste Kategorie-/Beitragsübersichtsebene.
     * Ermittelt aus dem individuellen Produktthema ein belastbares Kriterienprofil.
     * Höhere Ebenen und Einzelbeiträge verwenden diese Funktion nicht.
     */
    private static function leaf_category_topic_profile_v150330($topic) {
        $topic_key = self::normalize_match_key($topic);
        $profiles = self::category_text_topic_profiles();
        if (isset($profiles[$topic_key]) && is_array($profiles[$topic_key])) {
            return $profiles[$topic_key];
        }

        $canonical_topic = str_replace(['-und-', '-fuer-', '-im-', '-am-'], '-', $topic_key);
        $profile_keys = array_keys($profiles);
        usort($profile_keys, function($a, $b) { return strlen((string)$b) - strlen((string)$a); });
        foreach ($profile_keys as $profile_key) {
            $canonical_profile = str_replace(['-und-', '-fuer-', '-im-', '-am-'], '-', self::normalize_match_key($profile_key));
            if ($canonical_profile === '') { continue; }
            if (strpos($canonical_topic, $canonical_profile) !== false || strpos($canonical_profile, $canonical_topic) !== false) {
                return is_array($profiles[$profile_key]) ? $profiles[$profile_key] : [];
            }
        }

        $aliases = [
            'decken' => 'decken', 'halfter' => 'halfter-stricke', 'stricke' => 'halfter-stricke',
            'sattel' => 'sattel', 'trense' => 'trensen-gebisse', 'gebiss' => 'trensen-gebisse',
            'zaun' => 'zaeune', 'futter' => 'fuetterung', 'heu' => 'heuqualitaet',
            'trank' => 'traenken', 'wasser' => 'wassertechnik', 'huf' => 'hufe',
            'haut' => 'fell-haut', 'fell' => 'fell-haut', 'insekten' => 'insekten-schutz',
            'anhaenger' => 'pferdeanhaenger', 'transport' => 'transport-zubehoer',
            'software' => 'apps-software', 'app' => 'apps-software', 'versicherung' => 'versicherungen-recht',
        ];
        foreach ($aliases as $needle => $profile_key) {
            if (strpos($topic_key, $needle) !== false && isset($profiles[$profile_key]) && is_array($profiles[$profile_key])) {
                return $profiles[$profile_key];
            }
        }
        return ['focus' => 'Eignung, Qualität und praktische Nutzung', 'criteria' => ['Eignung', 'Qualität', 'Handhabung', 'Praxisnutzen']];
    }

    /**
     * V1.50.330 – individueller Einleitungstext der untersten Kategorieebene.
     * Der erste Satz beginnt portalweit mit „Diese Seite hilft dir“, wiederholt
     * den Seitentitel aber nicht am Satzanfang. Thema und Beitragsart steuern
     * den restlichen Text deterministisch.
     */
    private static function leaf_category_intro_v150330($type, $topic, $criteria, $seed = '', $parent = '') {
        $topic = trim((string)$topic) !== '' ? trim((string)$topic) : 'dieses Thema';
        $pilot_key = 'leaf/' . self::normalize_match_key($topic) . '/' . trim((string)$type);
        $pilot_intro = self::deck_intro_only_v150389($pilot_key, '');
        if ($pilot_intro !== '') { return $pilot_intro; }
        $criteria = array_values(array_filter(array_map('trim', (array)$criteria)));
        while (count($criteria) < 4) { $criteria[] = 'Praxisnutzen'; }
        $intent_map = [
            'FAQ' => 'Antworten auf häufige Fragen', 'Beratung' => 'Auswahlhilfen und Entscheidungshilfen',
            'Vergleich' => 'Vergleiche und Unterschiede', 'Pflege' => 'Pflegehinweise und Werterhalt',
            'Sicherheit' => 'Sicherheitshinweise und Risikoprüfung', 'Anwendung' => 'Anwendungstipps und Praxiswissen',
            'Kosten' => 'Kostenübersichten und Preisfragen', 'Installation' => 'Planung und Umsetzung',
            'Lagerung' => 'Lagerung und Qualitätsschutz', 'Übungen' => 'Übungen und Trainingsaufbau',
            'Anleitung' => 'Anleitungen und konkrete Schritte', 'Checkliste' => 'Checklisten und Prüfpunkte',
            'Test' => 'Tests, Kriterien und Einordnung',
        ];
        $intent = $intent_map[$type] ?? ($type !== '' ? $type . ' und Praxiswissen' : 'Ratgeber und praktische Hinweise');
        $subject = $topic;
        $profile = self::leaf_category_topic_profile_v150330($topic);
        $focus = trim((string)($profile['focus'] ?? ('Eignung, Qualität und praktische Nutzung von ' . $topic)));
        $seed = ($seed !== '' ? $seed : 'leaf|' . self::normalize_match_key($parent) . '|' . self::normalize_match_key($topic) . '|' . self::normalize_match_key($type));
        return self::portal_lower_intro_v150396($subject, $focus, $criteria, $parent, [], $intent, $seed);
    }

    /**
     * V1.50.330 – kurze individuelle Partner-H2 ohne Seitentitel und ohne
     * Hauptkeyword. Kriterien, Beitragsart und ein deterministischer Themenwert
     * verhindern eine portalweite Einheitsüberschrift, ohne konkrete Produkte
     * oder eine bestimmte Befüllung zu behaupten.
     */
    /**
     * V1.50.335 – Partner-H2 der untersten Kategorieebene.
     * Zuerst wird die auf der geblockten Referenzebene redaktionell gepflegte
     * Überschrift genutzt. Sie darf das Hauptthema nicht wörtlich wiederholen.
     * Nur wenn keine belastbare Referenz vorliegt, folgt ein kurzer, neutraler
     * Fallback ohne Produkt- oder Verfügbarkeitsbehauptung.
     */
    private static function leaf_category_partner_heading_v150335($type, $topic, $criteria) {
        $topic = trim((string)$topic);
        $reference = self::contextual_section_headings_v150286($topic, '', $criteria);
        $heading = trim((string)($reference['network_title'] ?? ''));
        $topic_key = self::normalize_match_key($topic);
        $heading_key = self::normalize_match_key($heading);
        $is_generic_reference = strpos($heading_key, 'marken-und-angebote-rund-um') !== false;
        // Die Referenzueberschrift wird nur fuer Vergleichsseiten direkt
        // uebernommen. Alle anderen Beitragsarten erhalten aus denselben
        // Kriterien eine eigene Formulierung, damit jede Seite individuell
        // bleibt und keine produktweite Wiederholung entsteht.
        if ($type === 'Vergleich' && !$is_generic_reference && $heading !== '' && ($topic_key === '' || strpos('-' . $heading_key . '-', '-' . $topic_key . '-') === false)) {
            return $heading;
        }

        $criteria = array_values(array_filter(array_map('trim', (array)$criteria)));
        while (count($criteria) < 4) { $criteria[] = 'Praxisnutzen'; }
        $seed = abs(crc32(self::normalize_match_key($topic) . '|' . self::normalize_match_key($type)));
        $orders = [
            [0,1,2], [0,2,3], [1,2,0], [1,3,2], [2,3,1], [3,0,2],
            [2,0,1], [3,1,0], [0,3,1], [1,0,3], [2,1,3], [3,2,0],
        ];
        $order = $orders[$seed % count($orders)];
        $a = $criteria[$order[0]]; $b = $criteria[$order[1]]; $c = $criteria[$order[2]];
        $templates = [
            'FAQ' => ['%1$s und %2$s verständlich erklärt', '%1$s, %2$s und %3$s im Blick', 'Klare Antworten zu %1$s und %2$s'],
            'Beratung' => ['%1$s und %2$s sicher abwägen', '%1$s, %2$s und %3$s gut einordnen', 'Orientierung bei %1$s und %2$s'],
            'Vergleich' => ['%1$s und %2$s sinnvoll abwägen', '%1$s, %2$s und %3$s im Vergleich', 'Klare Orientierung bei %1$s und %2$s'],
            'Pflege' => ['%1$s und %2$s dauerhaft erhalten', '%1$s, %2$s und %3$s richtig pflegen', 'Werterhalt durch %1$s und %2$s'],
            'Sicherheit' => ['%1$s und %2$s zuverlässig absichern', '%1$s, %2$s und %3$s sicher prüfen', 'Mehr Sicherheit bei %1$s und %2$s'],
            'Anwendung' => ['%1$s und %2$s richtig verbinden', '%1$s, %2$s und %3$s praktisch nutzen', 'Sicherer Einsatz mit %1$s und %2$s'],
            'Kosten' => ['%1$s und %2$s realistisch bewerten', '%1$s, %2$s und %3$s im Kostenblick', 'Preisfragen zu %1$s und %2$s'],
            'Installation' => ['%1$s und %2$s sauber umsetzen', '%1$s, %2$s und %3$s richtig vorbereiten', 'Planung mit %1$s und %2$s'],
            'Lagerung' => ['%1$s und %2$s sinnvoll bewahren', '%1$s, %2$s und %3$s gut organisieren', 'Ordnung für %1$s und %2$s'],
            'Übungen' => ['%1$s und %2$s gezielt trainieren', '%1$s, %2$s und %3$s sinnvoll aufbauen', 'Praxis mit %1$s und %2$s'],
            'Anleitung' => ['%1$s und %2$s Schritt für Schritt', '%1$s, %2$s und %3$s sicher umsetzen', 'Klare Schritte für %1$s und %2$s'],
            'Checkliste' => ['%1$s und %2$s schnell überblicken', '%1$s, %2$s und %3$s sicher prüfen', 'Wichtige Punkte zu %1$s und %2$s'],
            'Test' => ['%1$s und %2$s sachlich einordnen', '%1$s, %2$s und %3$s praxisnah prüfen', 'Praxischeck für %1$s und %2$s'],
        ];
        $choices = $templates[$type] ?? ['%1$s und %2$s im Blick', '%1$s, %2$s und %3$s gut einordnen', 'Orientierung bei %1$s und %2$s'];
        return sprintf($choices[intdiv($seed, 13) % count($choices)], $a, $b, $c);
    }

    /**
     * V1.50.331 – ausschließlich reale Befüllung auf der untersten Ebene.
     * Die echte Kategorie-Term-ID wird an die Affiliate-Zentrale übergeben.
     * Dadurch entscheidet nicht mehr ein zufälliges globales Beitragsobjekt über
     * die Ausgabe. Ohne reale Antwort entstehen weder Sektion noch Leerraum.
     */
    private static function leaf_category_affiliate_slot_v150331($term_id, $slot) {
        $term_id = absint($term_id);
        $slot = sanitize_key((string)$slot);
        if ($term_id <= 0 || $slot === '') { return ''; }
        $context = [
            'contract' => self::AFFILIATE_CONTRACT,
            'design_version' => self::VERSION,
            'template' => 'leaf_category_archive',
        ];
        $candidate = apply_filters('pftk_leaf_category_affiliate_slot_html', '', $term_id, $slot, $context);
        return is_string($candidate) ? trim($candidate) : '';
    }

    private static function leaf_category_real_banner_v150331($term_id) {
        $candidate = self::leaf_category_affiliate_slot_v150331($term_id, 'product_after_category_tiles');
        return self::category_affiliate_banner_is_real_v150308($candidate) ? $candidate : '';
    }

    private static function leaf_category_real_products_v150331($term_id) {
        $products = [];
        for ($index = 1; $index <= 3; $index++) {
            $slot = 'category_product_' . $index;
            $candidate = self::leaf_category_affiliate_slot_v150331($term_id, $slot);
            if (!self::category_affiliate_product_is_real_v150308($candidate)) { continue; }
            $products[] = '<div class="pa266-product is-real" data-pa266-slot="' . esc_attr($slot) . '">' . $candidate . '</div>';
        }
        return $products;
    }

    /**
     * V1.50.335 – neutrale, rein grafische Admin-Prüfflächen ausschließlich
     * auf der untersten Kategorieebene. Referenz ist die bereits bestätigte
     * Einzelbeitrags-Vorschau: keine Texte, keine Bilder, keine Buttons.
     */
    private static function leaf_category_banner_preview_v150335() {
        return '<div class="pa335-banner-preview" data-pa335-admin-preview="1" role="img" aria-label="Neutrale Banner-Prüffläche"></div>';
    }

    private static function leaf_category_product_preview_v150335($index) {
        $index = max(1, min(3, intval($index)));
        return '<div class="pa266-product pa335-product-preview" data-pa335-admin-preview="1" data-pa335-product-preview="' . $index . '" aria-hidden="true"></div>';
    }

    private static function leaf_category_hub_context_v150396($term) {
        if (!is_object($term)) { return ''; }
        $slug = sanitize_title((string)($term->slug ?? ''));
        if ($slug === '') { return ''; }
        static $portal_map = null;
        if ($portal_map === null) {
            $portal_map = [];
            $path = plugin_dir_path(__FILE__) . 'assets/breadcrumb-portal-map-v150310.json';
            if (is_readable($path)) {
                $decoded = json_decode((string)file_get_contents($path), true);
                if (is_array($decoded) && isset($decoded['categories']) && is_array($decoded['categories'])) {
                    $portal_map = $decoded['categories'];
                }
            }
        }
        $entry = $portal_map[$slug] ?? null;
        $pages = is_array($entry) && isset($entry['pages']) && is_array($entry['pages']) ? array_values($entry['pages']) : [];
        if (count($pages) >= 2) {
            $hub = $pages[count($pages) - 2];
            $title = is_array($hub) ? trim((string)($hub['title'] ?? '')) : '';
            if ($title !== '') { return $title; }
        }
        $parent_term_id = absint($term->parent ?? 0);
        if ($parent_term_id > 0) {
            $parent_term = get_term($parent_term_id, 'category');
            if ($parent_term && !is_wp_error($parent_term)) { return trim((string)($parent_term->name ?? '')); }
        }
        return '';
    }

    private static function leaf_category_profile_v150273($term) {
        $title = trim((string)($term->name ?? 'Inhalte'));
        $slug = sanitize_title($title);
        $type = 'Inhalte';
        $topic = $title;
        $rules = [
            'faq' => ['type'=>'FAQ','kicker'=>'Klare Antworten auf wichtige Fragen'],
            'beratung' => ['type'=>'Beratung','kicker'=>'Sicher und passend entscheiden'],
            'vergleich' => ['type'=>'Vergleich','kicker'=>'Unterschiede klar erkennen'],
            'pflege' => ['type'=>'Pflege','kicker'=>'Länger sauber und funktionstüchtig'],
            'sicherheit' => ['type'=>'Sicherheit','kicker'=>'Risiken erkennen und vermeiden'],
            'anwendung' => ['type'=>'Anwendung','kicker'=>'Sicher und sinnvoll einsetzen'],
            'kosten' => ['type'=>'Kosten','kicker'=>'Preise realistisch einordnen'],
            'installation' => ['type'=>'Installation','kicker'=>'Sauber planen und umsetzen'],
            'lagerung' => ['type'=>'Lagerung','kicker'=>'Ordnung und Qualität bewahren'],
            'uebungen' => ['type'=>'Übungen','kicker'=>'Gezielt üben und weiterkommen'],
            'test' => ['type'=>'Test','kicker'=>'Praxisnah geprüft und eingeordnet'],
            'anleitung' => ['type'=>'Anleitung','kicker'=>'Schritt für Schritt richtig handeln'],
            'checkliste' => ['type'=>'Checkliste','kicker'=>'Wichtige Punkte schnell im Blick'],
        ];
        $matched = null;
        foreach ($rules as $key=>$r) {
            if (strpos($slug, $key) !== false) { $matched=$r; break; }
        }
        if ($matched) {
            $type=$matched['type'];
            $topic=trim(preg_replace('/\b'.preg_quote($type,'/').'\b/iu','',$title));
            if ($topic==='') { $topic=$title; }
            $kicker=$matched['kicker'];
        } else {
            $kicker='Wissen für den Alltag mit Pferd';
        }
        $profile = self::leaf_category_topic_profile_v150330($topic);
        $criteria = array_values(array_filter(array_map('trim', (array)($profile['criteria'] ?? []))));
        while (count($criteria) < 4) { $criteria[] = 'Praxisnutzen'; }
        $hub_context = self::leaf_category_hub_context_v150396($term);
        $intro = self::category_intro_editorial_leaf_batch1359_v150421($term);
        if ($intro === '') { $intro = self::leaf_category_intro_v150330(
            $type,
            $topic,
            $criteria,
            'leaf-term|' . self::normalize_match_key($hub_context) . '|' . self::normalize_match_key($topic) . '|' . self::normalize_match_key($type),
            $hub_context
        ); }
        return [
            'title'=>$title,
            'topic'=>$topic,
            'type'=>$type,
            'kicker'=>$kicker,
            'intro'=>$intro,
            'posts_title'=>$type . ' zu ' . $topic,
            'posts_intro'=>'Hier findest du alle vorhandenen Beiträge zu ' . $title . '. Jeder Beitrag behandelt eine konkrete Frage und führt direkt zum vollständigen Inhalt.',
            'banner_kicker'=>'Ausgewählter Partner',
            'banner_title'=>self::leaf_category_partner_heading_v150335($type, $topic, $criteria),
            'banner_intro'=>'',
            'products_kicker'=>'Produktvorschläge',
            'products_title'=>'Passende Produkte zu ' . $topic,
            'products_intro'=>'',
        ];
    }

    private static function leaf_category_posts_v150273($term_id, $limit = 30) {
        return self::top_posts_by_importance([absint($term_id)], max(1, intval($limit)));
    }

    /**
     * V1.50.376: Ausschliesslich der separate Renderer eines geoeffneten,
     * untersten normalen WordPress-Kategoriearchivs darf das von der
     * Bildzentrale gepflegte Termbild oberhalb des vorhandenen Intro-Kickers
     * ausgeben. Ohne gueltiges thumbnail_id bleibt der bisherige Renderer
     * vollstaendig unveraendert und erzeugt weder Markup noch Leerraum.
     */
    private static function leaf_category_term_image_markup_v150376($term) {
        if (!is_object($term) || (string)($term->taxonomy ?? '') !== 'category') { return ''; }
        $term_id = absint($term->term_id ?? 0);
        if ($term_id <= 0) { return ''; }

        $attachment_id = absint(get_term_meta($term_id, 'thumbnail_id', true));
        if ($attachment_id <= 0 || get_post_type($attachment_id) !== 'attachment' || !wp_attachment_is_image($attachment_id)) { return ''; }

        $full = wp_get_attachment_image_src($attachment_id, 'full');
        if (!is_array($full) || empty($full[0])) { return ''; }

        $src = (string)$full[0];
        $width = absint($full[1] ?? 0);
        $height = absint($full[2] ?? 0);
        if ($src === '' || $width <= 0 || $height <= 0) { return ''; }

        $alt = trim((string)get_post_meta($attachment_id, '_wp_attachment_image_alt', true));
        if ($alt === '') { $alt = trim((string)get_the_title($attachment_id)); }

        $image = '<img src="' . esc_url($src) . '" width="' . intval($width) . '" height="' . intval($height) . '" alt="' . esc_attr($alt) . '" class="pa376-category-image-element" loading="eager" decoding="async" fetchpriority="high">';

        return '<figure class="pa376-category-image" data-pa376-term-image="' . intval($attachment_id) . '">' . $image . '</figure>';
    }

    public static function render_leaf_category_archive_v150273() {
        $term = get_queried_object();
        if (!$term || empty($term->term_id)) { return ''; }
        $term_id=absint($term->term_id);
        $t=self::leaf_category_profile_v150273($term);
        $posts=self::leaf_category_posts_v150273($term_id,30);
        $affiliate_banner = self::leaf_category_real_banner_v150331($term_id);
        $affiliate_products = self::leaf_category_real_products_v150331($term_id);

        // V1.50.335 – gleiche Sichtpruefung wie auf den bestaetigten hoeheren
        // Ebenen: Administratoren sehen bei leerer realer Befuellung eine neutrale
        // Vorschau an der endgueltigen Position. Ausgeloggte Besucher sehen weder
        // Vorschau noch Ueberschrift noch Leerraum.
        $admin_preview_count = self::category_affiliate_admin_preview_count_v150308();
        if ($affiliate_banner === '' && $admin_preview_count > 0) {
            $affiliate_banner = self::leaf_category_banner_preview_v150335();
        }
        if (!$affiliate_products && $admin_preview_count > 0) {
            for ($index = 1; $index <= $admin_preview_count; $index++) {
                $affiliate_products[] = self::leaf_category_product_preview_v150335($index);
            }
        }
        $affiliate_product_count = count($affiliate_products);
        $category_image = self::leaf_category_term_image_markup_v150376($term);

        $leaf_image_class = $category_image !== '' ? ' pa273-leaf-archive-has-image-v150385' : '';
        $intro_image_class = $category_image !== '' ? ' pa273-intro-has-image-v150385' : '';
        $out='<main id="primary" class="site-main pa273-leaf-archive'.$leaf_image_class.'" data-pa335-leaf-only="1">';
        $out.='<section class="pa273-intro'.$intro_image_class.'">'.$category_image.'<span>'.esc_html($t['kicker']).'</span><h1>'.esc_html($t['title']).'</h1>'.self::deck_intro_markup_v150390($t['intro']).'</section>';

        // V1.50.335 – Partnerbereich ausnahmslos oberhalb der Beitragskarten.
        // Oeffentlich nur bei realer Befuellung; Admin-Vorschau nur eingeloggt.
        if ($affiliate_banner !== '') {
            $out.='<section class="pa273-section pa335-partner-section"><header><span>'.esc_html($t['banner_kicker']).'</span><h2>'.esc_html($t['banner_title']).'</h2></header><div class="pa273-banner-slot is-real">'.$affiliate_banner.'</div></section>';
        }

        $out.='<section class="pa273-section pa277-posts-section">';
        if (!$posts) {
            $out.='<div class="pa273-empty">Zu '.esc_html($t['title']).' sind aktuell noch keine Beiträge veröffentlicht.</div>';
        } else {
            $out.='<div class="pa273-post-grid count-' . intval(count((array)$posts)) . '" data-pftk-post-card-count="' . intval(count((array)$posts)) . '">';
            foreach ($posts as $post) {
                $out.=self::render_leaf_post_card_v150272($post);
            }
            $out.='</div>';
        }
        $out.='</section>';

        // V1.50.335 – Produktvorschlaege ausnahmslos unterhalb der Beitragskarten.
        // Oeffentlich nur 1–3 reale Produkte; Admin-Vorschau nur eingeloggt.
        if ($affiliate_product_count > 0) {
            $out.='<section class="pa273-section pa335-products-section"><header><span>'.esc_html($t['products_kicker']).'</span><h2>'.esc_html($t['products_title']).'</h2>'.(trim((string)$t['products_intro']) !== '' ? '<p>'.esc_html($t['products_intro']).'</p>' : '').'</header><div class="pa273-product-grid count-'.intval($affiliate_product_count).'" data-pa335-product-count="'.intval($affiliate_product_count).'">'.implode('', $affiliate_products).'</div></section>';
        }

        // V1.50.360 – Der direkt buchbare Werbeplatz ist auch auf echten
        // Kategoriearchiven wieder sichtbar und nutzt den Startseiten-Renderer.
        $out.='<section class="pa273-section pa336-direct pftk-direct-responsive-v150360"><header><span>Direkt buchbarer Werbeplatz</span><h2>Hier könnte Ihre Anzeige stehen</h2></header>'.self::start_ad_slot_v150162('leaf-category-direct-'.$term_id, 'leaf-category-direktwerbung', 'wide').'</section>';
        $out.='</main>';
        $out.='<!-- pftk-v'.esc_html(self::VERSION).' leaf-template-active term='.intval($term_id).' -->';
        $out.='<style id="pa335-leaf-css">'
            .'.pa273-leaf-archive{--o:#35422A;--a:#C89214;--copy:#687066;--t:#1F231F;width:min(calc(100vw - 32px),1180px);margin:0 auto;padding:12px 0 72px;color:var(--t)}'
            .'.pa273-leaf-archive h1,.pa273-leaf-archive h2,.pa273-leaf-archive h3,.pa273-leaf-archive h3 a,.pa273-leaf-archive h3 a:visited{font-family:Georgia,serif;color:var(--o)!important;text-align:center;text-decoration:none!important}'
            .'.pa273-intro{border-top:1px solid rgba(53,66,42,.24);border-bottom:1px solid rgba(53,66,42,.24);padding:32px 0;text-align:center}'
            .'.pa273-intro>span,.pa273-section>header>span{display:flex;align-items:center;justify-content:center;gap:12px;color:var(--a);font-size:11px;font-weight:700;letter-spacing:.09em;text-transform:uppercase}'
            .'.pa273-intro>span:before,.pa273-intro>span:after,.pa273-section>header>span:before,.pa273-section>header>span:after{content:"";width:42px;height:1px;background:rgba(200,146,20,.45)}'
