            .'.pa273-intro p,.pa273-section>header p{margin:0 auto}'
            .($category_image !== '' ? '.pa273-leaf-archive-has-image-v150385{padding-top:0!important}.pa273-intro-has-image-v150385{padding-top:0!important}.pa376-category-image{display:block!important;position:static!important;box-sizing:border-box!important;width:100%!important;max-width:100%!important;height:auto!important;min-height:0!important;max-height:none!important;aspect-ratio:auto!important;margin:0 0 26px!important;margin-left:0!important;margin-right:0!important;padding:0!important;overflow:hidden!important;background:#FAF7F0!important;transform:none!important}.pa376-category-image .pa376-category-image-element{display:block;width:100%!important;height:auto!important;max-width:100%!important;aspect-ratio:auto!important;object-fit:initial!important;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important}@media(max-width:620px){.pa376-category-image{margin-bottom:22px!important}}' : '')
            .'.pa273-section{margin-top:48px}.pa273-section>header{text-align:center;margin-bottom:22px}.pa273-section>header h2{font-size:30px;margin:8px 0}'
            .'.pa273-post-grid,.pa273-product-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:stretch}'
