    public static function auto_append_category_tiles_to_content($content) {
        // Keine Admin-, Feed-, Archiv- oder Fremdloop-Ausgabe.
        if (is_admin() || is_feed() || !is_singular('page') || !in_the_loop() || !is_main_query()) { return $content; }

        $current = self::current_page_as_menu_like_item();
        $page_type = self::current_page_template_type($current);
        if (in_array($page_type, ['start', 'hub1', 'hub2', 'category', 'leaf'], true)) {
            $content = self::normalize_portal_spacing_content($content);
        }

        // Hubseiten ohne bereits ausgegebenen Shortcode automatisch mit dem richtigen
        // Hub-Template versorgen. Quelle sind echte direkte, veroeffentlichte Unterseiten;
        // Kategorie-Matching darf Hub 1/2 niemals ersetzen.
        if (in_array($page_type, ['hub1', 'hub2'], true)) {
            // Sobald bereits irgendein Volltemplate gerendert wurde, niemals ein
            // zweites Template automatisch anhaengen. Falsch hinterlegte Altshortcodes
            // werden zuvor durch render_shortcode_template auf den echten Seitentyp umgeleitet.
            if (!empty(self::$rendered_types) || strpos((string)$content, 'pftk-' . $page_type) !== false) { return $content; }
            $ctx = self::context($page_type);
            $children = self::published_page_items($ctx['top_items'] ?? [], 0, false);
            if (empty($children)) {
                $debug = current_user_can('manage_options')
                    ? '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_hub type=' . esc_html($page_type) . ' current_id=' . intval($current->object_id ?? 0) . ' children=0 rendered=1 -->'
                    : '';
                return $debug . self::render($page_type) . $content;
            }
            return self::render($page_type) . $content;
        }

        if ($page_type === 'leaf') {
            if (self::$auto_category_tiles_appended || !empty(self::$rendered_types)) { return $content; }
            if (strpos((string)$content, 'pa272-leaf') !== false) { return $content; }
            self::$auto_category_tiles_appended = true;
            $page_id = absint($current->object_id ?? get_the_ID());
            if ($page_id > 0) {
                self::$category_intro_rendered[$page_id] = true;
                self::$page_shortline_rendered[$page_id] = true;
            }
            $debug = current_user_can('manage_options')
                ? '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_leaf_full_renderer=1 current_id=' . intval($page_id) . ' -->'
                : '';
            return $debug . self::render_leaf_level_v150272();
        }

        if ($page_type !== 'category') {
            $skip_debug = current_user_can('manage_options')
                ? '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_template skipped=not_portal_level current_id=' . intval($current->object_id ?? 0) . ' current_title=' . esc_html($current->title ?? '') . ' -->'
                : '';
            return $content . $skip_debug;
        }

        if (self::$auto_category_tiles_appended || !empty(self::$rendered_types)) { return $content; }
        if (strpos((string)$content, 'pa266-category') !== false || strpos((string)$content, 'pftk-auto-category-tiles') !== false) { return $content; }

        // V1.50.266: Ebene 3 wird nicht mehr ueber den alten Kachel-Anhaenger
        // ausgegeben. Der vollstaendige, geprüfte Kategorie-Renderer wird direkt
        // im realen the_content-Pfad verwendet. Damit erscheint Regendecken auch
        // ohne eigens eingefuegten Shortcode.
        self::$auto_category_tiles_appended = true;
        self::$category_grid_ad_rendered = false;
        $page_id = absint($current->object_id ?? get_the_ID());
        if ($page_id > 0) {
            self::$category_intro_rendered[$page_id] = true;
            self::$page_shortline_rendered[$page_id] = true;
        }
        $debug = current_user_can('manage_options')
            ? '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_category_full_renderer=1 current_id=' . intval($page_id) . ' -->'
            : '';
        return $debug . self::render_category_level_v150269();
    }

    private static function current_page_template_type($current) {
        if (!$current || ($current->object ?? '') !== 'page') { return ''; }
        $page_id = intval($current->object_id ?? 0);
        if ($page_id <= 0) { return ''; }

        // Primaerquelle: echte WordPress-Seitenhierarchie. Sie wurde vom Importer
        // verbindlich angelegt und bleibt auch bei ausgeblendeten/gefilterten Menues erhalten.
        $ancestor_depth = count((array)get_post_ancestors($page_id));
        if ($ancestor_depth >= 3) { return 'leaf'; }
        if ($ancestor_depth === 2) { return 'category'; }
        $page_children = self::direct_published_page_children($page_id);
        if ($ancestor_depth === 0 && !empty($page_children)) { return 'hub1'; }
        if ($ancestor_depth === 1 && !empty($page_children)) { return 'hub2'; }

        // Fallback fuer allgemeine Portale ohne gepflegte Seitenhierarchie: rohe Menuestruktur.
        $items = self::menu_items();
        $items_by_id = [];
        $children_map = [];
        foreach ((array)$items as $item) {
            if (!is_object($item)) { continue; }
            $items_by_id[intval($item->ID ?? 0)] = $item;
            $parent = intval($item->menu_item_parent ?? 0);
            if (!isset($children_map[$parent])) { $children_map[$parent] = []; }
            $children_map[$parent][] = $item;
        }
        $depths = [];
        foreach ((array)$items as $item) {
            if (!is_object($item)) { continue; }
            if (($item->object ?? '') !== 'page' || intval($item->object_id ?? 0) !== $page_id) { continue; }
            $depths[] = self::menu_depth(intval($item->ID ?? 0), $items_by_id);
        }
        if (in_array(2, $depths, true)) { return 'category'; }
        $menu_children = self::direct_page_children_across_menu_occurrences($items, $children_map, $current);
        if (!empty($menu_children) && in_array(1, $depths, true)) { return 'hub2'; }
        if (!empty($menu_children) && in_array(0, $depths, true)) { return 'hub1'; }
        return '';
    }

    private static function current_page_as_menu_like_item() {
        $post = get_queried_object();
        if (!$post instanceof WP_Post) {
            $post_id = get_the_ID();
            $post = $post_id ? get_post(intval($post_id)) : null;
        }
        if (!$post instanceof WP_Post || $post->post_type !== 'page') { return false; }
        $item = new stdClass();
        $item->ID = -200000 - intval($post->ID);
        $item->db_id = $item->ID;
        $item->menu_item_parent = 0;
        $item->object_id = intval($post->ID);
        $item->object = 'page';
        $item->type = 'post_type';
        $item->title = get_the_title($post);
        $item->url = get_permalink($post);
        $item->menu_order = 0;
        return $item;
    }

    private static function auto_category_tiles_auto_debug_comment($current, $tiles) {
        if (!$current) { return '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_category_tiles hook=the_content current=none count=0 -->'; }
        $sample = [];
        foreach ((array)$tiles as $tile) {
            if (count($sample) >= 8) { break; }
            $sample[] = isset($tile->title) ? $tile->title : '';
        }
        $keys = self::category_tile_product_keys_for_current($current);
        $valid_count = intval(count(self::valid_card_items($tiles)));
        $diag = '';
        if ($valid_count === 0 && current_user_can('manage_options')) {
            $diag = ' diag=' . esc_html(self::category_tile_empty_diag($keys));
        }
        return '<!-- pftk-v' . esc_html(self::VERSION) . ' auto_category_tiles hook=the_content current_object=' . esc_html($current->object ?? '') .
            ' current_id=' . intval($current->object_id ?? 0) .
            ' current_title=' . esc_html($current->title ?? '') .
            ' keys=' . esc_html(implode(',', array_slice($keys, 0, 8))) .
            ' count=' . $valid_count .
            ' sample=' . esc_html(implode(',', $sample)) . $diag . ' -->';
    }



    private static function category_tile_empty_diag($keys) {
        $keys = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        $hits = [];
        foreach (self::all_category_terms_cached() as $term) {
            if (!is_object($term)) { continue; }
            $hay = self::normalize_match_key(($term->slug ?? '') . '-' . ($term->name ?? ''));
            foreach ($keys as $key) {
                if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
                $kc = self::compact_match_key($key);
                if (($kc !== '' && strpos(self::compact_match_key($hay), $kc) !== false) || strpos($hay, $key) !== false) {
                    $hits[] = ($term->slug ?? '') . ':' . ($term->name ?? '');
                    break;
                }
            }
            if (count($hits) >= 8) { break; }
        }
        return implode('|', $hits);
    }

