    public static function legacy_banner_shortcode($atts = []) {
        $atts = shortcode_atts(['url' => '', 'image' => '', 'text' => '', 'target' => '_blank'], $atts, 'pferde_banner');
        if (trim($atts['url']) === '' && trim($atts['image']) === '' && trim($atts['text']) === '') { return ''; }
        $inner = trim($atts['image']) !== '' ? '<img src="' . esc_url($atts['image']) . '" alt="' . esc_attr($atts['text']) . '">' : '<strong>' . esc_html($atts['text']) . '</strong>';
        return '<div class="pftk"><div class="pftk-banner pftk-curve">' . self::wrap_link($inner, $atts['url'], $atts['target'], true, '') . '</div></div>';
    }

    public static function legacy_products_shortcode($atts = []) { return ''; }

    private static function context($type) {
        $items = self::menu_items();
        $children_map = [];
        $items_by_id = [];
        foreach ($items as $item) {
            $items_by_id[intval($item->ID)] = $item;
            $parent = intval($item->menu_item_parent);
            if (!isset($children_map[$parent])) { $children_map[$parent] = []; }
            $children_map[$parent][] = $item;
        }

        if ($type === 'start') {
            $manual = self::start_manual_topic_items();
            $all_root_topics = self::published_page_items($children_map[0] ?? [], 0, true);
            $top_items = $manual['configured'] ? $manual['items'] : array_slice($all_root_topics, 0, 8);

            // „Weitere Themen“ auf der Startseite:
            // - keine Wiederholung der oben gewählten Themen,
            // - keine Startseite,
            // - keine administrativen Einzel-/Serviceseiten ohne echte Unterthemen,
            // - nur veröffentlichte Themenbereiche mit mindestens einer
            //   veröffentlichten Unterseite.
            $selected_page_ids = [];
            foreach ((array)$top_items as $selected_item) {
                $selected_id = intval($selected_item->object_id ?? 0);
                if ($selected_id > 0) { $selected_page_ids[$selected_id] = true; }
            }
            $structure_items = [];
            $structure_children_map = [];
            foreach ($all_root_topics as $candidate) {
                $candidate_page_id = intval($candidate->object_id ?? 0);
                if ($candidate_page_id <= 0 || isset($selected_page_ids[$candidate_page_id])) { continue; }
                $menu_children = self::direct_page_children_across_menu_occurrences($items, $children_map, $candidate);
                $hierarchy_children = self::direct_published_page_children($candidate_page_id);
                $topic_children = self::merge_item_lists($menu_children, $hierarchy_children);
                if (empty($topic_children)) { continue; }
                $structure_items[] = $candidate;
                $structure_children_map[intval($candidate->ID)] = $topic_children;
            }

            return [
                'top_items' => $top_items,
                'structure_items' => $structure_items,
                'structure_children_map' => $structure_children_map,
                'children_map' => $children_map,
                'cat_ids' => self::all_menu_cat_ids($items),
                'force_all_category_tiles' => false,
                'manual_start_selection' => $manual['configured'],
            ];
        }

        $current = self::find_current_item($items);
        $fallback_current = false;
        if (!$current) {
            $current = self::fallback_current_page_item();
            $fallback_current = $current ? true : false;
        }
        if (!$current) {
            return ['top_items' => [], 'children_map' => $children_map, 'cat_ids' => [], 'force_all_category_tiles' => false];
        }

        $direct = isset($children_map[$current->ID]) ? $children_map[$current->ID] : [];
        if (in_array($type, ['hub1', 'hub2'], true)) {
            $menu_direct = $fallback_current ? [] : self::direct_page_children_across_menu_occurrences($items, $children_map, $current);
            $hierarchy_direct = self::direct_published_page_children(intval($current->object_id ?? 0));
            $direct = self::merge_item_lists($menu_direct, $hierarchy_direct);
        }
        $depth = $fallback_current ? self::fallback_page_depth($current) : self::menu_depth(intval($current->ID), $items_by_id);

        // Harte Regel ab V1.6.0: Die letzte Menueebene (Kategorien/Ebene 4)
        // ist dauerhaft aus der Hauptnavigation ausgeblendet. Deshalb muss jede
        // Ebene-3-Produktseite ihre passenden Ebene-4-Kategorien selbst als
        // Kacheln anzeigen. Diese Logik darf nicht davon abhaengen, ob die
        // Kategorien im Header-Menue sichtbar sind. Sie zieht Kategorien live
        // aus der WordPress-Taxonomie und nutzt das Menue nur als Zusatzquelle.
        $auto_category_tiles = $type === 'category' ? self::auto_category_tiles_for_current($current) : [];
        $force_all_category_tiles = false;
        // Harte Regel ab V1.8.0: Wenn passende Kategorien live in der WordPress-
        // Taxonomie gefunden werden, werden sie auf Hub-/Produktseiten sichtbar.
        // Das ist bewusst unabhaengig von Menue-Tiefe, sichtbaren Menuepunkten,
        // Seitenhierarchie und vorhandenen Shortcode-Varianten.
        if (!empty($auto_category_tiles) && $type === 'category') {
            // V2.5 / Design 1.16.0:
            // Wenn live erkannte Produkt-/Ebene-4-Kategorien vorhanden sind,
            // duerfen sie NICHT mit breiten Menue-Kindern gemischt werden.
            // Beispiel: Fell/Haut -> Fliegensprays darf nur Fliegenspray-
            // Kategorien zeigen, nicht alle Fell-/Haut-Unterkategorien.
            // Kategorie-Kacheln bleiben unbegrenzt, aber strikt produktbezogen.
            $direct = $auto_category_tiles;
            $force_all_category_tiles = true;
        } elseif ($type === 'category') {
            // Produkt-/Kategorieebene darf bei fehlendem exaktem Taxonomie-Match
            // nicht auf breite Menue-Kinder zurueckfallen. Sonst entstehen Listen
            // aus kompletten Bereichsgruppen. Besser nichts anzeigen und Debug liefern.
            $direct = [];
        }

        $descendants = $fallback_current ? [] : self::descendants($current->ID, $children_map);
        $cat_ids = [];
        foreach ($descendants as $desc) {
            if ($desc->object === 'category') { $cat_ids[] = intval($desc->object_id); }
        }
        foreach ($direct as $d) {
            if ($d->object === 'category') { $cat_ids[] = intval($d->object_id); }
        }
        if ($current->object === 'category') { $cat_ids[] = intval($current->object_id); }

        $hub_post_cat_ids = [];
        if (in_array($type, ['hub1', 'hub2'], true)) {
            $hub_post_cat_ids = self::hub_post_category_ids($items, $children_map, $current);
            if (!empty($hub_post_cat_ids)) { $cat_ids = array_merge($cat_ids, $hub_post_cat_ids); }
        }

        return [
            'top_items' => $direct,
            'children_map' => $children_map,
            'cat_ids' => array_values(array_unique(array_filter($cat_ids))),
            'hub_post_cat_ids' => array_values(array_unique(array_filter($hub_post_cat_ids))),
            'force_all_category_tiles' => $force_all_category_tiles,
            'category_tile_debug' => self::category_tile_debug_comment($current, $type, $auto_category_tiles, $force_all_category_tiles),
            'current_item' => $current,
        ];
    }

    private static function category_tile_debug_comment($current, $type, $tiles, $forced) {
        if (!$current) { return '<!-- pftk-v' . esc_html(self::VERSION) . ' category_tiles current=none -->'; }
        $count = is_array($tiles) ? count($tiles) : 0;
        $sample = [];
        foreach (array_slice((array)$tiles, 0, 8) as $tile) { if (is_object($tile)) { $sample[] = $tile->title . '|' . $tile->object_id; } }
        $cur_obj = isset($current->object) ? $current->object : 'unknown';
        $cur_title = isset($current->title) ? $current->title : '';
        return "<!-- pftk-v" . esc_html(self::VERSION) . " category_tiles type=" . esc_html($type) . " current_object=" . esc_html($cur_obj) . " current_id=" . intval($current->object_id ?? 0) . " current_title=" . esc_html($cur_title) . " count=" . intval($count) . " forced=" . ($forced ? '1' : '0') . " sample=" . esc_html(implode(',', $sample)) . " -->";
    }

    private static function menu_depth($item_id, $items_by_id) {
        $depth = 0;
        $guard = 0;
        $current = isset($items_by_id[$item_id]) ? $items_by_id[$item_id] : null;
        while ($current && intval($current->menu_item_parent) > 0 && $guard < 10) {
            $parent_id = intval($current->menu_item_parent);
            if (!isset($items_by_id[$parent_id])) { break; }
            $depth++;
            $current = $items_by_id[$parent_id];
            $guard++;
        }
        return $depth;
    }

    private static function fallback_current_page_item() {
        $post_id = get_the_ID();
        if (!$post_id) { return false; }
        $post = get_post(intval($post_id));
        if (!$post || !in_array($post->post_type, ['page','post'], true)) { return false; }
        $item = new stdClass();
        $item->ID = -200000 - intval($post->ID);
        $item->db_id = $item->ID;
        $item->menu_item_parent = 0;
        $item->object_id = intval($post->ID);
        $item->object = $post->post_type;
        $item->type = 'post_type';
        $item->title = get_the_title($post);
        $item->url = get_permalink($post);
        $item->menu_order = 0;
        return $item;
    }

    private static function fallback_page_depth($current) {
        if (!$current || $current->object !== 'page') { return 0; }
        $post_id = intval($current->object_id);
        if ($post_id <= 0) { return 0; }
        $depth = count(get_post_ancestors($post_id));
        return max(0, min(10, intval($depth)));
    }


    private static function merge_item_lists($base, $add) {
        $seen = [];
        $out = [];
        foreach (array_merge((array)$base, (array)$add) as $item) {
            if (!is_object($item)) { continue; }
            $key = (string)$item->object . ':' . (string)$item->object_id;
            if (isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $out[] = $item;
        }
        return $out;
    }


    private static function direct_menu_category_children_for_current($current) {
        $items = self::menu_items();
        if (empty($items)) { return []; }
        $current_item = self::find_matching_menu_item_for_current($current, $items);
        if (!$current_item || empty($current_item->ID)) { return []; }
        $children = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            if (intval($item->menu_item_parent ?? 0) !== intval($current_item->ID)) { continue; }

            // Ebene-4 kann als echte Kategorie ODER als Custom-Link im Menue liegen.
            // Custom-Link muss als Kachel sichtbar bleiben, sonst bleiben Produktseiten wie Frostschutzkabel leer.
            $object = (string)($item->object ?? '');
            if ($object === 'category') {
                $children[] = $item;
                continue;
            }

            $url = (string)($item->url ?? '');
            $title = trim((string)($item->title ?? ''));
            if ($title === '' || $url === '') { continue; }

            $url_tail = self::normalize_match_key(self::last_path_part_from_url($url));
            $title_key = self::normalize_match_key($title);
            $looks_like_category = false;
            if (strpos($url, '/category/') !== false || strpos($url, 'category_name=') !== false) { $looks_like_category = true; }
            foreach (['faq','beratung','vergleich','kosten','pflege','anwendung','sicherheit','checkliste','checklisten'] as $intent) {
                if (self::slug_has_token($url_tail, $intent) || self::slug_has_token($title_key, $intent)) { $looks_like_category = true; break; }
            }
            if (!$looks_like_category) { continue; }

            $copy = clone $item;
            $copy->object = 'custom_category';
            $copy->type = 'custom';
            $copy->object_id = self::resolve_category_id_from_item($copy);
            $children[] = $copy;
        }
        $decorated = [];
        $product_title = '';
        foreach (self::category_tile_product_keys_for_current($current) as $key_for_title) {
            $key_for_title = self::normalize_match_key($key_for_title);
            if ($key_for_title !== '' && !self::is_generic_category_tile_key($key_for_title)) { $product_title = self::title_from_key($key_for_title); break; }
        }
        foreach ($children as $child) {
            if (is_object($child) && $product_title !== '' && self::is_intent_only_category_label($child->title ?? '')) {
                $copy = clone $child;
                $copy->title = trim((string)$copy->title) . ' ' . $product_title;
                $decorated[] = $copy;
            } else {
                $decorated[] = $child;
            }
        }
        return self::dedupe_category_tile_items($decorated);
    }

    private static function descendant_menu_category_items_for_current($current) {
        $items = self::menu_items();
        if (empty($items)) { return []; }
        $current_item = self::find_matching_menu_item_for_current($current, $items);
        if (!$current_item || empty($current_item->ID)) { return []; }

        $children_map = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $parent = intval($item->menu_item_parent ?? 0);
            if (!isset($children_map[$parent])) { $children_map[$parent] = []; }
            $children_map[$parent][] = $item;
        }

        $desc = self::menu_descendants_limited(intval($current_item->ID), $children_map, 0, 5);
        if (empty($desc)) { return []; }

        $keys = self::category_tile_product_keys_for_current($current);
        $product_title = '';
        foreach ($keys as $key_for_title) {
            $key_for_title = self::normalize_match_key($key_for_title);
            if ($key_for_title !== '' && !self::is_generic_category_tile_key($key_for_title)) {
                $product_title = self::title_from_key($key_for_title);
                break;
            }
        }

        $out = [];
        foreach ($desc as $item) {
            if (!is_object($item)) { continue; }
            $object = (string)($item->object ?? '');
            $url = (string)($item->url ?? '');
            $title = trim((string)($item->title ?? ''));
            $url_tail = self::normalize_match_key(self::last_path_part_from_url($url));
            $title_key = self::normalize_match_key($title);

            $looks_like_category = ($object === 'category');
            if (!$looks_like_category && (strpos($url, '/category/') !== false || strpos($url, 'category_name=') !== false)) { $looks_like_category = true; }
            $has_intent = false;
            foreach (self::category_tile_intents() as $intent) {
                if (self::slug_has_token($url_tail, $intent) || self::slug_has_token($title_key, $intent)) { $has_intent = true; break; }
            }
            if (!$looks_like_category && !$has_intent) { continue; }
            if (!$has_intent && $object !== 'category') { continue; }

            $copy = clone $item;
            if (($copy->object ?? '') !== 'category') {
                $copy->object = 'custom_category';
                $copy->type = 'custom';
                $copy->object_id = self::resolve_category_id_from_item($copy);
            }
            if ($product_title !== '' && self::is_intent_only_category_label($copy->title ?? '')) {
                $copy->title = trim((string)$copy->title) . ' ' . $product_title;
            }
            $out[] = $copy;
        }
        return self::dedupe_category_tile_items($out);
    }

    private static function menu_descendants_limited($parent_id, $children_map, $depth = 0, $max_depth = 5) {
        if ($depth > $max_depth || empty($children_map[$parent_id])) { return []; }
        $out = [];
        foreach ((array)$children_map[$parent_id] as $child) {
            if (!is_object($child)) { continue; }
            $out[] = $child;
            $out = array_merge($out, self::menu_descendants_limited(intval($child->ID ?? 0), $children_map, $depth + 1, $max_depth));
        }
        return $out;
    }

    private static function taxonomy_child_category_items_for_current_product($current) {
        $terms = self::all_category_terms_cached();
        if (empty($terms)) { return []; }
        $keys = self::category_tile_product_keys_for_current($current);
        $keys = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        if (empty($keys)) { return []; }
        $terms_by_id = self::terms_by_id($terms);
        $candidate_parents = [];
        foreach ($terms as $term) {
            if (!is_object($term) || empty($term->term_id) || empty($term->slug) || $term->slug === 'uncategorized') { continue; }
            $label = self::normalize_match_key(($term->slug ?? '') . '-' . ($term->name ?? ''));
            $has_intent = false;
            foreach (self::category_tile_intents() as $intent) {
                if (self::slug_has_token($label, $intent)) { $has_intent = true; break; }
            }
            if ($has_intent) { continue; }
            $score = self::category_strict_product_score($term, $keys);
            if ($score > 0) { $candidate_parents[] = ['score' => $score, 'term' => $term]; }
        }
        if (empty($candidate_parents)) { return []; }
        usort($candidate_parents, function($a, $b) { return $b['score'] <=> $a['score']; });
        $out = [];
        $order = 0;
        $seen = [];
        foreach ($candidate_parents as $row) {
            $parent = $row['term'];
            $pid = intval($parent->term_id);
            foreach ($terms as $term) {
                if (!is_object($term) || intval($term->parent ?? 0) !== $pid) { continue; }
                $label = self::normalize_match_key(($term->slug ?? '') . '-' . ($term->name ?? ''));
                $has_intent = false;
                foreach (self::category_tile_intents() as $intent) {
                    if (self::slug_has_token($label, $intent)) { $has_intent = true; break; }
                }
                if (!$has_intent) { continue; }
                $tid = intval($term->term_id);
                if (isset($seen[$tid])) { continue; }
                $seen[$tid] = true;
                $title = self::category_tile_display_title_for_term($term, $keys, $terms_by_id);
                $out[] = self::term_to_menu_like_item($term, $order++, $title);
            }
            if (!empty($out)) { break; }
        }
        return self::dedupe_category_tile_items($out);
    }

    private static function find_matching_menu_item_for_current($current, $items) {
        $post_id = 0;
        $post_slug = '';
        $post_title = '';
        $post_url_tail = '';
        if (is_object($current)) {
            if (in_array($current->object ?? '', ['page','post'], true) && !empty($current->object_id)) {
                $post_id = intval($current->object_id);
                $p = get_post($post_id);
                if ($p instanceof WP_Post) {
                    $post_slug = self::normalize_match_key($p->post_name);
                    $post_title = self::normalize_match_key(get_the_title($p));
                }
            }
            if (!empty($current->title)) { $post_title = self::normalize_match_key($current->title); }
            if (!empty($current->url)) { $post_url_tail = self::normalize_match_key(self::last_path_part_from_url($current->url)); }
        }
        if (!$post_id) {
            $qid = get_the_ID();
            if ($qid) { $post_id = intval($qid); }
        }
        if ($post_id && ($post_slug === '' || $post_title === '')) {
            $p = get_post($post_id);
            if ($p instanceof WP_Post) {
                if ($post_slug === '') { $post_slug = self::normalize_match_key($p->post_name); }
                if ($post_title === '') { $post_title = self::normalize_match_key(get_the_title($p)); }
            }
        }
        if ($post_url_tail === '' && $post_id) { $post_url_tail = self::normalize_match_key(self::last_path_part_from_url(get_permalink($post_id))); }

        $needles = array_values(array_unique(array_filter([$post_slug, $post_url_tail, $post_title])));
        $needles_compact = array_values(array_unique(array_filter(array_map([__CLASS__, 'compact_match_key'], $needles))));

        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            if (in_array($item->object ?? '', ['page','post'], true) && $post_id && intval($item->object_id ?? 0) === $post_id) { return $item; }
        }
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $candidates = [];
            if (!empty($item->url)) { $candidates[] = self::normalize_match_key(self::last_path_part_from_url($item->url)); }
            if (!empty($item->title)) { $candidates[] = self::normalize_match_key($item->title); }
            foreach ($candidates as $candidate) {
                if ($candidate === '') { continue; }
                if (in_array($candidate, $needles, true)) { return $item; }
                $compact = self::compact_match_key($candidate);
                if ($compact !== '' && in_array($compact, $needles_compact, true)) { return $item; }
            }
        }
        return false;
    }

    private static function dedupe_category_tile_items($items) {
        $seen = [];
        $out = [];
        foreach ((array)$items as $item) {
            if (!is_object($item)) { continue; }
            $title = self::normalize_match_key($item->title ?? '');
            $obj = (string)($item->object ?? '');
            $oid = intval($item->object_id ?? 0);
            $url_tail = !empty($item->url) ? self::normalize_match_key(self::last_path_part_from_url($item->url)) : '';
            // Gleiche sichtbare Kategorie nur einmal zeigen. Wenn Titel fehlt, auf Objekt/URL fallen.
            $key = $title !== '' ? 'title:' . $title : $obj . ':' . $oid . ':' . $url_tail;
            if (isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $out[] = $item;
        }
        return $out;
    }

    private static function menu_category_items_matching_product_keys($keys) {
        $items = self::menu_items();
        if (empty($items) || empty($keys)) { return []; }
        $keys = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        $items_by_id = [];
        foreach ($items as $maybe_parent) {
            if (is_object($maybe_parent) && !empty($maybe_parent->ID)) { $items_by_id[intval($maybe_parent->ID)] = $maybe_parent; }
        }
        $out = [];
        $seen_titles = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $object = (string)($item->object ?? '');
            $url = (string)($item->url ?? '');
            $title = trim((string)($item->title ?? ''));
            $looks_like_category = ($object === 'category');
            if (!$looks_like_category) {
                if (strpos($url, '/category/') !== false || strpos($url, 'category_name=') !== false) { $looks_like_category = true; }
                $url_tail_tmp = self::normalize_match_key(self::last_path_part_from_url($url));
                $title_key_tmp = self::normalize_match_key($title);
                foreach (self::category_tile_intents() as $intent_tmp) {
                    if (self::slug_has_token($url_tail_tmp, $intent_tmp) || self::slug_has_token($title_key_tmp, $intent_tmp)) { $looks_like_category = true; break; }
                }
            }
            if (!$looks_like_category) { continue; }

            // V1.31.0: Nicht nur den Kategoriepunkt selbst prüfen, sondern den kompletten Menüpfad.
            // Live-Fall: Kindkachel heißt nur „FAQ“, der Produktbezug steht im Elternpfad „Frostschutzkabel“.
            $haystacks = self::menu_item_path_haystacks($item, $items_by_id);
            $own_haystacks = [];
            if ($title !== '') { $own_haystacks[] = self::normalize_match_key($title); }
            if ($url !== '') { $own_haystacks[] = self::normalize_match_key(self::last_path_part_from_url($url)); }
            $has_intent = false;
            foreach ($own_haystacks as $own_hay) {
                foreach (self::category_tile_intents() as $intent_check) {
                    if (self::slug_has_token($own_hay, $intent_check)) { $has_intent = true; break 2; }
                }
            }
            if (!$has_intent && $object !== 'category') { continue; }

            $match = false;
            foreach ($keys as $key) {
                if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
                foreach (array_merge([$key], self::strict_product_key_variants($key), self::semantic_key_variants($key)) as $variant) {
                    $variant = self::normalize_match_key($variant);
                    if ($variant === '' || self::is_generic_category_tile_key($variant)) { continue; }
                    $variant_compact = self::compact_match_key($variant);
                    foreach ($haystacks as $hay) {
                        if ($hay === '') { continue; }
                        if (self::slug_has_token($hay, $variant)) { $match = true; break 3; }
                        if ($variant_compact !== '' && strlen($variant_compact) >= 7 && strpos(self::compact_match_key($hay), $variant_compact) !== false) { $match = true; break 3; }
                    }
                }
            }
            if (!$match) { continue; }
            $title_key = self::normalize_match_key($item->title ?? '');
            if ($title_key !== '' && isset($seen_titles[$title_key])) { continue; }
            if ($title_key !== '') { $seen_titles[$title_key] = true; }
            $copy = clone $item;
            if (($copy->object ?? '') !== 'category') {
                $copy->object = 'custom_category';
                $copy->type = 'custom';
                $copy->object_id = self::resolve_category_id_from_item($copy);
            }
            if (self::is_intent_only_category_label($copy->title ?? '')) {
                foreach ($keys as $key_for_title) {
                    if ($key_for_title !== '' && !self::is_generic_category_tile_key($key_for_title)) { $copy->title = trim((string)$copy->title) . ' ' . self::title_from_key($key_for_title); break; }
                }
            }
            $out[] = $copy;
        }
        return self::dedupe_category_tile_items($out);
    }

    private static function menu_item_path_haystacks($item, $items_by_id) {
        $hay = [];
        $seen = [];
        $current = $item;
        $guard = 0;
        while (is_object($current) && $guard < 12) {
            $sig = intval($current->ID ?? 0);
            if ($sig && isset($seen[$sig])) { break; }
            if ($sig) { $seen[$sig] = true; }
            $title = trim((string)($current->title ?? ''));
            $url = (string)($current->url ?? '');
            if ($title !== '') { $hay[] = self::normalize_match_key($title); }
            if ($url !== '') {
                $hay[] = self::normalize_match_key(self::last_path_part_from_url($url));
                foreach (self::path_parts_from_url($url) as $part) { $hay[] = self::normalize_match_key($part); }
            }
            $parent_id = intval($current->menu_item_parent ?? 0);
            if ($parent_id <= 0 || empty($items_by_id[$parent_id])) { break; }
            $current = $items_by_id[$parent_id];
            $guard++;
        }
        return array_values(array_unique(array_filter($hay)));
    }


    private static function auto_category_tiles_for_current($current) {
        // V1.34.0: Ursache der Live-Leerfaelle ist nicht CSS, sondern fehlender
        // Produktbezug in manchen Kategorie-Slugs/Namen. Deshalb zuerst sauber
        // das echte Menue lesen: aktuelle Ebene-3-Seite -> darunterliegende
        // Kategorie-Menuepunkte. Erst danach Taxonomie-Fallback.
        static $cache = [];
        $cache_key = 'none';
        if (is_object($current)) {
            $cache_key = implode('|', [
                (string)($current->object ?? ''),
                (string)($current->object_id ?? ''),
                self::normalize_match_key($current->title ?? ''),
                self::last_path_part_from_url($current->url ?? '')
            ]);
        }
        if (isset($cache[$cache_key])) { return $cache[$cache_key]; }

        $deadline = microtime(true) + 0.75;
        $menu_items = self::bounded_menu_child_category_items_for_current_page($current, $deadline);
        if (!empty($menu_items)) {
            return $cache[$cache_key] = self::dedupe_category_tile_items($menu_items);
        }

        // V1.50.0: Ist die aktuelle Seite eindeutig im Portalmenue vorhanden,
        // dann ist auch "keine direkte Unterkategorie" ein verbindliches Ergebnis.
        // Der Taxonomie-Fallback darf in diesem Fall keine gleichnamigen Kategorien
        // aus einem anderen Bereich einschleusen (z. B. Fohlenhalfter,
        // Sicherheitshalfter, Schermaschinen, Kuehlgamaschen oder Dualgassen).
        if (self::current_page_has_authoritative_menu_parent($current)) {
            return $cache[$cache_key] = [];
        }

        foreach (self::category_tile_product_key_groups_for_current($current) as $group) {
            $keys = self::expand_strict_product_keys($group);
            $keys = array_values(array_filter($keys, function($key) {
                return $key !== '' && strlen($key) >= 5 && !self::is_generic_category_tile_key($key);
            }));
            $keys = array_slice(array_values(array_unique($keys)), 0, 12);
            if (empty($keys)) { continue; }

            $tax_items = self::fast_taxonomy_category_items_matching_product_keys($keys, $deadline);
            if (!empty($tax_items)) {
                return $cache[$cache_key] = self::dedupe_category_tile_items($tax_items);
            }
            if (microtime(true) > $deadline) { break; }
        }

        return $cache[$cache_key] = [];
    }


    private static function current_page_has_authoritative_menu_parent($current) {
        if (!is_object($current) || empty($current->object_id)) { return false; }
        $items = self::raw_nav_menu_items_unfiltered_bounded();
        if (empty($items)) { return false; }

        $current_object_id = intval($current->object_id ?? 0);
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            if (($item->object ?? '') === 'page' && $current_object_id > 0 && intval($item->object_id ?? 0) === $current_object_id) {
                return true;
            }
        }

        $current_slug = self::normalize_match_key(self::last_path_part_from_url($current->url ?? ''));
        if ($current_slug !== '') {
            foreach ($items as $item) {
                if (!is_object($item) || !in_array((string)($item->object ?? ''), ['page', 'custom'], true)) { continue; }
                $item_last = self::normalize_match_key(self::last_path_part_from_url($item->url ?? ''));
                if ($item_last !== '' && $item_last === $current_slug) { return true; }
            }
        }

        $current_title = self::normalize_match_key($current->title ?? '');
        if ($current_title !== '') {
            foreach ($items as $item) {
                if (!is_object($item) || !in_array((string)($item->object ?? ''), ['page', 'custom'], true)) { continue; }
                $item_title = self::normalize_match_key($item->title ?? '');
                if ($item_title !== '' && $item_title === $current_title) { return true; }
            }
        }
        return false;
    }

    private static function bounded_menu_child_category_items_for_current_page($current, $deadline) {
        if (!is_object($current) || empty($current->object_id)) { return []; }
        $items = self::raw_nav_menu_items_unfiltered_bounded();
        if (empty($items)) { return []; }

        $by_id = [];
        $children = [];
        foreach ($items as $item) {
            if (!is_object($item) || empty($item->ID)) { continue; }
            $id = intval($item->ID);
            $by_id[$id] = $item;
            $parent = intval($item->menu_item_parent ?? 0);
            if (!isset($children[$parent])) { $children[$parent] = []; }
            $children[$parent][] = $item;
        }

        $current_slug = self::normalize_match_key(self::last_path_part_from_url($current->url ?? ''));
        $current_title = self::normalize_match_key($current->title ?? '');
        $current_object_id = intval($current->object_id ?? 0);
        $parents_exact = [];
        $parents_slug = [];
        $parents_title = [];
        foreach ($items as $item) {
            if (!is_object($item)) { continue; }
            $object = (string)($item->object ?? '');
            if (!in_array($object, ['page', 'custom'], true)) { continue; }

            // V1.50.0: Die exakte WordPress-Seiten-ID hat immer Vorrang.
            // Titel wie "Fohlenhalfter", "Schermaschinen" oder "Dualgassen"
            // kommen in unterschiedlichen Portalbereichen mehrfach vor und duerfen
            // niemals als gleichartige Elternknoten zusammengefuehrt werden.
            if ($object === 'page' && $current_object_id > 0 && intval($item->object_id ?? 0) === $current_object_id) {
                $parents_exact[intval($item->ID)] = $item;
                continue;
            }

            if ($current_slug !== '') {
                $item_last = self::normalize_match_key(self::last_path_part_from_url($item->url ?? ''));
                if ($item_last !== '' && $item_last === $current_slug) {
                    $parents_slug[intval($item->ID)] = $item;
                    continue;
                }
            }

            if ($current_title !== '') {
                $item_title = self::normalize_match_key($item->title ?? '');
                if ($item_title !== '' && $item_title === $current_title) {
                    $parents_title[intval($item->ID)] = $item;
                }
            }
        }
        $parents = !empty($parents_exact) ? $parents_exact : (!empty($parents_slug) ? $parents_slug : $parents_title);
        if (empty($parents)) { return []; }

        $product_title = trim((string)($current->title ?? ''));
        $out = [];
        $seen = [];

        // V1.49.9: Direkte Kategorie-Kinder sind die verbindliche Strukturquelle.
        // Sie werden vollständig verarbeitet - ohne 0,75-Sekunden-Abbruch und ohne
        // starre Themenwort-Whitelist. Dadurch verschwinden weder "Installation"
        // noch "Übungen" oder zukünftige legitime Unterkategorien.
        foreach ($parents as $parent_id => $parent_item) {
            $direct_guard = 0;
            foreach (($children[$parent_id] ?? []) as $node) {
                if (++$direct_guard > 100) { break; }
                $candidate = self::menu_node_to_category_tile_item($node, $product_title);
                if (!$candidate) { continue; }
                $key = (string)($candidate->object ?? '') . ':' . intval($candidate->object_id ?? 0) . ':' . self::normalize_match_key($candidate->title ?? '') . ':' . (string)($candidate->url ?? '');
                if (isset($seen[$key])) { continue; }
                $seen[$key] = true;
                $candidate->menu_order = count($out) + 1;
                $out[] = $candidate;
                if (count($out) >= 24) { break 2; }
            }
        }
        if (!empty($out)) { return self::dedupe_category_tile_items($out); }

        // Nur als Altstruktur-Fallback werden tiefere Nachfahren zeitlich begrenzt
        // und weiterhin durch die Themenwort-Prüfung abgesichert.
        foreach ($parents as $parent_id => $parent_item) {
            $queue = [];
            foreach (($children[$parent_id] ?? []) as $child) { $queue[] = [$child, 1]; }
            $visited = [];
            $guard = 0;
            while (!empty($queue) && $guard < 120 && microtime(true) <= $deadline) {
                [$node, $depth] = array_shift($queue);
                $guard++;
                if (!is_object($node) || empty($node->ID)) { continue; }
                $nid = intval($node->ID);
                if (isset($visited[$nid])) { continue; }
                $visited[$nid] = true;

                $candidate = self::menu_node_to_category_tile_item($node, $product_title);
                if ($candidate && self::menu_category_tile_label_allowed($candidate->title ?? '')) {
                    $key = (string)($candidate->object ?? '') . ':' . intval($candidate->object_id ?? 0) . ':' . self::normalize_match_key($candidate->title ?? '') . ':' . (string)($candidate->url ?? '');
                    if (!isset($seen[$key])) {
                        $seen[$key] = true;
                        $candidate->menu_order = count($out) + 1;
                        $out[] = $candidate;
                        if (count($out) >= 24) { break 2; }
                    }
                }

                if ($depth < 4) {
                    foreach (($children[$nid] ?? []) as $child) { $queue[] = [$child, $depth + 1]; }
                }
            }
        }
        return self::dedupe_category_tile_items($out);
    }

    private static function menu_node_to_category_tile_item($node, $product_title) {
        if (!is_object($node)) { return null; }
        $item = clone $node;
        $term_id = 0;
        if (($item->object ?? '') === 'category' && !empty($item->object_id)) {
            $term_id = intval($item->object_id);
        } elseif (!empty($item->url)) {
            $slug = self::category_slug_from_url($item->url);
            if ($slug !== '') {
                $term = get_term_by('slug', $slug, 'category');
                if ($term && !is_wp_error($term) && !empty($term->term_id)) { $term_id = intval($term->term_id); }
            }
        }
        if ($term_id <= 0) { return null; }
        $term = get_term($term_id, 'category');
        if (!$term || is_wp_error($term)) { return null; }
        $item->object = 'category';
        $item->type = 'taxonomy';
        $item->object_id = $term_id;
        $item->url = get_category_link($term);
        $title = trim((string)($item->title ?? ''));
        if ($title === '') { $title = trim((string)($term->name ?? '')); }
        if (self::is_intent_only_category_label($title) && trim((string)$product_title) !== '') {
            $title .= ' ' . trim((string)$product_title);
        }
        $item->title = $title;
        return $item;
    }

    private static function category_slug_from_url($url) {
        $parts = self::path_parts_from_url($url);
        if (empty($parts)) { return ''; }
        for ($i = count($parts) - 1; $i >= 0; $i--) {
            $part = self::normalize_match_key($parts[$i]);
            if ($part !== '' && !in_array($part, ['category','kategorie','produkt-kategorie'], true)) { return $part; }
        }
        return '';
    }

    private static function menu_category_tile_label_allowed($title) {
        $key = self::normalize_match_key($title);
        if ($key === '') { return false; }
        if (self::category_label_has_tile_intent($key)) { return true; }
        // Navigationskacheln sollen thematische Ebene-4-Labels sein; reine Bereichsseiten nicht.
        return false;
    }

    private static function raw_nav_menu_items_unfiltered_bounded() {
        static $items = null;
        if ($items !== null) { return $items; }
        $posts = get_posts([
            'post_type' => 'nav_menu_item',
            'post_status' => 'publish',
            'posts_per_page' => 2500,
            'orderby' => 'menu_order',
            'order' => 'ASC',
            'no_found_rows' => true,
            'update_post_meta_cache' => true,
            'update_post_term_cache' => false,
            'suppress_filters' => true,
        ]);
        if (empty($posts)) { return $items = []; }
        $items = [];
        $count = 0;
        foreach ($posts as $post) {
            if (!is_object($post) || empty($post->ID)) { continue; }
            if (++$count > 2500) { break; }
            $type = (string)get_post_meta($post->ID, '_menu_item_type', true);
            $object = (string)get_post_meta($post->ID, '_menu_item_object', true);
            $object_id = intval(get_post_meta($post->ID, '_menu_item_object_id', true));
            $url = (string)get_post_meta($post->ID, '_menu_item_url', true);
            $title = trim((string)($post->post_title ?? ''));
            if ($title === '' && $object === 'category' && $object_id > 0) {
                $term = get_term($object_id, 'category');
                if ($term && !is_wp_error($term)) { $title = trim((string)$term->name); }
            }
            if ($title === '' && $object === 'page' && $object_id > 0) { $title = get_the_title($object_id); }
            if ($url === '') {
                if ($object === 'category' && $object_id > 0) {
                    $term_url = get_term_link($object_id, 'category');
                    if (!is_wp_error($term_url)) { $url = (string)$term_url; }
                } elseif ($object === 'page' && $object_id > 0) {
                    $url = get_permalink($object_id);
                }
            }
            $item = new stdClass();
            $item->ID = intval($post->ID);
            $item->db_id = intval($post->ID);
            $item->menu_item_parent = intval(get_post_meta($post->ID, '_menu_item_menu_item_parent', true));
            $item->object_id = $object_id;
            $item->object = $object;
            $item->type = $type;
            $item->title = $title;
            $item->url = $url;
            $item->menu_order = intval($post->menu_order ?? 0);
            $items[] = $item;
        }
        return $items;
    }

    private static function fast_taxonomy_category_items_matching_product_keys($keys, $deadline) {
        $terms = self::all_category_terms_cached();
        if (empty($terms) || empty($keys)) { return []; }
        $terms_by_id = self::terms_by_id($terms);
        $scored = [];
        $seen = [];
        foreach ($terms as $term) {
            if (microtime(true) > $deadline) { break; }
            if (!is_object($term) || empty($term->term_id) || empty($term->slug) || $term->slug === 'uncategorized') { continue; }
            $label = self::normalize_match_key(($term->slug ?? '') . '-' . ($term->name ?? ''));
            if (!self::category_label_has_tile_intent($label)) { continue; }

            $score = self::fast_category_product_match_score($term, $keys, $terms_by_id);
            if ($score <= 0) { continue; }
            $tid = intval($term->term_id);
            if (isset($seen[$tid])) { continue; }
            $seen[$tid] = true;
            $title = self::category_tile_display_title_for_term($term, $keys, $terms_by_id);
            $scored[] = [
                'score' => $score,
                'intent_order' => self::category_intent_order($label),
                'term' => $term,
                'title' => $title,
            ];
        }
        if (empty($scored)) { return []; }
        usort($scored, function($a, $b) {
            if ($a['intent_order'] === $b['intent_order']) {
                if ($a['score'] === $b['score']) { return strcmp((string)$a['term']->slug, (string)$b['term']->slug); }
                return $b['score'] <=> $a['score'];
            }
            return $a['intent_order'] <=> $b['intent_order'];
        });
        $items = [];
        $order = 0;
        foreach ($scored as $row) {
            $items[] = self::term_to_menu_like_item($row['term'], $order++, $row['title']);
        }
        return self::dedupe_category_tile_items($items);
    }

    private static function category_label_has_tile_intent($label) {
        $label = self::normalize_match_key($label);
        foreach (self::category_tile_intents() as $intent) {
            if (self::slug_has_token($label, $intent)) { return true; }
        }
        return false;
    }

    private static function category_intent_order($label) {
        $label = self::normalize_match_key($label);
        $order = ['faq'=>10,'beratung'=>20,'kaufberatung'=>21,'vergleich'=>30,'pflege'=>40,'kosten'=>50,'checkliste'=>60,'checklisten'=>61,'anwendung'=>70,'sicherheit'=>80,'lagerung'=>90,'installation'=>95,'uebungen'=>97,'einsatz'=>100,'material'=>110,'modelle'=>120,'arten'=>130,'ratgeber'=>140];
        foreach ($order as $intent => $pos) {
            if (self::slug_has_token($label, $intent)) { return $pos; }
        }
        return 999;
    }

    private static function fast_category_product_match_score($term, $keys, $terms_by_id) {
        if (!is_object($term)) { return 0; }
        $parts = [];
        $current = $term;
        $guard = 0;
        while (is_object($current) && $guard < 8) {
            $parts[] = self::normalize_match_key(($current->slug ?? '') . '-' . ($current->name ?? ''));
            $parent = !empty($current->parent) ? intval($current->parent) : 0;
            if ($parent <= 0 || empty($terms_by_id[$parent])) { break; }
            $current = $terms_by_id[$parent];
            $guard++;
        }
        $own = $parts[0] ?? '';
        $path = implode('-', $parts);
        $best = 0;
        foreach ((array)$keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            $variants = array_values(array_unique(array_merge([$key], self::semantic_key_variants($key), self::strict_product_key_variants($key))));
            foreach ($variants as $variant) {
                $variant = self::normalize_match_key($variant);
                if ($variant === '' || self::is_generic_category_tile_key($variant)) { continue; }
                $vc = self::compact_match_key($variant);
                if (self::slug_has_token($own, $variant)) { $best = max($best, 220); }
                if ($vc !== '' && strlen($vc) >= 7 && strpos(self::compact_match_key($own), $vc) !== false) { $best = max($best, 218); }
                if (self::slug_has_token($path, $variant)) { $best = max($best, 190); }
                if ($vc !== '' && strlen($vc) >= 7 && strpos(self::compact_match_key($path), $vc) !== false) { $best = max($best, 188); }
            }
            foreach (self::compound_required_token_sets($key) as $set) {
                if (empty($set)) { continue; }
                if (self::all_tokens_present($own, $set)) { $best = max($best, 210); }
                if (self::all_tokens_present($path, $set)) { $best = max($best, 185); }
            }
        }
        if ($best <= 0) { return 0; }
        return $best + self::category_intent_bonus($own);
    }

    private static function expand_strict_product_keys($keys) {
        $out = [];
        foreach ((array)$keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            $out[] = $key;
            foreach (self::semantic_key_variants($key) as $v) { $out[] = $v; }
            foreach (self::strict_product_key_variants($key) as $v) { $out[] = $v; }
            foreach (self::compound_required_token_sets($key) as $set) {
                if (!empty($set)) { $out[] = implode('-', array_map([__CLASS__, 'normalize_match_key'], $set)); }
            }
        }
        return array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], $out))));
    }


    private static function category_tile_intents() {
        return ['faq','beratung','vergleich','pflege','kosten','kaufberatung','checkliste','checklisten','ratgeber','anwendung','sicherheit','lagerung','installation','uebungen','einsatz','material','modelle','arten'];
    }

    private static function exact_intent_category_items_for_product_keys($keys) {
        $keys = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        if (empty($keys)) { return []; }
        $items = [];
        $seen = [];
        $order = 0;
        foreach (self::category_tile_intents() as $intent) {
            foreach ($keys as $key) {
                if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
                foreach (array_merge([$key], self::semantic_key_variants($key), self::strict_product_key_variants($key)) as $variant) {
                    $variant = self::normalize_match_key($variant);
                    if ($variant === '' || self::is_generic_category_tile_key($variant)) { continue; }
                    $slug_candidates = array_values(array_unique([
                        $intent . '-' . $variant,
                        $variant . '-' . $intent,
                        $intent . '-' . str_replace('-', '', $variant),
                        str_replace('-', '', $variant) . '-' . $intent,
                    ]));
                    foreach ($slug_candidates as $slug) {
                        $term = get_term_by('slug', $slug, 'category');
                        if (!$term || is_wp_error($term) || empty($term->term_id)) { continue; }
                        $tid = intval($term->term_id);
                        if (isset($seen[$tid])) { continue; }
                        $seen[$tid] = true;
                        $title = self::category_tile_display_title_for_term($term, $keys, self::terms_by_id([$term]));
                        $items[] = self::term_to_menu_like_item($term, $order++, $title);
                        break 2;
                    }
                }
            }
        }
        return self::dedupe_category_tile_items($items);
    }

    private static function all_category_terms_cached() {
        static $terms = null;
        if ($terms !== null) { return $terms; }
        $terms = get_terms(['taxonomy' => 'category', 'hide_empty' => false, 'fields' => 'all']);
        if (is_wp_error($terms) || empty($terms)) { $terms = []; }
        return $terms;
    }

    private static function taxonomy_category_items_matching_product_keys($keys) {
        $terms = self::all_category_terms_cached();
        if (empty($terms)) { return []; }
        $keys = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$keys))));
        if (empty($keys)) { return []; }
        $terms_by_id = self::terms_by_id($terms);
        $scored = [];
        foreach ($terms as $term) {
            if (empty($term->slug) || $term->slug === 'uncategorized') { continue; }
            $score = self::category_tile_term_score_for_product($term, $keys, $terms_by_id);
            if ($score <= 0) { continue; }
            $title = self::category_tile_display_title_for_term($term, $keys, $terms_by_id);
            $scored[] = ['score' => $score, 'term' => $term, 'title' => $title];
        }
        if (empty($scored)) { return []; }
        usort($scored, function($a, $b) {
            if ($a['score'] === $b['score']) { return strcmp($a['term']->slug, $b['term']->slug); }
            return $b['score'] <=> $a['score'];
        });
        $items = [];
        $order = 0;
        foreach ($scored as $row) { $items[] = self::term_to_menu_like_item($row['term'], $order++, $row['title']); }
        return self::dedupe_category_tile_items($items);
    }

    private static function terms_by_id($terms) {
        $out = [];
        foreach ((array)$terms as $term) {
            if (is_object($term) && !empty($term->term_id)) { $out[intval($term->term_id)] = $term; }
        }
        return $out;
    }

    private static function category_tile_term_score_for_product($term, $keys, $terms_by_id) {
        if (!is_object($term)) { return 0; }
        $term_slug = self::normalize_match_key(($term->slug ?? '') . '-' . ($term->name ?? ''));
        $intent_bonus = self::category_intent_bonus($term_slug);
        $direct_score = self::category_strict_product_score($term, $keys);
        $ancestor = self::nearest_matching_product_ancestor($term, $keys, $terms_by_id);
        $ancestor_score = $ancestor ? self::category_strict_product_score($ancestor, $keys) : 0;
        $path_score = self::category_path_strict_product_score($term, $keys, $terms_by_id);

        // Ebene-4 darf entweder den Produktschluessel selbst enthalten
        // oder als generische Intent-Kategorie unter einem passenden Produkt-Elternterm liegen.
        // V1.31.0: zusätzlich kompletter Kategoriepfad, weil Live-Strukturen auch
        // intent-only Kinder wie „FAQ“ unter Produkt-Eltern nutzen können.
        if ($intent_bonus > 0 && $direct_score > 0) { return $direct_score + 40 + $intent_bonus; }
        if ($intent_bonus > 0 && $ancestor_score > 0) { return $ancestor_score + 30 + $intent_bonus; }
        if ($intent_bonus > 0 && $path_score > 0) { return $path_score + 25 + $intent_bonus; }
        return 0;
    }

    private static function category_path_strict_product_score($term, $keys, $terms_by_id) {
        if (!is_object($term)) { return 0; }
        $hay = [];
        $current = $term;
        $guard = 0;
        while (is_object($current) && $guard < 12) {
            $hay[] = self::normalize_match_key(($current->slug ?? '') . '-' . ($current->name ?? ''));
            $parent = !empty($current->parent) ? intval($current->parent) : 0;
            if ($parent <= 0 || empty($terms_by_id[$parent])) { break; }
            $current = $terms_by_id[$parent];
            $guard++;
        }
        $best = 0;
        foreach ((array)$keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            foreach (array_merge([$key], self::strict_product_key_variants($key), self::semantic_key_variants($key)) as $variant) {
                $variant = self::normalize_match_key($variant);
                if ($variant === '' || self::is_generic_category_tile_key($variant)) { continue; }
                $variant_compact = self::compact_match_key($variant);
                foreach ($hay as $path_part) {
                    if ($path_part === '') { continue; }
                    if (self::slug_has_token($path_part, $variant)) { $best = max($best, 118); }
                    if ($variant_compact !== '' && strlen($variant_compact) >= 7 && strpos(self::compact_match_key($path_part), $variant_compact) !== false) { $best = max($best, 114); }
                }
            }
            foreach (self::compound_required_token_sets($key) as $token_set) {
                $path_joined = implode('-', $hay);
                if (!empty($token_set) && self::all_tokens_present($path_joined, $token_set)) { $best = max($best, 110); }
            }
        }
        return $best;
    }

    private static function nearest_matching_product_ancestor($term, $keys, $terms_by_id) {
        if (!is_object($term)) { return null; }
        $parent = !empty($term->parent) ? intval($term->parent) : 0;
        $guard = 0;
        while ($parent > 0 && $guard < 12) {
            $ancestor = $terms_by_id[$parent] ?? null;
            if (!$ancestor) { break; }
            if (self::category_strict_product_score($ancestor, $keys) > 0) { return $ancestor; }
            $parent = !empty($ancestor->parent) ? intval($ancestor->parent) : 0;
            $guard++;
        }
        return null;
    }

    private static function category_tile_display_title_for_term($term, $keys, $terms_by_id) {
        $title = trim((string)($term->name ?? ''));
        if ($title === '') { return $title; }
        if (!self::is_intent_only_category_label($title)) { return $title; }
        $ancestor = self::nearest_matching_product_ancestor($term, $keys, $terms_by_id);
        if ($ancestor && !empty($ancestor->name)) { return $title . ' ' . trim((string)$ancestor->name); }
        foreach ((array)$keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key !== '' && !self::is_generic_category_tile_key($key)) {
                return $title . ' ' . self::title_from_key($key);
            }
        }
        return $title;
    }

    private static function is_intent_only_category_label($title) {
        $key = self::normalize_match_key($title);
        return in_array($key, self::category_tile_intents(), true);
    }

    private static function title_from_key($key) {
        $key = str_replace('-', ' ', self::normalize_match_key($key));
        if ($key === '') { return ''; }
        return ucwords($key);
    }

    private static function category_items_from_matching_posts($keys) {
        $posts = self::posts_by_product_keys($keys, 60);
        if (empty($posts)) { return []; }
        $term_scores = [];
        $terms_by_id = [];
        foreach ($posts as $post) {
            if (!$post instanceof WP_Post) { continue; }
            $cats = get_the_category($post->ID);
            if (empty($cats) || is_wp_error($cats)) { continue; }
            foreach ($cats as $term) {
                if (empty($term->term_id) || empty($term->slug) || $term->slug === 'uncategorized') { continue; }
                $score = self::category_strict_product_score($term, $keys);
                if ($score <= 0) { continue; }
                $tid = intval($term->term_id);
                $terms_by_id[$tid] = $term;
                $term_scores[$tid] = max($term_scores[$tid] ?? 0, $score);
            }
        }
        if (empty($term_scores)) { return []; }
        arsort($term_scores);
        $items = [];
        $order = 0;
        foreach (array_keys($term_scores) as $tid) {
            if (!empty($terms_by_id[$tid])) { $items[] = self::term_to_menu_like_item($terms_by_id[$tid], $order++); }
        }
        return self::dedupe_category_tile_items($items);
    }

    private static function category_tile_product_key_groups_for_current($current) {
        $exact_raw = [];
        $tail_raw = [];

        $queried = get_queried_object();
        if ($queried instanceof WP_Post) {
            if (!empty($queried->post_name)) { $exact_raw[] = $queried->post_name; }
            $exact_raw[] = get_the_title($queried);
            $last = self::last_path_part_from_url(get_permalink($queried));
            if ($last !== '') { $exact_raw[] = $last; }
        }

        $post_id = get_the_ID();
        if ($post_id) {
            $post = get_post(intval($post_id));
            if ($post instanceof WP_Post) {
                if (!empty($post->post_name)) { $exact_raw[] = $post->post_name; }
                $exact_raw[] = get_the_title($post);
                $last = self::last_path_part_from_url(get_permalink($post));
                if ($last !== '') { $exact_raw[] = $last; }
            }
        }

        if (is_object($current)) {
            if (!empty($current->title)) { $exact_raw[] = $current->title; }
            if (!empty($current->url)) {
                $last = self::last_path_part_from_url($current->url);
                if ($last !== '') { $exact_raw[] = $last; }
            }
            if (!empty($current->object_id) && in_array($current->object ?? '', ['page','post'], true)) {
                $linked_post = get_post(intval($current->object_id));
                if ($linked_post instanceof WP_Post) {
                    if (!empty($linked_post->post_name)) { $exact_raw[] = $linked_post->post_name; }
                    $exact_raw[] = get_the_title($linked_post);
                }
            }
        }

        if (!empty($_SERVER['REQUEST_URI'])) {
            $last = self::last_path_part_from_url(wp_unslash($_SERVER['REQUEST_URI']));
            if ($last !== '') { $exact_raw[] = $last; }
        }

        $exact = [];
        foreach ($exact_raw as $value) {
            $norm = self::normalize_match_key($value);
            if ($norm === '' || self::is_generic_category_tile_key($norm)) { continue; }
            $exact[] = $norm;
            foreach (self::semantic_key_variants($norm) as $variant) { $exact[] = $variant; }
        }
        $exact = array_values(array_unique(array_filter($exact, function($n) {
            return $n !== '' && strlen($n) >= 5 && !self::is_generic_category_tile_key($n);
        })));

        foreach ($exact as $norm) {
            $parts = array_values(array_filter(explode('-', $norm)));
            $parts = array_values(array_filter($parts, function($part) {
                return !in_array($part, ['und','oder','fuer','fur','mit','ohne','beim','zum','zur','thema','seite','alle'], true);
            }));
            $count = count($parts);
            if ($count >= 2) {
                $last1 = $parts[$count - 1];
                if (strlen($last1) >= 5 && !self::is_generic_category_tile_key($last1)) { $tail_raw[] = $last1; }
            }
            if ($count >= 3) {
                $last2 = $parts[$count - 2] . '-' . $parts[$count - 1];
                if (strlen($last2) >= 5 && !self::is_generic_category_tile_key($last2)) { $tail_raw[] = $last2; }
            }
        }
        $tail = array_values(array_unique(array_filter($tail_raw, function($n) {
            return $n !== '' && strlen($n) >= 5 && !self::is_generic_category_tile_key($n);
        })));

        $groups = [];
        if (!empty($exact)) { $groups[] = $exact; }
        if (!empty($tail)) { $groups[] = $tail; }
        return $groups;
    }

    private static function category_tile_product_keys_for_current($current) {
        $out = [];
        foreach (self::category_tile_product_key_groups_for_current($current) as $group) {
            foreach ((array)$group as $key) { $out[] = $key; }
        }
        return array_values(array_unique(array_filter($out)));
    }

    private static function is_generic_category_tile_key($key) {
        $key = self::normalize_match_key($key);
        $generic = [
            'pferde','pferd','portal','atelier','ausruestung','ausstattung','training','wissen',
            'decken','pferdedecken','decke','fell','haut','hautpflege','zubehoer','zubehor','grundlagen','ratgeber','themen',
            'faq','beratung','vergleich','kosten','pflege','kaufberatung','checkliste','checklisten'
        ];
        return in_array($key, $generic, true);
    }

    private static function category_strict_product_score($term, $keys) {
        $slug = self::normalize_match_key($term->slug);
        $name_slug = self::normalize_match_key($term->name);
        $best = 0;
        $intent_bonus = self::category_intent_bonus($slug);
        foreach ($keys as $key) {
            $key = self::normalize_match_key($key);
            if ($key === '' || self::is_generic_category_tile_key($key)) { continue; }
            $key_compact = self::compact_match_key($key);
            if ($key_compact !== '' && strlen($key_compact) >= 7) {
                if (strpos(self::compact_match_key($slug), $key_compact) !== false) { $best = max($best, 124); }
                if (strpos(self::compact_match_key($name_slug), $key_compact) !== false) { $best = max($best, 120); }
            }

            foreach (self::strict_product_key_variants($key) as $variant) {
                if ($variant === '' || self::is_generic_category_tile_key($variant)) { continue; }
                if (self::slug_has_token($slug, $variant)) { $best = max($best, $variant === $key ? 120 : 112); }
                if (self::slug_has_token($name_slug, $variant)) { $best = max($best, $variant === $key ? 116 : 108); }
            }

            foreach (self::compound_required_token_sets($key) as $token_set) {
                if (empty($token_set)) { continue; }
                if (self::all_tokens_present($slug, $token_set) || self::all_tokens_present($name_slug, $token_set)) {
                    $best = max($best, 104);
                }
            }
        }
        if ($best <= 0) { return 0; }
        return $best + $intent_bonus;
    }

    private static function semantic_key_variants($key) {
        $key = self::normalize_match_key($key);
        if ($key === '') { return []; }
        $variants = [$key];
        // Harte Produktvarianten fuer zusammengesetzte Begriffe ohne Bindestrich.
        $map = [
            'frostschutzkabel' => ['frostschutz-kabel', 'frostschutzkabel', 'frostschutz kabel'],
            'frostschutz-kabel' => ['frostschutz-kabel', 'frostschutzkabel', 'frostschutz kabel'],
            'fliegensprays' => ['fliegenspray', 'fliegensprays'],
            'fliegenspray' => ['fliegenspray', 'fliegensprays'],
        ];
        if (isset($map[$key])) { $variants = array_merge($variants, $map[$key]); }
        foreach (['kabel','sprays','spray','decken','decke','masken','maske','fallen','falle','gamaschen','anhaenger','kupplungen','maschinen','maschine','taschen','tasche','gurte','gurt'] as $suffix) {
            if (substr($key, -strlen($suffix)) === $suffix && strlen($key) > strlen($suffix) + 4) {
                $prefix = substr($key, 0, -strlen($suffix));
                $prefix = trim($prefix, '-');
                if (strlen($prefix) >= 4 && !self::is_generic_category_tile_key($prefix)) {
                    $variants[] = $prefix . '-' . $suffix;
                }
            }
        }
        return array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], $variants), function($v) {
            return strlen($v) >= 5 && !self::is_generic_category_tile_key($v);
        })));
    }

    private static function strict_product_key_variants($key) {
        $key = self::normalize_match_key($key);
        if ($key === '') { return []; }
        $variants = [$key];

        // einfache Singular-/Plural-Varianten, damit fliegenspray(s), decke(n), maske(n) etc. stabil matchen
        foreach (['s','n','en','e','er'] as $suffix) {
            if (substr($key, -strlen($suffix)) === $suffix && strlen($key) > strlen($suffix) + 4) {
                $variants[] = substr($key, 0, -strlen($suffix));
            }
            $variants[] = $key . $suffix;
        }

        foreach (self::compound_required_token_sets($key) as $set) {
            if (count($set) >= 2) { $variants[] = implode('-', $set); }
        }

        $variants = array_values(array_unique(array_filter(array_map([__CLASS__, 'normalize_match_key'], $variants))));
        return array_values(array_filter($variants, function($v) { return strlen($v) >= 5 && !self::is_generic_category_tile_key($v); }));
    }

    private static function compound_required_token_sets($key) {
        $key = self::normalize_match_key($key);
        $sets = [];
        if ($key === '') { return []; }

        $suffixes = [
            'frostschutzkabel' => ['frostschutz','kabel'],
            'fliegensprays' => ['fliegensprays'],
            'fliegenspray' => ['fliegenspray'],
            'pferdeanhaenger' => ['pferdeanhaenger'],
        ];
        if (isset($suffixes[$key])) { $sets[] = $suffixes[$key]; }

        // allgemeiner Compound-Fallback fuer typische Produkt-Endungen.
        // Wichtig: Es muessen ALLE Teile vorkommen. Dadurch matcht frostschutzkabel
        // auf frostschutz-kabel, aber NICHT auf nur frostschutz.
        foreach (['kabel','sprays','spray','decken','decke','masken','maske','fallen','falle','gamaschen','anhaenger','kupplungen','maschinen','maschine','taschen','tasche','gurte','gurt'] as $suffix) {
            if (substr($key, -strlen($suffix)) === $suffix && strlen($key) > strlen($suffix) + 4) {
                $prefix = substr($key, 0, -strlen($suffix));
                $prefix = trim($prefix, '-');
                if (strlen($prefix) >= 4 && !self::is_generic_category_tile_key($prefix)) {
                    $sets[] = [$prefix, $suffix];
                }
            }
        }

        $clean = [];
        foreach ($sets as $set) {
            $set = array_values(array_filter(array_map([__CLASS__, 'normalize_match_key'], (array)$set), function($v) {
                return strlen($v) >= 4 && !self::is_generic_category_tile_key($v);
            }));
            if (!empty($set)) { $clean[] = $set; }
        }
        // dedupe sets
        $seen = []; $out = [];
        foreach ($clean as $set) {
            $sig = implode('|', $set);
            if (!isset($seen[$sig])) { $seen[$sig] = true; $out[] = $set; }
        }
        return $out;
    }

    private static function all_tokens_present($slug, $tokens) {
        foreach ((array)$tokens as $token) {
            if (!self::slug_has_token($slug, $token)) { return false; }
        }
        return true;
    }

    private static function compact_match_key($value) {
        return str_replace('-', '', self::normalize_match_key($value));
    }

    private static function slug_has_token($slug, $token) {
        $slug_norm = trim(self::normalize_match_key($slug), '-');
        $token_norm = trim(self::normalize_match_key($token), '-');
        if ($slug_norm === '' || $token_norm === '') { return false; }
        $slug_wrapped = '-' . $slug_norm . '-';
        if (strpos($slug_wrapped, '-' . $token_norm . '-') !== false) { return true; }
        // Compound-Fall: frostschutzkabel muss frostschutz-kabel-faq treffen,
        // aber nicht nur frostschutz. Dadurch werden leere Produktseiten reduziert,
        // ohne breite Eltern-/Bereichstreffer zuzulassen.
        $slug_compact = self::compact_match_key($slug_norm);
        $token_compact = self::compact_match_key($token_norm);
        return $token_compact !== '' && strlen($token_compact) >= 7 && strpos($slug_compact, $token_compact) !== false;
    }

    private static function last_path_part_from_url($url) {
        $parts = self::path_parts_from_url($url);
        if (empty($parts)) { return ''; }
        return (string)end($parts);
    }

    private static function path_parts_from_url($url) {
        $path = trim((string)parse_url((string)$url, PHP_URL_PATH), '/');
        if ($path === '') { return []; }
        return array_values(array_filter(explode('/', $path), function($part) { return trim((string)$part) !== ''; }));
    }

    private static function normalize_match_key($value) {
        $value = strtolower((string)$value);
        $value = str_replace(['ä','ö','ü','ß'], ['ae','oe','ue','ss'], $value);
        $value = sanitize_title($value);
        return trim($value, '-');
    }

    private static function strong_tokens($slug) {
        $parts = explode('-', (string)$slug);
        $stop = ['und','oder','fuer','fur','mit','ohne','beim','zum','zur','thema','seite','alle','faq','beratung','vergleich','kosten','pflege','kaufberatung','ratgeber','checkliste','checklisten','installation','uebungen'];
        $out = [];
        foreach ($parts as $part) {
            $part = self::normalize_match_key($part);
            if (strlen($part) < 5) { continue; }
            if (in_array($part, $stop, true)) { continue; }
            $out[] = $part;
        }
        return array_values(array_unique($out));
    }

    private static function category_match_score_for_page($term, $needles) {
        $slug = self::normalize_match_key($term->slug);
        $name_slug = self::normalize_match_key($term->name);
        $best = 0;
        $intent_bonus = self::category_intent_bonus($slug);

        foreach ($needles as $needle) {
            $needle = self::normalize_match_key($needle);
            if ($needle === '') { continue; }
            if ($slug === $needle) { $best = max($best, 100); }
            if (strpos($slug, $needle . '-') === 0) { $best = max($best, 96); }
            if (strpos($slug, '-' . $needle . '-') !== false) { $best = max($best, 92); }
            if (substr($slug, -strlen('-' . $needle)) === '-' . $needle) { $best = max($best, 90); }
            if (strpos($slug, $needle) !== false) { $best = max($best, 84); }
            if (strpos($name_slug, $needle) !== false) { $best = max($best, 80); }
        }
        if ($best > 0) { return $best + $intent_bonus; }

        $strong_hits = 0;
        foreach ($needles as $needle) {
            foreach (self::strong_tokens($needle) as $token) {
                if (strpos($slug, $token) !== false || strpos($name_slug, $token) !== false) { $strong_hits++; }
            }
        }
        if ($strong_hits > 0 && $intent_bonus > 0) { return 60 + min(30, $strong_hits * 10) + $intent_bonus; }
        return 0;
    }

    private static function category_intent_bonus($slug) {
        foreach (['vergleich'=>25,'beratung'=>22,'kaufberatung'=>22,'kosten'=>20,'faq'=>18,'pflege'=>14,'anwendung'=>14,'sicherheit'=>14,'lagerung'=>14,'installation'=>14,'uebungen'=>14,'einsatz'=>13,'material'=>13,'modelle'=>13,'arten'=>13,'checkliste'=>14,'checklisten'=>14,'ratgeber'=>12] as $needle => $bonus) {
            if (strpos($slug, $needle) !== false) { return $bonus; }
        }
        return 0;
    }

    private static function term_to_menu_like_item($term, $order, $title_override = '') {
        $item = new stdClass();
        $item->ID = -100000 - intval($term->term_id);
        $item->db_id = $item->ID;
        $item->menu_item_parent = 0;
        $item->object_id = intval($term->term_id);
        $item->object = 'category';
        $item->type = 'taxonomy';
        $item->title = trim((string)$title_override) !== '' ? trim((string)$title_override) : $term->name;
        $item->url = get_category_link($term);
        $item->menu_order = intval($order);
        return $item;
    }

    private static function start_manual_topic_items() {
        $selection = self::start_selection();
        if ($selection['configured'] !== '1') { return ['configured' => false, 'items' => []]; }
        $items = [];
        foreach (array_slice($selection['page_ids'], 0, 8) as $order => $page_id) {
            $post = get_post(intval($page_id));
            if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') { continue; }
            if (intval(get_option('page_on_front')) === intval($post->ID)) { continue; }
            $item = new stdClass();
            $item->ID = -300000 - intval($post->ID);
            $item->db_id = $item->ID;
            $item->menu_item_parent = 0;
            $item->object_id = intval($post->ID);
            $item->object = 'page';
            $item->type = 'post_type';
            $item->title = get_the_title($post);
            $item->url = get_permalink($post);
            $item->menu_order = intval($order);
            $items[] = $item;
        }
        return ['configured' => true, 'items' => $items];
    }

    private static function direct_published_page_children($page_id) {
        $page_id = intval($page_id);
        if ($page_id <= 0 || !function_exists('get_pages')) { return []; }
        $pages = get_pages([
            'parent' => $page_id,
            'post_type' => 'page',
            'post_status' => 'publish',
            'sort_column' => 'menu_order,post_title',
            'sort_order' => 'ASC',
        ]);
        $out = [];
        foreach ((array)$pages as $post) {
            if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') { continue; }
            $item = new stdClass();
            $item->ID = -400000 - intval($post->ID);
            $item->db_id = $item->ID;
            $item->menu_item_parent = 0;
            $item->object_id = intval($post->ID);
            $item->object = 'page';
            $item->type = 'post_type';
            $item->title = get_the_title($post);
            $item->url = get_permalink($post);
            $item->menu_order = intval($post->menu_order ?? 0);
            $out[] = $item;
        }
        return array_values($out);
    }

    private static function direct_page_children_across_menu_occurrences($items, $children_map, $current) {
        $current_object = (string)($current->object ?? '');
        $current_object_id = intval($current->object_id ?? 0);
        $children = [];
        foreach ((array)$items as $candidate) {
            if (!is_object($candidate)) { continue; }
            if ((string)($candidate->object ?? '') !== $current_object || intval($candidate->object_id ?? 0) !== $current_object_id) { continue; }
            foreach ((array)($children_map[intval($candidate->ID)] ?? []) as $child) { $children[] = $child; }
        }
        return self::published_page_items($children, 0, false);
    }

    /**
     * Kategoriequelle für Hub-1-/Hub-2-Ratgeber.
     *
     * 1. Alle Kategorie-Nachfahren unter sämtlichen Menüvorkommen des aktuellen
     *    Hubs werden strukturell gesammelt.
     * 2. Alle veröffentlichten Nachfahrenseiten aus Menü und WP-Seitenhierarchie
     *    werden gesammelt.
     * 3. Falls ein Tiefe-/Menüfilter Kategorien aus der sichtbaren Struktur entfernt,
     *    werden nur Kategorien mit exakt produktbezogenem Slugmuster ergänzt
     *    (produkt-slug-intent oder intent-produkt-slug).
     */
    private static function hub_post_category_ids($items, $children_map, $current) {
        if (!is_object($current) || (string)($current->object ?? '') !== 'page') { return []; }
        $current_page_id = intval($current->object_id ?? 0);
        if ($current_page_id <= 0) { return []; }

        $page_occurrences = [];
        foreach ((array)$items as $item) {
            if (!is_object($item) || (string)($item->object ?? '') !== 'page') { continue; }
            $page_id = intval($item->object_id ?? 0);
            $item_id = intval($item->ID ?? 0);
            if ($page_id <= 0 || $item_id === 0) { continue; }
            if (!isset($page_occurrences[$page_id])) { $page_occurrences[$page_id] = []; }
            $page_occurrences[$page_id][] = $item_id;
        }

        $page_ids = [$current_page_id => true];
        $category_ids = [];
        $queue = array_values(array_map('intval', (array)($page_occurrences[$current_page_id] ?? [])));
        $visited_items = [];
        $pos = 0;
        while (isset($queue[$pos])) {
            $parent_item_id = intval($queue[$pos++]);
            if ($parent_item_id === 0 || isset($visited_items[$parent_item_id])) { continue; }
            $visited_items[$parent_item_id] = true;
            foreach ((array)($children_map[$parent_item_id] ?? []) as $child) {
                if (!is_object($child)) { continue; }
                $child_item_id = intval($child->ID ?? 0);
                $object = (string)($child->object ?? '');
                $object_id = intval($child->object_id ?? 0);
                if ($object === 'category' && $object_id > 0) { $category_ids[$object_id] = true; }
                if ($object === 'page' && $object_id > 0) {
                    $page_ids[$object_id] = true;
                    foreach ((array)($page_occurrences[$object_id] ?? []) as $occurrence_id) {
                        if (!isset($visited_items[intval($occurrence_id)])) { $queue[] = intval($occurrence_id); }
                    }
                }
                if ($child_item_id !== 0 && !isset($visited_items[$child_item_id])) { $queue[] = $child_item_id; }
            }
        }

        if (function_exists('get_pages')) {
            $hierarchy_pages = get_pages([
                'child_of' => $current_page_id,
                'post_type' => 'page',
                'post_status' => 'publish',
                'sort_column' => 'menu_order,post_title',
                'sort_order' => 'ASC',
            ]);
            foreach ((array)$hierarchy_pages as $page) {
                if ($page instanceof WP_Post && intval($page->ID) > 0) { $page_ids[intval($page->ID)] = true; }
            }
        }

        $product_slugs = [];
        foreach (array_keys($page_ids) as $page_id) {
            if (intval($page_id) === $current_page_id) { continue; }
            $page = get_post(intval($page_id));
            if (!$page instanceof WP_Post || $page->post_type !== 'page' || $page->post_status !== 'publish') { continue; }
            $slug = self::normalize_match_key($page->post_name);
            if ($slug !== '') { $product_slugs[$slug] = true; }
        }

        if (!empty($product_slugs)) {
            foreach (self::all_category_terms_cached() as $term) {
                if (!is_object($term) || empty($term->term_id)) { continue; }
                $term_slug = self::normalize_match_key($term->slug ?? '');
                if ($term_slug === '') { continue; }
                foreach (array_keys($product_slugs) as $product_slug) {
                    foreach (self::category_tile_intents() as $intent) {
                        if ($term_slug === $product_slug . '-' . $intent || $term_slug === $intent . '-' . $product_slug) {
                            $category_ids[intval($term->term_id)] = true;
                            break 3;
                        }
                    }
                }
            }
        }

        return array_values(array_map('intval', array_keys($category_ids)));
    }

    private static function published_page_items($items, $limit = 0, $exclude_front = false) {
        if ($items instanceof Traversable) { $items = iterator_to_array($items); }
        $front_id = $exclude_front ? intval(get_option('page_on_front')) : 0;
        $out = [];
        $seen = [];
        foreach ((array)$items as $item) {
            if (!is_object($item) || (string)($item->object ?? '') !== 'page') { continue; }
            $page_id = intval($item->object_id ?? 0);
            if ($page_id <= 0 || ($front_id > 0 && $page_id === $front_id) || isset($seen[$page_id])) { continue; }
            $post = get_post($page_id);
            if (!$post instanceof WP_Post || $post->post_type !== 'page' || $post->post_status !== 'publish') { continue; }
            $url = get_permalink($post);
            if (!$url) { continue; }
            $copy = clone $item;
            $copy->title = get_the_title($post);
            $copy->url = $url;
            $copy->object = 'page';
            $copy->object_id = $page_id;
            $out[] = $copy;
            $seen[$page_id] = true;
            if ($limit > 0 && count($out) >= $limit) { break; }
        }
        return array_values($out);
    }

    private static function sort_structural_items($items) {
        usort($items, function($a, $b) {
            $order = intval($a->menu_order ?? 0) <=> intval($b->menu_order ?? 0);
            if ($order !== 0) { return $order; }
            return strcasecmp((string)($a->title ?? ''), (string)($b->title ?? ''));
        });
        return $items;
    }

    private static function menu_items() {
        // V1.23.0: Alle Menues zusammenfuehren, nicht nur das erste/aktive Header-Menue.
        // Grund: Ebene-4-Kategorien koennen in einem vollstaendigen Strukturmenue liegen,
        // waehrend das sichtbare Header-Menue durch ein Tiefe-Plugin gekuerzt wird.
        $menu_ids = [];
        $locations = get_nav_menu_locations();
        foreach ((array)$locations as $mid) { if ($mid) { $menu_ids[] = intval($mid); } }
        foreach ((array)wp_get_nav_menus() as $menu) { if (!empty($menu->term_id)) { $menu_ids[] = intval($menu->term_id); } }
        $menu_ids = array_values(array_unique(array_filter($menu_ids)));
        $all = [];
        $seen = [];
        foreach ($menu_ids as $menu_id) {
            $items = wp_get_nav_menu_items($menu_id);
            if (!is_array($items)) { continue; }
            foreach ($items as $item) {
                if (!is_object($item)) { continue; }
                $key = intval($item->db_id ?: $item->ID) . ':' . (string)($item->object ?? '') . ':' . intval($item->object_id ?? 0) . ':' . (string)($item->url ?? '');
                if (isset($seen[$key])) { continue; }
                $seen[$key] = true;
                $all[] = $item;
            }
        }
        // V1.31.0: rohe nav_menu_item-Posts zusaetzlich lesen. Damit greift die
        // Ebene-4-Kachel-Ausgabe auch dann, wenn ein Menue-Tiefen-Plugin die
        // sichtbaren Menue-Objekte im Frontend bereits gekuerzt hat.
        foreach (self::raw_nav_menu_items_unfiltered() as $item) {
            if (!is_object($item)) { continue; }
            $key = intval($item->db_id ?: $item->ID) . ':' . (string)($item->object ?? '') . ':' . intval($item->object_id ?? 0) . ':' . (string)($item->url ?? '');
            if (isset($seen[$key])) { continue; }
            $seen[$key] = true;
            $all[] = $item;
        }
        return $all;
    }

    private static function raw_nav_menu_items_unfiltered() {
        $posts = get_posts([
            'post_type' => 'nav_menu_item',
            'post_status' => 'publish',
            'posts_per_page' => -1,
            'orderby' => 'menu_order',
            'order' => 'ASC',
            'no_found_rows' => true,
            'update_post_meta_cache' => true,
            'update_post_term_cache' => false,
            'suppress_filters' => true,
        ]);
        if (empty($posts)) { return []; }
        $items = [];
        foreach ($posts as $post) {
            if (!$post instanceof WP_Post) { continue; }
            $type = (string)get_post_meta($post->ID, '_menu_item_type', true);
            $object = (string)get_post_meta($post->ID, '_menu_item_object', true);
            $object_id = intval(get_post_meta($post->ID, '_menu_item_object_id', true));
            $url = (string)get_post_meta($post->ID, '_menu_item_url', true);
            $title = trim((string)$post->post_title);
            if ($title === '' && $object === 'category' && $object_id > 0) {
                $term = get_term($object_id, 'category');
                if ($term && !is_wp_error($term)) { $title = trim((string)$term->name); }
            }
            if ($title === '' && in_array($object, ['page','post'], true) && $object_id > 0) { $title = get_the_title($object_id); }
            if ($url === '') {
                if ($object === 'category' && $object_id > 0) {
                    $term_url = get_term_link($object_id, 'category');
                    if (!is_wp_error($term_url)) { $url = (string)$term_url; }
                } elseif (in_array($object, ['page','post'], true) && $object_id > 0) {
                    $url = get_permalink($object_id);
                }
            }
            $item = new stdClass();
            $item->ID = intval($post->ID);
            $item->db_id = intval($post->ID);
            $item->menu_item_parent = intval(get_post_meta($post->ID, '_menu_item_menu_item_parent', true));
            $item->object_id = $object_id;
            $item->object = $object;
            $item->type = $type;
            $item->title = $title;
            $item->url = $url;
            $item->menu_order = intval($post->menu_order);
            $items[] = $item;
        }
        return $items;
    }

    private static function frontend_visible_post_statuses() {
        return current_user_can('edit_posts') ? ['publish','draft','pending','future','private'] : 'publish';
    }

    private static function find_menu_id() {
        $locations = get_nav_menu_locations();
        foreach (['primary', 'menu-1', 'main', 'header-menu', 'ast-hf-menu-1'] as $loc) {
            if (!empty($locations[$loc])) { return intval($locations[$loc]); }
        }
        if (!empty($locations)) { return intval(reset($locations)); }
        $menus = wp_get_nav_menus();
        if (!empty($menus)) { return intval($menus[0]->term_id); }
        return 0;
    }

    private static function find_current_item($items) {
        $page_id = get_the_ID();
        if ($page_id) {
            foreach ($items as $item) {
                if (in_array($item->object, ['page', 'post'], true) && intval($item->object_id) === intval($page_id)) {
                    return $item;
                }
            }
        }
        if (is_category()) {
            $term = get_queried_object();
            if ($term && !empty($term->term_id)) {
                foreach ($items as $item) {
                    if ($item->object === 'category' && intval($item->object_id) === intval($term->term_id)) { return $item; }
                }
            }
        }
        return false;
    }

    private static function descendants($parent_id, $children_map) {
        $out = [];
        if (empty($children_map[$parent_id])) { return $out; }
        foreach ($children_map[$parent_id] as $child) {
            $out[] = $child;
            $out = array_merge($out, self::descendants($child->ID, $children_map));
        }
        return $out;
    }

    private static function all_menu_cat_ids($items) {
        $ids = [];
        foreach ($items as $item) { if ($item->object === 'category') { $ids[] = intval($item->object_id); } }
        return array_values(array_unique($ids));
    }

    private static function sort_items($items) {
        usort($items, function($a, $b) {
            $sa = self::item_score($a); $sb = self::item_score($b);
            if ($sa === $sb) { return intval($a->menu_order) <=> intval($b->menu_order); }
            return $sb <=> $sa;
        });
        return $items;
    }

    private static function post_view_day_v150297() {
        return wp_date('Y-m-d');
    }

    private static function post_view_day_timestamp_v150297($day) {
        $day = sanitize_text_field((string)$day);
        $dt = DateTimeImmutable::createFromFormat('!Y-m-d', $day, wp_timezone());
        return $dt instanceof DateTimeImmutable ? $dt->getTimestamp() : false;
    }

    private static function post_view_token_v150297($post_id, $day) {
        return hash_hmac('sha256', absint($post_id) . '|' . sanitize_text_field((string)$day), wp_salt('nonce'));
    }

    private static function post_view_is_bot_v150297($user_agent) {
        $ua = strtolower((string)$user_agent);
        if ($ua === '') { return false; }
        return (bool)preg_match('/bot|crawl|spider|slurp|bingpreview|facebookexternalhit|whatsapp|telegrambot|monitor|uptime|headless|lighthouse|pagespeed|preview/i', $ua);
    }

    public static function render_post_view_beacon_v150297() {
        if (is_admin() || is_feed() || is_preview() || !is_singular('post')) { return; }
        $post_id = absint(get_queried_object_id());
        if ($post_id < 1 || current_user_can('edit_post', $post_id)) { return; }
        $post = get_post($post_id);
        if (!$post instanceof WP_Post || $post->post_status !== 'publish') { return; }
        $day = self::post_view_day_v150297();
        $data = [
            'endpoint' => admin_url('admin-ajax.php'),
            'postId' => $post_id,
            'day' => $day,
            'token' => self::post_view_token_v150297($post_id, $day),
        ];
        echo '<script id="pftk-post-view-v150297">(function(){"use strict";var c=' . wp_json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE) . ';if(!c||!c.postId){return;}var sent=false;function send(){if(sent||document.visibilityState==="hidden"){return;}sent=true;var f=new FormData();f.append("action","pftk_record_post_view");f.append("post_id",String(c.postId));f.append("day",c.day);f.append("token",c.token);try{if(navigator.sendBeacon&&navigator.sendBeacon(c.endpoint,f)){return;}}catch(e){}fetch(c.endpoint,{method:"POST",body:f,credentials:"same-origin",keepalive:true}).catch(function(){});}window.setTimeout(send,3000);})();</script>';
    }

    public static function ajax_record_post_view_v150297() {
        nocache_headers();
        $post_id = absint($_POST['post_id'] ?? 0);
        $day = sanitize_text_field(wp_unslash($_POST['day'] ?? ''));
        $token = sanitize_text_field(wp_unslash($_POST['token'] ?? ''));
        $post = $post_id > 0 ? get_post($post_id) : null;
        if (!$post instanceof WP_Post || $post->post_type !== 'post' || $post->post_status !== 'publish') {
            wp_send_json_error(['reason' => 'invalid_post'], 400);
        }
        if (current_user_can('edit_post', $post_id) || self::post_view_is_bot_v150297($_SERVER['HTTP_USER_AGENT'] ?? '')) {
            wp_send_json_success(['counted' => false]);
        }
        $today = self::post_view_day_v150297();
        $yesterday = current_datetime()->modify('-1 day')->format('Y-m-d');
        $valid = ($day === $today && hash_equals(self::post_view_token_v150297($post_id, $today), $token))
            || ($day === $yesterday && hash_equals(self::post_view_token_v150297($post_id, $yesterday), $token));
        if (!$valid) { wp_send_json_error(['reason' => 'invalid_token'], 403); }
        $referer = wp_get_referer();
        if ($referer) {
            $home_host = strtolower((string)wp_parse_url(home_url('/'), PHP_URL_HOST));
            $ref_host = strtolower((string)wp_parse_url($referer, PHP_URL_HOST));
            if ($home_host === '' || $ref_host !== $home_host) { wp_send_json_error(['reason' => 'invalid_referer'], 403); }
        }
        $fingerprint = hash_hmac('sha256', $post_id . '|' . ($_SERVER['REMOTE_ADDR'] ?? '') . '|' . ($_SERVER['HTTP_USER_AGENT'] ?? ''), wp_salt('auth'));
        $transient = 'pftk_view_' . substr($fingerprint, 0, 32);
        if (get_transient($transient)) { wp_send_json_success(['counted' => false]); }
        set_transient($transient, 1, self::POST_VIEW_DEDUPE_SECONDS);

        $daily = get_post_meta($post_id, self::META_POST_VIEWS_DAILY, true);
        if (!is_array($daily)) { $daily = []; }
        $cutoff = current_datetime()->getTimestamp() - ((self::POST_VIEW_WINDOW_DAYS + 7) * DAY_IN_SECONDS);
        $clean = [];
        foreach ($daily as $stored_day => $count) {
            $stored_day = sanitize_text_field((string)$stored_day);
            $ts = self::post_view_day_timestamp_v150297($stored_day);
            if ($ts !== false && $ts >= $cutoff) { $clean[$stored_day] = max(0, intval($count)); }
        }
        $clean[$today] = intval($clean[$today] ?? 0) + 1;
        update_post_meta($post_id, self::META_POST_VIEWS_DAILY, $clean);
        update_post_meta($post_id, self::META_POST_VIEWS_90D, self::post_views_from_daily_v150297($clean, self::POST_VIEW_WINDOW_DAYS));
        wp_send_json_success(['counted' => true]);
    }

    private static function post_views_from_daily_v150297($daily, $days = 90) {
        $days = max(1, intval($days));
        if (!is_array($daily)) { return 0; }
        $cutoff = current_datetime()->getTimestamp() - (($days - 1) * DAY_IN_SECONDS);
        $total = 0;
        foreach ($daily as $day => $count) {
            $ts = self::post_view_day_timestamp_v150297($day);
            if ($ts !== false && $ts >= $cutoff) { $total += max(0, intval($count)); }
        }
        return $total;
    }

    private static function post_views_in_window_v150297($post_id, $days = 90) {
        $daily = get_post_meta(absint($post_id), self::META_POST_VIEWS_DAILY, true);
        return self::post_views_from_daily_v150297(is_array($daily) ? $daily : [], $days);
    }

    private static function item_score($item) {
        $score = 0;
        if (in_array($item->object, ['page','post'], true)) { $score = intval(get_post_meta(intval($item->object_id), 'pft_affiliate_score', true)); }
        elseif ($item->object === 'category') { $score = intval(get_term_meta(intval($item->object_id), 'pft_affiliate_score', true)); }
        $title = mb_strtolower((string)$item->title);
        foreach (['vergleich'=>25,'test'=>22,'beste'=>22,'kaufberatung'=>25,'kosten'=>16,'preis'=>16,'kaufen'=>18,'erfahrung'=>12,'faq'=>4,'pflege'=>6] as $kw => $add) {
            if (strpos($title, $kw) !== false) { $score += $add; }
        }
        return $score;
    }

    /**
     * Strukturierte Portalbereiche: meistgelesene Beiträge der letzten 90 Tage.
     * Unterkategorien werden rekursiv einbezogen. Bis mindestens zehn gueltige
     * Aufrufe im Kandidatenfeld vorliegen, bleibt die bestehende redaktionelle
     * Gewichtung der belastbare Fallback. Datum ist kein Sortierkriterium.
     */
    private static function top_posts_by_importance($cat_ids, $limit = 4) {
        $cat_ids = self::category_ids_with_descendants_v150297($cat_ids);
        if (empty($cat_ids)) { return []; }
        $limit = max(1, min(50, intval($limit)));
        $posts = get_posts([
            'post_type' => 'post',
            'post_status' => 'publish',
            'posts_per_page' => -1,
            'orderby' => 'title',
            'order' => 'ASC',
            'ignore_sticky_posts' => true,
            'no_found_rows' => true,
            'update_post_meta_cache' => true,
            'update_post_term_cache' => false,
            'category__in' => $cat_ids,
        ]);
        if (empty($posts)) { return []; }
        $views = [];
        $total_views = 0;
        foreach ($posts as $post) {
            $count = $post instanceof WP_Post ? self::post_views_in_window_v150297($post->ID, self::POST_VIEW_WINDOW_DAYS) : 0;
            $views[intval($post->ID)] = $count;
            $total_views += $count;
        }
        $minimum = max(1, intval(apply_filters('pftk_popularity_minimum_sample', 10, $cat_ids, $posts)));
        $use_popularity = $total_views >= $minimum;
        usort($posts, function($a, $b) use ($views, $use_popularity) {
            if ($use_popularity) {
                $va = intval($views[intval($a->ID)] ?? 0);
                $vb = intval($views[intval($b->ID)] ?? 0);
                if ($va !== $vb) { return $vb <=> $va; }
            }
            $sa = self::post_importance_score($a);
            $sb = self::post_importance_score($b);
            if ($sa !== $sb) { return $sb <=> $sa; }
            $title_cmp = strcasecmp((string)get_the_title($a), (string)get_the_title($b));
            if ($title_cmp !== 0) { return $title_cmp; }
            return intval($a->ID) <=> intval($b->ID);
        });
        return array_slice($posts, 0, $limit);
    }

    private static function category_ids_with_descendants_v150297($cat_ids) {
        $ids = array_values(array_unique(array_filter(array_map('intval', (array)$cat_ids))));
        $all = $ids;
        foreach ($ids as $term_id) {
            $children = get_term_children($term_id, 'category');
            if (is_wp_error($children)) { continue; }
            $all = array_merge($all, array_map('intval', (array)$children));
        }
        return array_values(array_unique(array_filter($all)));
    }

    private static function post_importance_score($post) {
        if (!$post instanceof WP_Post) { return 0; }
        $manual = intval(get_post_meta(intval($post->ID), 'pft_affiliate_score', true));
        $manual = max(0, min(100, $manual));
        return ($manual * 1000) + self::post_strategy_score($post);
    }

    private static function top_posts_from_categories($cat_ids, $limit, $mode = 'strategic_span') {
        if (empty($cat_ids)) { return []; }
        // V1.50.297: Kuratierte Artikelauswahlen werden unabhängig von einem
        // historischen Backend-Wert nicht mehr nach Veröffentlichungsdatum sortiert.
        // Nur ausdrücklich als "neu/aktuell" bezeichnete Sonderblöcke besitzen
        // weiterhin eine eigene chronologische Abfrage.
        return self::top_posts_by_importance($cat_ids, max(1, min(50, intval($limit))));
    }

    private static function post_strategy_score($post) {
        $text = mb_strtolower(get_the_title($post) . ' ' . $post->post_name);
        $score = 0;
        foreach ([
            'vergleich' => 35, 'test' => 28, 'beste' => 26, 'vor-und-nachteile' => 28,
            'kauf' => 30, 'kaufen' => 30, 'kosten' => 26, 'preis' => 24, 'auswahl' => 22,
            'beratung' => 24, 'ratgeber' => 20, 'checkliste' => 22, 'beachten' => 18,
            'faq' => 12, 'was' => 8, 'welche' => 8, 'wann' => 8,
            'pflege' => 16, 'reinigen' => 16, 'sicher' => 14
        ] as $kw => $add) {
            if (strpos($text, $kw) !== false) { $score += $add; }
        }
        return $score;
    }

    private static function post_search_intent($post) {
        $text = mb_strtolower(get_the_title($post) . ' ' . $post->post_name);
        $map = [
            'comparison' => ['vergleich','test','beste','vor-und-nachteile','vorteile','nachteile'],
            'buying' => ['kauf','kaufen','kosten','preis','angebot','auswahl','lohnt'],
            'advice' => ['beratung','ratgeber','checkliste','beachten','worauf','helfen','sinnvoll'],
            'faq' => ['faq','was','welche','wann','ist','muss'],
            'care' => ['pflege','reinigen','anwendung','nutzen','sicher'],
        ];
        foreach ($map as $intent => $keywords) {
            foreach ($keywords as $kw) { if (strpos($text, $kw) !== false) { return $intent; } }
        }
        return 'general';
    }

    private static function item_excerpt($item) {
        if (in_array($item->object, ['page','post'], true)) {
            $post = get_post(intval($item->object_id));
            if ($post) { return self::clean_excerpt($post); }
        }
        if ($item->object === 'category') {
            $term = get_term(intval($item->object_id), 'category');
            if ($term && !is_wp_error($term) && !empty($term->description)) { return wp_trim_words(wp_strip_all_tags($term->description), 16); }
        }
        return '';
    }

    private static function clean_excerpt($post) {
        $raw = has_excerpt($post) ? $post->post_excerpt : $post->post_content;
        $raw = preg_replace('/\[[^\]]+\]/', ' ', $raw);
        $raw = preg_replace('/<style\b[^>]*>.*?<\/style>/is', ' ', $raw);
        $raw = preg_replace('/[a-z0-9\.\#\-_,\s]+\{[^\}]{5,}\}/i', ' ', $raw);
        $text = wp_strip_all_tags(strip_shortcodes($raw));
        $text = preg_replace('/\s+/', ' ', trim($text));
        return wp_trim_words($text, 18);
    }

    private static function color($index) {
        $colors = ['#37abf2', '#27a653', '#f3cb04', '#f17798'];
        return $colors[$index % count($colors)];
    }

    private static function font_css($font) { return self::sanitize_font($font); }

