tk-card-grid-count-5>.pftk-card,.pftk-hub2 .pftk-card-grid-count-5>.pftk-card:nth-child(n+4),.pftk-auto-category-tiles .pftk-card-grid-count-5>.pftk-card,.pftk-category .pftk-card-grid-count-5>.pftk-card{grid-column:auto!important}.pftk-card,.pftk-structure-card{min-height:0;height:auto!important}.pftk-hub1 .pftk-card-grid-count-5>.pftk-card,.pftk-hub1 .pftk-card-grid-count-6>.pftk-card,.pftk-hub2 .pftk-card-grid-count-5>.pftk-card,.pftk-hub2 .pftk-card-grid-count-6>.pftk-card,.pftk-category .pftk-card-grid-count-6>.pftk-card,.pftk-auto-category-tiles .pftk-card-grid-count-6>.pftk-card{height:auto!important}}";

        foreach (self::templates() as $type => $cfg) {
            if ($type === 'start') { continue; } // V1.50.176: alte Startseiten-Typografieoptionen dürfen das neue Design nicht überschreiben.
            foreach (self::heading_keys() as $key => $label) {
                $size = intval(self::style($type, $key . '_size'));
                $color = self::style($type, $key . '_color');
                $font = self::font_css(self::style($type, $key . '_font'));
                $selector = '.pftk-' . $type . ' .pftk-heading-' . str_replace('_', '\\_', $key);
                if ($key === 'hero_title') {
                    $css .= $selector . '{font-size:clamp(30px,4.3vw,' . $size . 'px)!important;color:' . $color . ';font-family:' . $font . '}';
                } elseif ($key === 'hero_eyebrow') {
                    $css .= $selector . '{font-size:' . $size . 'px!important;color:' . $color . ';font-family:' . $font . '}';
                } elseif ($key === 'card_title') {
                    $css .= $selector . '{display:block;margin:0!important;padding:0!important;font-size:' . $size . 'px!important;line-height:1.18!important;letter-spacing:-.015em;color:' . $color . ';font-family:' . $font . ';font-weight:800}';
                } else {
                    $css .= $selector . '{margin:0 0 5px!important;padding:0!important;font-size:clamp(22px,3vw,' . $size . 'px)!important;line-height:1.15!important;letter-spacing:-.02em;color:' . $color . ';font-family:' . $font . ';font-weight:800}';
                }
            }
            $level_heading_font = self::font_css(self::style($type, 'level_heading_font'));
            $level_heading_weight = self::sanitize_font_weight(self::style($type, 'level_heading_font_weight'));
            $level_heading_color = self::style($type, 'level_heading_color') ?: '#172018';
            $level_heading_deco = self::style($type, 'level_heading_decoration') === 'underline' ? 'underline' : 'none';
            $level_heading_margin = max(0, min(200, intval(self::style($type, 'level_heading_margin_top'))));
            $level_heading_margin_bottom = max(0, min(200, intval(self::style($type, 'level_heading_margin_bottom'))));
            $level_card_font = self::font_css(self::style($type, 'level_card_font'));
            $level_card_weight = self::sanitize_font_weight(self::style($type, 'level_card_font_weight'));
            $level_card_color = self::style($type, 'level_card_color') ?: '#172018';
            $level_card_deco = self::style($type, 'level_card_decoration') === 'underline' ? 'underline' : 'none';
            $scope = '.pftk-' . $type;
            // V1.46.4: einheitliche Schriftstaerke fuer alle Plugin-Ueberschriften der Ebene,
            // einschliesslich Startseiten-Hero. !important neutralisiert alte 700/800-Regeln.
            $css .= $scope . ' .pftk-heading:not(.pftk-heading-card_title){' .
