                'font-weight:' . $level_heading_weight . '!important;' .
                'font-synthesis:none!important;' .
                'text-align:center!important}';
            $css .= $scope . ' .pftk-section-head .pftk-heading{' .
                'font-family:' . $level_heading_font . '!important;' .
                'font-weight:' . $level_heading_weight . '!important;' .
                'font-synthesis:none!important;' .
                'color:' . $level_heading_color . '!important;' .
                'text-decoration:' . $level_heading_deco . '!important;' .
                'margin-top:' . $level_heading_margin . 'px!important;' .
                'margin-bottom:' . $level_heading_margin_bottom . 'px!important}';
            $css .= $scope . ' .pftk-card .pftk-heading-card_title,' . $scope . ' .pftk-structure-card .pftk-heading-card_title{' .
                'font-family:' . $level_card_font . '!important;' .
                'font-weight:' . $level_card_weight . '!important;' .
                'font-synthesis:none!important;' .
                'color:' . $level_card_color . '!important;' .
                'text-decoration:' . $level_card_deco . '!important}';
        }
        $hub1_ad_bg = self::style('hub1', 'hub_grid_ad_background_color') ?: '#ffffff';
        $hub2_ad_bg = self::style('hub2', 'hub_grid_ad_background_color') ?: '#ffffff';
        $css .= '.pftk-hub1 .pftk-hub-grid-ad{background-color:' . $hub1_ad_bg . '!important}.pftk-hub2 .pftk-hub-grid-ad{background-color:' . $hub2_ad_bg . '!important}';

        $tile_size = intval(self::style('category', 'category_tile_font_size'));
        if ($tile_size < 10) { $tile_size = 18; }
        $tile_color = self::style('category', 'level_card_color') ?: '#172018';
        $tile_hover = self::style('category', 'category_tile_hover_color') ?: '#27a653';
        $tile_deco = self::style('category', 'level_card_decoration') === 'underline' ? 'underline' : 'none';
        $tile_hover_deco = self::style('category', 'category_tile_link_hover_decoration') === 'underline' ? 'underline' : 'none';
        $css .= '.pftk-category .pftk-card,.pftk-auto-category-tiles .pftk-card{color:' . $tile_color . '!important;text-decoration:' . $tile_deco . '!important}.pftk-category .pftk-card:hover,.pftk-auto-category-tiles .pftk-card:hover{color:' . $tile_hover . '!important;text-decoration:' . $tile_hover_deco . '!important}.pftk-category .pftk-card .pftk-heading-card_title,.pftk-auto-category-tiles .pftk-card .pftk-heading-card_title{font-size:' . $tile_size . 'px!important;color:inherit!important}.pftk-category .pftk-card b,.pftk-auto-category-tiles .pftk-card b{color:inherit!important}';

        // V1.46.0: zentrale Farbsteuerung in den Haupteinstellungen.
        $global_card_colors = self::global_card_title_colors();
        $global_layout = self::global_layout_settings();
        $category_tile_font_family = self::font_css($global_layout['category_tile_font_family'] ?? 'inherit');
        $main_block_top_gap = max(0, min(200, intval($global_layout['main_block_top_gap'] ?? 30)));
        $content_width = max(760, min(1600, intval($global_layout['content_width'] ?? 1200)));
        $intro_max_width = max(320, min(1600, intval($global_layout['intro_max_width'] ?? 740)));
        $intro_font_family = self::font_css($global_layout['intro_font_family'] ?? 'inherit');
        $intro_font_size = max(10, min(40, intval($global_layout['intro_font_size'] ?? 17)));
        $intro_font_weight = self::sanitize_font_weight($global_layout['intro_font_weight'] ?? '400');
        $intro_font_style = in_array((string)($global_layout['intro_font_style'] ?? 'normal'), ['normal','italic'], true) ? (string)$global_layout['intro_font_style'] : 'normal';
        $intro_text_decoration = in_array((string)($global_layout['intro_text_decoration'] ?? 'none'), ['none','underline'], true) ? (string)$global_layout['intro_text_decoration'] : 'none';
        $intro_text_color = sanitize_hex_color((string)($global_layout['intro_text_color'] ?? '')) ?: '#2b2b2b';
        $intro_line_height = (float)($global_layout['intro_line_height'] ?? 1.7);
        if ($intro_line_height < 1.0 || $intro_line_height > 2.5) { $intro_line_height = 1.7; }
        $intro_text_align = in_array((string)($global_layout['intro_text_align'] ?? 'left'), ['left','center','right'], true) ? (string)$global_layout['intro_text_align'] : 'left';
        $intro_margin_top = max(0, min(200, intval($global_layout['intro_margin_top'] ?? 0)));
        $intro_margin_bottom = max(0, min(200, intval($global_layout['intro_margin_bottom'] ?? 34)));
        $section_heading_color = $global_card_colors['section_heading_color'];
        $category_title_color = $global_card_colors['category_title_color'];
        $post_title_color = $global_card_colors['post_title_color'];
        $guide_title_color = $global_card_colors['guide_title_color'];
        // V1.46.2: explizite Selektoren je Ebene verhindern, dass Hub-1/2-Titel durch
