        $css .= '.pftk-start #pftk-topics .pftk-card:not(.pftk-hub-grid-ad) .pftk-heading-card_title,' .
            '.pftk-hub1 #pftk-topics .pftk-card:not(.pftk-hub-grid-ad) .pftk-heading-card_title,' .
            '.pftk-hub2 #pftk-topics .pftk-card:not(.pftk-hub-grid-ad) .pftk-heading-card_title,' .
            '.pftk-category #pftk-topics .pftk-card:not(.pftk-hub-grid-ad) .pftk-heading-card_title,' .
            '.pftk-auto-category-tiles #pftk-topics .pftk-card:not(.pftk-hub-grid-ad) .pftk-heading-card_title,' .
            '.pftk-start #pftk-structure .pftk-structure-card .pftk-heading-card_title{' .
            'color:' . $category_title_color . '!important}';
        $css .= '.pftk-start #pftk-posts .pftk-card .pftk-heading-card_title,' .
            '.pftk-hub1 #pftk-posts .pftk-card .pftk-heading-card_title,' .
            '.pftk-hub2 #pftk-posts .pftk-card .pftk-heading-card_title,' .
            '.pftk-category #pftk-posts .pftk-card .pftk-heading-card_title,' .
            '.pftk-category #pftk-product-articles .pftk-card .pftk-heading-card_title,' .
