     * Nur der problematische schmale Zwischenbereich wird vertikal dargestellt.
     */
    public static function responsive_card_layout_script() {
        if (is_admin()) { return; }
        echo <<<'HTML'
<script id="pftk-responsive-card-layout-v15036">
(function(){
  var selector=".pftk .pftk-card.pftk-card-nav.pftk-has-category-icon";
  var limit=285;
  function update(card){
    var width=card.getBoundingClientRect().width||0;
    card.classList.toggle("pftk-card-narrow",width>0&&width<=limit);
  }
  function scan(){document.querySelectorAll(selector).forEach(function(card){observe(card);update(card);});}
  var seen=new WeakSet();
  var ro=window.ResizeObserver?new ResizeObserver(function(entries){entries.forEach(function(entry){update(entry.target);});}):null;
  function observe(card){if(seen.has(card))return;seen.add(card);if(ro)ro.observe(card);}
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",scan);else scan();
  window.addEventListener("resize",scan,{passive:true});
  new MutationObserver(scan).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
HTML;
    }

