    important(grid,'grid-auto-flow','row');
    important(grid,'gap',width<=620?'14px':'18px');
    important(grid,'width','100%');
    important(grid,'max-width',width<=620?'none':'100%');
    important(grid,'margin-left','auto');
    important(grid,'margin-right','auto');
    important(grid,'justify-content','stretch');
    important(grid,'align-items','stretch');
    cards.forEach(function(card){
      card.setAttribute('data-pftk-three-product-card-v150373','1');
      important(card,'width','100%');
      important(card,'max-width','none');
      important(card,'min-width','0');
      important(card,'height','auto');
    });
  }
  function scan(){
    var width=window.innerWidth||document.documentElement.clientWidth||0;
    selectors.forEach(function(selector){
      document.querySelectorAll(selector).forEach(function(grid){
        var cards=directElements(grid);
        if(cards.length!==3){clearGrid(grid,cards);return;}
        if(width<=1100){applyGrid(grid,cards,width);}else{clearGrid(grid,cards);}
      });
    });
  }
  var queued=false;
  function queue(){if(queued)return;queued=true;requestAnimationFrame(function(){queued=false;scan();});}
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',scan,{once:true});}else{scan();}
  window.addEventListener('resize',queue,{passive:true});
  new MutationObserver(queue).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
HTML;
    }

    public static function placeholder_image_autocrop_script() {
        if (is_admin()) { return; }
        echo <<<'HTML'
<script id="pftk-placeholder-autocrop-v15036">
(function(){
  var selector=".pftk .pftk-card.pftk-card-ad[data-pftk-placeholder=\"1\"]";
  var cache={};
  function state(card,value){card.setAttribute("data-pftk-autocrop",value);}
  function createCrop(src){
    if(cache[src])return cache[src];
    cache[src]=new Promise(function(resolve){
      var image=new Image();
      image.decoding="async";
      image.onload=function(){
        try{
          var w=image.naturalWidth||0,h=image.naturalHeight||0;
          if(w<2||h<2){resolve("");return;}
          var scale=Math.min(1,800/Math.max(w,h));
          var sw=Math.max(1,Math.round(w*scale)),sh=Math.max(1,Math.round(h*scale));
          var scan=document.createElement("canvas");scan.width=sw;scan.height=sh;
          var ctx=scan.getContext("2d",{willReadFrequently:true});
          ctx.drawImage(image,0,0,sw,sh);
          var pixels=ctx.getImageData(0,0,sw,sh).data;
          function pale(x,y){var i=(y*sw+x)*4;return pixels[i+3]<16||(pixels[i]>244&&pixels[i+1]>244&&pixels[i+2]>244);}
          var inset=Math.max(1,Math.round(Math.min(sw,sh)*0.01));
          var corners=[[inset,inset],[sw-1-inset,inset],[inset,sh-1-inset],[sw-1-inset,sh-1-inset]];
          var paleCorners=0;for(var c=0;c<corners.length;c++){if(pale(corners[c][0],corners[c][1]))paleCorners++;}
          if(paleCorners<3){resolve("");return;}
          var minX=sw,minY=sh,maxX=-1,maxY=-1;
          var step=Math.max(1,Math.floor(Math.max(sw,sh)/600));
          for(var y=0;y<sh;y+=step){for(var x=0;x<sw;x+=step){if(!pale(x,y)){if(x<minX)minX=x;if(x>maxX)maxX=x;if(y<minY)minY=y;if(y>maxY)maxY=y;}}}
          if(maxX<minX||maxY<minY){resolve("");return;}
          var boxW=maxX-minX+1,boxH=maxY-minY+1;
          if(boxW/sw>0.94&&boxH/sh>0.94){resolve("");return;}
          // Kein Aussen-Padding: Genau dieses Padding erzeugte live die verbleibenden weissen Seitenstreifen.
          // Horizontal wird 1 % innerhalb der erkannten Motivkante geschnitten; vertikal bleibt die echte
          // Motivkante erhalten, weil `cover` dort ohnehin passend beschneidet.
          var trimX=Math.max(2,Math.round(boxW*0.01));
          minX=Math.min(maxX-1,minX+trimX);maxX=Math.max(minX+1,maxX-trimX);
          var sx=Math.max(0,Math.floor(minX/scale)),sy=Math.max(0,Math.floor(minY/scale));
          var cw=Math.min(w-sx,Math.ceil((maxX-minX+1)/scale)),ch=Math.min(h-sy,Math.ceil((maxY-minY+1)/scale));
          if(cw<2||ch<2){resolve("");return;}
          var out=document.createElement("canvas");out.width=cw;out.height=ch;
          out.getContext("2d").drawImage(image,sx,sy,cw,ch,0,0,cw,ch);
          out.toBlob(function(blob){resolve(blob?URL.createObjectURL(blob):"");},"image/webp",0.92);
        }catch(error){resolve("");}
      };
      image.onerror=function(){resolve("");};
      image.src=src;
    });
    return cache[src];
  }
  function apply(card){
    if(card.getAttribute("data-pftk-autocrop"))return;
    state(card,"pending");
    var img=card.querySelector(".pftk-hub-grid-ad-image>img");
    var src=img?(img.currentSrc||img.src||""):"";
    if(!src){state(card,"no-image");return;}
    createCrop(src).then(function(url){if(url){card.style.setProperty("background-image","url(\""+url+"\")","important");state(card,"done");}else{state(card,"skipped");}});
  }
  function run(){document.querySelectorAll(selector).forEach(apply);}
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",run);else run();
  window.addEventListener("load",run,{once:true});
  new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});
})();
</script>
HTML;
    }

    public static function article_design_script() {
        if (is_admin() || !is_singular('post')) { return; }
        echo <<<'HTML'
<script id="pftk-article-design-v150365">
(function(){
  var c=document.querySelector("body.single-post .entry-content");
  if(!c)return;

  var norm=function(v){
    return String(v||"").replace(/\u00a0/g," ").replace(/\s+/g," ").trim().toLowerCase();
  };
  var isMedia=function(e){
    return !!(e&&(
      (e.matches&&e.matches("figure,.wp-block-image,.wp-caption,picture"))||
      (e.querySelector&&e.querySelector("img"))
    ));
  };
  var firstTextParagraph=function(root){
    if(!root)return null;
    return Array.prototype.slice.call(root.querySelectorAll("p")).find(function(p){
      return norm(p.textContent).length>0;
    })||null;
  };
  var topChildOf=function(root,node){
    var current=node;
    while(current&&current.parentElement&&current.parentElement!==root){
      current=current.parentElement;
    }
    return current&&current.parentElement===root?current:null;
  };
  var findExternalFeaturedImage=function(){
    var themeArticle=c.closest("article");
    if(!themeArticle)return null;
    var candidate=themeArticle.querySelector(
      ".ast-single-post-featured-section,.post-thumb,.post-thumb-img-content,.ast-blog-featured-section"
    );
    if(!candidate||c.contains(candidate))return null;
    var outer=candidate;
    while(outer.parentElement&&outer.parentElement!==themeArticle&&outer.parentElement!==c){
      outer=outer.parentElement;
    }
    return outer;
  };
  var findAdjacentMediaBefore=function(root,node){
    var current=node;
    while(current&&current!==root){
      var previous=current.previousElementSibling;
      while(previous&&
        !isMedia(previous)&&
        !norm(previous.textContent).length&&
        !previous.querySelector("h1,h2,h3,h4,h5,h6,p,ul,ol,table,blockquote")){
        previous=previous.previousElementSibling;
      }
      if(previous&&isMedia(previous))return previous;
      current=current.parentElement;
    }
    return null;
  };

  /* V1.50.365: Produktionsmaschinen-Artikel werden nicht nur an der
     optionalen Klasse, sondern auch am verbindlichen data-article-type
     erkannt. Ohne diese Erkennung wurde ein inneres article-Element ohne
     ppm-generated fälschlich als kompletter Introinhalt behandelt und damit
     der gesamte Beitrag farbig hinterlegt. */
  var structured=c.querySelector("article.ppm-generated,article[data-article-type]");
  if(structured&&!structured.classList.contains("ppm-generated")){
    structured.classList.add("ppm-generated");
  }
  var scope=structured||c;
  var intro=null;
  var firstP=null;
  var photo=null;

  if(structured){
    structured.classList.remove("pa-ppm-compat-v150290");
    structured.classList.add("pa-ppm-compat-v150291");

    var structuredDirect=Array.prototype.slice.call(structured.children);
    var firstStructuredHeading=Array.prototype.slice.call(structured.querySelectorAll("h2,h3")).find(function(h){
      return !h.closest('section[data-block="conclusion"]');
    })||null;
    var headingTop=topChildOf(structured,firstStructuredHeading);
    var structuredBoundary=headingTop?structuredDirect.indexOf(headingTop):structuredDirect.length;
    if(structuredBoundary<0)structuredBoundary=structuredDirect.length;
    var structuredBefore=structuredDirect.slice(0,structuredBoundary).filter(function(e){
      return !/^(SCRIPT|STYLE|NOSCRIPT)$/.test(e.tagName)&&
        !e.matches('section[data-block="conclusion"]');
    });
    var isBeforeBoundary=function(node,boundaryNode){
      if(!node)return false;
      if(!boundaryNode)return true;
      return !!(node.compareDocumentPosition(boundaryNode)&Node.DOCUMENT_POSITION_FOLLOWING);
    };
    var introParagraphs=Array.prototype.slice.call(structured.querySelectorAll("p")).filter(function(p){
      if(!norm(p.textContent).length)return false;
      if(p.closest("figure,figcaption,table,thead,tbody,tfoot,ul,ol,blockquote"))return false;
      if(p.closest('section[data-block="conclusion"]'))return false;
      return isBeforeBoundary(p,firstStructuredHeading);
    }).slice(0,2);

    intro=structured.querySelector('section[data-block="intro"]');
    photo=structuredBefore.find(function(e){
      return e!==intro&&e.tagName!=="H1"&&isMedia(e);
    })||null;

    /* V1.50.292: Ein nachträglich im WordPress-Editor eingefügtes Bild kann
       unmittelbar VOR dem inneren article.ppm-generated liegen. V1.50.291
       suchte nur innerhalb des strukturierten Artikels und konnte diesen
       realen DOM-Fall deshalb nicht rahmen. Es wird ausschließlich das direkt
       angrenzende Medienelement vor dem strukturierten Artikel bzw. dessen
       äußerem Wrapper übernommen. */
    if(!photo){
      photo=findAdjacentMediaBefore(c,structured);
    }

    if(!photo&&intro){
      var embedded=intro.querySelector("figure,.wp-block-image,.wp-caption,picture,img");
      if(embedded){
        photo=embedded.closest("figure,.wp-block-image,.wp-caption,picture")||embedded;
      }
    }

    if(!photo){
      photo=findExternalFeaturedImage();
    }

    /* V1.50.291: Der obere Text kann bei Produktionsmaschinen-Beiträgen
       direkt oder in einem gemeinsamen Inhaltswrapper liegen. Unabhängig von
       dieser Verschachtelung werden die ersten beiden echten Absätze vor der
       ersten H2/H3 als Intro erfasst. */
    if(!intro&&introParagraphs.length){
      intro=document.createElement("section");
      intro.className="pa-article-intro pa-ppm-reconstructed-intro-v150291";
      introParagraphs[0].parentNode.insertBefore(intro,introParagraphs[0]);
    }
    if(intro&&introParagraphs.length){
      introParagraphs.forEach(function(p){
        if(!intro.contains(p))intro.appendChild(p);
      });
    }

    if(intro){
      intro.classList.add("pa-article-intro");
      firstP=firstTextParagraph(intro);
      if(firstP)firstP.classList.add("pa-article-intro-first");
    }

    /* V1.50.291: Vorhandene Teilrahmen werden nicht übersprungen, sondern
       normalisiert. Dadurch liegen Bild UND die beiden ersten echten Absätze
       nachweislich im selben Rahmen – auch wenn article.ppm-generated in einem
       zusätzlichen WordPress-/Block-Wrapper verschachtelt ist. */
    var frame=structured.querySelector(":scope > .pa-photo-intro-frame")||
      c.querySelector(":scope > .pa-photo-intro-frame");

    if(intro&&photo){
      if(frame&&photo===frame){
        photo=frame.querySelector(":scope > .pa-photo-intro-media")||
          frame.querySelector("figure,.wp-block-image,.wp-caption,picture,img");
      }
      if(!photo)return;
      photo.classList.add("pa-photo-intro-media");

      if(!frame){
        frame=document.createElement("section");
        frame.className="pa-photo-intro-frame pa-ppm-photo-intro-frame-v150291";

        var introTop=topChildOf(structured,intro)||intro;
        var photoTop=topChildOf(structured,photo)||photo;
        var anchor=introTop;
        if(photoTop.parentElement===structured){
          var current=structured.firstElementChild;
          while(current){
            if(current===photoTop){anchor=photoTop;break;}
            if(current===introTop){anchor=introTop;break;}
            current=current.nextElementSibling;
          }
        }
        structured.insertBefore(frame,anchor);
      }else{
        frame.classList.add("pa-ppm-photo-intro-frame-v150291");
      }

      if(!frame.contains(photo)){
        frame.insertBefore(photo,frame.firstElementChild||null);
      }
      if(!frame.contains(intro)){
        frame.appendChild(intro);
      }
    }

    var structuredConclusion=structured.querySelector('section[data-block="conclusion"]');
    if(structuredConclusion){
      structuredConclusion.classList.add("pa-fazit-auto","pa-ppm-conclusion-v150290");
    }
  }else{
    var direct=Array.prototype.slice.call(c.children);
    var firstH2=direct.find(function(e){return e.tagName==="H2";});
    var boundary=firstH2?direct.indexOf(firstH2):direct.length;
    var before=direct.slice(0,boundary).filter(function(e){
      return !/^(SCRIPT|STYLE|NOSCRIPT)$/.test(e.tagName);
    });

    before.some(function(e){
      if(e.tagName==="P"&&norm(e.textContent).length){firstP=e;return true;}
      var p=e.querySelector?e.querySelector("p"):null;
      if(p&&norm(p.textContent).length){firstP=p;return true;}
      return false;
    });

    photo=findExternalFeaturedImage();
    if(!photo)photo=before.find(isMedia)||null;

    intro=c.querySelector(":scope > .pa-article-intro");
    if(!intro&&firstP){
      intro=document.createElement("section");
      intro.className="pa-article-intro";
      var movable=before.filter(function(e){
        return e!==photo&&(
          norm(e.textContent).length||
          e.tagName==="P"||
          e.tagName==="DIV"||
          e.tagName==="BLOCKQUOTE"
        );
      });
      if(movable.length){
        movable[0].parentNode.insertBefore(intro,movable[0]);
        movable.forEach(function(e){intro.appendChild(e);});
        firstP.classList.add("pa-article-intro-first");
      }
    }else if(intro&&firstP){
      firstP.classList.add("pa-article-intro-first");
    }

    if(intro&&photo&&!c.querySelector(":scope > .pa-photo-intro-frame")){
      photo.classList.add("pa-photo-intro-media");
      var legacyFrame=document.createElement("section");
      legacyFrame.className="pa-photo-intro-frame";
      var legacyAnchor=photo.parentNode===c?photo:intro;
      c.insertBefore(legacyFrame,legacyAnchor);
      legacyFrame.appendChild(photo);
      legacyFrame.appendChild(intro);
    }
  }

  scope.querySelectorAll("ul,ol").forEach(function(l){
    if(!l.closest(".pa-weiter-links"))l.classList.add("pa-article-list");
  });
  scope.querySelectorAll("p").forEach(function(p){
    var t=norm(p.textContent);
    if(/^praxistipp\s*:/.test(t))p.classList.add("pa-praxistipp-auto");
    if(t==="dieser beitrag wurde mithilfe von ki vorformuliert und anschließend redaktionell geprüft und überarbeitet."){
      p.classList.add("pa-ai-disclaimer-v150290");
    }
  });

  var conclusion=scope.querySelector(':scope > section[data-block="conclusion"]');
  if(!conclusion){
    var hs=Array.prototype.slice.call(scope.querySelectorAll("h2,h3"));
    var f=hs.find(function(h){
      return /^fazit(?:$|\s|:|–|—|-)/.test(norm(h.textContent));
    });
    if(f){
      var existing=f.closest('[data-block="conclusion"]');
      if(existing){
        existing.classList.add("pa-fazit-auto","pa-ppm-conclusion-v150290");
      }else if(!f.parentElement.classList.contains("pa-fazit-auto")){
        var box=document.createElement("section");
        box.className="pa-fazit-auto";
        f.parentNode.insertBefore(box,f);
        var n=f;
        while(n){
          var next=n.nextElementSibling;
          box.appendChild(n);
          if(!next||/^(H2|H3)$/.test(next.tagName))break;
          n=next;
        }
      }
    }
  }

  var w=Array.prototype.slice.call(scope.querySelectorAll("h2,h3")).find(function(h){
    return /^weiterführende informationen(?:$|\s|:|–|—|-)/.test(norm(h.textContent));
  });
  if(w){
    var nx=w.nextElementSibling;
    if(nx&&nx.tagName==="UL"){
      nx.classList.remove("pa-article-list");
      nx.classList.add("pa-weiter-links");
    }
  }
})();
</script>
HTML;
    }

    /**
     * V1.50.121 – kontrollierte Integration des bisherigen Plugins
     * „Pferdeportal Menü-Tiefe 3“.
     *
     * Sicherheitsregel: Ist das Altplugin aktiv, bleibt dieser integrierte
     * Baustein vollständig passiv. Nach dessen Deaktivierung übernimmt er
     * automatisch dieselbe Option und dieselbe Filterlogik. Dadurch gibt es
     * zu keinem Zeitpunkt zwei konkurrierende Menüfilter.
     */
    public static function maybe_init_integrated_menu_depth_v150121() {
        if (class_exists('Pferdeportal_Menu_Depth_3', false)) {
            return;
        }
        self::ensure_integrated_menu_depth_defaults_v150121();
        add_action('admin_menu', [__CLASS__, 'integrated_menu_depth_admin_menu_v150121']);
        add_action('admin_init', [__CLASS__, 'integrated_menu_depth_register_settings_v150121']);
        add_filter('wp_nav_menu_args', [__CLASS__, 'integrated_menu_depth_limit_args_v150121'], 20, 1);
        add_filter('wp_nav_menu_objects', [__CLASS__, 'integrated_menu_depth_remove_items_v150121'], 20, 2);
        add_filter('nav_menu_css_class', [__CLASS__, 'integrated_menu_depth_clean_child_class_v150121'], 20, 4);
    }

    private static function ensure_integrated_menu_depth_defaults_v150121() {
        if (get_option(self::OPTION_MENU_DEPTH_V150121, null) !== null) { return; }
        $registered = function_exists('get_registered_nav_menus') ? (array)get_registered_nav_menus() : [];
        $selected = [];
        foreach (['primary','ast-hf-menu-1','menu-1','main','header-menu'] as $location) {
            if (isset($registered[$location])) { $selected[] = $location; break; }
        }
        add_option(self::OPTION_MENU_DEPTH_V150121, [
            'enabled' => 1,
            'depth' => 3,
            'locations' => $selected,
        ], '', false);
    }

    private static function integrated_menu_depth_options_v150121() {
        $value = get_option(self::OPTION_MENU_DEPTH_V150121, []);
        $value = is_array($value) ? $value : [];
        $value = array_merge(['enabled'=>1,'depth'=>3,'locations'=>[]], $value);
        $value['enabled'] = !empty($value['enabled']) ? 1 : 0;
        $value['depth'] = max(1, min(10, intval($value['depth'])));
        $value['locations'] = array_values(array_filter(array_map('sanitize_key', (array)$value['locations'])));
        return $value;
    }

    public static function integrated_menu_depth_admin_menu_v150121() {
        // V1.50.312: Die Navigation ist vertraglich auf drei Ebenen gesperrt.
        // Die historische Einstellungsseite wird nicht mehr registriert.
        return;
    }
    public static function integrated_menu_depth_register_settings_v150121() {
        // V1.50.313: Kein beschreibbarer Backend-Endpunkt mehr. Die drei
        // Navigationsebenen bleiben intern und fail-closed verriegelt.
        return;
    }

    public static function integrated_menu_depth_sanitize_v150121($input) {
        $input = is_array($input) ? $input : [];
        $registered = function_exists('get_registered_nav_menus') ? (array)get_registered_nav_menus() : [];
        $allowed = array_keys($registered);
        $locations = [];
        foreach ((array)($input['locations'] ?? self::integrated_menu_depth_options_v150121()['locations']) as $location) {
            $location = sanitize_key($location);
            if (in_array($location, $allowed, true)) { $locations[] = $location; }
        }
        return [
            'enabled' => 1,
            'depth' => 3,
            'locations' => array_values(array_unique($locations)),
        ];
    }


    public static function integrated_menu_depth_settings_page_v150121() {
        if (!current_user_can('manage_options')) { return; }
        $o = self::integrated_menu_depth_options_v150121();
        $registered = function_exists('get_registered_nav_menus') ? (array)get_registered_nav_menus() : [];
        echo '<div class="wrap"><h1>Navigationstiefe</h1>';
        echo '<p>Integrierter Nachfolger von „Pferdeportal Menü-Tiefe 3“. Ebene 4 bleibt im Header verborgen; Inhalte und URLs werden nicht verändert.</p>';
        echo '<form method="post" action="options.php">';
        settings_fields('pftk_menu_depth_group_v150121');
        echo '<table class="form-table" role="presentation"><tr><th>Aktiv</th><td><label><input type="checkbox" name="' . esc_attr(self::OPTION_MENU_DEPTH_V150121) . '[enabled]" value="1" ' . checked($o['enabled'], 1, false) . '> Menüausgabe begrenzen</label></td></tr>';
        echo '<tr><th>Maximale Ebenen</th><td><input class="small-text" type="number" min="1" max="10" name="' . esc_attr(self::OPTION_MENU_DEPTH_V150121) . '[depth]" value="' . esc_attr((string)$o['depth']) . '"></td></tr>';
        echo '<tr><th>Menüpositionen</th><td>';
        foreach ($registered as $location => $label) {
            echo '<label style="display:block;margin:0 0 8px"><input type="checkbox" name="' . esc_attr(self::OPTION_MENU_DEPTH_V150121) . '[locations][]" value="' . esc_attr($location) . '" ' . checked(in_array($location, $o['locations'], true), true, false) . '> <code>' . esc_html($location) . '</code> – ' . esc_html($label) . '</label>';
        }
        echo '</td></tr></table>';
        submit_button('Speichern');
        echo '</form></div>';
    }

    private static function integrated_menu_depth_frontend_v150121() {
        if (is_admin()) { return false; }
        if (function_exists('wp_doing_ajax') && wp_doing_ajax()) { return false; }
        if (defined('REST_REQUEST') && REST_REQUEST) { return false; }
        return true;
    }

    private static function integrated_menu_depth_should_limit_v150121($args) {
        $o = self::integrated_menu_depth_options_v150121();
        if (empty($o['enabled']) || empty($o['locations'])) { return false; }
        $location = sanitize_key((string)($args['theme_location'] ?? ''));
        return $location !== '' && in_array($location, $o['locations'], true);
    }

    public static function integrated_menu_depth_limit_args_v150121($args) {
        if (!self::integrated_menu_depth_frontend_v150121() || !self::integrated_menu_depth_should_limit_v150121((array)$args)) { return $args; }
        $max = self::integrated_menu_depth_options_v150121()['depth'];
        $current = isset($args['depth']) ? intval($args['depth']) : 0;
        if ($current === 0 || $current > $max) { $args['depth'] = $max; }
        return $args;
    }

    public static function integrated_menu_depth_remove_items_v150121($items, $args) {
        if (!self::integrated_menu_depth_frontend_v150121()) { return $items; }
        $arg_array = is_object($args) ? get_object_vars($args) : (array)$args;
        if (!self::integrated_menu_depth_should_limit_v150121($arg_array)) { return $items; }
        $max = self::integrated_menu_depth_options_v150121()['depth'];
        $parents = [];
        foreach ((array)$items as $item) { $parents[intval($item->ID)] = intval($item->menu_item_parent); }
        $cache = [];
        $kept = [];
        foreach ((array)$items as $item) {
            if (self::integrated_menu_item_depth_v150121(intval($item->ID), $parents, $cache) <= $max) { $kept[] = $item; }
        }
        return array_values($kept);
    }

    public static function integrated_menu_depth_clean_child_class_v150121($classes, $item, $args, $depth) {
        if (!self::integrated_menu_depth_frontend_v150121()) { return $classes; }
        $arg_array = is_object($args) ? get_object_vars($args) : (array)$args;
        if (!self::integrated_menu_depth_should_limit_v150121($arg_array)) { return $classes; }
        $max = self::integrated_menu_depth_options_v150121()['depth'];
        if ((intval($depth) + 1) >= $max) { $classes = array_diff((array)$classes, ['menu-item-has-children']); }
        return array_values($classes);
    }

    private static function integrated_menu_item_depth_v150121($item_id, $parents, &$cache) {
        if (isset($cache[$item_id])) { return $cache[$item_id]; }
        $depth = 1;
        $parent = intval($parents[$item_id] ?? 0);
        $guard = 0;
        while ($parent > 0 && isset($parents[$parent]) && $guard < 20) {
            $depth++; $parent = intval($parents[$parent] ?? 0); $guard++;
        }
        return $cache[$item_id] = $depth;
    }


